--------------------------------------------------------
--  DDL for Package Body PKG_GSTP
--------------------------------------------------------

  CREATE OR REPLACE NONEDITIONABLE PACKAGE BODY "GSCM"."PKG_GSTP" AS
PROCEDURE GSTP_HOME_MAP(
  in_DonViLogin IN NUMBER,
  inHienTai_TuNgay IN DATE,
  inHienTai_DenNgay IN DATE,
  inTruoc_TuNgay IN DATE,
  inTruoc_DenNgay IN DATE,
  curReturn OUT sys_refcursor
)AS
  v_CapToa_DonVi_Login VARCHAR2(250);
  v_CapToa VARCHAR2(250);
  v_ToaAn NUMBER DEFAULT 0;
  v_THULY NUMBER DEFAULT 0;
  v_GIAIQUYET NUMBER DEFAULT 0;
  v_CHUAGQ NUMBER DEFAULT 0;
  v_AN NUMBER DEFAULT 0;
  v_THAMPHAN NUMBER DEFAULT 0;
  v_TONG_THULY NUMBER DEFAULT 0;
  v_TONG_GIAIQUYET NUMBER DEFAULT 0;
  v_TONG_CHUAGQ NUMBER DEFAULT 0;
  v_TONG_AN NUMBER DEFAULT 0;
  v_TONG_THAMPHAN NUMBER DEFAULT 0;
  v_ARRAY THONGKE_AN_BANDO_VN_T;
  v_CapChaID NUMBER DEFAULT 0;
BEGIN
  v_CapToa:='';-- cả nước
  SELECT LOAITOA INTO v_CapToa_DonVi_Login FROM DM_TOAAN WHERE ID=in_DonViLogin;
  v_ARRAY:=new THONGKE_AN_BANDO_VN_T();
  -- ******** MÔ TẢ 
  -- 1. Đơn vị Login là tòa tối cao
  -- -- Drop Đơn vị: Cả nước, tòa tối cao, các tòa cấp cao, các tòa tỉnh
  -- -- 1.a Tính Cả nước
  -- -- 1.a.1: Cả nước: sơ thẩm + phúc thẩm + GDTT, Thẩm phán (tất cả các đơn vị)
  -- -- 1.a.2: Các đơn vị khác: tòa tối cao, các tòa cấp cao, các tòa tỉnh
  -- 2. Đơn vị Login là tòa cấp cao
  -- -- Drop Đơn vị sẽ có tòa cấp cao Login + các tòa cấp tỉnh trực thuộc
  -- -- 2.a Tính tòa cấp cao Login + các tòa cấp tỉnh trực thuộc
  -- -- 2.b Vẫn phải khai báo các tòa cấp tỉnh không trực thuộc tòa cấp cao login vào bản đồ
  -- 3. Đơn vị Login là tòa cấp tỉnh
  -- -- Drop Đơn vị chỉ có tòa cấp tỉnh Login
  -- -- 3.a Tính tòa cấp tỉnh Login
  -- -- 3.b Vẫn phải khai báo các tòa tỉnh còn thiếu vào bản đồ
  -- 4. Đơn vị Login là tòa cấp huyện
  -- -- 4.a Bản đồ chỉ tới cấp tỉnh -> sẽ hiện tòa cấp trên của Tòa cấp Huyện Login
  -- -- 4.b Vẫn phải khai báo các tòa tỉnh không phải là tòa cấp trên của Tòa cấp Huyện Login
  
  -- ******* THỰC HIỆN TỔNG HỢP
  -- 1. Đơn vị Login là tòa tối cao
  -- -- Drop Đơn vị: Cả nước, tòa tối cao, các tòa cấp cao, các tòa tỉnh
  -- -- 1.a Tính Cả nước, tòa tối cao, các tòa cấp cao, các tòa tỉnh
  -- -- 1.a.1: Cả nước: sơ thẩm + phúc thẩm + GDTT, Thẩm phán (tất cả các đơn vị)
  IF v_CapToa_DonVi_Login='TOICAO' THEN
        -- Sơ thẩm cả nước
        SELECT 
          v_TOAAN,V_THULYMOI,V_GIAIQUYET,V_CHUA_GQ,V_TONGTHULY
          INTO
          v_ToaAn,v_THULY,v_GIAIQUYET,v_CHUAGQ,v_AN
        FROM TABLE(PKG_GSTP.FUN_GSTP_HOME_ST(in_DonViLogin,v_CapToa,inHienTai_TuNgay,inHienTai_DenNgay,inTruoc_TuNgay,inTruoc_DenNgay));
        v_TONG_THULY:=v_TONG_THULY+v_THULY;
        v_TONG_GIAIQUYET:=v_TONG_GIAIQUYET+v_GIAIQUYET;
        v_TONG_CHUAGQ:=v_TONG_CHUAGQ+v_CHUAGQ;
        v_TONG_AN:=v_TONG_AN+v_AN;
        -- Phúc thẩm cả nước
        SELECT 
          v_TOAAN,V_THULYMOI,V_GIAIQUYET,V_CHUA_GQ,V_TONGTHULY
          INTO
          v_ToaAn,v_THULY,v_GIAIQUYET,v_CHUAGQ,v_AN
        FROM TABLE(PKG_GSTP.FUN_GSTP_HOME_PT(in_DonViLogin,v_CapToa,inHienTai_TuNgay,inHienTai_DenNgay,inTruoc_TuNgay,inTruoc_DenNgay));
        v_TONG_THULY:=v_TONG_THULY+v_THULY;
        v_TONG_GIAIQUYET:=v_TONG_GIAIQUYET+v_GIAIQUYET;
        v_TONG_CHUAGQ:=v_TONG_CHUAGQ+v_CHUAGQ;
        v_TONG_AN:=v_TONG_AN+v_AN;
        -- GDT cả nước
        SELECT 
          v_TOAAN,XX_ThuLyMoi,XX_DaGQ_KyBC,XX_ChuaGQ_KyBC,XX_TongSo_KyBC
          INTO
          v_ToaAn,v_THULY,v_GIAIQUYET,v_CHUAGQ,v_AN
        FROM TABLE(PKG_GSTP.FUN_GSTP_HOME_GDT(in_DonViLogin,inHienTai_TuNgay,inHienTai_DenNgay));
        v_TONG_THULY:=v_TONG_THULY+v_THULY;
        v_TONG_GIAIQUYET:=v_TONG_GIAIQUYET+v_GIAIQUYET;
        v_TONG_CHUAGQ:=v_TONG_CHUAGQ+v_CHUAGQ;
        v_TONG_AN:=v_TONG_AN+v_AN;
        -- Thẩm phán cả nước
        SELECT v_ID INTO v_TONG_THAMPHAN FROM TABLE(FUN_GSTP_HOME_TP_DANGCT(in_DonViLogin,v_CapToa,inHienTai_TuNgay,inHienTai_DenNgay));
        v_ARRAY.EXTEND(1);
        v_ARRAY(1):=THONGKE_AN_BANDO_VN_R(1,0,v_TONG_THULY,v_TONG_GIAIQUYET,v_TONG_CHUAGQ,v_TONG_AN,v_TONG_THAMPHAN,'VNM000','--- Cả nước ---','Tổng số vụ án: ' || v_TONG_AN || '<br>Thụ lý: ' || v_TONG_THULY || '<br>Giải quyết: ' || v_TONG_GIAIQUYET || '<br>Còn lại: ' || v_TONG_CHUAGQ || '<br>Thẩm phán: ' || v_TONG_THAMPHAN,'default','default','');
  -- -- 1.a.2: Các đơn vị khác: tòa tối cao, các tòa cấp cao, các tòa tỉnh,
        FOR ITEM IN(
          SELECT T1.ID,T1.LOAITOA,T2.MA,T2.NAME FROM DM_TOAAN T1
          INNER JOIN DM_TOAAN_MAP T2 ON T2.TOAANID=T1.ID
          WHERE INSTR('TOICAO,CAPCAO,CAPTINH,QSTRUNGUONG,QSQUANKHU',LOAITOA)>0
          ORDER BY ARRTHUTU
        ) LOOP
          v_TONG_THULY:=0;
          v_TONG_GIAIQUYET:=0;
          v_TONG_CHUAGQ:=0;
          v_TONG_AN:=0;
        -- Sơ thẩm
          IF INSTR('CAPTINH,QSQUANKHU',ITEM.LOAITOA)>0 THEN
            SELECT 
              v_TOAAN,V_THULYMOI,V_GIAIQUYET,V_CHUA_GQ,V_TONGTHULY
              INTO
              v_ToaAn,v_THULY,v_GIAIQUYET,v_CHUAGQ,v_AN
            FROM TABLE(PKG_GSTP.FUN_GSTP_HOME_ST(ITEM.ID,ITEM.LOAITOA,inHienTai_TuNgay,inHienTai_DenNgay,inTruoc_TuNgay,inTruoc_DenNgay));
            v_TONG_THULY:=v_TONG_THULY+v_THULY;
            v_TONG_GIAIQUYET:=v_TONG_GIAIQUYET+v_GIAIQUYET;
            v_TONG_CHUAGQ:=v_TONG_CHUAGQ+v_CHUAGQ;
            v_TONG_AN:=v_TONG_AN+v_AN;
          END IF;
        -- Phúc thẩm
          IF INSTR('CAPCAO,CAPTINH,QSTRUNGUONG,QSQUANKHU',ITEM.LOAITOA)>0 THEN
            SELECT 
              v_TOAAN,V_THULYMOI,V_GIAIQUYET,V_CHUA_GQ,V_TONGTHULY
              INTO
              v_ToaAn,v_THULY,v_GIAIQUYET,v_CHUAGQ,v_AN
            FROM TABLE(PKG_GSTP.FUN_GSTP_HOME_PT(ITEM.ID,ITEM.LOAITOA,inHienTai_TuNgay,inHienTai_DenNgay,inTruoc_TuNgay,inTruoc_DenNgay));
            v_TONG_THULY:=v_TONG_THULY+v_THULY;
            v_TONG_GIAIQUYET:=v_TONG_GIAIQUYET+v_GIAIQUYET;
            v_TONG_CHUAGQ:=v_TONG_CHUAGQ+v_CHUAGQ;
            v_TONG_AN:=v_TONG_AN+v_AN;
          END IF;
        -- GDT
          IF INSTR('TOICAO,CAPCAO,QSTRUNGUONG',ITEM.LOAITOA)>0 THEN
            SELECT 
              v_TOAAN,XX_ThuLyMoi,XX_DaGQ_KyBC,XX_ChuaGQ_KyBC,XX_TongSo_KyBC
              INTO
              v_ToaAn,v_THULY,v_GIAIQUYET,v_CHUAGQ,v_AN
            FROM TABLE(PKG_GSTP.FUN_GSTP_HOME_GDT(ITEM.ID,inHienTai_TuNgay,inHienTai_DenNgay));
            v_TONG_THULY:=v_TONG_THULY+v_THULY;
            v_TONG_GIAIQUYET:=v_TONG_GIAIQUYET+v_GIAIQUYET;
            v_TONG_CHUAGQ:=v_TONG_CHUAGQ+v_CHUAGQ;
            v_TONG_AN:=v_TONG_AN+v_AN;
          END IF;
        -- Thẩm phán
        SELECT v_ID INTO v_TONG_THAMPHAN FROM TABLE(FUN_GSTP_HOME_TP_DANGCT(ITEM.ID,ITEM.LOAITOA,inHienTai_TuNgay,inHienTai_DenNgay));
        v_ARRAY.EXTEND();
        v_ARRAY(v_ARRAY.COUNT):=THONGKE_AN_BANDO_VN_R(v_ARRAY.COUNT,ITEM.ID,v_TONG_THULY,v_TONG_GIAIQUYET,v_TONG_CHUAGQ,v_TONG_AN,v_TONG_THAMPHAN,ITEM.MA,ITEM.NAME,'Tổng số vụ án: ' || v_TONG_AN || '<br>Thụ lý: ' || v_TONG_THULY || '<br>Giải quyết: ' || v_TONG_GIAIQUYET || '<br>Còn lại: ' || v_TONG_CHUAGQ || '<br>Thẩm phán: ' || v_TONG_THAMPHAN,'default','default','');
        END LOOP;
        
  ELSIF INSTR('CAPCAO,QSTRUNGUONG',v_CapToa_DonVi_Login)>0 THEN
  -- 2. Đơn vị Login là tòa cấp cao
  -- -- Drop Đơn vị sẽ có tòa cấp cao Login + các tòa cấp tỉnh trực thuộc
  -- -- 2.a Tính tòa cấp cao Login + các tòa cấp tỉnh trực thuộc
  -- -- 2.b Vẫn phải khai báo các tòa cấp tỉnh không trực thuộc tòa cấp cao login vào bản đồ
        FOR ITEM IN
        (
          SELECT T1.ID,T1.LOAITOA,T2.MA,T2.NAME,
                 CASE WHEN INSTR('CAPCAO,QSTRUNGUONG',T1.LOAITOA)>0 AND T1.ID=in_DonViLogin THEN 1
                      WHEN INSTR('CAPTINH,QSQUANKHU',T1.LOAITOA)>0 AND T1.CAPCHAID=in_DonViLogin THEN 1 ELSE 0 END AS ISSHOW
          FROM DM_TOAAN T1
          INNER JOIN DM_TOAAN_MAP T2 ON T2.TOAANID=T1.ID
          WHERE INSTR('CAPCAO,CAPTINH,QSTRUNGUONG,QSQUANKHU',T1.LOAITOA)>0
                AND 1=CASE WHEN INSTR('CAPCAO,QSTRUNGUONG',T1.LOAITOA)>0 AND T1.ID=in_DonViLogin THEN 1
                           WHEN INSTR('CAPTINH,QSQUANKHU',T1.LOAITOA)>0 THEN 1 ELSE 0 END
          ORDER BY T1.ARRTHUTU 
        )LOOP
          v_TONG_THULY:=0;
          v_TONG_GIAIQUYET:=0;
          v_TONG_CHUAGQ:=0;
          v_TONG_AN:=0;
          IF ITEM.ISSHOW=1 THEN --> những đơn vị cần tính
          -- Sơ thẩm
            IF ITEM.LOAITOA='CAPTINH' THEN
              SELECT 
                v_TOAAN,V_THULYMOI,V_GIAIQUYET,V_CHUA_GQ,V_TONGTHULY
                INTO
                v_ToaAn,v_THULY,v_GIAIQUYET,v_CHUAGQ,v_AN
              FROM TABLE(PKG_GSTP.FUN_GSTP_HOME_ST(ITEM.ID,ITEM.LOAITOA,inHienTai_TuNgay,inHienTai_DenNgay,inTruoc_TuNgay,inTruoc_DenNgay));
              v_TONG_THULY:=v_TONG_THULY+v_THULY;
              v_TONG_GIAIQUYET:=v_TONG_GIAIQUYET+v_GIAIQUYET;
              v_TONG_CHUAGQ:=v_TONG_CHUAGQ+v_CHUAGQ;
              v_TONG_AN:=v_TONG_AN+v_AN;
            END IF;
          -- Phúc thẩm
            IF ITEM.LOAITOA='CAPCAO' OR ITEM.LOAITOA='CAPTINH' THEN
              SELECT 
                v_TOAAN,V_THULYMOI,V_GIAIQUYET,V_CHUA_GQ,V_TONGTHULY
                INTO
                v_ToaAn,v_THULY,v_GIAIQUYET,v_CHUAGQ,v_AN
              FROM TABLE(PKG_GSTP.FUN_GSTP_HOME_PT(ITEM.ID,ITEM.LOAITOA,inHienTai_TuNgay,inHienTai_DenNgay,inTruoc_TuNgay,inTruoc_DenNgay));
              v_TONG_THULY:=v_TONG_THULY+v_THULY;
              v_TONG_GIAIQUYET:=v_TONG_GIAIQUYET+v_GIAIQUYET;
              v_TONG_CHUAGQ:=v_TONG_CHUAGQ+v_CHUAGQ;
              v_TONG_AN:=v_TONG_AN+v_AN;
            END IF;
          -- GDT
            IF ITEM.LOAITOA='CAPCAO' THEN
              SELECT 
                v_TOAAN,XX_ThuLyMoi,XX_DaGQ_KyBC,XX_ChuaGQ_KyBC,XX_TongSo_KyBC
                INTO
                v_ToaAn,v_THULY,v_GIAIQUYET,v_CHUAGQ,v_AN
              FROM TABLE(PKG_GSTP.FUN_GSTP_HOME_GDT(ITEM.ID,inHienTai_TuNgay,inHienTai_DenNgay));
              v_TONG_THULY:=v_TONG_THULY+v_THULY;
              v_TONG_GIAIQUYET:=v_TONG_GIAIQUYET+v_GIAIQUYET;
              v_TONG_CHUAGQ:=v_TONG_CHUAGQ+v_CHUAGQ;
              v_TONG_AN:=v_TONG_AN+v_AN;
            END IF;
          -- Thẩm phán
            SELECT v_ID INTO v_TONG_THAMPHAN FROM TABLE(FUN_GSTP_HOME_TP_DANGCT(ITEM.ID,ITEM.LOAITOA,inHienTai_TuNgay,inHienTai_DenNgay));
            v_ARRAY.EXTEND();
            v_ARRAY(v_ARRAY.COUNT):=THONGKE_AN_BANDO_VN_R(v_ARRAY.COUNT,ITEM.ID,v_TONG_THULY,v_TONG_GIAIQUYET,v_TONG_CHUAGQ,v_TONG_AN,v_TONG_THAMPHAN,ITEM.MA,ITEM.NAME,'Tổng số vụ án: ' || v_TONG_AN || '<br>Thụ lý: ' || v_TONG_THULY || '<br>Giải quyết: ' || v_TONG_GIAIQUYET || '<br>Còn lại: ' || v_TONG_CHUAGQ || '<br>Thẩm phán: ' || v_TONG_THAMPHAN,'default','default','');
          ELSE
            v_ARRAY.EXTEND();
            v_ARRAY(v_ARRAY.COUNT):=THONGKE_AN_BANDO_VN_R(v_ARRAY.COUNT,ITEM.ID,0,0,0,0,0,ITEM.MA,ITEM.NAME,'','default','default','');
          END IF;
      END LOOP;
  ELSIF INSTR('CAPTINH,QSQUANKHU',v_CapToa_DonVi_Login)>0 THEN
  -- 3. Đơn vị Login là tòa cấp tỉnh
  -- -- Drop Đơn vị chỉ có tòa cấp tỉnh Login
  -- -- 3.a Tính tòa cấp tỉnh Login
  -- -- 3.b Vẫn phải khai báo các tòa tỉnh còn thiếu vào bản đồ
        FOR ITEM IN
        (
          SELECT T1.ID,T1.LOAITOA,T2.MA,T2.NAME,
                 CASE WHEN T1.ID=in_DonViLogin THEN 1 ELSE 0 END AS ISSHOW
          FROM DM_TOAAN T1
          INNER JOIN DM_TOAAN_MAP T2 ON T2.TOAANID=T1.ID
          WHERE T1.LOAITOA='CAPTINH'
          ORDER BY T1.ARRTHUTU
        )LOOP
          v_TONG_THULY:=0;
          v_TONG_GIAIQUYET:=0;
          v_TONG_CHUAGQ:=0;
          v_TONG_AN:=0;
          IF ITEM.ISSHOW=1 THEN
        -- Sơ thẩm
            SELECT 
              v_TOAAN,V_THULYMOI,V_GIAIQUYET,V_CHUA_GQ,V_TONGTHULY
              INTO
              v_ToaAn,v_THULY,v_GIAIQUYET,v_CHUAGQ,v_AN
            FROM TABLE(PKG_GSTP.FUN_GSTP_HOME_ST(ITEM.ID,ITEM.LOAITOA,inHienTai_TuNgay,inHienTai_DenNgay,inTruoc_TuNgay,inTruoc_DenNgay));
            v_TONG_THULY:=v_TONG_THULY+v_THULY;
            v_TONG_GIAIQUYET:=v_TONG_GIAIQUYET+v_GIAIQUYET;
            v_TONG_CHUAGQ:=v_TONG_CHUAGQ+v_CHUAGQ;
            v_TONG_AN:=v_TONG_AN+v_AN;
        -- Phúc thẩm
            SELECT 
              v_TOAAN,V_THULYMOI,V_GIAIQUYET,V_CHUA_GQ,V_TONGTHULY
              INTO
              v_ToaAn,v_THULY,v_GIAIQUYET,v_CHUAGQ,v_AN
            FROM TABLE(PKG_GSTP.FUN_GSTP_HOME_PT(ITEM.ID,ITEM.LOAITOA,inHienTai_TuNgay,inHienTai_DenNgay,inTruoc_TuNgay,inTruoc_DenNgay));
            v_TONG_THULY:=v_TONG_THULY+v_THULY;
            v_TONG_GIAIQUYET:=v_TONG_GIAIQUYET+v_GIAIQUYET;
            v_TONG_CHUAGQ:=v_TONG_CHUAGQ+v_CHUAGQ;
            v_TONG_AN:=v_TONG_AN+v_AN;
        -- Thẩm phán
            SELECT v_ID INTO v_TONG_THAMPHAN FROM TABLE(FUN_GSTP_HOME_TP_DANGCT(ITEM.ID,ITEM.LOAITOA,inHienTai_TuNgay,inHienTai_DenNgay));
            v_ARRAY.EXTEND();
            v_ARRAY(v_ARRAY.COUNT):=THONGKE_AN_BANDO_VN_R(v_ARRAY.COUNT,ITEM.ID,v_TONG_THULY,v_TONG_GIAIQUYET,v_TONG_CHUAGQ,v_TONG_AN,v_TONG_THAMPHAN,ITEM.MA,ITEM.NAME,'Tổng số vụ án: ' || v_TONG_AN || '<br>Thụ lý: ' || v_TONG_THULY || '<br>Giải quyết: ' || v_TONG_GIAIQUYET || '<br>Còn lại: ' || v_TONG_CHUAGQ || '<br>Thẩm phán: ' || v_TONG_THAMPHAN,'default','default','');
          ELSE
            v_ARRAY.EXTEND();
            v_ARRAY(v_ARRAY.COUNT):=THONGKE_AN_BANDO_VN_R(v_ARRAY.COUNT,ITEM.ID,0,0,0,0,0,ITEM.MA,ITEM.NAME,'','default','default','');
          END IF;
        END LOOP;
  ELSIF INSTR('CAPHUYEN,QSKHUVUC',v_CapToa_DonVi_Login)>0 THEN
  -- 4. Đơn vị Login là tòa cấp huyện
  -- -- 4.a Bản đồ chỉ tới cấp tỉnh -> sẽ hiện tòa cấp trên của Tòa cấp Huyện Login
  -- -- 4.b Vẫn phải khai báo các tòa tỉnh không phải là tòa cấp trên của Tòa cấp Huyện Login
        SELECT CAPCHAID INTO v_CapChaID FROM DM_TOAAN WHERE ID=in_DonViLogin;
        FOR ITEM IN
        (
          SELECT T1.ID,T1.LOAITOA,T2.MA,T2.NAME,
                 CASE WHEN T1.ID=v_CapChaID THEN 1 ELSE 0 END AS ISSHOW
          FROM DM_TOAAN T1
          INNER JOIN DM_TOAAN_MAP T2 ON T2.TOAANID=T1.ID
          WHERE T1.LOAITOA='CAPTINH'
          ORDER BY T1.ARRTHUTU
        )LOOP
          v_TONG_THULY:=0;
          v_TONG_GIAIQUYET:=0;
          v_TONG_CHUAGQ:=0;
          v_TONG_AN:=0;
          IF ITEM.ISSHOW=1 THEN
        -- Sơ thẩm
            SELECT 
              v_TOAAN,V_THULYMOI,V_GIAIQUYET,V_CHUA_GQ,V_TONGTHULY
              INTO
              v_ToaAn,v_THULY,v_GIAIQUYET,v_CHUAGQ,v_AN
            FROM TABLE(PKG_GSTP.FUN_GSTP_HOME_ST(ITEM.ID,ITEM.LOAITOA,inHienTai_TuNgay,inHienTai_DenNgay,inTruoc_TuNgay,inTruoc_DenNgay));
            v_TONG_THULY:=v_TONG_THULY+v_THULY;
            v_TONG_GIAIQUYET:=v_TONG_GIAIQUYET+v_GIAIQUYET;
            v_TONG_CHUAGQ:=v_TONG_CHUAGQ+v_CHUAGQ;
            v_TONG_AN:=v_TONG_AN+v_AN;
        -- Phúc thẩm
            SELECT 
              v_TOAAN,V_THULYMOI,V_GIAIQUYET,V_CHUA_GQ,V_TONGTHULY
              INTO
              v_ToaAn,v_THULY,v_GIAIQUYET,v_CHUAGQ,v_AN
            FROM TABLE(PKG_GSTP.FUN_GSTP_HOME_PT(ITEM.ID,ITEM.LOAITOA,inHienTai_TuNgay,inHienTai_DenNgay,inTruoc_TuNgay,inTruoc_DenNgay));
            v_TONG_THULY:=v_TONG_THULY+v_THULY;
            v_TONG_GIAIQUYET:=v_TONG_GIAIQUYET+v_GIAIQUYET;
            v_TONG_CHUAGQ:=v_TONG_CHUAGQ+v_CHUAGQ;
            v_TONG_AN:=v_TONG_AN+v_AN;
        -- Thẩm phán
            SELECT v_ID INTO v_TONG_THAMPHAN FROM TABLE(FUN_GSTP_HOME_TP_DANGCT(ITEM.ID,ITEM.LOAITOA,inHienTai_TuNgay,inHienTai_DenNgay));
            v_ARRAY.EXTEND();
            v_ARRAY(v_ARRAY.COUNT):=THONGKE_AN_BANDO_VN_R(v_ARRAY.COUNT,ITEM.ID,v_TONG_THULY,v_TONG_GIAIQUYET,v_TONG_CHUAGQ,v_TONG_AN,v_TONG_THAMPHAN,ITEM.MA,ITEM.NAME,'Tổng số vụ án: ' || v_TONG_AN || '<br>Thụ lý: ' || v_TONG_THULY || '<br>Giải quyết: ' || v_TONG_GIAIQUYET || '<br>Còn lại: ' || v_TONG_CHUAGQ || '<br>Thẩm phán: ' || v_TONG_THAMPHAN,'default','default','');
          ELSE
            v_ARRAY.EXTEND();
          v_ARRAY(v_ARRAY.COUNT):=THONGKE_AN_BANDO_VN_R(v_ARRAY.COUNT,ITEM.ID,0,0,0,0,0,ITEM.MA,ITEM.NAME,'','default','default','');
          END IF;
        END LOOP;
  END IF;
  
  OPEN curReturn FOR
  SELECT T1.* FROM TABLE(v_ARRAY) T1;
END GSTP_HOME_MAP;

