    -- TÍNH CẤP TỈNH
    -- -- Lấy danh sách các tòa cấp tỉnh
    SELECT GSTP_PAGE2_SOTHAM_DS_R(
      V_STT => ROW_NUMBER() OVER(ORDER BY T1.ID),
      V_TOAAN => T1.ID,
      V_CAPTOA => 'Cấp tỉnh',
      V_TONGTHULY => 0,
      V_GQ_CHUYENHOSO => 0,
      V_GQ_DINHCHI => 0,
      V_GQ_CONGNHANTHOATHUAN => 0,
      V_GQ_XETXU => 0,
      V_GQ_TONGGQ => 0,
      V_GQ_TYLEGQ => 0,
      V_ANHUY => 0,
      V_ANHUY_TYLE => 0,
      V_ANSUA => 0,
      V_ANSUA_TYLE => 0,
      V_CONLAI => 0,
      V_QUAHAN_CHUAGQ => 0,
      V_QUAHAN_CHUAGQ_TYLE => 0
      ) BULK COLLECT INTO v_ARRAY_EX
      FROM DM_TOAAN T1 
      WHERE T1.LOAITOA='CAPTINH'
            AND 1=CASE WHEN T1.LOAITOA='CAPTINH' AND T1.ID=inToaAnID THEN 1
                       WHEN v_CAPTOA || ' '=' ' THEN 1 ELSE 0 END;
      -- Fill dữ liệu Cấp tỉnh
      PKG_GSTP.FILL_GSTP_PAGE2_SOTHAM_HNGD(v_ARRAY_EX,vDate_Nam_HienTai_DauKy,vDate_Nam_HienTai_CuoiKy,vDate_Nam_Truoc_DauKy,vDate_Nam_Truoc_CuoiKy);
      -- Gán dữ liệu cấp tỉnh vào Bảng Chung v_ARRAY
      SELECT
        SUM(V_TONGTHULY),
        SUM(V_GQ_CHUYENHOSO),
        SUM(V_GQ_DINHCHI),
        SUM(V_GQ_CONGNHANTHOATHUAN),
        SUM(V_GQ_XETXU),
        SUM(V_GQ_TONGGQ),
        DECODE(SUM(V_TONGTHULY),0,0,ROUND(SUM(V_GQ_TONGGQ)/SUM(V_TONGTHULY)*100)),
        SUM(V_ANHUY),
