        SUM(V_TONGTHULY)-SUM(V_GQ_TONGGQ),
        SUM(V_QUAHAN_CHUAGQ),
        DECODE(SUM(V_TONGTHULY),0,0,ROUND(SUM(V_QUAHAN_CHUAGQ)/SUM(V_TONGTHULY)*100))
        INTO 
        v_ARRAY(v_INDEX).V_TONGTHULY,
        v_ARRAY(v_INDEX).V_GQ_CHUYENHOSO,
        v_ARRAY(v_INDEX).V_GQ_DINHCHI,
