      V_GQ_TONGGQ => 0,
      V_GQ_TYLEGQ => 0,
      V_ANHUY => 0,
      V_ANHUY_TYLE => 0,
      V_ANSUA => 0,
      V_ANSUA_TYLE => 0,
      V_CONLAI => 0,
      V_QUAHAN_CHUAGQ => 0,
      V_QUAHAN_CHUAGQ_TYLE => 0
      ) BULK COLLECT INTO v_ARRAY_EX
      FROM DM_TOAAN T1 
      WHERE T1.LOAITOA='CAPHUYEN'
            AND 1=CASE WHEN T1.LOAITOA='CAPHUYEN' AND T1.ID=inToaAnID THEN 1
                       WHEN v_CAPTOA || ' '=' ' THEN 1 ELSE 0 END;
      -- Fill dữ liệu Cấp huyện
      PKG_GSTP.FILL_GSTP_PAGE2_SOTHAM_HNGD(v_ARRAY_EX,vDate_Nam_HienTai_DauKy,vDate_Nam_HienTai_CuoiKy,vDate_Nam_Truoc_DauKy,vDate_Nam_Truoc_CuoiKy);
      -- Gán dữ liệu cấp huyện vào Bảng Chung v_ARRAY
      SELECT
        SUM(V_TONGTHULY),
        SUM(V_GQ_CHUYENHOSO),
        SUM(V_GQ_DINHCHI),
        SUM(V_GQ_CONGNHANTHOATHUAN),
        SUM(V_GQ_XETXU),
        SUM(V_GQ_TONGGQ),
        DECODE(SUM(V_TONGTHULY),0,0,ROUND(SUM(V_GQ_TONGGQ)/SUM(V_TONGTHULY)*100)),
        SUM(V_ANHUY),
        DECODE(SUM(V_TONGTHULY),0,0,ROUND(SUM(V_ANHUY)/SUM(V_TONGTHULY)*100)),
        SUM(V_ANSUA),
        DECODE(SUM(V_TONGTHULY),0,0,ROUND(SUM(V_ANSUA)/SUM(V_TONGTHULY)*100)),
         SUM(V_TONGTHULY)-SUM(V_GQ_TONGGQ),
        SUM(V_QUAHAN_CHUAGQ),
        DECODE(SUM(V_TONGTHULY),0,0,ROUND(SUM(V_QUAHAN_CHUAGQ)/SUM(V_TONGTHULY)*100))
        INTO 
        v_ARRAY(v_INDEX).V_TONGTHULY,
        v_ARRAY(v_INDEX).V_GQ_CHUYENHOSO,
        v_ARRAY(v_INDEX).V_GQ_DINHCHI,
        v_ARRAY(v_INDEX).V_GQ_CONGNHANTHOATHUAN,
        v_ARRAY(v_INDEX).V_GQ_XETXU,
        v_ARRAY(v_INDEX).V_GQ_TONGGQ,
        v_ARRAY(v_INDEX).V_GQ_TYLEGQ,
        v_ARRAY(v_INDEX).V_ANHUY,
        v_ARRAY(v_INDEX).V_ANHUY_TYLE,
        v_ARRAY(v_INDEX).V_ANSUA,
        v_ARRAY(v_INDEX).V_ANSUA_TYLE,
        v_ARRAY(v_INDEX).V_CONLAI,
        v_ARRAY(v_INDEX).V_QUAHAN_CHUAGQ,
        v_ARRAY(v_INDEX).V_QUAHAN_CHUAGQ_TYLE
      FROM TABLE(v_ARRAY_EX);
  END IF;
  
  -- XUẤT DỮ LIỆU
  OPEN CurReturn FOR
  SELECT NVL(TO_CHAR(T1.V_CAPTOA), 'Cộng') as V_CAPTOA,
    SUM(V_TONGTHULY) V_TONGTHULY,
    SUM(V_GQ_CHUYENHOSO) V_GQ_CHUYENHOSO,
    SUM(V_GQ_DINHCHI) V_GQ_DINHCHI,
    SUM(V_GQ_CONGNHANTHOATHUAN) V_GQ_CONGNHANTHOATHUAN,
