    -- TÍNH CẤP HUYỆN
    -- -- Lấy danh sách các tòa cấp huyện
    SELECT GSTP_PAGE2_SOTHAM_DS_R(
      V_STT => ROW_NUMBER() OVER(ORDER BY T1.ID),
      V_TOAAN => T1.ID,
      V_CAPTOA => 'Cấp huyện',
