                       WHEN v_CAPTOA || ' '=' ' THEN 1 ELSE 0 END;
      -- Fill dữ liệu
      PKG_GSTP.FILL_GSTP_PAGE2_PHUCTHAM_AHN(v_ARRAY_EX,vDate_Nam_HienTai_DauKy,vDate_Nam_HienTai_CuoiKy,vDate_Nam_Truoc_DauKy,vDate_Nam_Truoc_CuoiKy);
      -- Gán dữ liệu vào Bảng Chung v_ARRAY
      SELECT
        SUM(V_TONGTHULY),
        SUM(V_GQ_TONGGQ),
        DECODE(SUM(V_TONGTHULY),0,0,ROUND(SUM(V_GQ_TONGGQ)/SUM(V_TONGTHULY)*100)),
        SUM(V_GQ_RUTKINHNGHIEM),
        SUM(V_PHANTICH_TAMDINHCHI),
        SUM(V_PHANTICH_ANLE),
        SUM(V_PHANTICH_DC_RUTKHANGCAO),
        SUM(V_PHANTICH_DC_RUTKHANGNGHI),
        SUM(V_PHANTICH_DC_LYDOKHAC),
        SUM(V_PHANTICH_SUA_CAPSOTHAMSAI),
        SUM(V_PHANTICH_SUA_TINHTIETMOI),
        SUM(V_PHANTICH_HUY_CAPSOTHAMSAI),
        SUM(V_PHANTICH_HUY_TINHTIETMOI),
        SUM(V_TONGTHULY)-SUM(V_GQ_TONGGQ),
        SUM(V_QUAHAN_CHUAGQ)
        INTO 
        v_ARRAY(v_INDEX).V_TONGTHULY,
        v_ARRAY(v_INDEX).V_GQ_TONGGQ,
        v_ARRAY(v_INDEX).V_GQ_TYLEGQ,
        v_ARRAY(v_INDEX).V_GQ_RUTKINHNGHIEM,
        v_ARRAY(v_INDEX).V_PHANTICH_TAMDINHCHI,
        v_ARRAY(v_INDEX).V_PHANTICH_ANLE,
        v_ARRAY(v_INDEX).V_PHANTICH_DC_RUTKHANGCAO,
        v_ARRAY(v_INDEX).V_PHANTICH_DC_RUTKHANGNGHI,
        v_ARRAY(v_INDEX).V_PHANTICH_DC_LYDOKHAC,
        v_ARRAY(v_INDEX).V_PHANTICH_SUA_CAPSOTHAMSAI,
        v_ARRAY(v_INDEX).V_PHANTICH_SUA_TINHTIETMOI,
        v_ARRAY(v_INDEX).V_PHANTICH_HUY_CAPSOTHAMSAI,
        v_ARRAY(v_INDEX).V_PHANTICH_HUY_TINHTIETMOI,
        v_ARRAY(v_INDEX).V_CONLAI,
        v_ARRAY(v_INDEX).V_QUAHAN_CHUAGQ
      FROM TABLE(v_ARRAY_EX);
  END IF;
  -- XUẤT DỮ LIỆU
  OPEN CurReturn FOR
  SELECT 
    NVL(TO_CHAR(T1.V_CAPTOA), 'Cộng') as V_CAPTOA,
    SUM(V_TONGTHULY) V_TONGTHULY,
    SUM(V_GQ_TONGGQ) V_GQ_TONGGQ,
    DECODE(SUM(V_TONGTHULY),0,0,ROUND(SUM(V_GQ_TONGGQ)/SUM(V_TONGTHULY)*100)) V_GQ_TYLEGQ,
    SUM(V_GQ_RUTKINHNGHIEM) V_GQ_RUTKINHNGHIEM,
    SUM(V_PHANTICH_TAMDINHCHI) V_PHANTICH_TAMDINHCHI,
    SUM(V_PHANTICH_ANLE) V_PHANTICH_ANLE,
    SUM(V_PHANTICH_DC_RUTKHANGCAO) V_PHANTICH_DC_RUTKHANGCAO,
    SUM(V_PHANTICH_DC_RUTKHANGNGHI) V_PHANTICH_DC_RUTKHANGNGHI,
    SUM(V_PHANTICH_DC_LYDOKHAC) V_PHANTICH_DC_LYDOKHAC,
    SUM(V_PHANTICH_SUA_CAPSOTHAMSAI) V_PHANTICH_SUA_CAPSOTHAMSAI,
