      -- Fill dữ liệu
      PKG_GSTP.FILL_GSTP_PAGE2_PHUCTHAM_AHC(v_ARRAY_EX,vDate_Nam_HienTai_DauKy,vDate_Nam_HienTai_CuoiKy,vDate_Nam_Truoc_DauKy,vDate_Nam_Truoc_CuoiKy);
      -- Gán dữ liệu vào Bảng Chung v_ARRAY
      SELECT
