PROCEDURE DS_AN_OFTP_BY_VAITRO_PLUS 
(
	vThamPhanID IN number,
	vVaiTro in varchar2,
	vTenVuAn in varchar2,
	vTuNgay in date,
	vDenNgay in date,
  vGetAll in int,
	CurReturn OUT sys_refcursor
) AS
	strVaiTro varchar2(250);
  strTenVuAn varchar(250);
BEGIN
  select lower(vTenVuAn) into strTenVuAn from dual;
	strVaiTro:=vVaiTro;
  
	OPEN CurReturn FOR
	SELECT re.VuAnID,re.MaVuAn,re.TenVuAn,re.LinhVuc,re.MAGIAIDOAN,
    REPLACE(ta.TEN,'Tòa án nhân dân','TAND') as TenToaAn,
		re.TenMaGiaiDoan,re.NGAYPHANCONG,ta.ARRTHUTU,re.TrangThai
	FROM (
  -- Hình sự không có quá hạn ở phúc thẩm
        SELECT va.ID AS VuAnID,va.MAVUAN AS MaVuAn,va.TENVUAN AS TenVuAn,
          DECODE(va.TOAPHUCTHAMID,NULL,va.TOAANID,va.TOAPHUCTHAMID) AS ToaAnID,
          'Hình sự' as LinhVuc,va.MAGIAIDOAN,
          DECODE(xetxu_PT.VUANID,NULL,DECODE(xetxu_ST.VUANID,NULL,DECODE(gqan.MAVAITRO,'VTTP_GIAIQUYETPHUCTHAM','Phúc thẩm',DECODE(gqan.MAVAITRO,'VTTP_GIAIQUYETSOTHAM','Sơ thẩm','Hồ sơ')),'Sơ thẩm'),'Phúc thẩm') as TenMaGiaiDoan,
          DECODE(xetxu_PT.NGAYPHANCONG,NULL,DECODE(xetxu_ST.NGAYPHANCONG,NULL,DECODE(gqan.VUANID,NULL,NULL,gqan.NGAYPHANCONG),xetxu_ST.NGAYPHANCONG),xetxu_PT.NGAYPHANCONG) AS NGAYPHANCONG,
          DECODE(qdst.VUANID,NULL,NULL,DECODE(xetxu_ST.CANBOID,NULL,NULL,qdst.TrangThai || ',<br/>')) ||
          DECODE(bast.VUANID,NULL,NULL,DECODE(xetxu_ST.CANBOID,NULL,NULL,'Vụ án quá hạn' || ',<br/>')) ||
          DECODE(qdpt.VUANID,NULL,NULL,DECODE(xetxu_PT.CANBOID,NULL,NULL,qdpt.TrangThai || ',<br/>')) ||
          DECODE(suahuyST.VUANID,NULL,NULL,DECODE(xetxu_ST.CANBOID,NULL,NULL,suahuyST.TrangThai)) AS TrangThai
        FROM AHS_VUAN va
        LEFT JOIN AHS_SOTHAM_BANAN bast ON bast.VUANID=va.ID AND (bast.TK_QUAHAN_CHUQUAN=1 OR bast.TK_QUAHAN_KHACHQUAN=1)
        LEFT JOIN (SELECT b.VUANID,b.NGAYPHANCONG,b.MAVAITRO FROM AHS_THAMPHANGIAIQUYET b
                    WHERE b.CANBOID=vThamPhanID 
                          AND b.NGAYPHANCONG=(SELECT MAX(a.NGAYPHANCONG) 
                                              FROM AHS_THAMPHANGIAIQUYET a
                                              WHERE  a.CANBOID=vThamPhanID AND a.VUANID=b.VUANID
                                              GROUP BY a.VUANID)
                  ) gqan ON gqan.VUANID=va.ID
        LEFT JOIN AHS_SOTHAM_HDXX xetxu_ST ON xetxu_ST.VUANID=va.ID AND xetxu_ST.CANBOID=vThamPhanID 
        LEFT JOIN AHS_PHUCTHAM_HDXX xetxu_PT ON xetxu_PT.VUANID=va.ID AND xetxu_PT.CANBOID=vThamPhanID
        LEFT JOIN (SELECT a.VUANID,LISTAGG(a.TrangThai,',<br/>') WITHIN GROUP (ORDER BY a.VUANID) AS TrangThai
                   FROM (
                         SELECT DISTINCT qd.VUANID,DECODE(loai.MA,'DC','Vụ án bị đình chỉ','TDC','Vụ án tạm đình chỉ','ADBPTT','Vụ án có áp dụng các biện pháp khẩn cấp tạm thời','') TrangThai 
                         FROM AHS_SOTHAM_QUYETDINH_VUAN qd
                         INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
                         WHERE loai.ISDANSU=1 AND loai.HIEULUC=1 AND INSTR('TDC,DC,ADBPTT,',loai.MA || ',')>0
                         )a GROUP BY a.VUANID
                  ) qdst ON qdst.VUANID=va.ID
        LEFT JOIN (SELECT ba.VUANID,
                          CASE WHEN INSTR('03,04,06,12,13,14,15',kq.MA)>0 THEN 'Vụ án bị hủy' || ',<br/>' 
                               WHEN INSTR('02,05,11,16,17',kq.MA)>0 THEN 'Vụ án bị sửa' || ',<br/>' ELSE '' END AS TrangThai
                    FROM AHS_PHUCTHAM_BANAN ba
                    INNER JOIN DM_KETQUA_PHUCTHAM kq ON kq.ID=ba.KETQUAPHUCTHAMID
                    WHERE (kq.ISADS=1 AND INSTR('03,04,06,12,13,14,15,02,05,11,16,17',kq.MA)>0)
                    ) suahuyST ON suahuyST.VUANID=va.ID
        LEFT JOIN (SELECT a.VUANID,LISTAGG(a.TrangThai,',<br/>') WITHIN GROUP (ORDER BY a.VUANID) AS TrangThai
                   FROM (
                         SELECT DISTINCT qd.VUANID,DECODE(loai.MA,'DC','Vụ án bị đình chỉ','TDC','Vụ án tạm đình chỉ','ADBPTT','Vụ án có áp dụng các biện pháp khẩn cấp tạm thời','') TrangThai 
                         FROM AHS_PHUCTHAM_QUYETDINH_VUAN qd
                         INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
                         WHERE loai.ISDANSU=1 AND loai.HIEULUC=1 AND INSTR('TDC,DC,ADBPTT,',loai.MA || ',')>0
                         )a GROUP BY a.VUANID
                  ) qdpt ON qdpt.VUANID=va.ID
        WHERE (
                (gqan.VUANID > 0 
                  AND 1=CASE WHEN vGetAll=1 THEN 1
                             WHEN strVaiTro='VTTP_GIAIQUYETDON,' AND INSTR('VTTP_GIAIQUYETSOTHAM,VTTP_GIAIQUYETPHUCTHAM',gqan.MAVAITRO)=0 THEN 1 
                             WHEN strVaiTro='VTTP_GIAIQUYETSOTHAM,' AND INSTR('VTTP_GIAIQUYETDON,VTTP_GIAIQUYETPHUCTHAM',gqan.MAVAITRO) = 0 THEN 1 
                             WHEN strVaiTro='VTTP_GIAIQUYETPHUCTHAM,' AND INSTR('VTTP_GIAIQUYETDON,VTTP_GIAIQUYETSOTHAM',gqan.MAVAITRO) = 0 THEN 1 ELSE 0 END
                  AND xetxu_ST.VUANID || ' '=' '
                  AND xetxu_PT.VUANID || ' '=' '
                  AND 1=CASE WHEN vTuNgay IS NULL THEN 1 WHEN vTuNgay <= gqan.NGAYPHANCONG THEN 1 ELSE 0 END 
                  AND 1=CASE WHEN vDenNgay IS NULL THEN 1 WHEN gqan.NGAYPHANCONG <= vDenNgay THEN 1 ELSE 0 END 
                )
                OR 
                (xetxu_ST.VUANID > 0 
                  AND INSTR(strVaiTro,xetxu_ST.MAVAITRO || ',') > 0
                  AND 1=CASE WHEN vTuNgay IS NULL THEN 1 WHEN vTuNgay <= xetxu_ST.NGAYPHANCONG THEN 1 ELSE 0 END 
                  AND 1=CASE WHEN vDenNgay IS NULL THEN 1 WHEN xetxu_ST.NGAYPHANCONG <= vDenNgay THEN 1 ELSE 0 END
                )
                OR 
                (xetxu_PT.VUANID > 0 
                  AND INSTR(strVaiTro,xetxu_PT.MAVAITRO || ',') > 0
                  AND 1=CASE WHEN vTuNgay IS NULL THEN 1 WHEN vTuNgay <= xetxu_PT.NGAYPHANCONG THEN 1 ELSE 0 END 
                  AND 1=CASE WHEN vDenNgay IS NULL THEN 1 WHEN xetxu_PT.NGAYPHANCONG <= vDenNgay THEN 1 ELSE 0 END
                )
            )
             AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(va.TENVUAN) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
