                    WHERE (kq.ISADS=1 AND INSTR('03,04,06,12,13,14,15,02,05,11,16,17',kq.MA)>0)
                    ) suahuyST ON suahuyST.DONID=don.ID
        LEFT JOIN (SELECT a.DONID,LISTAGG(a.TrangThai,',<br/>') WITHIN GROUP (ORDER BY a.DONID) AS TrangThai
                   FROM (
                         SELECT DISTINCT qd.DONID,DECODE(loai.MA,'DC','Vụ việc bị đình chỉ','TDC','Vụ việc tạm đình chỉ','ADBPTT','Vụ việc có áp dụng các biện pháp khẩn cấp tạm thời','') TrangThai 
                         FROM ADS_PHUCTHAM_QUYETDINH qd
                         INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
                         WHERE loai.ISDANSU=1 AND loai.HIEULUC=1 AND INSTR('TDC,DC,ADBPTT,',loai.MA || ',')>0
                         )a GROUP BY a.DONID
                  ) qdpt ON qdpt.DONID=don.ID
        WHERE (
