          DECODE(xetxu_PT.NGAYPHANCONG,NULL,DECODE(xetxu_ST.NGAYPHANCONG,NULL,DECODE(gqan.DONID,NULL,NULL,gqan.NGAYPHANCONG),xetxu_ST.NGAYPHANCONG),xetxu_PT.NGAYPHANCONG) AS NGAYPHANCONG,
          DECODE(qdst.DONID,NULL,NULL,DECODE(xetxu_ST.CANBOID,NULL,NULL,qdst.TrangThai || ',<br/>')) ||
          DECODE(suahuyST.DONID,NULL,NULL,DECODE(xetxu_ST.CANBOID,NULL,NULL,suahuyST.TrangThai)) ||
          DECODE(bast.DONID,NULL,NULL,DECODE(xetxu_ST.CANBOID,NULL,NULL,'Vụ việc quá hạn' || ',<br/>')) || 
