        LEFT JOIN AHC_PHUCTHAM_BANAN bapt ON bapt.DONID=don.ID AND bapt.TK_ISQUAHAN=1
        LEFT JOIN (SELECT b.DONID,b.NGAYPHANCONG,b.MAVAITRO FROM AHC_DON_THAMPHAN b
