                  ) gqan ON gqan.DONID=don.ID
        LEFT JOIN AKT_SOTHAM_HDXX xetxu_ST ON xetxu_ST.DONID=don.ID AND xetxu_ST.CANBOID=vThamPhanID
        LEFT JOIN AKT_PHUCTHAM_HDXX xetxu_PT ON xetxu_PT.DONID=don.ID AND xetxu_PT.CANBOID=vThamPhanID
        LEFT JOIN (SELECT a.DONID,LISTAGG(a.TrangThai,',<br/>') WITHIN GROUP (ORDER BY a.DONID) AS TrangThai
                   FROM (
                         SELECT DISTINCT qd.DONID,DECODE(loai.MA,'DC','Vụ việc bị đình chỉ','TDC','Vụ việc tạm đình chỉ','ADBPTT','Vụ việc có áp dụng các biện pháp khẩn cấp tạm thời','') TrangThai 
                         FROM AKT_SOTHAM_QUYETDINH qd
                         INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
                         WHERE loai.ISDANSU=1 AND loai.HIEULUC=1 AND INSTR('TDC,DC,ADBPTT,',loai.MA || ',')>0
                         )a GROUP BY a.DONID
                  ) qdst ON qdst.DONID=don.ID
        LEFT JOIN (SELECT ba.DONID,
                                 CASE WHEN INSTR('03,04,06,12,13,14,15',kq.MA)>0 THEN 'Vụ việc bị hủy' || ',<br/>' 
                                      WHEN INSTR('02,05,11,16,17',kq.MA)>0 THEN 'Vụ việc bị sửa' || ',<br/>' ELSE '' END AS TrangThai
                    FROM AKT_PHUCTHAM_BANAN ba
                    LEFT JOIN DM_KETQUA_PHUCTHAM kq ON kq.ID=ba.KETQUAPHUCTHAMID
                    WHERE (kq.ISADS=1 AND INSTR('03,04,06,12,13,14,15,02,05,11,16,17',kq.MA)>0)
                    ) suahuyST ON suahuyST.DONID=don.ID
        LEFT JOIN (SELECT a.DONID,LISTAGG(a.TrangThai,',<br/>') WITHIN GROUP (ORDER BY a.DONID) AS TrangThai
                   FROM (
                         SELECT DISTINCT qd.DONID,DECODE(loai.MA,'DC','Vụ việc bị đình chỉ','TDC','Vụ việc tạm đình chỉ','ADBPTT','Vụ việc có áp dụng các biện pháp khẩn cấp tạm thời','') TrangThai 
