          DECODE(xetxu_PT.NGAYPHANCONG,NULL,DECODE(xetxu_ST.NGAYPHANCONG,NULL,DECODE(gqan.DONID,NULL,NULL,gqan.NGAYPHANCONG),xetxu_ST.NGAYPHANCONG),xetxu_PT.NGAYPHANCONG) AS NGAYPHANCONG,
          DECODE(qdst.DONID,NULL,NULL,DECODE(xetxu_ST.CANBOID,NULL,NULL,qdst.TrangThai || ',<br/>')) ||
          DECODE(suahuyST.DONID,NULL,NULL,DECODE(xetxu_ST.CANBOID,NULL,NULL,suahuyST.TrangThai)) ||
          DECODE(bast.DONID,NULL,NULL,DECODE(xetxu_ST.CANBOID,NULL,NULL,'Vụ việc quá hạn' || ',<br/>')) || 
          DECODE(qdpt.DONID,NULL,NULL,DECODE(xetxu_PT.CANBOID,NULL,NULL,qdpt.TrangThai || ',<br/>')) ||
          DECODE(bapt.DONID,NULL,NULL,DECODE(xetxu_PT.CANBOID,NULL,NULL,'Vụ việc quá hạn' || ',<br/>')) AS TrangThai
        FROM ALD_DON don
        LEFT JOIN ALD_SOTHAM_BANAN bast ON bast.DONID=don.ID AND bast.TK_ISQUAHAN=1
        LEFT JOIN ALD_PHUCTHAM_BANAN bapt ON bapt.DONID=don.ID AND bapt.TK_ISQUAHAN=1
        LEFT JOIN (SELECT b.DONID,b.NGAYPHANCONG,b.MAVAITRO FROM ALD_DON_THAMPHAN b
                    WHERE b.CANBOID=vThamPhanID 
                          AND b.NGAYPHANCONG=(SELECT MAX(a.NGAYPHANCONG) 
                                              FROM ALD_DON_THAMPHAN a
                                              WHERE  a.CANBOID=vThamPhanID AND a.DONID=b.DONID
                                              GROUP BY a.DONID)
                  ) gqan ON gqan.DONID=don.ID
        LEFT JOIN ALD_SOTHAM_HDXX xetxu_ST ON xetxu_ST.DONID=don.ID AND xetxu_ST.CANBOID=vThamPhanID
        LEFT JOIN ALD_PHUCTHAM_HDXX xetxu_PT ON xetxu_PT.DONID=don.ID AND xetxu_PT.CANBOID=vThamPhanID
        LEFT JOIN (SELECT a.DONID,LISTAGG(a.TrangThai,',<br/>') WITHIN GROUP (ORDER BY a.DONID) AS TrangThai
                   FROM (
                         SELECT DISTINCT qd.DONID,DECODE(loai.MA,'DC','Vụ việc bị đình chỉ','TDC','Vụ việc tạm đình chỉ','ADBPTT','Vụ việc có áp dụng các biện pháp khẩn cấp tạm thời','') TrangThai 
                         FROM ALD_SOTHAM_QUYETDINH qd
                         INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
                         WHERE loai.ISDANSU=1 AND loai.HIEULUC=1 AND INSTR('TDC,DC,ADBPTT,',loai.MA || ',')>0
                         )a GROUP BY a.DONID
                  ) qdst ON qdst.DONID=don.ID
        LEFT JOIN (SELECT ba.DONID,
                                 CASE WHEN INSTR('03,04,06,12,13,14,15',kq.MA)>0 THEN 'Vụ việc bị hủy' || ',<br/>' 
                                      WHEN INSTR('02,05,11,16,17',kq.MA)>0 THEN 'Vụ việc bị sửa' || ',<br/>' ELSE '' END AS TrangThai
                    FROM ALD_PHUCTHAM_BANAN ba
                    LEFT JOIN DM_KETQUA_PHUCTHAM kq ON kq.ID=ba.KETQUAPHUCTHAMID
                    WHERE (kq.ISADS=1 AND INSTR('03,04,06,12,13,14,15,02,05,11,16,17',kq.MA)>0)
                    ) suahuyST ON suahuyST.DONID=don.ID
        LEFT JOIN (SELECT a.DONID,LISTAGG(a.TrangThai,',<br/>') WITHIN GROUP (ORDER BY a.DONID) AS TrangThai
                   FROM (
                         SELECT DISTINCT qd.DONID,DECODE(loai.MA,'DC','Vụ việc bị đình chỉ','TDC','Vụ việc tạm đình chỉ','ADBPTT','Vụ việc có áp dụng các biện pháp khẩn cấp tạm thời','') TrangThai 
                         FROM ALD_PHUCTHAM_QUYETDINH qd
                         INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
                         WHERE loai.ISDANSU=1 AND loai.HIEULUC=1 AND INSTR('TDC,DC,ADBPTT,',loai.MA || ',')>0
                         )a GROUP BY a.DONID
                  ) qdpt ON qdpt.DONID=don.ID
        WHERE (
				(gqan.DONID > 0 
          AND 1=CASE WHEN vGetAll=1 THEN 1
                     WHEN strVaiTro='VTTP_GIAIQUYETDON,' AND INSTR('VTTP_GIAIQUYETSOTHAM,VTTP_GIAIQUYETPHUCTHAM',gqan.MAVAITRO)=0 THEN 1 
                     WHEN strVaiTro='VTTP_GIAIQUYETSOTHAM,' AND INSTR('VTTP_GIAIQUYETDON,VTTP_GIAIQUYETPHUCTHAM',gqan.MAVAITRO) = 0 THEN 1 
                     WHEN strVaiTro='VTTP_GIAIQUYETPHUCTHAM,' AND INSTR('VTTP_GIAIQUYETDON,VTTP_GIAIQUYETSOTHAM',gqan.MAVAITRO) = 0 THEN 1 ELSE 0 END
          AND xetxu_ST.DONID || ' '=' '
          AND xetxu_PT.DONID || ' '=' '
					AND 1=CASE WHEN vTuNgay IS NULL THEN 1 WHEN vTuNgay <= gqan.NGAYPHANCONG THEN 1 ELSE 0 END 
					AND 1=CASE WHEN vDenNgay IS NULL THEN 1 WHEN gqan.NGAYPHANCONG <= vDenNgay THEN 1 ELSE 0 END 
