        LEFT JOIN XLHC_SOTHAM_HDXX xetxu_ST ON xetxu_ST.DONID=don.ID AND xetxu_ST.CANBOID=vThamPhanID
        LEFT JOIN XLHC_PHUCTHAM_HDXX xetxu_PT ON xetxu_PT.DONID=don.ID AND xetxu_PT.CANBOID=vThamPhanID
        LEFT JOIN (SELECT a.DONID,LISTAGG(a.TrangThai,',<br/>') WITHIN GROUP (ORDER BY a.DONID) AS TrangThai
