          AND 1=CASE WHEN vGetAll=1 THEN 1
                     WHEN strVaiTro='VTTP_GIAIQUYETDON,' AND INSTR('VTTP_GIAIQUYETSOTHAM,VTTP_GIAIQUYETPHUCTHAM',gqan.MAVAITRO)=0 THEN 1 
                     WHEN strVaiTro='VTTP_GIAIQUYETSOTHAM,' AND INSTR('VTTP_GIAIQUYETDON,VTTP_GIAIQUYETPHUCTHAM',gqan.MAVAITRO) = 0 THEN 1 
                     WHEN strVaiTro='VTTP_GIAIQUYETPHUCTHAM,' AND INSTR('VTTP_GIAIQUYETDON,VTTP_GIAIQUYETSOTHAM',gqan.MAVAITRO) = 0 THEN 1 ELSE 0 END
          AND xetxu_ST.DONID || ' '=' '
          AND xetxu_PT.DONID || ' '=' '
					AND 1=CASE WHEN vTuNgay IS NULL THEN 1 WHEN vTuNgay <= gqan.NGAYPHANCONG THEN 1 ELSE 0 END 
					AND 1=CASE WHEN vDenNgay IS NULL THEN 1 WHEN gqan.NGAYPHANCONG <= vDenNgay THEN 1 ELSE 0 END 
				)
				OR 
				(xetxu_ST.DONID > 0 
					AND INSTR(strVaiTro,xetxu_ST.MAVAITRO || ',') > 0
					AND 1=CASE WHEN vTuNgay IS NULL THEN 1 WHEN vTuNgay <= xetxu_ST.NGAYPHANCONG THEN 1 ELSE 0 END 
					AND 1=CASE WHEN vDenNgay IS NULL THEN 1 WHEN xetxu_ST.NGAYPHANCONG <= vDenNgay THEN 1 ELSE 0 END
				)
				OR 
				(xetxu_PT.DONID > 0 
					AND INSTR(strVaiTro,xetxu_PT.MAVAITRO || ',') > 0
					AND 1=CASE WHEN vTuNgay IS NULL THEN 1 WHEN vTuNgay <= xetxu_PT.NGAYPHANCONG THEN 1 ELSE 0 END 
					AND 1=CASE WHEN vDenNgay IS NULL THEN 1 WHEN xetxu_PT.NGAYPHANCONG <= vDenNgay THEN 1 ELSE 0 END
				)
			  )
			   AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(don.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	) re
	INNER JOIN DM_TOAAN ta ON re.TOAANID=ta.ID;
END DS_AN_OFTP_BY_VAITRO_PLUS;

PROCEDURE DS_AN_DAGIAIQUYET_BYTP 
(
	vThamPhanID IN number,
	vTenVuAn in varchar2,
	vSoQDBA in varchar2,
	vNgayQDBA in date,
	CurReturn OUT sys_refcursor
) AS
BEGIN
	OPEN CurReturn FOR
	SELECT re.VuAnID,re.MaVuAn,re.TenVuAn,ta.TEN AS TenToaAn,re.LinhVuc,re.MAGIAIDOAN,
					CASE re.MAGIAIDOAN WHEN 1 THEN 'Hồ sơ'
											WHEN 2 THEN 'Sơ thẩm'
											WHEN 3 THEN 'Phúc thẩm'
											WHEN 4 THEN 'Giám đốc thẩm, tái thẩm'
											ELSE '' END AS TenMaGiaiDoan,
					re.NGAYPHANCONG
	FROM (
	-- Dân sự
	SELECT a.ID AS VuAnID,a.MAVUVIEC AS MaVuAn,a.TENVUVIEC AS TenVuAn,a.TOAANID,'Dân sự' AS LinhVuc,
		a.MAGIAIDOAN,hdxx.NGAYPHANCONG
	FROM ADS_DON a
	INNER JOIN ADS_SOTHAM_HDXX hdxx ON a.ID=hdxx.DONID AND hdxx.CANBOID=vThamPhanID AND hdxx.MAVAITRO='THAMPHAN'
	LEFT JOIN (SELECT qd.DONID FROM ADS_SOTHAM_QUYETDINH qd
							INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
							WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(qd.SOQD) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
										 AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(qd.NGAYQD,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
										 AND loai.ISDANSU=1 AND loai.HIEULUC=1 AND INSTR('TDC,CNTT,CVA',loai.MA)>0
							) qdst ON qdst.DONID=a.ID
	LEFT JOIN (SELECT ba.DONID FROM ADS_SOTHAM_BANAN ba
				WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(ba.SOBANAN) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
						AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(ba.NGAYTUYENAN,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
				) bast ON bast.DONID=a.ID
	WHERE 1=CASE WHEN vTenVuAn || ' '=' ' THEN 1 WHEN LOWER(a.TENVUVIEC) LIKE '%' || vTenVuAn || '%' THEN 1 ELSE 0 END
			AND (qdst.DONID>0 OR bast.DONID>0)
	UNION
	SELECT a.ID AS VuAnID,a.MAVUVIEC AS MaVuAn,a.TENVUVIEC AS TenVuAn,a.TOAANID,'Dân sự' AS LinhVuc,
		a.MAGIAIDOAN,hdxx.NGAYPHANCONG
	FROM ADS_DON a
	INNER JOIN ADS_PHUCTHAM_HDXX hdxx ON a.ID=hdxx.DONID AND hdxx.CANBOID=vThamPhanID AND hdxx.MAVAITRO='THAMPHAN'
	LEFT JOIN (SELECT qd.DONID FROM ADS_PHUCTHAM_QUYETDINH qd
							INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
							WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(qd.SOQD) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
										 AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(qd.NGAYQD,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
										 AND loai.ISDANSU=1 AND loai.HIEULUC=1 AND INSTR('TDC,CNTT,CVA',loai.MA)>0
							) qdst ON qdst.DONID=a.ID
	LEFT JOIN (SELECT ba.DONID FROM ADS_PHUCTHAM_BANAN ba
				WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(ba.SOBANAN) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
						AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(ba.NGAYTUYENAN,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
				) bast ON bast.DONID=a.ID
	WHERE 1=CASE WHEN vTenVuAn || ' '=' ' THEN 1 WHEN LOWER(a.TENVUVIEC) LIKE '%' || vTenVuAn || '%' THEN 1 ELSE 0 END
			AND (qdst.DONID>0 OR bast.DONID>0)
	UNION
	-- Hành chính
	SELECT a.ID AS VuAnID,a.MAVUVIEC AS MaVuAn,a.TENVUVIEC AS TenVuAn,a.TOAANID,'Hành chính' AS LinhVuc,
		a.MAGIAIDOAN,hdxx.NGAYPHANCONG
	FROM AHC_DON a
	INNER JOIN AHC_SOTHAM_HDXX hdxx ON a.ID=hdxx.DONID AND hdxx.CANBOID=vThamPhanID AND hdxx.MAVAITRO='THAMPHAN'
	LEFT JOIN (SELECT qd.DONID FROM AHC_SOTHAM_QUYETDINH qd
							INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
							WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(qd.SOQD) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
										 AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(qd.NGAYQD,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
										 AND loai.ISHANHCHINH=1 AND loai.HIEULUC=1 AND INSTR('TDC,CNTT,CVA',loai.MA)>0
							) qdst ON qdst.DONID=a.ID
	LEFT JOIN (SELECT ba.DONID FROM AHC_SOTHAM_BANAN ba
				WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(ba.SOBANAN) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
						AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(ba.NGAYTUYENAN,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
				) bast ON bast.DONID=a.ID
	WHERE 1=CASE WHEN vTenVuAn || ' '=' ' THEN 1 WHEN LOWER(a.TENVUVIEC) LIKE '%' || vTenVuAn || '%' THEN 1 ELSE 0 END
			AND (qdst.DONID>0 OR bast.DONID>0)
	UNION
	SELECT a.ID AS VuAnID,a.MAVUVIEC AS MaVuAn,a.TENVUVIEC AS TenVuAn,a.TOAANID,'Hành chính' AS LinhVuc,
		a.MAGIAIDOAN,hdxx.NGAYPHANCONG
	FROM AHC_DON a
	INNER JOIN AHC_PHUCTHAM_HDXX hdxx ON a.ID=hdxx.DONID AND hdxx.CANBOID=vThamPhanID AND hdxx.MAVAITRO='THAMPHAN'
	LEFT JOIN (SELECT qd.DONID FROM AHC_PHUCTHAM_QUYETDINH qd
							INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
							WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(qd.SOQD) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
										 AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(qd.NGAYQD,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
										 AND loai.ISHANHCHINH=1 AND loai.HIEULUC=1 AND INSTR('TDC,CNTT,CVA',loai.MA)>0
							) qdst ON qdst.DONID=a.ID
	LEFT JOIN (SELECT ba.DONID FROM AHC_PHUCTHAM_BANAN ba
				WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(ba.SOBANAN) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
						AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(ba.NGAYTUYENAN,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
				) bast ON bast.DONID=a.ID
	WHERE 1=CASE WHEN vTenVuAn || ' '=' ' THEN 1 WHEN LOWER(a.TENVUVIEC) LIKE '%' || vTenVuAn || '%' THEN 1 ELSE 0 END
