	SELECT a.ID AS VuAnID,a.MAVUVIEC AS MaVuAn,a.TENVUVIEC AS TenVuAn,a.TOAANID,'HN & GĐ' AS LinhVuc,
		a.MAGIAIDOAN,hdxx.NGAYPHANCONG
	FROM AHN_DON a
	INNER JOIN AHN_SOTHAM_HDXX hdxx ON a.ID=hdxx.DONID AND hdxx.CANBOID=vThamPhanID AND hdxx.MAVAITRO='THAMPHAN'
	LEFT JOIN (SELECT qd.DONID FROM AHN_SOTHAM_QUYETDINH qd
							INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
							WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(qd.SOQD) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
										 AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(qd.NGAYQD,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
										 AND loai.ISHNGD=1 AND loai.HIEULUC=1 AND INSTR('TDC,CNTT,CVA',loai.MA)>0
							) qdst ON qdst.DONID=a.ID
	LEFT JOIN (SELECT ba.DONID FROM AHN_SOTHAM_BANAN ba
				WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(ba.SOBANAN) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
						AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(ba.NGAYTUYENAN,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
				) bast ON bast.DONID=a.ID
	WHERE 1=CASE WHEN vTenVuAn || ' '=' ' THEN 1 WHEN LOWER(a.TENVUVIEC) LIKE '%' || vTenVuAn || '%' THEN 1 ELSE 0 END
			AND (qdst.DONID>0 OR bast.DONID>0)
