	SELECT a.ID AS VuAnID,a.MAVUVIEC AS MaVuAn,a.TENVUVIEC AS TenVuAn,a.TOAANID,'HN & GĐ' AS LinhVuc,
		a.MAGIAIDOAN,hdxx.NGAYPHANCONG
