	INNER JOIN AHN_PHUCTHAM_HDXX hdxx ON a.ID=hdxx.DONID AND hdxx.CANBOID=vThamPhanID AND hdxx.MAVAITRO='THAMPHAN'
	LEFT JOIN (SELECT qd.DONID FROM AHN_PHUCTHAM_QUYETDINH qd
