	FROM ALD_DON a
	INNER JOIN ALD_PHUCTHAM_HDXX hdxx ON a.ID=hdxx.DONID AND hdxx.CANBOID=vThamPhanID AND hdxx.MAVAITRO='THAMPHAN'
	LEFT JOIN (SELECT qd.DONID FROM ALD_PHUCTHAM_QUYETDINH qd
