							WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(qd.SOQD) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
										 AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(qd.NGAYQD,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
										 AND loai.ISLAODONG=1 AND loai.HIEULUC=1 AND INSTR('TDC,CNTT,CVA',loai.MA)>0
							) qdst ON qdst.DONID=a.ID
	LEFT JOIN (SELECT ba.DONID FROM ALD_PHUCTHAM_BANAN ba
				WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(ba.SOBANAN) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
						AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(ba.NGAYTUYENAN,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
