	INNER JOIN APS_SOTHAM_HDXX hdxx ON a.ID=hdxx.DONID AND hdxx.CANBOID=vThamPhanID AND hdxx.MAVAITRO='THAMPHAN'
	LEFT JOIN (SELECT qd.DONID FROM APS_SOTHAM_QUYETDINH qd
