				) bast ON bast.DONID=a.ID
	WHERE 1=CASE WHEN vTenVuAn || ' '=' ' THEN 1 WHEN LOWER(a.TENVUVIEC) LIKE '%' || vTenVuAn || '%' THEN 1 ELSE 0 END
