		a.MAGIAIDOAN,hdxx.NGAYPHANCONG
	FROM APS_DON a
	INNER JOIN APS_PHUCTHAM_HDXX hdxx ON a.ID=hdxx.DONID AND hdxx.CANBOID=vThamPhanID AND hdxx.MAVAITRO='THAMPHAN'
	LEFT JOIN (SELECT qd.DONID FROM APS_PHUCTHAM_QUYETDINH qd
							INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
							WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(qd.SOQD) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
										 AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(qd.NGAYQD,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
										 AND loai.ISPHASAN=1 AND loai.HIEULUC=1 AND INSTR('TDC,CNTT,CVA',loai.MA)>0
							) qdst ON qdst.DONID=a.ID
	LEFT JOIN (SELECT ba.DONID FROM APS_PHUCTHAM_BANAN ba
				WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(ba.SOBANAN) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
						AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(ba.NGAYTUYENAN,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
				) bast ON bast.DONID=a.ID
	WHERE 1=CASE WHEN vTenVuAn || ' '=' ' THEN 1 WHEN LOWER(a.TENVUVIEC) LIKE '%' || vTenVuAn || '%' THEN 1 ELSE 0 END
			AND (qdst.DONID>0 OR bast.DONID>0)
	UNION
	-- Biện pháp xử lý hành chính
	SELECT a.ID AS VuAnID,a.MAVUVIEC AS MaVuAn,a.TENVUVIEC AS TenVuAn,a.TOAANID,'BP XLHC' AS LinhVuc,
		a.MAGIAIDOAN,hdxx.NGAYPHANCONG
	FROM XLHC_DON a
	INNER JOIN XLHC_SOTHAM_HDXX hdxx ON a.ID=hdxx.DONID AND hdxx.CANBOID=vThamPhanID AND hdxx.MAVAITRO='THAMPHAN'
	LEFT JOIN (SELECT qd.DONID FROM XLHC_SOTHAM_QUYETDINH qd
							INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
							WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(qd.SOQD) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
										 AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(qd.NGAYQD,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
										 AND loai.ISXLHC=1 AND loai.HIEULUC=1 AND INSTR('TDC,CNTT,CVA',loai.MA)>0
							) qdst ON qdst.DONID=a.ID
	LEFT JOIN (SELECT ba.DONID FROM XLHC_SOTHAM_BANAN ba
				WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(ba.SOBANAN) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
						AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(ba.NGAYTUYENAN,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
				) bast ON bast.DONID=a.ID
	WHERE 1=CASE WHEN vTenVuAn || ' '=' ' THEN 1 WHEN LOWER(a.TENVUVIEC) LIKE '%' || vTenVuAn || '%' THEN 1 ELSE 0 END
			AND (qdst.DONID>0 OR bast.DONID>0)
	UNION
	SELECT a.ID AS VuAnID,a.MAVUVIEC AS MaVuAn,a.TENVUVIEC AS TenVuAn,a.TOAANID,'BP XLHC' AS LinhVuc,
		a.MAGIAIDOAN,hdxx.NGAYPHANCONG
	FROM XLHC_DON a
	INNER JOIN XLHC_PHUCTHAM_HDXX hdxx ON a.ID=hdxx.DONID AND hdxx.CANBOID=vThamPhanID AND hdxx.MAVAITRO='THAMPHAN'
	LEFT JOIN (SELECT qd.DONID FROM XLHC_PHUCTHAM_QUYETDINH qd
							INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
							WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(qd.SOQD) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
										 AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(qd.NGAYQD,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
										 AND loai.ISXLHC=1 AND loai.HIEULUC=1 AND INSTR('TDC,CNTT,CVA',loai.MA)>0
							) qdst ON qdst.DONID=a.ID
	LEFT JOIN (SELECT ba.DONID FROM XLHC_PHUCTHAM_BANAN ba
				WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(ba.SOBANAN) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
						AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(ba.NGAYTUYENAN,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
				) bast ON bast.DONID=a.ID
	WHERE 1=CASE WHEN vTenVuAn || ' '=' ' THEN 1 WHEN LOWER(a.TENVUVIEC) LIKE '%' || vTenVuAn || '%' THEN 1 ELSE 0 END
			AND (qdst.DONID>0 OR bast.DONID>0)
	UNION
	-- Hình sự
	SELECT a.ID AS VuAnID,a.MAVUAN AS MaVuAn,a.TENVUAN AS TenVuAn,a.TOAANID,'Hình sự' AS LinhVuc,
		a.MAGIAIDOAN,hdxx.NGAYPHANCONG
	FROM AHS_VUAN a
	INNER JOIN AHS_SOTHAM_HDXX hdxx ON a.ID=hdxx.VUANID AND hdxx.CANBOID=vThamPhanID AND hdxx.MAVAITRO='THAMPHAN'
	LEFT JOIN (SELECT qd.VUANID FROM AHS_SOTHAM_QUYETDINH_VUAN qd
							INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
							WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(qd.SOQUYETDINH) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
										 AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(qd.NGAYQD,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
										 AND loai.ISHINHSU=1 AND loai.HIEULUC=1 AND INSTR('TDC,CNTT,CVA',loai.MA)>0
							) qdst ON qdst.VUANID=a.ID
	LEFT JOIN (SELECT ba.VUANID FROM AHS_SOTHAM_BANAN ba
				WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(ba.SOBANAN) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
						AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(ba.NGAYBANAN,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
				) bast ON bast.VUANID=a.ID
	WHERE 1=CASE WHEN vTenVuAn || ' '=' ' THEN 1 WHEN LOWER(a.TENVUAN) LIKE '%' || vTenVuAn || '%' THEN 1 ELSE 0 END
			AND (qdst.VUANID>0 OR bast.VUANID>0)
	UNION
	SELECT a.ID AS VuAnID,a.MAVUAN AS MaVuAn,a.TENVUAN AS TenVuAn,a.TOAANID,'Hình sự' AS LinhVuc,
		a.MAGIAIDOAN,hdxx.NGAYPHANCONG
	FROM AHS_VUAN a
	INNER JOIN AHS_PHUCTHAM_HDXX hdxx ON a.ID=hdxx.VUANID AND hdxx.CANBOID=vThamPhanID AND hdxx.MAVAITRO='THAMPHAN'
	LEFT JOIN (SELECT qd.VUANID FROM AHS_PHUCTHAM_QUYETDINH_VUAN qd
							INNER JOIN DM_QD_LOAI loai ON loai.ID=qd.LOAIQDID
							WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(qd.SOQUYETDINH) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
										 AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(qd.NGAYQD,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
										 AND loai.ISHINHSU=1 AND loai.HIEULUC=1 AND INSTR('TDC,CNTT,CVA',loai.MA)>0
							) qdst ON qdst.VUANID=a.ID
	LEFT JOIN (SELECT ba.VUANID FROM AHS_PHUCTHAM_BANAN ba
				WHERE 1=CASE WHEN vSoQDBA || ' '=' ' THEN 1 WHEN LOWER(ba.SOBANAN) LIKE '%' || vSoQDBA || '%' THEN 1 ELSE 0 END
						AND 1=CASE WHEN vNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(ba.NGAYBANAN,'dd/MM/yyyy')=TO_CHAR(vNgayQDBA,'dd/MM/yyyy') THEN 1 ELSE 0 END
				) bast ON bast.VUANID=a.ID
	WHERE 1=CASE WHEN vTenVuAn || ' '=' ' THEN 1 WHEN LOWER(a.TENVUAN) LIKE '%' || vTenVuAn || '%' THEN 1 ELSE 0 END
			AND (qdst.VUANID>0 OR bast.VUANID>0)
  
	)re
	INNER JOIN DM_TOAAN ta ON re.TOAANID=ta.ID;
END DS_AN_DAGIAIQUYET_BYTP;

PROCEDURE DS_AN_KHANGCAO_KHANGNGHI_BYTP
(
  vThamPhanID IN NUMBER,
  vTenVuAn IN VARCHAR2,
  vSoQDBA IN VARCHAR2,
  vNgayQDBA IN DATE,
  CurReturn OUT sys_refcursor
)AS
  strTenVuAn VARCHAR2(250);
  strSoQDBA VARCHAR2(250);
  strNgayQDBA VARCHAR2(15);
BEGIN
  strTenVuAn:=LOWER(vTenVuAn);
  strSoQDBA:=LOWER(vSoQDBA);
  strNgayQDBA:=TO_CHAR(vNgayQDBA,'dd/MM/yyyy');
  -- Sau này còn phát triển khi hệ thống thêm kháng cáo, kháng nghị ở phúc thẩm
  OPEN CurReturn FOR
  SELECT re.VuAnID,re.MAVUAN,re.TENVUAN,ta.TEN as TENTOAAN,re.LinhVuc,re.MAGIAIDOAN,re.LOAIAN,
    CASE re.MAGIAIDOAN WHEN 2 THEN 'Sơ thẩm'
											 WHEN 3 THEN 'Phúc thẩm'
											 ELSE '' END AS TenMaGiaiDoan
  FROM (
  SELECT T1.ID AS VuAnID,T1.MAVUAN,T1.TENVUAN,
    DECODE(T2.VUANID,NULL,T1.TOAPHUCTHAMID,T1.TOAANID) AS TOAANID,
    'Hình sự' AS LinhVuc,T2.MAGIAIDOAN,'AHS' AS LOAIAN
  FROM AHS_VUAN T1
  LEFT JOIN (SELECT DISTINCT T5.VUANID,2 MAGIAIDOAN FROM AHS_SOTHAM_HDXX T5
              LEFT JOIN AHS_SOTHAM_KHANGCAO T3 ON T3.VUANID=T5.VUANID
              LEFT JOIN AHS_SOTHAM_KHANGNGHI T4 ON T4.VUANID=T5.VUANID
              WHERE (
                      ( T3.VUANID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T3.LOAIKHANGCAO=0 AND (SELECT COUNT(ID) FROM AHS_SOTHAM_BANAN WHERE ID=T3.SOQDBA AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T3.LOAIKHANGCAO=1 AND (SELECT COUNT(ID) FROM AHS_SOTHAM_QUYETDINH_VUAN WHERE ID=T3.SOQDBA AND LOWER(SOQUYETDINH) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQDBA,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                      OR 
                      ( T4.VUANID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T4.LOAIKN=0 AND (SELECT COUNT(ID) FROM AHS_SOTHAM_BANAN WHERE ID=T4.BANANID AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T4.LOAIKN=1 AND (SELECT COUNT(ID) FROM AHS_SOTHAM_QUYETDINH_VUAN WHERE ID=T4.BANANID AND LOWER(SOQUYETDINH) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T4.NGAYBANAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                    )
                    AND T5.CANBOID=vThamPhanID AND T5.MAVAITRO='THAMPHAN'
              )T2 ON T2.VUANID=T1.ID
  WHERE 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUAN) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
        AND T2.VUANID>0
  UNION
  SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MAVUAN,T1.TENVUVIEC AS TENVUAN,
    DECODE(T2.DONID,NULL,T1.TOAPHUCTHAMID,T1.TOAANID) AS TOAANID,
    'Dân sự' AS LinhVuc,T2.MAGIAIDOAN,'ADS' AS LOAIAN
  FROM ADS_DON T1
  LEFT JOIN (SELECT DISTINCT T5.DONID,2 MAGIAIDOAN FROM ADS_SOTHAM_HDXX T5
              LEFT JOIN ADS_SOTHAM_KHANGCAO T3 ON T3.DONID=T5.DONID
              LEFT JOIN ADS_SOTHAM_KHANGNGHI T4 ON T4.DONID=T5.DONID
              WHERE (
                      ( T3.DONID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T3.LOAIKHANGCAO=0 AND (SELECT COUNT(ID) FROM ADS_SOTHAM_BANAN WHERE ID=T3.SOQDBA AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T3.LOAIKHANGCAO=1 AND (SELECT COUNT(ID) FROM ADS_SOTHAM_QUYETDINH WHERE ID=T3.SOQDBA AND LOWER(SOQD) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQDBA,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                      OR 
                      ( T4.DONID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T4.LOAIKN=0 AND (SELECT COUNT(ID) FROM ADS_SOTHAM_BANAN WHERE ID=T4.BANANID AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T4.LOAIKN=1 AND (SELECT COUNT(ID) FROM ADS_SOTHAM_QUYETDINH WHERE ID=T4.BANANID AND LOWER(SOQD) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T4.NGAYBANAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                    )
                    AND T5.CANBOID=vThamPhanID AND T5.MAVAITRO='THAMPHAN'
              )T2 ON T2.DONID=T1.ID
  WHERE 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
        AND T2.DONID>0
  UNION
  SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MAVUAN,T1.TENVUVIEC AS TENVUAN,
    DECODE(T2.DONID,NULL,T1.TOAPHUCTHAMID,T1.TOAANID) AS TOAANID,
    'Hành chính' AS LinhVuc,T2.MAGIAIDOAN,'AHC' AS LOAIAN
  FROM AHC_DON T1
  LEFT JOIN (SELECT DISTINCT T5.DONID,2 MAGIAIDOAN FROM AHC_SOTHAM_HDXX T5
              LEFT JOIN AHC_SOTHAM_KHANGCAO T3 ON T3.DONID=T5.DONID
              LEFT JOIN AHC_SOTHAM_KHANGNGHI T4 ON T4.DONID=T5.DONID
              WHERE (
                      ( T3.DONID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T3.LOAIKHANGCAO=0 AND (SELECT COUNT(ID) FROM AHC_SOTHAM_BANAN WHERE ID=T3.SOQDBA AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T3.LOAIKHANGCAO=1 AND (SELECT COUNT(ID) FROM AHC_SOTHAM_QUYETDINH WHERE ID=T3.SOQDBA AND LOWER(SOQD) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQDBA,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                      OR 
                      ( T4.DONID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T4.LOAIKN=0 AND (SELECT COUNT(ID) FROM AHC_SOTHAM_BANAN WHERE ID=T4.BANANID AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T4.LOAIKN=1 AND (SELECT COUNT(ID) FROM AHC_SOTHAM_QUYETDINH WHERE ID=T4.BANANID AND LOWER(SOQD) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T4.NGAYBANAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                    )
                    AND T5.CANBOID=vThamPhanID AND T5.MAVAITRO='THAMPHAN'
              )T2 ON T2.DONID=T1.ID
  WHERE 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
        AND T2.DONID>0
  UNION
  SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MAVUAN,T1.TENVUVIEC AS TENVUAN,
    DECODE(T2.DONID,NULL,T1.TOAPHUCTHAMID,T1.TOAANID) AS TOAANID,
    'HN & GĐ' AS LinhVuc,T2.MAGIAIDOAN,'AHN' AS LOAIAN
  FROM AHN_DON T1
  LEFT JOIN (SELECT DISTINCT T5.DONID,2 MAGIAIDOAN FROM AHN_SOTHAM_HDXX T5
              LEFT JOIN AHN_SOTHAM_KHANGCAO T3 ON T3.DONID=T5.DONID
              LEFT JOIN AHN_SOTHAM_KHANGNGHI T4 ON T4.DONID=T5.DONID
              WHERE (
                      ( T3.DONID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T3.LOAIKHANGCAO=0 AND (SELECT COUNT(ID) FROM AHN_SOTHAM_BANAN WHERE ID=T3.SOQDBA AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T3.LOAIKHANGCAO=1 AND (SELECT COUNT(ID) FROM AHN_SOTHAM_QUYETDINH WHERE ID=T3.SOQDBA AND LOWER(SOQD) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQDBA,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                      OR 
                      ( T4.DONID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T4.LOAIKN=0 AND (SELECT COUNT(ID) FROM AHN_SOTHAM_BANAN WHERE ID=T4.BANANID AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T4.LOAIKN=1 AND (SELECT COUNT(ID) FROM AHN_SOTHAM_QUYETDINH WHERE ID=T4.BANANID AND LOWER(SOQD) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T4.NGAYBANAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                    )
                    AND T5.CANBOID=vThamPhanID AND T5.MAVAITRO='THAMPHAN'
              )T2 ON T2.DONID=T1.ID
  WHERE 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
        AND T2.DONID>0
  UNION
  SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MAVUAN,T1.TENVUVIEC AS TENVUAN,
    DECODE(T2.DONID,NULL,T1.TOAPHUCTHAMID,T1.TOAANID) AS TOAANID,
    'KD, TM' AS LinhVuc,T2.MAGIAIDOAN,'AKT' AS LOAIAN
  FROM AKT_DON T1
  LEFT JOIN (SELECT DISTINCT T5.DONID,2 MAGIAIDOAN FROM AKT_SOTHAM_HDXX T5
              LEFT JOIN AKT_SOTHAM_KHANGCAO T3 ON T3.DONID=T5.DONID
              LEFT JOIN AKT_SOTHAM_KHANGNGHI T4 ON T4.DONID=T5.DONID
              WHERE (
                      ( T3.DONID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T3.LOAIKHANGCAO=0 AND (SELECT COUNT(ID) FROM AKT_SOTHAM_BANAN WHERE ID=T3.SOQDBA AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T3.LOAIKHANGCAO=1 AND (SELECT COUNT(ID) FROM AKT_SOTHAM_QUYETDINH WHERE ID=T3.SOQDBA AND LOWER(SOQD) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQDBA,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                      OR 
                      ( T4.DONID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T4.LOAIKN=0 AND (SELECT COUNT(ID) FROM AKT_SOTHAM_BANAN WHERE ID=T4.BANANID AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T4.LOAIKN=1 AND (SELECT COUNT(ID) FROM AKT_SOTHAM_QUYETDINH WHERE ID=T4.BANANID AND LOWER(SOQD) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T4.NGAYBANAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                    )
                    AND T5.CANBOID=vThamPhanID AND T5.MAVAITRO='THAMPHAN'
              )T2 ON T2.DONID=T1.ID
  WHERE 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
        AND T2.DONID>0
  UNION
  SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MAVUAN,T1.TENVUVIEC AS TENVUAN,
    DECODE(T2.DONID,NULL,T1.TOAPHUCTHAMID,T1.TOAANID) AS TOAANID,
    'Lao động' AS LinhVuc,T2.MAGIAIDOAN,'ALD' AS LOAIAN
  FROM ALD_DON T1
  LEFT JOIN (SELECT DISTINCT T5.DONID,2 MAGIAIDOAN FROM ALD_SOTHAM_HDXX T5
              LEFT JOIN ALD_SOTHAM_KHANGCAO T3 ON T3.DONID=T5.DONID
              LEFT JOIN ALD_SOTHAM_KHANGNGHI T4 ON T4.DONID=T5.DONID
              WHERE (
                      ( T3.DONID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T3.LOAIKHANGCAO=0 AND (SELECT COUNT(ID) FROM ALD_SOTHAM_BANAN WHERE ID=T3.SOQDBA AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T3.LOAIKHANGCAO=1 AND (SELECT COUNT(ID) FROM ALD_SOTHAM_QUYETDINH WHERE ID=T3.SOQDBA AND LOWER(SOQD) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQDBA,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                      OR 
                      ( T4.DONID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T4.LOAIKN=0 AND (SELECT COUNT(ID) FROM ALD_SOTHAM_BANAN WHERE ID=T4.BANANID AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T4.LOAIKN=1 AND (SELECT COUNT(ID) FROM ALD_SOTHAM_QUYETDINH WHERE ID=T4.BANANID AND LOWER(SOQD) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T4.NGAYBANAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                    )
                    AND T5.CANBOID=vThamPhanID AND T5.MAVAITRO='THAMPHAN'
              )T2 ON T2.DONID=T1.ID
  WHERE 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
        AND T2.DONID>0
  UNION
  SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MAVUAN,T1.TENVUVIEC AS TENVUAN,
    DECODE(T2.DONID,NULL,T1.TOAPHUCTHAMID,T1.TOAANID) AS TOAANID,
    'Phá sản' AS LinhVuc,T2.MAGIAIDOAN,'APS' AS LOAIAN
  FROM APS_DON T1
  LEFT JOIN (SELECT DISTINCT T5.DONID,2 MAGIAIDOAN FROM APS_SOTHAM_HDXX T5
              LEFT JOIN APS_SOTHAM_KHANGCAO T3 ON T3.DONID=T5.DONID
              LEFT JOIN APS_SOTHAM_KHANGNGHI T4 ON T4.DONID=T5.DONID
              WHERE (
                      ( T3.DONID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T3.LOAIKHANGCAO=0 AND (SELECT COUNT(ID) FROM APS_SOTHAM_BANAN WHERE ID=T3.SOQDBA AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T3.LOAIKHANGCAO=1 AND (SELECT COUNT(ID) FROM APS_SOTHAM_QUYETDINH WHERE ID=T3.SOQDBA AND LOWER(SOQD) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQDBA,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                      OR 
                      ( T4.DONID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T4.LOAIKN=0 AND (SELECT COUNT(ID) FROM APS_SOTHAM_BANAN WHERE ID=T4.BANANID AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T4.LOAIKN=1 AND (SELECT COUNT(ID) FROM APS_SOTHAM_QUYETDINH WHERE ID=T4.BANANID AND LOWER(SOQD) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T4.NGAYBANAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                    )
                    AND T5.CANBOID=vThamPhanID AND T5.MAVAITRO='THAMPHAN'
              )T2 ON T2.DONID=T1.ID
  WHERE 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
        AND T2.DONID>0
  UNION
  SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MAVUAN,T1.TENVUVIEC AS TENVUAN,
    DECODE(T2.DONID,NULL,T1.TOAPHUCTHAMID,T1.TOAANID) AS TOAANID,
    'BP XLHC' AS LinhVuc,T2.MAGIAIDOAN,'XLHC' AS LOAIAN
  FROM XLHC_DON T1
  LEFT JOIN (SELECT DISTINCT T5.DONID,2 MAGIAIDOAN FROM XLHC_SOTHAM_HDXX T5
              LEFT JOIN XLHC_SOTHAM_KHANGCAO T3 ON T3.DONID=T5.DONID
              LEFT JOIN XLHC_SOTHAM_KHANGNGHI T4 ON T4.DONID=T5.DONID
              WHERE (
                      ( T3.DONID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T3.LOAIKHANGCAO=0 AND (SELECT COUNT(ID) FROM XLHC_SOTHAM_BANAN WHERE ID=T3.SOQDBA AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T3.LOAIKHANGCAO=1 AND (SELECT COUNT(ID) FROM XLHC_SOTHAM_QUYETDINH WHERE ID=T3.SOQDBA AND LOWER(SOQD) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQDBA,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                      OR 
                      ( T4.DONID>0
                        AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 
                                   WHEN T4.LOAIKN=0 AND (SELECT COUNT(ID) FROM XLHC_SOTHAM_BANAN WHERE ID=T4.BANANID AND LOWER(SOBANAN) LIKE '%' || strSoQDBA || '%')>0 THEN 1
                                   WHEN T4.LOAIKN=1 AND (SELECT COUNT(ID) FROM XLHC_SOTHAM_QUYETDINH WHERE ID=T4.BANANID AND LOWER(SOQD) LIKE '%' || strSoQDBA || '%')>0 THEN 1 ELSE 0 END
                        AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T4.NGAYBANAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
                      )
                    )
                    AND T5.CANBOID=vThamPhanID AND T5.MAVAITRO='THAMPHAN'
              )T2 ON T2.DONID=T1.ID
  WHERE 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
        AND T2.DONID>0
  ) re
  INNER JOIN DM_TOAAN ta ON ta.ID=re.TOAANID
  ORDER BY ta.ARRTHUTU,re.LinhVuc,re.MAGIAIDOAN;
END DS_AN_KHANGCAO_KHANGNGHI_BYTP;

PROCEDURE DS_AN_APDUNGANLE_BYTP 
(
	vThamPhanID IN NUMBER, 
	vTenVuAn IN VARCHAR2,
	vSoQDBA IN VARCHAR2,
	vNgayQDBA IN DATE,
	CurReturn OUT sys_refcursor
)
AS
	strTenVuAn VARCHAR2(250);
  strSoQDBA VARCHAR2(250);
  strNgayQDBA VARCHAR2(15);
BEGIN
  strTenVuAn:=LOWER(vTenVuAn);
  strSoQDBA:=LOWER(vSoQDBA);
  strNgayQDBA:=TO_CHAR(vNgayQDBA,'dd/MM/yyyy');
	OPEN CurReturn FOR
	SELECT re.VuAnID,re.MaVuAn,re.TenVuAn,ta.TEN TenToaAn,re.LinhVuc,re.LOAIAN,re.TenMaGiaiDoan
	FROM
	(
	-- án dân sự
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,'Dân sự' LinhVuc,2 MAGIAIDOAN,T1.TOAANID,'Sơ thẩm' TenMaGiaiDoan,'ADS' LOAIAN
	FROM ADS_DON T1
	INNER JOIN ADS_SOTHAM_BANAN T2 ON T2.DONID=T1.ID
	INNER JOIN ADS_SOTHAM_HDXX T3 ON T3.DONID=T1.ID
	WHERE T2.APDUNGANLE=1 AND T3.CANBOID=vThamPhanID AND T3.MAVAITRO='THAMPHAN'
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T2.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,'Dân sự' LinhVuc,3 MAGIAIDOAN,T1.TOAPHUCTHAMID TOAANID,'Phúc thẩm' TenMaGiaiDoan,'ADS' LOAIAN
	FROM ADS_DON T1
	INNER JOIN ADS_PHUCTHAM_BANAN T2 ON T2.DONID=T1.ID
	INNER JOIN ADS_PHUCTHAM_HDXX T3 ON T3.DONID=T1.ID
	WHERE T2.APDUNGANLE=1 AND T3.CANBOID=vThamPhanID AND T3.MAVAITRO='THAMPHAN'
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T2.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
	UNION
	-- án hành chính
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,'Hành chính' LinhVuc,2 MAGIAIDOAN,T1.TOAANID,'Sơ thẩm' TenMaGiaiDoan,'AHC' LOAIAN
	FROM AHC_DON T1
	INNER JOIN AHC_SOTHAM_BANAN T2 ON T2.DONID=T1.ID
	INNER JOIN AHC_SOTHAM_HDXX T3 ON T3.DONID=T1.ID
	WHERE T2.TK_ISANLE=1 AND T3.CANBOID=vThamPhanID AND T3.MAVAITRO='THAMPHAN'
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T2.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,'Hành chính' LinhVuc,3 MAGIAIDOAN,T1.TOAPHUCTHAMID TOAANID,'Phúc thẩm' TenMaGiaiDoan,'AHC' LOAIAN
	FROM AHC_DON T1
	INNER JOIN AHC_PHUCTHAM_BANAN T2 ON T2.DONID=T1.ID
	INNER JOIN AHC_PHUCTHAM_HDXX T3 ON T3.DONID=T1.ID
	WHERE T2.APDUNGANLE=1 AND T3.CANBOID=vThamPhanID AND T3.MAVAITRO='THAMPHAN'
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T2.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
	UNION
	-- án Hôn nhân
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,'HN & GĐ' LinhVuc,2 MAGIAIDOAN,T1.TOAANID,'Sơ thẩm' TenMaGiaiDoan,'AHN' LOAIAN
	FROM AHN_DON T1
	INNER JOIN AHN_SOTHAM_BANAN T2 ON T2.DONID=T1.ID
	INNER JOIN AHN_SOTHAM_HDXX T3 ON T3.DONID=T1.ID
	WHERE T2.TK_APDUNGANLE=1 AND T3.CANBOID=vThamPhanID AND T3.MAVAITRO='THAMPHAN'
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T2.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,'HN & GĐ' LinhVuc,3 MAGIAIDOAN,T1.TOAPHUCTHAMID TOAANID,'Phúc thẩm' TenMaGiaiDoan,'AHN' LOAIAN
	FROM AHN_DON T1
	INNER JOIN AHN_PHUCTHAM_BANAN T2 ON T2.DONID=T1.ID
	INNER JOIN AHN_PHUCTHAM_HDXX T3 ON T3.DONID=T1.ID
	WHERE T2.APDUNGANLE=1 AND T3.CANBOID=vThamPhanID AND T3.MAVAITRO='THAMPHAN'
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T2.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
	UNION
	-- án Hình sự
	SELECT T1.ID AS VuAnID,T1.MAVUAN AS MaVuAn,T1.TENVUAN AS TenVuAn,'Hình sự' AS LinhVuc,2 MAGIAIDOAN,T1.TOAANID,'Sơ thẩm' TenMaGiaiDoan,'AHS' LOAIAN
	FROM AHS_VUAN T1
	INNER JOIN AHS_SOTHAM_BANAN T2 ON T2.VUANID=T1.ID
	INNER JOIN AHS_SOTHAM_HDXX T3 ON T3.VUANID=T1.ID
	WHERE T2.ISANLE=1 AND T3.CANBOID=vThamPhanID AND T3.MAVAITRO='THAMPHAN'
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUAN) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T2.NGAYBANAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID AS VuAnID,T1.MAVUAN AS MaVuAn,T1.TENVUAN AS TenVuAn,'Hình sự' AS LinhVuc,3 MAGIAIDOAN,T1.TOAANID,'Phúc thẩm' TenMaGiaiDoan,'AHS' LOAIAN
	FROM AHS_VUAN T1
	INNER JOIN AHS_PHUCTHAM_BANAN T2 ON T2.VUANID=T1.ID
	INNER JOIN AHS_PHUCTHAM_HDXX T3 ON T3.VUANID=T1.ID
	WHERE T2.ISANLE=1 AND T3.CANBOID=vThamPhanID AND T3.MAVAITRO='THAMPHAN'
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUAN) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T2.NGAYBANAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
	UNION
	-- án Kinh tế
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,'KD, TM' LinhVuc,2 MAGIAIDOAN,T1.TOAANID,'Sơ thẩm' TenMaGiaiDoan,'AKT' LOAIAN
	FROM AKT_DON T1
	INNER JOIN AKT_SOTHAM_BANAN T2 ON T2.DONID=T1.ID
	INNER JOIN AKT_SOTHAM_HDXX T3 ON T3.DONID=T1.ID
	WHERE T2.TK_APDUNGANLE=1 AND T3.CANBOID=vThamPhanID AND T3.MAVAITRO='THAMPHAN'
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T2.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,'KD, TM' LinhVuc,3 MAGIAIDOAN,T1.TOAPHUCTHAMID TOAANID,'Phúc thẩm' TenMaGiaiDoan,'AKT' LOAIAN
	FROM AKT_DON T1
	INNER JOIN AKT_PHUCTHAM_BANAN T2 ON T2.DONID=T1.ID
	INNER JOIN AKT_PHUCTHAM_HDXX T3 ON T3.DONID=T1.ID
	WHERE T2.APDUNGANLE=1 AND T3.CANBOID=vThamPhanID AND T3.MAVAITRO='THAMPHAN'
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T2.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
	UNION
	-- án Lao động
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,'Lao động' LinhVuc,2 MAGIAIDOAN,T1.TOAANID,'Sơ thẩm' TenMaGiaiDoan,'ALD' LOAIAN
	FROM ALD_DON T1
	INNER JOIN ALD_SOTHAM_BANAN T2 ON T2.DONID=T1.ID
	INNER JOIN ALD_SOTHAM_HDXX T3 ON T3.DONID=T1.ID
	WHERE T2.APDUNGANLE=1 AND T3.CANBOID=vThamPhanID AND T3.MAVAITRO='THAMPHAN'
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T2.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,'Lao động' LinhVuc,3 MAGIAIDOAN,T1.TOAPHUCTHAMID TOAANID,'Phúc thẩm' TenMaGiaiDoan,'ALD' LOAIAN
	FROM ALD_DON T1
	INNER JOIN ALD_PHUCTHAM_BANAN T2 ON T2.DONID=T1.ID
	INNER JOIN ALD_PHUCTHAM_HDXX T3 ON T3.DONID=T1.ID
	WHERE T2.APDUNGANLE=1 AND T3.CANBOID=vThamPhanID AND T3.MAVAITRO='THAMPHAN'
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T2.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
	UNION
	-- án Phá sản
	-- án BPXLHC
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,'BP XLHC' LinhVuc,2 MAGIAIDOAN,T1.TOAANID,'Sơ thẩm' TenMaGiaiDoan,'XLHC' LOAIAN
	FROM XLHC_DON T1
	INNER JOIN XLHC_SOTHAM_BANAN T2 ON T2.DONID=T1.ID
	INNER JOIN XLHC_SOTHAM_HDXX T3 ON T3.DONID=T1.ID
	WHERE T2.APDUNGANLE=1 AND T3.CANBOID=vThamPhanID AND T3.MAVAITRO='THAMPHAN'
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T2.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,'BP XLHC' LinhVuc,3 MAGIAIDOAN,T1.TOAPHUCTHAMID TOAANID,'Phúc thẩm' TenMaGiaiDoan,'XLHC' LOAIAN
	FROM XLHC_DON T1
	INNER JOIN XLHC_PHUCTHAM_BANAN T2 ON T2.DONID=T1.ID
	INNER JOIN XLHC_PHUCTHAM_HDXX T3 ON T3.DONID=T1.ID
	WHERE T2.APDUNGANLE=1 AND T3.CANBOID=vThamPhanID AND T3.MAVAITRO='THAMPHAN'
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T2.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
	) re
	INNER JOIN DM_TOAAN ta ON ta.ID=re.TOAANID
	ORDER BY ta.ARRTHUTU,re.LinhVuc,re.MAGIAIDOAN; 
END DS_AN_APDUNGANLE_BYTP;

PROCEDURE DS_AN_HOAGIAI_DOITHOAI_BYTP 
(
	vThamPhanID IN number,
	vTenVuAn in varchar2,
	vSoQDBA in varchar2,
	vNgayQDBA in date,
	CurReturn OUT sys_refcursor
) AS
	strTenVuAn VARCHAR2(250);
  strSoQDBA VARCHAR2(250);
  strNgayQDBA VARCHAR2(15);
BEGIN
  strTenVuAn:=LOWER(vTenVuAn);
  strSoQDBA:=LOWER(vSoQDBA);
  strNgayQDBA:=TO_CHAR(vNgayQDBA,'dd/MM/yyyy');
	OPEN CurReturn FOR
	SELECT re.VuAnID,re.MaVuAn,re.TenVuAn,ta.TEN TenToaAn,re.LinhVuc,re.LOAIAN,re.TenMaGiaiDoan
	FROM (
	-- Dân sự
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAANID,'Dân sự' LinhVuc,'Sơ thẩm' TenMaGiaiDoan,'ADS' LOAIAN,2 MAGIAIDOAN
	FROM ADS_DON T1
	INNER JOIN ADS_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN ADS_SOTHAM_QUYETDINH T3 ON T3.DONID=T1.ID
	INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
			AND T4.ISDANSU=1 AND T4.MA='CNTT'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAPHUCTHAMID TOAANID,'Dân sự' LinhVuc,'Phúc thẩm' TenMaGiaiDoan,'ADS' LOAIAN,3 MAGIAIDOAN
	FROM ADS_DON T1
	INNER JOIN ADS_PHUCTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN ADS_PHUCTHAM_QUYETDINH T3 ON T3.DONID=T1.ID
	INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
			AND T4.ISDANSU=1 AND T4.MA='CNTT'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	UNION
	-- Hành chính
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAANID,'Hành chính' LinhVuc,'Sơ thẩm' TenMaGiaiDoan,'AHC' LOAIAN,2 MAGIAIDOAN
	FROM AHC_DON T1
	INNER JOIN AHC_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN AHC_SOTHAM_QUYETDINH T3 ON T3.DONID=T1.ID
	INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
			AND T4.ISHANHCHINH=1 AND T4.MA='CNTT'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
