	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAPHUCTHAMID TOAANID,'KD, TM' LinhVuc,'Phúc thẩm' TenMaGiaiDoan,'AKT' LOAIAN,3 MAGIAIDOAN
