			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
