			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAPHUCTHAMID TOAANID,'Phá sản' LinhVuc,'Phúc thẩm' TenMaGiaiDoan,'APS' LOAIAN,3 MAGIAIDOAN
	FROM APS_DON T1
	INNER JOIN APS_PHUCTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN APS_PHUCTHAM_QUYETDINH T3 ON T3.DONID=T1.ID
