			AND T4.ISXLHC=1 AND T4.MA='CNTT'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAPHUCTHAMID TOAANID,'BP XLHC' LinhVuc,'Phúc thẩm' TenMaGiaiDoan,'XLHC' LOAIAN,3 MAGIAIDOAN
	FROM XLHC_DON T1
	INNER JOIN XLHC_PHUCTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN XLHC_PHUCTHAM_QUYETDINH T3 ON T3.DONID=T1.ID
	INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
			AND T4.ISXLHC=1 AND T4.MA='CNTT'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	UNION
	-- Hình sự
	SELECT T1.ID VuAnID,T1.MAVUAN MaVuAn,T1.TENVUAN TenVuAn,T1.TOAANID,'Hình sự' LinhVuc,'Sơ thẩm' TenMaGiaiDoan,'AHS' LOAIAN,2 MAGIAIDOAN
	FROM AHS_VUAN T1
	INNER JOIN AHS_SOTHAM_HDXX T2 ON T2.VUANID=T1.ID
	INNER JOIN AHS_SOTHAM_QUYETDINH_VUAN T3 ON T3.VUANID=T1.ID
	INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
			AND T4.ISHINHSU=1 AND T4.MA='CNTT'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQUYETDINH) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUAN) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID VuAnID,T1.MAVUAN MaVuAn,T1.TENVUAN TenVuAn,T1.TOAPHUCTHAMID TOAANID,'Hình sự' LinhVuc,'Phúc thẩm' TenMaGiaiDoan,'AHS' LOAIAN,3 MAGIAIDOAN
	FROM AHS_VUAN T1
	INNER JOIN AHS_PHUCTHAM_HDXX T2 ON T2.VUANID=T1.ID
	INNER JOIN AHS_PHUCTHAM_QUYETDINH_VUAN T3 ON T3.VUANID=T1.ID
	INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
			AND T4.ISHINHSU=1 AND T4.MA='CNTT'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQUYETDINH) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUAN) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	)re
	INNER JOIN DM_TOAAN ta ON re.TOAANID=ta.ID
	ORDER BY ta.ARRTHUTU,re.LinhVuc,re.MAGIAIDOAN;
END DS_AN_HOAGIAI_DOITHOAI_BYTP;

PROCEDURE DANHGIA_ANSUAHUY_OFTP 
(
	vThamPhanID in number, 
	vTenVuAn in VARCHAR2,
	vMaVuAn in VARCHAR2,
	vAnSuaHuy in VARCHAR2,
	vSoQDBA in VARCHAR2,
	vNgayQDBA in VARCHAR2,
	vLoaiAn in VARCHAR2,
	vTrangThai in VARCHAR2,
	CurReturn OUT sys_refcursor
) AS
	strTenVuAn VARCHAR2(250);
	strMaVuAn VARCHAR2(250);
	strSoQDBA VARCHAR2(250);
	strNgayQDBA VARCHAR2(15);
BEGIN
	strTenVuAn:=LOWER(vTenVuAn);
	strMaVuAn:=LOWER(vMaVuAn);
  strSoQDBA:=LOWER(vSoQDBA);
  strNgayQDBA:=vNgayQDBA;
	OPEN CurReturn FOR
	SELECT dg.ID,re.VuAnID,re.MaVuAn,re.TenVuAn,re.LinhVuc,re.LoaiAn,re.LOAIAN_SHORT,
				 re.SOBANAN AS SoQDBA,re.NGAYTUYENAN AS NgayQDBA,re.AnSuaHuy_Ten,
			DECODE(dg.VUANID,NULL,'Chưa đánh giá','Đã đánh giá') TenTrangThai,
			CASE WHEN re.MAVAITRO='THAMPHAN' THEN 'Chủ tọa phiên tòa'
					 WHEN re.MAVAITRO='THAMPHANHDXX' THEN 'Thành viên HDXX'
					 WHEN re.MAVAITRO='THAMPHANDUKHUYET' THEN 'Thẩm phán dự khuyết' ELSE '' END VaiTro
	FROM(
 -- Dân sự
	SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MaVuAn,T1.TENVUVIEC AS TenVuAn,'Dân sự' AS LinhVuc,
		T1.MAGIAIDOAN,'AN_DANSU' AS LOAIAN,T3.NGAYTUYENAN,'ADS' LOAIAN_SHORT,T2.MAVAITRO,T3.SOBANAN,
		CASE WHEN INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 'Án hủy'
			   WHEN INSTR('02,05,11,16,17',T4.MA)>0 THEN 'Án sửa' ELSE '' END AnSuaHuy_Ten
	FROM ADS_DON T1
	INNER JOIN ADS_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN ADS_PHUCTHAM_BANAN T3 ON T3.DONID=T1.ID
	INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
	WHERE T2.CANBOID=vThamPhanID
		AND T4.ISADS=1
		AND (1=CASE WHEN vAnSuaHuy='TatCa' AND INSTR('03,04,06,12,13,14,15,02,05,11,16,17',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnHuy' AND INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnSua' AND INSTR('02,05,11,16,17',T4.MA)>0 THEN 1 ELSE 0 END
			)
		AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strMaVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.MAVUVIEC) LIKE '%' || strMaVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strNgayQDBA || ' '=' '  THEN 1 WHEN TO_CHAR(T3.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
		AND 1=CASE WHEN strSoQDBA || ' ' = ' ' THEN 1 WHEN LOWER(T3.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
	UNION
	-- Hôn nhân
	SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MaVuAn,T1.TENVUVIEC AS TenVuAn,'HN & GĐ' AS LinhVuc,
		T1.MAGIAIDOAN,'AN_HNGD' AS LOAIAN,T3.NGAYTUYENAN,'AHN' LOAIAN_SHORT,T2.MAVAITRO,T3.SOBANAN,
		CASE WHEN INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 'Án hủy'
			 WHEN INSTR('02,05,11,16,17',T4.MA)>0 THEN 'Án sửa' ELSE '' END AnSuaHuy_Ten
	FROM AHN_DON T1
	INNER JOIN AHN_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN AHN_PHUCTHAM_BANAN T3 ON T3.DONID=T1.ID
	INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
	WHERE T2.CANBOID=vThamPhanID
		AND T4.ISAHN=1
		AND (1=CASE WHEN vAnSuaHuy='TatCa' AND INSTR('03,04,06,12,13,14,15,02,05,11,16,17',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnHuy' AND INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnSua' AND INSTR('02,05,11,16,17',T4.MA)>0 THEN 1 ELSE 0 END
			)
		AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strMaVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.MAVUVIEC) LIKE '%' || strMaVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strNgayQDBA || ' '=' '  THEN 1 WHEN TO_CHAR(T3.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
		AND 1=CASE WHEN strSoQDBA || ' ' = ' ' THEN 1 WHEN LOWER(T3.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
	UNION
	-- Hành chính
	SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MaVuAn,T1.TENVUVIEC AS TenVuAn,'Hành chính' AS LinhVuc,
		T1.MAGIAIDOAN,'AN_HANHCHINH' AS LOAIAN,T3.NGAYTUYENAN,'AHC' LOAIAN_SHORT,T2.MAVAITRO,T3.SOBANAN,
		CASE WHEN INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 'Án hủy'
			 WHEN INSTR('02,05,11,16,17',T4.MA)>0 THEN 'Án sửa' ELSE '' END AnSuaHuy_Ten
	FROM AHC_DON T1
	INNER JOIN AHC_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN AHC_PHUCTHAM_BANAN T3 ON T3.DONID=T1.ID
	INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
	WHERE T2.CANBOID=vThamPhanID
		AND T4.ISAHC=1
		AND (1=CASE WHEN vAnSuaHuy='TatCa' AND INSTR('03,04,06,12,13,14,15,02,05,11,16,17',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnHuy' AND INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnSua' AND INSTR('02,05,11,16,17',T4.MA)>0 THEN 1 ELSE 0 END
			)
		AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strMaVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.MAVUVIEC) LIKE '%' || strMaVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strNgayQDBA || ' '=' '  THEN 1 WHEN TO_CHAR(T3.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
		AND 1=CASE WHEN strSoQDBA || ' ' = ' ' THEN 1 WHEN LOWER(T3.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
	UNION
	-- Kinh tế
	SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MaVuAn,T1.TENVUVIEC AS TenVuAn,'Kinh tế' AS LinhVuc,
		T1.MAGIAIDOAN,'AN_KDTM' AS LOAIAN,T3.NGAYTUYENAN,'AKT' LOAIAN_SHORT,T2.MAVAITRO,T3.SOBANAN,
		CASE WHEN INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 'Án hủy'
			 WHEN INSTR('02,05,11,16,17',T4.MA)>0 THEN 'Án sửa' ELSE '' END AnSuaHuy_Ten
	FROM AKT_DON T1
	INNER JOIN AKT_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN AKT_PHUCTHAM_BANAN T3 ON T3.DONID=T1.ID
	INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
	WHERE T2.CANBOID=vThamPhanID
		AND T4.ISAKT=1
		AND (1=CASE WHEN vAnSuaHuy='TatCa' AND INSTR('03,04,06,12,13,14,15,02,05,11,16,17',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnHuy' AND INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnSua' AND INSTR('02,05,11,16,17',T4.MA)>0 THEN 1 ELSE 0 END
			)
		AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strMaVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.MAVUVIEC) LIKE '%' || strMaVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strNgayQDBA || ' '=' '  THEN 1 WHEN TO_CHAR(T3.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
		AND 1=CASE WHEN strSoQDBA || ' ' = ' ' THEN 1 WHEN LOWER(T3.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
	UNION
	-- Lao động
	SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MaVuAn,T1.TENVUVIEC AS TenVuAn,'Lao động' AS LinhVuc,
		T1.MAGIAIDOAN,'AN_LAODONG' AS LOAIAN,T3.NGAYTUYENAN,'ALD' LOAIAN_SHORT,T2.MAVAITRO,T3.SOBANAN,
		CASE WHEN INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 'Án hủy'
			 WHEN INSTR('02,05,11,16,17',T4.MA)>0 THEN 'Án sửa' ELSE '' END AnSuaHuy_Ten
	FROM ALD_DON T1
	INNER JOIN ALD_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN ALD_PHUCTHAM_BANAN T3 ON T3.DONID=T1.ID
	INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
	WHERE T2.CANBOID=vThamPhanID
		AND T4.ISALD=1
		AND (1=CASE WHEN vAnSuaHuy='TatCa' AND INSTR('03,04,06,12,13,14,15,02,05,11,16,17',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnHuy' AND INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnSua' AND INSTR('02,05,11,16,17',T4.MA)>0 THEN 1 ELSE 0 END
			)
		AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strMaVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.MAVUVIEC) LIKE '%' || strMaVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strNgayQDBA || ' '=' '  THEN 1 WHEN TO_CHAR(T3.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
		AND 1=CASE WHEN strSoQDBA || ' ' = ' ' THEN 1 WHEN LOWER(T3.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
	UNION
	-- Phá sản
	SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MaVuAn,T1.TENVUVIEC AS TenVuAn,'Phá sản' AS LinhVuc,
		T1.MAGIAIDOAN,'AN_PHASAN' AS LOAIAN,T3.NGAYTUYENAN,'APS' LOAIAN_SHORT,T2.MAVAITRO,T3.SOBANAN,
		CASE WHEN INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 'Án hủy'
			 WHEN INSTR('02,05,11,16,17',T4.MA)>0 THEN 'Án sửa' ELSE '' END AnSuaHuy_Ten
	FROM APS_DON T1
	INNER JOIN APS_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN APS_PHUCTHAM_BANAN T3 ON T3.DONID=T1.ID
	INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
	WHERE T2.CANBOID=vThamPhanID
		AND T4.ISAPS=1
		AND (1=CASE WHEN vAnSuaHuy='TatCa' AND INSTR('03,04,06,12,13,14,15,02,05,11,16,17',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnHuy' AND INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnSua' AND INSTR('02,05,11,16,17',T4.MA)>0 THEN 1 ELSE 0 END
			)
		AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strMaVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.MAVUVIEC) LIKE '%' || strMaVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strNgayQDBA || ' '=' '  THEN 1 WHEN TO_CHAR(T3.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
		AND 1=CASE WHEN strSoQDBA || ' ' = ' ' THEN 1 WHEN LOWER(T3.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
	UNION
	-- BP XLHC
	SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MaVuAn,T1.TENVUVIEC AS TenVuAn,'BP XLHC' AS LinhVuc,
		T1.MAGIAIDOAN,'BPXLHC' AS LOAIAN,T3.NGAYTUYENAN,'XLHC' LOAIAN_SHORT,T2.MAVAITRO,T3.SOBANAN,
		CASE WHEN INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 'Án hủy'
			 WHEN INSTR('02,05,11,16,17',T4.MA)>0 THEN 'Án sửa' ELSE '' END AnSuaHuy_Ten
	FROM XLHC_DON T1
	INNER JOIN XLHC_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN XLHC_PHUCTHAM_BANAN T3 ON T3.DONID=T1.ID
	INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
	WHERE T2.CANBOID=vThamPhanID
		AND T4.ISXLHC=1
		AND (1=CASE WHEN vAnSuaHuy='TatCa' AND INSTR('03,04,06,12,13,14,15,02,05,11,16,17',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnHuy' AND INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnSua' AND INSTR('02,05,11,16,17',T4.MA)>0 THEN 1 ELSE 0 END
			)
		AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strMaVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.MAVUVIEC) LIKE '%' || strMaVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strNgayQDBA || ' '=' '  THEN 1 WHEN TO_CHAR(T3.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
		AND 1=CASE WHEN strSoQDBA || ' ' = ' ' THEN 1 WHEN LOWER(T3.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
	UNION
	-- Hình sự
	SELECT T1.ID AS VuAnID,T1.MAVUAN AS MaVuAn,T1.TENVUAN AS TenVuAn,'Hình sự' AS LinhVuc,
		T1.MAGIAIDOAN,'AN_HINHSU' AS LOAIAN,T3.NGAYBANAN NGAYTUYENAN,'AHS' LOAIAN_SHORT,T2.MAVAITRO,T3.SOBANAN,
		CASE WHEN INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 'Án hủy'
			 WHEN INSTR('02,05,11,16,17',T4.MA)>0 THEN 'Án sửa' ELSE '' END AnSuaHuy_Ten
	FROM AHS_VUAN T1
	INNER JOIN AHS_SOTHAM_HDXX T2 ON T2.VUANID=T1.ID
	INNER JOIN AHS_PHUCTHAM_BANAN T3 ON T3.VUANID=T1.ID
	INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
	WHERE T2.CANBOID=vThamPhanID
		AND T4.ISAHS=1
		AND (1=CASE WHEN vAnSuaHuy='TatCa' AND INSTR('03,04,06,12,13,14,15,02,05,11,16,17',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnHuy' AND INSTR('03,04,06,12,13,14,15',T4.MA)>0 THEN 1
					WHEN vAnSuaHuy='AnSua' AND INSTR('02,05,11,16,17',T4.MA)>0 THEN 1 ELSE 0 END
			)
		AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUAN) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strMaVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.MAVUAN) LIKE '%' || strMaVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strNgayQDBA || ' '=' '  THEN 1 WHEN TO_CHAR(T3.NGAYBANAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
		AND 1=CASE WHEN strSoQDBA || ' ' = ' ' THEN 1 WHEN LOWER(T3.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
	) re
	LEFT JOIN GSTP_DANHGIAANHUYSUA dg ON dg.VUANID=re.VuAnID AND dg.LoaiAn=re.LOAIAN AND dg.THAMPHANID=vThamPhanID
	WHERE 1=CASE WHEN vLoaiAn='TATCA' THEN 1 WHEN re.LOAIAN=vLoaiAn THEN 1 ELSE 0 END
		AND 1=CASE WHEN vTrangThai='TatCa' THEN 1 
		           WHEN vTrangThai='ChuaDanhGia' AND dg.VUANID || ' '=' ' THEN 1
				       WHEN vTrangThai='DaDanhGia' AND dg.VUANID>0 THEN 1 ELSE 0 END
	ORDER BY re.NGAYTUYENAN DESC;
END DANHGIA_ANSUAHUY_OFTP;

PROCEDURE DS_ANTDC_BYTP 
(
	vThamPhanID IN NUMBER,
	vTenVuAn IN VARCHAR2,
	vSoQDBA IN VARCHAR2,
	vNgayQDBA IN DATE,
	CurReturn OUT sys_refcursor
) AS
	strTenVuAn VARCHAR2(250);
  strSoQDBA VARCHAR2(250);
  strNgayQDBA VARCHAR2(15);
BEGIN
  strTenVuAn:=LOWER(vTenVuAn);
  strSoQDBA:=LOWER(vSoQDBA);
  strNgayQDBA:=TO_CHAR(vNgayQDBA,'dd/MM/yyyy');
	OPEN CurReturn FOR
	SELECT re.VuAnID,re.MaVuAn,re.TenVuAn,ta.TEN TenToaAn,re.LinhVuc,re.LOAIAN,re.TenMaGiaiDoan
	FROM (
	-- Dân sự
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAANID,'Dân sự' LinhVuc,'Sơ thẩm' TenMaGiaiDoan,'ADS' LOAIAN,2 MAGIAIDOAN
	FROM ADS_DON T1
	INNER JOIN ADS_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN ADS_SOTHAM_QUYETDINH T3 ON T3.DONID=T1.ID
	INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
			AND T4.ISDANSU=1 AND T4.MA='TDC'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAPHUCTHAMID TOAANID,'Dân sự' LinhVuc,'Phúc thẩm' TenMaGiaiDoan,'ADS' LOAIAN,3 MAGIAIDOAN
	FROM ADS_DON T1
	INNER JOIN ADS_PHUCTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN ADS_PHUCTHAM_QUYETDINH T3 ON T3.DONID=T1.ID
	INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
			AND T4.ISDANSU=1 AND T4.MA='TDC'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	UNION
	-- Hành chính
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAANID,'Hành chính' LinhVuc,'Sơ thẩm' TenMaGiaiDoan,'AHC' LOAIAN,2 MAGIAIDOAN
	FROM AHC_DON T1
	INNER JOIN AHC_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN AHC_SOTHAM_QUYETDINH T3 ON T3.DONID=T1.ID
	INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
			AND T4.ISHANHCHINH=1 AND T4.MA='TDC'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAPHUCTHAMID TOAANID,'Hành chính' LinhVuc,'Phúc thẩm' TenMaGiaiDoan,'AHC' LOAIAN,3 MAGIAIDOAN
	FROM AHC_DON T1
	INNER JOIN AHC_PHUCTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN AHC_PHUCTHAM_QUYETDINH T3 ON T3.DONID=T1.ID
	INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
			AND T4.ISHANHCHINH=1 AND T4.MA='TDC'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	UNION
	-- Hôn nhân
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAANID,'HN & GĐ' LinhVuc,'Sơ thẩm' TenMaGiaiDoan,'AHN' LOAIAN,2 MAGIAIDOAN
	FROM AHN_DON T1
	INNER JOIN AHN_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN AHN_SOTHAM_QUYETDINH T3 ON T3.DONID=T1.ID
	INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
			AND T4.ISHNGD=1 AND T4.MA='TDC'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAPHUCTHAMID TOAANID,'HN & GĐ' LinhVuc,'Phúc thẩm' TenMaGiaiDoan,'AHN' LOAIAN,3 MAGIAIDOAN
	FROM AHN_DON T1
	INNER JOIN AHN_PHUCTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN AHN_PHUCTHAM_QUYETDINH T3 ON T3.DONID=T1.ID
	INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
			AND T4.ISHNGD=1 AND T4.MA='TDC'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	UNION
	-- Kinh tế
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAANID,'KD, TM' LinhVuc,'Sơ thẩm' TenMaGiaiDoan,'AKT' LOAIAN,2 MAGIAIDOAN
	FROM AKT_DON T1
	INNER JOIN AKT_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN AKT_SOTHAM_QUYETDINH T3 ON T3.DONID=T1.ID
	INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
			AND T4.ISKDTM=1 AND T4.MA='TDC'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAPHUCTHAMID TOAANID,'KD, TM' LinhVuc,'Phúc thẩm' TenMaGiaiDoan,'AKT' LOAIAN,3 MAGIAIDOAN
	FROM AKT_DON T1
	INNER JOIN AKT_PHUCTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN AKT_PHUCTHAM_QUYETDINH T3 ON T3.DONID=T1.ID
	INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
			AND T4.ISKDTM=1 AND T4.MA='TDC'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	UNION
	-- Lao động
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAANID,'Lao động' LinhVuc,'Sơ thẩm' TenMaGiaiDoan,'ALD' LOAIAN,2 MAGIAIDOAN
	FROM ALD_DON T1
	INNER JOIN ALD_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN ALD_SOTHAM_QUYETDINH T3 ON T3.DONID=T1.ID
	INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
			AND T4.ISLAODONG=1 AND T4.MA='TDC'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAPHUCTHAMID TOAANID,'Lao động' LinhVuc,'Phúc thẩm' TenMaGiaiDoan,'ALD' LOAIAN,3 MAGIAIDOAN
	FROM ALD_DON T1
	INNER JOIN ALD_PHUCTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN ALD_PHUCTHAM_QUYETDINH T3 ON T3.DONID=T1.ID
