	SELECT T1.ID VuAnID,T1.MAVUAN MaVuAn,T1.TENVUAN TenVuAn,T1.TOAPHUCTHAMID TOAANID,'Hình sự' LinhVuc,'Phúc thẩm' TenMaGiaiDoan,'AHS' LOAIAN,3 MAGIAIDOAN
