			AND T4.ISHINHSU=1 AND T4.MA='TDC'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQUYETDINH) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
