	OPEN CurReturn FOR
	SELECT re.VuAnID,re.MaVuAn,re.TenVuAn,ta.TEN TenToaAn,re.LinhVuc,re.LOAIAN,re.TenMaGiaiDoan
	FROM (
	-- Dân sự
	SELECT T1.ID VuAnID,T1.MAVUVIEC MaVuAn,T1.TENVUVIEC TenVuAn,T1.TOAANID,'Dân sự' LinhVuc,'Sơ thẩm' TenMaGiaiDoan,'ADS' LOAIAN,2 MAGIAIDOAN
