			AND T4.ISDANSU=1 AND T4.MA='DC'
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOQD) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
