	INNER JOIN AHS_PHUCTHAM_BANAN T3 ON T3.VUANID=T1.ID
	INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
	INNER JOIN GSTP_DANHGIAANHUYSUA T5 ON T5.VUANID=T1.ID AND T5.THAMPHANID=vThamPhanID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
		AND T4.ISAHS=1 AND T5.UBTP_DANHGIA=0 AND T5.LOAIAN='AN_HINHSU'
		AND INSTR('03,04,06,12,13,14,15',T4.MA)>0
		AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUAN) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strNgayQDBA || ' '=' '  THEN 1 WHEN TO_CHAR(T3.NGAYBANAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
		AND 1=CASE WHEN strSoQDBA || ' ' = ' ' THEN 1 WHEN LOWER(T3.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
