	-- Hành chính
	SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MaVuAn,T1.TENVUVIEC AS TenVuAn,T1.TOAPHUCTHAMID,'Hành chính' AS LinhVuc,
		T1.MAGIAIDOAN,'AHC' AS LOAIAN
	FROM AHC_DON T1
	INNER JOIN AHC_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN AHC_PHUCTHAM_BANAN T3 ON T3.DONID=T1.ID
	INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
	INNER JOIN GSTP_DANHGIAANHUYSUA T5 ON T5.VUANID=T1.ID AND T5.THAMPHANID=vThamPhanID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
		AND T4.ISAHC=1 AND T5.UBTP_DANHGIA=0 AND T5.LOAIAN='AN_HANHCHINH'
		AND INSTR('03,04,06,12,13,14,15',T4.MA)>0
		AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strNgayQDBA || ' '=' '  THEN 1 WHEN TO_CHAR(T3.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
		AND 1=CASE WHEN strSoQDBA || ' ' = ' ' THEN 1 WHEN LOWER(T3.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
	UNION
	-- Hôn nhân
	SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MaVuAn,T1.TENVUVIEC AS TenVuAn,T1.TOAPHUCTHAMID,'HN & GĐ' AS LinhVuc,
		T1.MAGIAIDOAN,'AHN' AS LOAIAN
	FROM AHN_DON T1
	INNER JOIN AHN_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN AHN_PHUCTHAM_BANAN T3 ON T3.DONID=T1.ID
	INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
	INNER JOIN GSTP_DANHGIAANHUYSUA T5 ON T5.VUANID=T1.ID AND T5.THAMPHANID=vThamPhanID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
		AND T4.ISAHN=1 AND T5.UBTP_DANHGIA=0 AND T5.LOAIAN='AN_HNGD'
		AND INSTR('03,04,06,12,13,14,15',T4.MA)>0
		AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strNgayQDBA || ' '=' '  THEN 1 WHEN TO_CHAR(T3.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
		AND 1=CASE WHEN strSoQDBA || ' ' = ' ' THEN 1 WHEN LOWER(T3.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
