	-- Kinh tế
	SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MaVuAn,T1.TENVUVIEC AS TenVuAn,T1.TOAPHUCTHAMID,'Kinh tế' AS LinhVuc,
		T1.MAGIAIDOAN,'AKT' AS LOAIAN
	FROM AKT_DON T1
	INNER JOIN AKT_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN AKT_PHUCTHAM_BANAN T3 ON T3.DONID=T1.ID
	INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
	INNER JOIN GSTP_DANHGIAANHUYSUA T5 ON T5.VUANID=T1.ID AND T5.THAMPHANID=vThamPhanID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
