		T1.MAGIAIDOAN,'APS' AS LOAIAN
	FROM APS_DON T1
	INNER JOIN APS_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN APS_PHUCTHAM_BANAN T3 ON T3.DONID=T1.ID
