	-- XLHC
	SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MaVuAn,T1.TENVUVIEC AS TenVuAn,T1.TOAPHUCTHAMID,'BP XLHC' AS LinhVuc,
		T1.MAGIAIDOAN,'XLHC' AS LOAIAN
