PROCEDURE DS_ANSUA_BYTP 
(
	vThamPhanID IN number,
	vTenVuAn in varchar2,
	vSoQDBA in varchar2,
	vNgayQDBA in date,
	CurReturn OUT sys_refcursor
) AS
	strTenVuAn VARCHAR2(250);
  strSoQDBA VARCHAR2(250);
  strNgayQDBA VARCHAR2(15);
BEGIN
  strTenVuAn:=LOWER(vTenVuAn);
  strSoQDBA:=LOWER(vSoQDBA);
  strNgayQDBA:=TO_CHAR(vNgayQDBA,'dd/MM/yyyy');
	OPEN CurReturn FOR
	-- Dân sự
	SELECT re.VuAnID,re.MaVuAn,re.TenVuAn,ta.TEN AS TenToaAn,re.LinhVuc,re.MAGIAIDOAN,re.LOAIAN,
					CASE re.MAGIAIDOAN WHEN 1 THEN 'Hồ sơ'
											WHEN 2 THEN 'Sơ thẩm'
											WHEN 3 THEN 'Phúc thẩm'
											WHEN 4 THEN 'Giám đốc thẩm, tái thẩm'
											ELSE '' END AS TenMaGiaiDoan
	FROM (
	-- Dân sự
	SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MaVuAn,T1.TENVUVIEC AS TenVuAn,T1.TOAPHUCTHAMID,'Dân sự' AS LinhVuc,
		T1.MAGIAIDOAN,'ADS' AS LOAIAN
	FROM ADS_DON T1
	INNER JOIN ADS_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN ADS_PHUCTHAM_BANAN T3 ON T3.DONID=T1.ID
	INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
		AND T4.ISADS=1
		AND INSTR('02,05,11,16,17',T4.MA)>0
		AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUVIEC) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
		AND 1=CASE WHEN strNgayQDBA || ' '=' '  THEN 1 WHEN TO_CHAR(T3.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
		AND 1=CASE WHEN strSoQDBA || ' ' = ' ' THEN 1 WHEN LOWER(T3.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
	UNION
	-- Hình sự
	SELECT T1.ID AS VuAnID,T1.MAVUAN AS MaVuAn,T1.TENVUAN AS TenVuAn,T1.TOAPHUCTHAMID,'Hình sự' AS LinhVuc,
		T1.MAGIAIDOAN,'AHS' AS LOAIAN
