		AND 1=CASE WHEN strNgayQDBA || ' '=' '  THEN 1 WHEN TO_CHAR(T3.NGAYTUYENAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
		AND 1=CASE WHEN strSoQDBA || ' ' = ' ' THEN 1 WHEN LOWER(T3.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
