	-- Phá sản
	SELECT T1.ID AS VuAnID,T1.MAVUVIEC AS MaVuAn,T1.TENVUVIEC AS TenVuAn,T1.TOAPHUCTHAMID,'Phá sản' AS LinhVuc,
		T1.MAGIAIDOAN,'APS' AS LOAIAN
	FROM APS_DON T1
	INNER JOIN APS_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
	INNER JOIN APS_PHUCTHAM_BANAN T3 ON T3.DONID=T1.ID
	INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
