PROCEDURE DS_ANTREO_BYTP 
(
	vThamPhanID IN NUMBER,
	vTenVuAn IN VARCHAR2,
	vSoQDBA IN VARCHAR2,
	vNgayQDBA DATE,
	CurReturn OUT sys_refcursor 
) AS
	strTenVuAn VARCHAR2(250);
  strSoQDBA VARCHAR2(250);
  strNgayQDBA VARCHAR2(15);
BEGIN
  strTenVuAn:=LOWER(vTenVuAn);
  strSoQDBA:=LOWER(vSoQDBA);
  strNgayQDBA:=TO_CHAR(vNgayQDBA,'dd/MM/yyyy');
-- Trong 1 vụ án thì 1 thẩm phán chỉ được xử ở Sơ thẩm hoặc Phúc thẩm
	OPEN CurReturn FOR
	SELECT T1.ID AS VuAnID,T1.TENVUAN,T5.TEN AS TenToaAn,T1.MAVUAN,2 MAGIAIDOAN,
				'Sơ thẩm' AS TenMaGiaiDoan,T3.SoBiCao
	FROM AHS_VUAN T1
	INNER JOIN AHS_SOTHAM_BANAN T2 ON T2.VUANID=T1.ID
	INNER JOIN (SELECT BANANID,COUNT(DISTINCT BICANID) SoBiCao FROM AHS_SOTHAM_BANAN_DIEU_CHITIET
              WHERE ISANTREO=1 GROUP BY BANANID
              ) T3 ON T3.BANANID=T2.ID
	INNER JOIN AHS_SOTHAM_HDXX T4 ON T4.VUANID=T1.ID
	INNER JOIN DM_TOAAN T5 ON T5.ID=T1.TOAANID
	WHERE T4.CANBOID=vThamPhanID AND T4.MAVAITRO='THAMPHAN'
		  AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUAN) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
		  AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
		  AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(vNgayQDBA,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
	UNION
	SELECT T1.ID AS VuAnID,T1.TENVUAN,T5.TEN AS TenToaAn,T1.MAVUAN,3 MAGIAIDOAN,
				'Phúc thẩm' AS TenMaGiaiDoan,T3.SoBiCao
	FROM AHS_VUAN T1
	INNER JOIN AHS_PHUCTHAM_BANAN T2 ON T2.VUANID=T1.ID
	INNER JOIN (SELECT BANANID,COUNT(DISTINCT BICANID) SoBiCao FROM AHS_PHUCTHAM_BANAN_DIEU_CT
              WHERE ISANTREO=1 GROUP BY BANANID
              ) T3 ON T3.BANANID=T2.ID
	INNER JOIN AHS_PHUCTHAM_HDXX T4 ON T4.VUANID=T1.ID
	INNER JOIN DM_TOAAN T5 ON T5.ID=T1.TOAPHUCTHAMID
	WHERE T4.CANBOID=vThamPhanID AND T4.MAVAITRO='THAMPHAN'
		  AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUAN) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
		  AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T2.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
		  AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(vNgayQDBA,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END;
END DS_ANTREO_BYTP;

PROCEDURE DS_AN_TOCHUC_PTRKN_BYTP 
