					)
					OR 
					(T3.PT_ISRUTKN=1
						AND
						(1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T6.SOQUYETDINH) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
							OR
						1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T7.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
						)
						AND
						(1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T6.NGAYQD,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
							OR
							1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T7.NGAYBANAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
						)
					)
				)
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUAN) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	)re
	INNER JOIN DM_TOAAN ta ON re.TOAANID=ta.ID
	ORDER BY ta.ARRTHUTU,re.LinhVuc,re.MAGIAIDOAN;
END DS_AN_TOCHUC_PTRKN_BYTP;

PROCEDURE DS_AN_VIPHAM_TAMGIAM_BYTP 
(
	vThamPhanID IN number,
	vTenVuAn in varchar2,
	vSoQDBA in varchar2,
	vNgayQDBA in date,
	CurReturn OUT sys_refcursor
) AS
	strTenVuAn VARCHAR2(250);
  strSoQDBA VARCHAR2(250);
  strNgayQDBA VARCHAR2(15);
BEGIN
  strTenVuAn:=LOWER(vTenVuAn);
  strSoQDBA:=LOWER(vSoQDBA);
  strNgayQDBA:=TO_CHAR(vNgayQDBA,'dd/MM/yyyy');
	OPEN CurReturn FOR
	
	SELECT T1.ID VuAnID,T1.MAVUAN MaVuAn,T1.TENVUAN TenVuAn,T4.TEN TenToaAn,'Hình sự' LinhVuc,'Sơ thẩm' TenMaGiaiDoan,'AHS' LOAIAN,2 MAGIAIDOAN
	FROM AHS_VUAN T1
	INNER JOIN AHS_SOTHAM_HDXX T2 ON T2.VUANID=T1.ID
	INNER JOIN AHS_SOTHAM_BANAN T3 ON T3.VUANID=T1.ID
	INNER JOIN DM_TOAAN T4 ON T4.ID=T1.TOAANID
	WHERE T2.CANBOID=vThamPhanID AND T2.MAVAITRO='THAMPHAN'
      AND T3.TK_ISVIPHAMHANTAMGIAM=1
			AND 1=CASE WHEN strSoQDBA || ' '=' ' THEN 1 WHEN LOWER(T3.SOBANAN) LIKE '%' || strSoQDBA || '%' THEN 1 ELSE 0 END
			AND 1=CASE WHEN strNgayQDBA || ' '=' ' THEN 1 WHEN TO_CHAR(T3.NGAYBANAN,'dd/MM/yyyy')=strNgayQDBA THEN 1 ELSE 0 END
			AND 1=CASE WHEN strTenVuAn || ' '=' ' THEN 1 WHEN LOWER(T1.TENVUAN) LIKE '%' || strTenVuAn || '%' THEN 1 ELSE 0 END
	;
END DS_AN_VIPHAM_TAMGIAM_BYTP;

PROCEDURE GETTHAMPHAN_ANDINHCHI
(
	vDonViID in number,
	CurReturn OUT sys_refcursor
) AS
	vGroupChucDanhID number;vTyLeDC number;
	vArrSapXep nvarchar2(250);
BEGIN
	-- Lấy danh sách các thẩm phán của đơn vị và đơn vị cấp con có án tạm đình chỉ >= tỷ lệ án tạm đình chỉ công bố
	-- Thẩm phán vẫn còn nhiệm kỳ
	-- 2 vụ án thẩm phán làm thẩm phán cánh gà = 1 vụ án làm chủ tọa
	if vDonViID>0 then
		select t.ARRSAPXEP into vArrSapXep from DM_TOAAN t where t.ID=vDonViID;
	else
		vArrSapXep:='0';
	end if;
	select a.ID into vGroupChucDanhID from DM_DATAGROUP a where a.MA='CHUCDANH';
	open CurReturn for
  
	select a.ID as TPID,a.HOTEN as TenTP,c.TEN as TenToaAn,b.TEN as CapTP,c.ARRTHUTU,
		PKG_GSTP.FUN_GETTYLE_ANDC_BYTP(a.ID,a.NGAYBONHIEM,a.NGAYKETTHUC) as TyLeDC
	from DM_CANBO a
	inner join (select g.ID,g.TEN from DM_DATAITEM g where g.GROUPID=vGroupChucDanhID  and lower(g.TEN) like '%thẩm phán%') b on b.ID=a.CHUCDANHID
	inner join (select d.ID,d.TEN,d.ARRTHUTU from DM_TOAAN d where (d.ARRSAPXEP like (vArrSapXep ||'/%') or d.ARRSAPXEP=vArrSapXep )) c on a.TOAANID=c.ID
	;
END GETTHAMPHAN_ANDINHCHI;
PROCEDURE THAMPHAN_TTTONGHOP 
(
	vThamPhanID IN NUMBER,
	CurReturn OUT sys_refcursor
) AS
vLoaiAn varchar2(100):='AN_HINHSU,AN_DANSU,AN_HANHCHINH,AN_HNGD,AN_KDTM,AN_LAODONG,AN_PHASAN,BPXLHC,';
BEGIN
	open CurReturn for
	select a.HOTEN,a.GIOITINH,a.NGAYSINH,a.QDBONHIEM,a.NGAYBONHIEM,c.TEN as TenToaAn,b.TEN as CapTP,
		PKG_GSTP.FUN_GETVUANCHUTOA_BY_TP(a.ID) + PKG_GSTP.FUN_GETVUANCANHGA_BY_TP(a.ID) as TongVuAnThamGia, 
		PKG_GSTP.FUN_GETVUANCHUTOA_BY_TP(a.ID) as VuAnLamChuToa, 
		PKG_GSTP.FUN_GETVUANCANHGA_BY_TP(a.ID) as VuAnLamCanhGa, 
		PKG_GSTP.FUN_GETVUANSUA_BY_TP(a.ID,a.NGAYBONHIEM,a.NGAYKETTHUC,vLoaiAn) as VuAnSua,
		PKG_GSTP.FUN_GETTYLE_ANSUA_BYTP(a.ID,a.NGAYBONHIEM,a.NGAYKETTHUC) as TyLeAnSua,
		PKG_GSTP.FUN_GETVUANHUY_BY_TP(a.ID,vLoaiAn) as VuAnHuy,
		PKG_GSTP.FUN_GETTYLE_ANHUY_BYTP(a.ID,a.NGAYBONHIEM,a.NGAYKETTHUC) as TyLeAnHuy,
		PKG_GSTP.FUN_GETVUANTREO_BY_TP(a.ID,a.NGAYBONHIEM,a.NGAYKETTHUC) as VuAnTreo,
		PKG_GSTP.FUN_GETTYLE_ANTREO_BYTP(a.ID,a.NGAYBONHIEM,a.NGAYKETTHUC) as TyLeAnTreo,
		PKG_GSTP.FUN_GETVUANBPTT_BY_TP(a.ID,a.NGAYBONHIEM,a.NGAYKETTHUC,vLoaiAn) as VuAnBPTamThoi,
		PKG_GSTP.FUN_GETTYLE_ANBPTT_BYTP(a.ID,a.NGAYBONHIEM,a.NGAYKETTHUC) as TyLeBPTT,
		PKG_GSTP.FUN_GETVUANTDC_BY_TP(a.ID,a.NGAYBONHIEM,a.NGAYKETTHUC,vLoaiAn) as VuAnTamDinhChi, 
		PKG_GSTP.FUN_GETTYLE_ANTDC_BYTP(a.ID,a.NGAYBONHIEM,a.NGAYKETTHUC) as TyLeTDC,
		PKG_GSTP.FUN_GETVUANDC_BY_TP(a.ID,a.NGAYBONHIEM,a.NGAYKETTHUC,vLoaiAn) as VuAnDinhChi, 
		PKG_GSTP.FUN_GETTYLE_ANDC_BYTP(a.ID,a.NGAYBONHIEM,a.NGAYKETTHUC) as TyLeDC,
		PKG_GSTP.FUN_GETVUANQH_BY_TP(a.ID,a.NGAYBONHIEM,a.NGAYKETTHUC,vLoaiAn) as VuAnQuaHan,
		PKG_GSTP.FUN_GETTYLE_ANQUAHAN_BYTP(a.ID,a.NGAYBONHIEM,a.NGAYKETTHUC) as TyLeQuaHan, 
			 0 as KhenThuong, 
			 0 as KyLuat, 
			 0 as KNToCao
	from DM_CANBO a
	inner join DM_TOAAN c on c.ID=a.TOAANID
	inner join DM_DATAITEM b on b.ID=a.CHUCDANHID
	where a.ID=vThamPhanID;
END THAMPHAN_TTTONGHOP;

PROCEDURE FILL_GSTP_HOME_ST
(
  v_ARRAY IN OUT GSTP_HOME_ST_PT_T,
  vHienTai_TuNgay IN DATE,
  vHienTai_DenNgay IN DATE,
  vTruoc_TuNgay IN DATE,
  vTruoc_DenNgay IN DATE
) AS
   vLoaiAN_HinhSu NUMBER DEFAULT 1;
   vLoaiAN_DanSu NUMBER DEFAULT 2;
   vLoaiAN_HNGD NUMBER DEFAULT 3;
   vLoaiAN_KinhTe NUMBER DEFAULT 4;
   vLoaiAN_LaoDong NUMBER DEFAULT 5;
   vLoaiAN_HanhChinh NUMBER DEFAULT 6;
   vLoaiAN_PhaSan NUMBER DEFAULT 7;
   vLoaiAN_BPXLHC NUMBER DEFAULT 8;
BEGIN
  --***** Tính tổng thụ lý trong kỳ --> V_TONGTHULY
  -- Tổng thụ lý= thụ lý trong kỳ + thụ lý còn lại chưa giải quyết kỳ trước
  -- thụ lý trong kỳ --> V_THULYMOI
  -- Hình sự - thụ lý trong kỳ --> V_HINHSU_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_HINHSU_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_HINHSU_TONGTHULY FROM AHS_VUAN T2
                INNER JOIN AHS_SOTHAM_THULY T3 ON T2.ID=T3.VUANID
                WHERE T3.NGAYTHULY BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HINHSU_TONGTHULY:=ITEM.V_HINHSU_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_THULYMOI:=ITEM.V_HINHSU_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY + ITEM.V_HINHSU_TONGTHULY;
  END LOOP;
  -- Hình sự -- Chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHS_SOTHAM_THULY T3 ON T3.VUANID=T2.ID
    LEFT JOIN ( SELECT T1.VUANID,T2.MA FROM AHS_SOTHAM_QUYETDINH_VUAN T1 
                INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              ) QD ON T2.ID =QD.VUANID 
    LEFT JOIN AHS_SOTHAM_BANAN BA ON T2.ID =BA.VUANID
    WHERE T3.NGAYTHULY BETWEEN vTruoc_TuNgay AND vTruoc_DenNgay
          AND (BA.VUANID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_HINHSU_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_HINHSU_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- Dân sự - thụ lý trong kỳ -->V_DANSU_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_DANSU_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_DANSU_TONGTHULY FROM ADS_DON T2
                INNER JOIN ADS_SOTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_DANSU_TONGTHULY:=ITEM.V_DANSU_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_THULYMOI:=v_ARRAY(ITEM.V_STT).V_THULYMOI + ITEM.V_DANSU_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY + ITEM.V_DANSU_TONGTHULY;
  END LOOP;
  -- Dân sự -- -- Chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN ADS_SOTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM ADS_SOTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN ADS_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vTruoc_TuNgay AND vTruoc_DenNgay
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_DANSU_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_DANSU_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- Hành chính - thụ lý trong kỳ -->V_HANHCHINH_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_HANHCHINH_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_HANHCHINH_TONGTHULY FROM AHC_DON T2
                INNER JOIN AHC_SOTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HANHCHINH_TONGTHULY:=ITEM.V_HANHCHINH_TONGTHULY;
	v_ARRAY(ITEM.V_STT).V_THULYMOI:=v_ARRAY(ITEM.V_STT).V_THULYMOI + ITEM.V_HANHCHINH_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_HANHCHINH_TONGTHULY;
  END LOOP;
  -- Hành chính --  Chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHC_SOTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM AHC_SOTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN AHC_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vTruoc_TuNgay AND vTruoc_DenNgay
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_HANHCHINH_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_HANHCHINH_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- Hôn nhân - thụ lý trong kỳ -->V_HNGD_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_HNGD_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_HNGD_TONGTHULY FROM AHN_DON T2
                INNER JOIN AHN_SOTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HNGD_TONGTHULY:=ITEM.V_HNGD_TONGTHULY;
	v_ARRAY(ITEM.V_STT).V_THULYMOI:=v_ARRAY(ITEM.V_STT).V_THULYMOI + ITEM.V_HNGD_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_HNGD_TONGTHULY;
  END LOOP;
  -- Hôn nhân -- Chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHN_SOTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM AHN_SOTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN AHN_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vTruoc_TuNgay AND vTruoc_DenNgay
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_HNGD_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_HNGD_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- Kinh tế - thụ lý trong kỳ -->V_KDTM_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_KDTM_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_KDTM_TONGTHULY FROM AKT_DON T2
                INNER JOIN AKT_SOTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_KDTM_TONGTHULY:=ITEM.V_KDTM_TONGTHULY;
	v_ARRAY(ITEM.V_STT).V_THULYMOI:=v_ARRAY(ITEM.V_STT).V_THULYMOI + ITEM.V_KDTM_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_KDTM_TONGTHULY;
  END LOOP;
  -- Kinh tế -- Chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AKT_SOTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM AKT_SOTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN AKT_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vTruoc_TuNgay AND vTruoc_DenNgay
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_KDTM_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_KDTM_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- Phá sản sẽ cộng dồn cho án kinh tế - thụ lý trong kỳ
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_KDTM_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_KDTM_TONGTHULY FROM APS_DON T2
                INNER JOIN APS_SOTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_KDTM_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_KDTM_TONGTHULY + ITEM.V_KDTM_TONGTHULY;
	v_ARRAY(ITEM.V_STT).V_THULYMOI:=v_ARRAY(ITEM.V_STT).V_THULYMOI + ITEM.V_KDTM_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_KDTM_TONGTHULY;
  END LOOP;
  -- Phá sản sẽ cộng dồn cho án kinh tế --  Chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN APS_SOTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM APS_SOTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN APS_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vTruoc_TuNgay AND vTruoc_DenNgay
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_KDTM_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_KDTM_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- Lao động - thụ lý trong kỳ -->V_LAODONG_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_LAODONG_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_LAODONG_TONGTHULY FROM ALD_DON T2
                INNER JOIN ALD_SOTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_LAODONG_TONGTHULY:=ITEM.V_LAODONG_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_THULYMOI:=v_ARRAY(ITEM.V_STT).V_THULYMOI + ITEM.V_LAODONG_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_LAODONG_TONGTHULY;
  END LOOP;
  -- Lao động -- Chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN ALD_SOTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM ALD_SOTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN ALD_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vTruoc_TuNgay AND vTruoc_DenNgay
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_LAODONG_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_LAODONG_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  --***** Tính tổng đã giải quyết trong kỳ -->V_GIAIQUYET
  -- Hình sự trong kỳ -->V_HINHSU_TONGGIAIQUYET
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_HINHSU_TONGGIAIQUYET
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAANID,COUNT(DISTINCT VA.ID) V_QD FROM AHS_VUAN VA
                INNER JOIN AHS_SOTHAM_QUYETDINH_VUAN QD ON QD.VUANID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay)
                GROUP BY VA.TOAANID
                ) T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAANID,COUNT(VA.ID) V_BA FROM AHS_VUAN VA
                INNER JOIN AHS_SOTHAM_BANAN BA ON BA.VUANID=VA.ID
                WHERE BA.NGAYBANAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY VA.TOAANID
                ) T3 ON T3.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HINHSU_TONGGIAIQUYET:=ITEM.V_HINHSU_TONGGIAIQUYET;
    v_ARRAY(ITEM.V_STT).V_GIAIQUYET:=ITEM.V_HINHSU_TONGGIAIQUYET;
  END LOOP;
  -- Dân sự trong kỳ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_DANSU_TONGGIAIQUYET
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAANID,COUNT(DISTINCT VA.ID) V_QD FROM ADS_DON VA
                INNER JOIN ADS_SOTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay)
                GROUP BY VA.TOAANID
                ) T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAANID,COUNT(VA.ID) V_BA FROM ADS_DON VA
                INNER JOIN ADS_SOTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY VA.TOAANID
                ) T3 ON T3.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_DANSU_TONGGIAIQUYET:=ITEM.V_DANSU_TONGGIAIQUYET;
    v_ARRAY(ITEM.V_STT).V_GIAIQUYET:=v_ARRAY(ITEM.V_STT).V_GIAIQUYET+ITEM.V_DANSU_TONGGIAIQUYET;
  END LOOP;
  -- Hành chính trong kỳ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_HANHCHINH_TONGGIAIQUYET
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAANID,COUNT(DISTINCT VA.ID) V_QD FROM AHC_DON VA
                INNER JOIN AHC_SOTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay)
                GROUP BY VA.TOAANID
                ) T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAANID,COUNT(VA.ID) V_BA FROM AHC_DON VA
                INNER JOIN AHC_SOTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY VA.TOAANID
                ) T3 ON T3.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HANHCHINH_TONGGIAIQUYET:=ITEM.V_HANHCHINH_TONGGIAIQUYET;
    v_ARRAY(ITEM.V_STT).V_GIAIQUYET:=v_ARRAY(ITEM.V_STT).V_GIAIQUYET+ITEM.V_HANHCHINH_TONGGIAIQUYET;
  END LOOP;
  -- Hôn nhân trong kỳ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_HNGD_TONGGIAIQUYET
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAANID,COUNT(DISTINCT VA.ID) V_QD FROM AHN_DON VA
                INNER JOIN AHN_SOTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay)
                GROUP BY VA.TOAANID
                ) T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAANID,COUNT(VA.ID) V_BA FROM AHN_DON VA
                INNER JOIN AHN_SOTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY VA.TOAANID
                ) T3 ON T3.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HNGD_TONGGIAIQUYET:=ITEM.V_HNGD_TONGGIAIQUYET;
    v_ARRAY(ITEM.V_STT).V_GIAIQUYET:=v_ARRAY(ITEM.V_STT).V_GIAIQUYET+ITEM.V_HNGD_TONGGIAIQUYET;
  END LOOP;
  -- Kinh tế trong kỳ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_KDTM_TONGGIAIQUYET
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAANID,COUNT(DISTINCT VA.ID) V_QD FROM AKT_DON VA
                INNER JOIN AKT_SOTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay)
                GROUP BY VA.TOAANID
                ) T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAANID,COUNT(VA.ID) V_BA FROM AKT_DON VA
                INNER JOIN AKT_SOTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY VA.TOAANID
                ) T3 ON T3.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_KDTM_TONGGIAIQUYET:=ITEM.V_KDTM_TONGGIAIQUYET;
    v_ARRAY(ITEM.V_STT).V_GIAIQUYET:=v_ARRAY(ITEM.V_STT).V_GIAIQUYET+ITEM.V_KDTM_TONGGIAIQUYET;
  END LOOP;
  -- Phá sản trong kỳ (cộng dồn vào kinh tế)
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_KDTM_TONGGIAIQUYET
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAANID,COUNT(DISTINCT VA.ID) V_QD FROM APS_DON VA
                INNER JOIN APS_SOTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay)
                GROUP BY VA.TOAANID
                ) T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAANID,COUNT(VA.ID) V_BA FROM APS_DON VA
                INNER JOIN APS_SOTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY VA.TOAANID
                ) T3 ON T3.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_KDTM_TONGGIAIQUYET:=v_ARRAY(ITEM.V_STT).V_KDTM_TONGGIAIQUYET+ITEM.V_KDTM_TONGGIAIQUYET;
    v_ARRAY(ITEM.V_STT).V_GIAIQUYET:=v_ARRAY(ITEM.V_STT).V_GIAIQUYET+ITEM.V_KDTM_TONGGIAIQUYET;
  END LOOP;
  -- Lao động trong kỳ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_LAODONG_TONGGIAIQUYET
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAANID,COUNT(DISTINCT VA.ID) V_QD FROM ALD_DON VA
                INNER JOIN ALD_SOTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay)
                GROUP BY VA.TOAANID
                ) T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAANID,COUNT(VA.ID) V_BA FROM ALD_DON VA
                INNER JOIN ALD_SOTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY VA.TOAANID
                ) T3 ON T3.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_LAODONG_TONGGIAIQUYET:=ITEM.V_LAODONG_TONGGIAIQUYET;
    v_ARRAY(ITEM.V_STT).V_GIAIQUYET:=v_ARRAY(ITEM.V_STT).V_GIAIQUYET+ITEM.V_LAODONG_TONGGIAIQUYET;
  END LOOP;
  --***** Tính tổng án bị hủy, sửa trong kỳ --> V_ANHUY_SUA
  -- Hình sự
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHS_PHUCTHAM_BANAN T3 ON T3.VUANID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T3.KETQUAPHUCTHAMID=T4.ID
    WHERE INSTR('02,03,04,05,06,11,12,13,14,15,16,17',T4.MA)>0
          AND T4.ISAHS=1
          AND T3.NGAYBANAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=ITEM.V_ANHUY_SUA;
  END LOOP;
  -- Dân sự
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN ADS_PHUCTHAM_BANAN T3 ON T3.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T3.KETQUAPHUCTHAMID=T4.ID
    WHERE INSTR('02,03,04,05,06,11,12,13,14,15,16,17',T4.MA)>0
          AND T4.ISADS=1
          AND T3.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=v_ARRAY(ITEM.V_STT).V_ANHUY_SUA+ITEM.V_ANHUY_SUA;
  END LOOP;
  -- Hành chính
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHC_PHUCTHAM_BANAN T3 ON T3.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T3.KETQUAPHUCTHAMID=T4.ID
    WHERE INSTR('02,03,04,05,06,11,12,13,14,15,16,17',T4.MA)>0
          AND T4.ISAHC=1
          AND T3.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=v_ARRAY(ITEM.V_STT).V_ANHUY_SUA+ITEM.V_ANHUY_SUA;
  END LOOP;
  -- Hôn nhân gia đình
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHN_PHUCTHAM_BANAN T3 ON T3.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T3.KETQUAPHUCTHAMID=T4.ID
    WHERE INSTR('02,03,04,05,06,11,12,13,14,15,16,17',T4.MA)>0
          AND T4.ISAHN=1
          AND T3.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=v_ARRAY(ITEM.V_STT).V_ANHUY_SUA+ITEM.V_ANHUY_SUA;
  END LOOP;
  -- Kinh tế
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AKT_PHUCTHAM_BANAN T3 ON T3.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T3.KETQUAPHUCTHAMID=T4.ID
    WHERE INSTR('02,03,04,05,06,11,12,13,14,15,16,17',T4.MA)>0
          AND T4.ISAKT=1
          AND T3.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=v_ARRAY(ITEM.V_STT).V_ANHUY_SUA+ITEM.V_ANHUY_SUA;
  END LOOP;
  -- Phá sản
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN APS_PHUCTHAM_BANAN T3 ON T3.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T3.KETQUAPHUCTHAMID=T4.ID
    WHERE INSTR('02,03,04,05,06,11,12,13,14,15,16,17',T4.MA)>0
          AND T4.ISAPS=1
          AND T3.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=v_ARRAY(ITEM.V_STT).V_ANHUY_SUA+ITEM.V_ANHUY_SUA;
  END LOOP;
  -- Lao động
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN ALD_PHUCTHAM_BANAN T3 ON T3.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T3.KETQUAPHUCTHAMID=T4.ID
    WHERE INSTR('02,03,04,05,06,11,12,13,14,15,16,17',T4.MA)>0
          AND T4.ISALD=1
          AND T3.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=v_ARRAY(ITEM.V_STT).V_ANHUY_SUA+ITEM.V_ANHUY_SUA;
  END LOOP;
  -- Tính án hủy, sửa theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
    WHERE T2.XXGDTTT_ISKETQUA = 1
          AND T2.LOAIAN IN (1,2,3,4,5,6,7)--> 1:HS; 2:DS; 3:HNGD; 4:KDTM; 5:LD; 6:HC; 7:PS
          AND T2.XXGDTTT_KETQUAID IN (1330,1262,1263,1268,1269,1270,1319,1322,1327,1328,1374)
          AND XXGDTTT_NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
    GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=v_ARRAY(ITEM.V_STT).V_ANHUY_SUA+ITEM.V_ANHUY_SUA;
	END LOOP;
  --***** Tính tổng án chưa giải quyết xong trong kỳ = tổng thụ lý - đã giải quyết trong kỳ --> V_CHUA_GQ
  --***** Tính tổng án quá hạn luật định trong kỳ --> V_QUAHAN
  -- Hình sự
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHS_SOTHAM_BANAN BA ON T2.ID =BA.VUANID
    WHERE BA.NGAYBANAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN:=ITEM.V_QUAHAN;
  END LOOP;
  -- Dân sự
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN ADS_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN:=v_ARRAY(ITEM.V_STT).V_QUAHAN + ITEM.V_QUAHAN;
  END LOOP;
  -- Hành chính
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHC_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN:=v_ARRAY(ITEM.V_STT).V_QUAHAN + ITEM.V_QUAHAN;
  END LOOP;
  -- Hôn nhân
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHN_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN:=v_ARRAY(ITEM.V_STT).V_QUAHAN + ITEM.V_QUAHAN;
  END LOOP;
  -- Kinh tế
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AKT_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN:=v_ARRAY(ITEM.V_STT).V_QUAHAN + ITEM.V_QUAHAN;
  END LOOP;
  -- Phá sản
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN APS_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN:=v_ARRAY(ITEM.V_STT).V_QUAHAN + ITEM.V_QUAHAN;
  END LOOP;
  -- Lao động
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN ALD_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN:=v_ARRAY(ITEM.V_STT).V_QUAHAN + ITEM.V_QUAHAN;
  END LOOP;
  --***** Tính tổng án tổ chức phiên tòa rút kinh nghiệm trong kỳ --> V_RUTKN
  -- Thẩm phán trong kỳ --> V_RUTKN_THAMPHAN
  -- Hình sự
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_RUTKN,COUNT(DISTINCT T3.CANBOID) V_RUTKN_THAMPHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN (SELECT T4.VUANID,T4.CANBOID FROM AHS_SOTHAM_HDXX T4
                WHERE INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T4.MAVAITRO)>0
                ) T3 ON T2.ID=T3.VUANID
    INNER JOIN AHS_SAUXETXU SXX ON SXX.VUANID=T2.ID
    WHERE SXX.ST_NGAYRUT BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND SXX.ST_ISRUTKN=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_RUTKN:=ITEM.V_RUTKN;
    v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN:=ITEM.V_RUTKN_THAMPHAN;
  END LOOP;
  -- Dân sự
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_RUTKN,COUNT(DISTINCT T3.CANBOID) V_RUTKN_THAMPHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN (SELECT T4.DONID,T4.CANBOID FROM ADS_SOTHAM_HDXX T4
                WHERE INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T4.MAVAITRO)>0
                ) T3 ON T2.ID=T3.DONID
    INNER JOIN ADS_SAUXETXU SXX ON SXX.VUANID=T2.ID
    WHERE SXX.ST_NGAYRUT BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND SXX.ST_ISRUTKN=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_RUTKN:=v_ARRAY(ITEM.V_STT).V_RUTKN+ITEM.V_RUTKN;
    v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN:=v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN+ITEM.V_RUTKN_THAMPHAN;
  END LOOP;
  -- Hành chính
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_RUTKN,COUNT(DISTINCT T3.CANBOID) V_RUTKN_THAMPHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN (SELECT T4.DONID,T4.CANBOID FROM AHC_SOTHAM_HDXX T4
                WHERE INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T4.MAVAITRO)>0
                ) T3 ON T2.ID=T3.DONID
    INNER JOIN AHC_SAUXETXU SXX ON SXX.VUANID=T2.ID
    WHERE SXX.ST_NGAYRUT BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND SXX.ST_ISRUTKN=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_RUTKN:=v_ARRAY(ITEM.V_STT).V_RUTKN+ITEM.V_RUTKN;
    v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN:=v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN+ITEM.V_RUTKN_THAMPHAN;
  END LOOP;
  -- Hôn nhân
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_RUTKN,COUNT(DISTINCT T3.CANBOID) V_RUTKN_THAMPHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN (SELECT T4.DONID,T4.CANBOID FROM AHN_SOTHAM_HDXX T4
                WHERE INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T4.MAVAITRO)>0
                ) T3 ON T2.ID=T3.DONID
    INNER JOIN AHN_SAUXETXU SXX ON SXX.VUANID=T2.ID
    WHERE SXX.ST_NGAYRUT BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND SXX.ST_ISRUTKN=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_RUTKN:=v_ARRAY(ITEM.V_STT).V_RUTKN+ITEM.V_RUTKN;
    v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN:=v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN+ITEM.V_RUTKN_THAMPHAN;
  END LOOP;
  -- Kinh tế
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_RUTKN,COUNT(DISTINCT T3.CANBOID) V_RUTKN_THAMPHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN (SELECT T4.DONID,T4.CANBOID FROM AKT_SOTHAM_HDXX T4
                WHERE INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T4.MAVAITRO)>0
                ) T3 ON T2.ID=T3.DONID
    INNER JOIN AKT_SAUXETXU SXX ON SXX.VUANID=T2.ID
    WHERE SXX.ST_NGAYRUT BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND SXX.ST_ISRUTKN=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_RUTKN:=v_ARRAY(ITEM.V_STT).V_RUTKN+ITEM.V_RUTKN;
    v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN:=v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN+ITEM.V_RUTKN_THAMPHAN;
  END LOOP;
  -- Phá sản
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_RUTKN,COUNT(DISTINCT T3.CANBOID) V_RUTKN_THAMPHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN (SELECT T4.DONID,T4.CANBOID FROM APS_SOTHAM_HDXX T4
                WHERE INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T4.MAVAITRO)>0
                ) T3 ON T2.ID=T3.DONID
    INNER JOIN APS_SAUXETXU SXX ON SXX.VUANID=T2.ID
    WHERE SXX.ST_NGAYRUT BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND SXX.ST_ISRUTKN=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_RUTKN:=v_ARRAY(ITEM.V_STT).V_RUTKN+ITEM.V_RUTKN;
    v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN:=v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN+ITEM.V_RUTKN_THAMPHAN;
  END LOOP;
  -- Lao động
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_RUTKN,COUNT(DISTINCT T3.CANBOID) V_RUTKN_THAMPHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN (SELECT T4.DONID,T4.CANBOID FROM ALD_SOTHAM_HDXX T4
                WHERE INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T4.MAVAITRO)>0
                ) T3 ON T2.ID=T3.DONID
    INNER JOIN ALD_SAUXETXU SXX ON SXX.VUANID=T2.ID
    WHERE SXX.ST_NGAYRUT BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND SXX.ST_ISRUTKN=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_RUTKN:=v_ARRAY(ITEM.V_STT).V_RUTKN+ITEM.V_RUTKN;
    v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN:=v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN+ITEM.V_RUTKN_THAMPHAN;
  END LOOP;
END;

PROCEDURE FILL_GSTP_HOME_PT
(
  v_ARRAY IN OUT GSTP_HOME_ST_PT_T,
  vHienTai_TuNgay IN DATE,
  vHienTai_DenNgay IN DATE,
  vTruoc_TuNgay IN DATE,
  vTruoc_DenNgay IN DATE
) AS
BEGIN
  --***** Tính tổng thụ lý trong kỳ --> V_TONGTHULY
  -- Tổng thụ lý= thụ lý trong kỳ + thụ lý còn lại chưa giải quyết kỳ trước
  -- thụ lý trong kỳ --> V_THULYMOI
-- Hình sự - thụ lý trong kỳ --> V_HINHSU_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_HINHSU_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_HINHSU_TONGTHULY FROM AHS_VUAN T2
                INNER JOIN AHS_PHUCTHAM_THULY T3 ON T2.ID=T3.VUANID
                WHERE T3.NGAYTHULY BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HINHSU_TONGTHULY:=ITEM.V_HINHSU_TONGTHULY;
	v_ARRAY(ITEM.V_STT).V_THULYMOI:=ITEM.V_HINHSU_TONGTHULY;
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY + ITEM.V_HINHSU_TONGTHULY;
  END LOOP;
  -- Hình sự -- Chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHS_PHUCTHAM_THULY T3 ON T3.VUANID=T2.ID
    LEFT JOIN ( SELECT T1.VUANID,T2.MA FROM AHS_PHUCTHAM_QUYETDINH_VUAN T1 
                INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              ) QD ON T2.ID =QD.VUANID 
    LEFT JOIN AHS_PHUCTHAM_BANAN BA ON T2.ID =BA.VUANID
    WHERE T3.NGAYTHULY BETWEEN vTruoc_TuNgay AND vTruoc_DenNgay
          AND (BA.VUANID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_HINHSU_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_HINHSU_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- Dân sự - thụ lý trong kỳ -->V_DANSU_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_DANSU_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_DANSU_TONGTHULY FROM ADS_DON T2
                INNER JOIN ADS_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_DANSU_TONGTHULY:=ITEM.V_DANSU_TONGTHULY;
	v_ARRAY(ITEM.V_STT).V_THULYMOI:=v_ARRAY(ITEM.V_STT).V_THULYMOI + ITEM.V_DANSU_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY + ITEM.V_DANSU_TONGTHULY;
  END LOOP;
  -- Dân sự -- -- Chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN ADS_PHUCTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM ADS_PHUCTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN ADS_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vTruoc_TuNgay AND vTruoc_DenNgay
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_DANSU_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_DANSU_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- Hành chính - thụ lý trong kỳ -->V_HANHCHINH_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_HANHCHINH_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_HANHCHINH_TONGTHULY FROM AHC_DON T2
                INNER JOIN AHC_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HANHCHINH_TONGTHULY:=ITEM.V_HANHCHINH_TONGTHULY;
	v_ARRAY(ITEM.V_STT).V_THULYMOI:=v_ARRAY(ITEM.V_STT).V_THULYMOI + ITEM.V_HANHCHINH_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_HANHCHINH_TONGTHULY;
  END LOOP;
  -- Hành chính --  Chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHC_PHUCTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM AHC_PHUCTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN AHC_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vTruoc_TuNgay AND vTruoc_DenNgay
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_HANHCHINH_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_HANHCHINH_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- Hôn nhân - thụ lý trong kỳ -->V_HNGD_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_HNGD_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_HNGD_TONGTHULY FROM AHN_DON T2
                INNER JOIN AHN_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HNGD_TONGTHULY:=ITEM.V_HNGD_TONGTHULY;
	v_ARRAY(ITEM.V_STT).V_THULYMOI:=v_ARRAY(ITEM.V_STT).V_THULYMOI + ITEM.V_HNGD_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_HNGD_TONGTHULY;
  END LOOP;
  -- Hôn nhân -- Chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHN_PHUCTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM AHN_PHUCTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN AHN_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vTruoc_TuNgay AND vTruoc_DenNgay
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_HNGD_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_HNGD_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- Kinh tế - thụ lý trong kỳ -->V_KDTM_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_KDTM_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_KDTM_TONGTHULY FROM AKT_DON T2
                INNER JOIN AKT_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_KDTM_TONGTHULY:=ITEM.V_KDTM_TONGTHULY;
	v_ARRAY(ITEM.V_STT).V_THULYMOI:=v_ARRAY(ITEM.V_STT).V_THULYMOI + ITEM.V_KDTM_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_KDTM_TONGTHULY;
  END LOOP;
  -- Kinh tế -- Chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AKT_PHUCTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM AKT_PHUCTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN AKT_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vTruoc_TuNgay AND vTruoc_DenNgay
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_KDTM_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_KDTM_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- Phá sản sẽ cộng dồn cho án kinh tế - thụ lý trong kỳ
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_KDTM_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_KDTM_TONGTHULY FROM APS_DON T2
                INNER JOIN APS_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_KDTM_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_KDTM_TONGTHULY + ITEM.V_KDTM_TONGTHULY;
	v_ARRAY(ITEM.V_STT).V_THULYMOI:=v_ARRAY(ITEM.V_STT).V_THULYMOI + ITEM.V_KDTM_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_KDTM_TONGTHULY;
  END LOOP;
  -- Phá sản sẽ cộng dồn cho án kinh tế --  Chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN APS_PHUCTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM APS_PHUCTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN APS_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vTruoc_TuNgay AND vTruoc_DenNgay
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_KDTM_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_KDTM_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- Lao động - thụ lý trong kỳ -->V_LAODONG_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_LAODONG_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_LAODONG_TONGTHULY FROM ALD_DON T2
                INNER JOIN ALD_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_LAODONG_TONGTHULY:=ITEM.V_LAODONG_TONGTHULY;
	v_ARRAY(ITEM.V_STT).V_THULYMOI:=v_ARRAY(ITEM.V_STT).V_THULYMOI + ITEM.V_LAODONG_TONGTHULY;
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_LAODONG_TONGTHULY;
  END LOOP;
  -- Lao động -- Chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN ALD_PHUCTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM ALD_PHUCTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN ALD_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vTruoc_TuNgay AND vTruoc_DenNgay
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_LAODONG_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_LAODONG_TONGTHULY + ITEM.V_CHUA_GQ_KY_TRUOC;
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  --***** Tính tổng đã giải quyết trong kỳ -->V_GIAIQUYET
  -- Hình sự trong kỳ -->V_HINHSU_TONGGIAIQUYET
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_HINHSU_TONGGIAIQUYET
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(DISTINCT VA.ID) V_QD FROM AHS_VUAN VA
                INNER JOIN AHS_PHUCTHAM_QUYETDINH_VUAN QD ON QD.VUANID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay)
                GROUP BY VA.TOAPHUCTHAMID
                ) T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(VA.ID) V_BA FROM AHS_VUAN VA
                INNER JOIN AHS_PHUCTHAM_BANAN BA ON BA.VUANID=VA.ID
                WHERE BA.NGAYBANAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY VA.TOAPHUCTHAMID
                ) T3 ON T3.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HINHSU_TONGGIAIQUYET:=ITEM.V_HINHSU_TONGGIAIQUYET;
    v_ARRAY(ITEM.V_STT).V_GIAIQUYET:=ITEM.V_HINHSU_TONGGIAIQUYET;
  END LOOP;
  -- Dân sự trong kỳ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_DANSU_TONGGIAIQUYET
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(DISTINCT VA.ID) V_QD FROM ADS_DON VA
                INNER JOIN ADS_PHUCTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay)
                GROUP BY VA.TOAPHUCTHAMID
                ) T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(VA.ID) V_BA FROM ADS_DON VA
                INNER JOIN ADS_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY VA.TOAPHUCTHAMID
                ) T3 ON T3.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_DANSU_TONGGIAIQUYET:=ITEM.V_DANSU_TONGGIAIQUYET;
    v_ARRAY(ITEM.V_STT).V_GIAIQUYET:=v_ARRAY(ITEM.V_STT).V_GIAIQUYET+ITEM.V_DANSU_TONGGIAIQUYET;
  END LOOP;
  -- Hành chính trong kỳ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_HANHCHINH_TONGGIAIQUYET
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(DISTINCT VA.ID) V_QD FROM AHC_DON VA
                INNER JOIN AHC_PHUCTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay)
                GROUP BY VA.TOAPHUCTHAMID
                ) T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(VA.ID) V_BA FROM AHC_DON VA
                INNER JOIN AHC_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY VA.TOAPHUCTHAMID
                ) T3 ON T3.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HANHCHINH_TONGGIAIQUYET:=ITEM.V_HANHCHINH_TONGGIAIQUYET;
    v_ARRAY(ITEM.V_STT).V_GIAIQUYET:=v_ARRAY(ITEM.V_STT).V_GIAIQUYET+ITEM.V_HANHCHINH_TONGGIAIQUYET;
  END LOOP;
  -- Hôn nhân trong kỳ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_HNGD_TONGGIAIQUYET
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(DISTINCT VA.ID) V_QD FROM AHN_DON VA
                INNER JOIN AHN_PHUCTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay)
                GROUP BY VA.TOAPHUCTHAMID
                ) T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(VA.ID) V_BA FROM AHN_DON VA
                INNER JOIN AHN_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY VA.TOAPHUCTHAMID
                ) T3 ON T3.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HNGD_TONGGIAIQUYET:=ITEM.V_HNGD_TONGGIAIQUYET;
    v_ARRAY(ITEM.V_STT).V_GIAIQUYET:=v_ARRAY(ITEM.V_STT).V_GIAIQUYET+ITEM.V_HNGD_TONGGIAIQUYET;
  END LOOP;
  -- Kinh tế trong kỳ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_KDTM_TONGGIAIQUYET
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(DISTINCT VA.ID) V_QD FROM AKT_DON VA
                INNER JOIN AKT_PHUCTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay)
                GROUP BY VA.TOAPHUCTHAMID
                ) T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(VA.ID) V_BA FROM AKT_DON VA
                INNER JOIN AKT_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY VA.TOAPHUCTHAMID
                ) T3 ON T3.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_KDTM_TONGGIAIQUYET:=ITEM.V_KDTM_TONGGIAIQUYET;
    v_ARRAY(ITEM.V_STT).V_GIAIQUYET:=v_ARRAY(ITEM.V_STT).V_GIAIQUYET+ITEM.V_KDTM_TONGGIAIQUYET;
  END LOOP;
  -- Phá sản trong kỳ (cộng dồn vào kinh tế)
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_KDTM_TONGGIAIQUYET
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(DISTINCT VA.ID) V_QD FROM APS_DON VA
                INNER JOIN APS_PHUCTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay)
                GROUP BY VA.TOAPHUCTHAMID
                ) T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(VA.ID) V_BA FROM APS_DON VA
                INNER JOIN APS_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY VA.TOAPHUCTHAMID
                ) T3 ON T3.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_KDTM_TONGGIAIQUYET:=v_ARRAY(ITEM.V_STT).V_KDTM_TONGGIAIQUYET+ITEM.V_KDTM_TONGGIAIQUYET;
    v_ARRAY(ITEM.V_STT).V_GIAIQUYET:=v_ARRAY(ITEM.V_STT).V_GIAIQUYET+ITEM.V_KDTM_TONGGIAIQUYET;
  END LOOP;
  -- Lao động trong kỳ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_LAODONG_TONGGIAIQUYET
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(DISTINCT VA.ID) V_QD FROM ALD_DON VA
                INNER JOIN ALD_PHUCTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay)
                GROUP BY VA.TOAPHUCTHAMID
                ) T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(VA.ID) V_BA FROM ALD_DON VA
                INNER JOIN ALD_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
                GROUP BY VA.TOAPHUCTHAMID
                ) T3 ON T3.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_LAODONG_TONGGIAIQUYET:=ITEM.V_LAODONG_TONGGIAIQUYET;
    v_ARRAY(ITEM.V_STT).V_GIAIQUYET:=v_ARRAY(ITEM.V_STT).V_GIAIQUYET+ITEM.V_LAODONG_TONGGIAIQUYET;
  END LOOP;
  --***** Tính tổng án bị hủy, sửa trong kỳ --> V_ANHUY_SUA
  -- Hình sự
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHS_PHUCTHAM_BANAN T3 ON T3.VUANID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T3.KETQUAPHUCTHAMID=T4.ID
    WHERE INSTR('02,03,04,05,06,11,12,13,14,15,16,17',T4.MA)>0
          AND T4.ISAHS=1
          AND T3.NGAYBANAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=ITEM.V_ANHUY_SUA;
  END LOOP;
  -- Dân sự
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN ADS_PHUCTHAM_BANAN T3 ON T3.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T3.KETQUAPHUCTHAMID=T4.ID
    WHERE INSTR('02,03,04,05,06,11,12,13,14,15,16,17',T4.MA)>0
          AND T4.ISADS=1
          AND T3.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=v_ARRAY(ITEM.V_STT).V_ANHUY_SUA+ITEM.V_ANHUY_SUA;
  END LOOP;
  -- Hành chính
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHC_PHUCTHAM_BANAN T3 ON T3.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T3.KETQUAPHUCTHAMID=T4.ID
    WHERE INSTR('02,03,04,05,06,11,12,13,14,15,16,17',T4.MA)>0
          AND T4.ISAHC=1
          AND T3.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=v_ARRAY(ITEM.V_STT).V_ANHUY_SUA+ITEM.V_ANHUY_SUA;
  END LOOP;
  -- Hôn nhân gia đình
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHN_PHUCTHAM_BANAN T3 ON T3.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T3.KETQUAPHUCTHAMID=T4.ID
    WHERE INSTR('02,03,04,05,06,11,12,13,14,15,16,17',T4.MA)>0
          AND T4.ISAHN=1
          AND T3.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=v_ARRAY(ITEM.V_STT).V_ANHUY_SUA+ITEM.V_ANHUY_SUA;
  END LOOP;
  -- Kinh tế
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AKT_PHUCTHAM_BANAN T3 ON T3.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T3.KETQUAPHUCTHAMID=T4.ID
    WHERE INSTR('02,03,04,05,06,11,12,13,14,15,16,17',T4.MA)>0
          AND T4.ISAKT=1
          AND T3.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=v_ARRAY(ITEM.V_STT).V_ANHUY_SUA+ITEM.V_ANHUY_SUA;
  END LOOP;
  -- Phá sản
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN APS_PHUCTHAM_BANAN T3 ON T3.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T3.KETQUAPHUCTHAMID=T4.ID
    WHERE INSTR('02,03,04,05,06,11,12,13,14,15,16,17',T4.MA)>0
          AND T4.ISAPS=1
          AND T3.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=v_ARRAY(ITEM.V_STT).V_ANHUY_SUA+ITEM.V_ANHUY_SUA;
  END LOOP;
  -- Lao động
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN ALD_PHUCTHAM_BANAN T3 ON T3.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T3.KETQUAPHUCTHAMID=T4.ID
    WHERE INSTR('02,03,04,05,06,11,12,13,14,15,16,17',T4.MA)>0
          AND T4.ISALD=1
          AND T3.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=v_ARRAY(ITEM.V_STT).V_ANHUY_SUA+ITEM.V_ANHUY_SUA;
  END LOOP;
  -- Tính án hủy, sửa theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY_SUA
    FROM TABLE(v_ARRAY) T1
	INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
	WHERE T2.XXGDTTT_ISKETQUA = 1
		AND T2.XXGDTTT_KETQUAID IN (1330,1264,1265,1268,1269,1270,1319,1322,1323,1327,1328,1372,1373,1374,1376)
		AND XXGDTTT_NGAYQD BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
	GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANHUY_SUA:=v_ARRAY(ITEM.V_STT).V_ANHUY_SUA+ITEM.V_ANHUY_SUA;
	END LOOP;
  --***** Tính tổng án chưa giải quyết xong trong kỳ = tổng thụ lý - đã giải quyết trong kỳ --> V_CHUA_GQ
  --***** Tính tổng án quá hạn luật định trong kỳ --> V_QUAHAN
  -- Hình sự -- Không tính quá hạn
  -- Dân sự
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN ADS_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN:=v_ARRAY(ITEM.V_STT).V_QUAHAN + ITEM.V_QUAHAN;
  END LOOP;
  -- Hành chính
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHC_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN:=v_ARRAY(ITEM.V_STT).V_QUAHAN + ITEM.V_QUAHAN;
  END LOOP;
  -- Hôn nhân
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHN_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN:=v_ARRAY(ITEM.V_STT).V_QUAHAN + ITEM.V_QUAHAN;
  END LOOP;
  -- Kinh tế
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AKT_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN:=v_ARRAY(ITEM.V_STT).V_QUAHAN + ITEM.V_QUAHAN;
  END LOOP;
  -- Phá sản -- Không tính quá hạn
  -- Lao động
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN ALD_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN:=v_ARRAY(ITEM.V_STT).V_QUAHAN + ITEM.V_QUAHAN;
  END LOOP;
  --***** Tính tổng án tổ chức phiên tòa rút kinh nghiệm trong kỳ --> V_RUTKN
  -- Thẩm phán trong kỳ --> V_RUTKN_THAMPHAN
  -- Hình sự
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_RUTKN,COUNT(DISTINCT T3.CANBOID) V_RUTKN_THAMPHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN (SELECT T4.VUANID,T4.CANBOID FROM AHS_PHUCTHAM_HDXX T4
                WHERE INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T4.MAVAITRO)>0
                ) T3 ON T2.ID=T3.VUANID
    INNER JOIN AHS_SAUXETXU SXX ON SXX.VUANID=T2.ID
    WHERE SXX.PT_NGAYRUT BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND SXX.PT_ISRUTKN=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_RUTKN:=ITEM.V_RUTKN;
    v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN:=ITEM.V_RUTKN_THAMPHAN;
  END LOOP;
  -- Dân sự
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_RUTKN,COUNT(DISTINCT T3.CANBOID) V_RUTKN_THAMPHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN (SELECT T4.DONID,T4.CANBOID FROM ADS_PHUCTHAM_HDXX T4
                WHERE INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T4.MAVAITRO)>0
                ) T3 ON T2.ID=T3.DONID
    INNER JOIN ADS_SAUXETXU SXX ON SXX.VUANID=T2.ID
    WHERE SXX.PT_NGAYRUT BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND SXX.PT_ISRUTKN=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_RUTKN:=v_ARRAY(ITEM.V_STT).V_RUTKN+ITEM.V_RUTKN;
    v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN:=v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN+ITEM.V_RUTKN_THAMPHAN;
  END LOOP;
  -- Hành chính
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_RUTKN,COUNT(DISTINCT T3.CANBOID) V_RUTKN_THAMPHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN (SELECT T4.DONID,T4.CANBOID FROM AHC_PHUCTHAM_HDXX T4
                WHERE INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T4.MAVAITRO)>0
                ) T3 ON T2.ID=T3.DONID
    INNER JOIN AHC_SAUXETXU SXX ON SXX.VUANID=T2.ID
    WHERE SXX.PT_NGAYRUT BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND SXX.PT_ISRUTKN=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_RUTKN:=v_ARRAY(ITEM.V_STT).V_RUTKN+ITEM.V_RUTKN;
    v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN:=v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN+ITEM.V_RUTKN_THAMPHAN;
  END LOOP;
  -- Hôn nhân
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_RUTKN,COUNT(DISTINCT T3.CANBOID) V_RUTKN_THAMPHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN (SELECT T4.DONID,T4.CANBOID FROM AHN_PHUCTHAM_HDXX T4
                WHERE INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T4.MAVAITRO)>0
                ) T3 ON T2.ID=T3.DONID
    INNER JOIN AHN_SAUXETXU SXX ON SXX.VUANID=T2.ID
    WHERE SXX.PT_NGAYRUT BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND SXX.PT_ISRUTKN=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_RUTKN:=v_ARRAY(ITEM.V_STT).V_RUTKN+ITEM.V_RUTKN;
    v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN:=v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN+ITEM.V_RUTKN_THAMPHAN;
  END LOOP;
  -- Kinh tế
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_RUTKN,COUNT(DISTINCT T3.CANBOID) V_RUTKN_THAMPHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN (SELECT T4.DONID,T4.CANBOID FROM AKT_PHUCTHAM_HDXX T4
                WHERE INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T4.MAVAITRO)>0
                ) T3 ON T2.ID=T3.DONID
    INNER JOIN AKT_SAUXETXU SXX ON SXX.VUANID=T2.ID
    WHERE SXX.PT_NGAYRUT BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND SXX.PT_ISRUTKN=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_RUTKN:=v_ARRAY(ITEM.V_STT).V_RUTKN+ITEM.V_RUTKN;
    v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN:=v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN+ITEM.V_RUTKN_THAMPHAN;
  END LOOP;
  -- Phá sản
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_RUTKN,COUNT(DISTINCT T3.CANBOID) V_RUTKN_THAMPHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN (SELECT T4.DONID,T4.CANBOID FROM APS_PHUCTHAM_HDXX T4
                WHERE INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T4.MAVAITRO)>0
                ) T3 ON T2.ID=T3.DONID
    INNER JOIN APS_SAUXETXU SXX ON SXX.VUANID=T2.ID
    WHERE SXX.PT_NGAYRUT BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND SXX.PT_ISRUTKN=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_RUTKN:=v_ARRAY(ITEM.V_STT).V_RUTKN+ITEM.V_RUTKN;
    v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN:=v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN+ITEM.V_RUTKN_THAMPHAN;
  END LOOP;
  -- Lao động
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_RUTKN,COUNT(DISTINCT T3.CANBOID) V_RUTKN_THAMPHAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN (SELECT T4.DONID,T4.CANBOID FROM ALD_PHUCTHAM_HDXX T4
                WHERE INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T4.MAVAITRO)>0
                ) T3 ON T2.ID=T3.DONID
    INNER JOIN ALD_SAUXETXU SXX ON SXX.VUANID=T2.ID
    WHERE SXX.PT_NGAYRUT BETWEEN vHienTai_TuNgay AND vHienTai_DenNgay
          AND SXX.PT_ISRUTKN=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_RUTKN:=v_ARRAY(ITEM.V_STT).V_RUTKN+ITEM.V_RUTKN;
    v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN:=v_ARRAY(ITEM.V_STT).V_RUTKN_THAMPHAN+ITEM.V_RUTKN_THAMPHAN;
  END LOOP;
END;

PROCEDURE FILL_GSTP_HOME_THAMPHAN
(
  v_ARRAY IN OUT GSTP_HOME_THAMPHAN_T,
  vTuNgay IN DATE,
  vDenNgay IN DATE
)AS
  vGroupChucDanhID NUMBER;
  vDayHetNhiemKy NUMBER DEFAULT 60;--> Trước 60 ngày so với ngày kết thúc nhiệm kỳ sẽ cảnh báo sắp hết nhiệm kỳ
  vNghiCongTac NUMBER DEFAULT 0;
  vDangCongTac NUMBER DEFAULT 1;
  vDungXetXu NUMBER DEFAULT 3;
BEGIN
  SELECT ID INTO vGroupChucDanhID FROM DM_DATAGROUP where MA='CHUCDANH';
  -- Tổng số Thẩm phán đang công tác -- V_TP_DANGCONGTAC
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(T2.ID) V_TP_DANGCONGTAC 
    FROM TABLE(v_ARRAY) T1
    INNER JOIN DM_CANBO T2 ON T1.V_TOAAN=T2.TOAANID
    INNER JOIN DM_DATAITEM T3 ON T3.ID=T2.CHUCDANHID
    WHERE T2.HIEULUC=vDangCongTac
      AND T3.GROUPID=vGroupChucDanhID
      AND INSTR('TPSC,TPTC,TPCC',T3.MA)>0 --> Thẩm phán
--      AND (
--            T2.NGAYKETTHUC BETWEEN vTuNgay AND vDenNgay
--            OR
--            vDenNgay BETWEEN T2.NGAYBONHIEM AND T2.NGAYKETTHUC
--          )
    GROUP BY T1.V_STT
   ) LOOP
    v_ARRAY(ITEM.V_STT).V_TP_DANGCONGTAC:=ITEM.V_TP_DANGCONGTAC;
   END LOOP;
   
   -- Tổng số Thẩm phán sắp hết nhiệm kỳ (còn dưới 2 tháng) -- V_TP_NHIEMKY
   FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(T2.ID) V_TP_NHIEMKY 
    FROM TABLE(v_ARRAY) T1
    INNER JOIN DM_CANBO T2 ON T1.V_TOAAN=T2.TOAANID
    INNER JOIN DM_DATAITEM T3 ON T3.ID=T2.CHUCDANHID
    WHERE T2.HIEULUC=vDangCongTac
      AND T3.GROUPID=vGroupChucDanhID
      AND INSTR('TPSC,TPTC,TPCC',T3.MA)>0 --> Thẩm phán
--      AND (
--            T2.NGAYKETTHUC BETWEEN vTuNgay AND vDenNgay
--            OR
--            vDenNgay BETWEEN T2.NGAYBONHIEM AND T2.NGAYKETTHUC
--          )
      AND ABS(TRUNC(SYSDATE - T2.NGAYKETTHUC))<=vDayHetNhiemKy
    GROUP BY T1.V_STT
   ) LOOP
    v_ARRAY(ITEM.V_STT).V_TP_NHIEMKY:=ITEM.V_TP_NHIEMKY;
   END LOOP;
   
   -- Tổng số TP bị dừng xét xử/ xử lý kỷ luật -- V_TP_DUNG_XETXU
   FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(T2.ID) V_TP_DUNG_XETXU 
    FROM TABLE(v_ARRAY) T1
    INNER JOIN DM_CANBO T2 ON T1.V_TOAAN=T2.TOAANID
    INNER JOIN DM_DATAITEM T3 ON T3.ID=T2.CHUCDANHID
    WHERE T2.HIEULUC=vDungXetXu
      AND T3.GROUPID=vGroupChucDanhID
      AND INSTR('TPSC,TPTC,TPCC',T3.MA)>0 --> Thẩm phán
--      AND (
--            T2.NGAYKETTHUC BETWEEN vTuNgay AND vDenNgay
--            OR
--            vDenNgay BETWEEN T2.NGAYBONHIEM AND T2.NGAYKETTHUC
--          )
    GROUP BY T1.V_STT
   ) LOOP
    v_ARRAY(ITEM.V_STT).V_TP_DUNG_XETXU:=ITEM.V_TP_DUNG_XETXU;
   END LOOP;
   
   -- Tổng số TP có đơn khiếu nại tố cáo -- V_TP_KHIEUNAI_TOCAO
   -- Tổng số TP có án bị hủy, sửa -- V_TP_SUAHUY
   FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T.CANBOID) V_TP_SUAHUY 
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (--Hình sự
                SELECT DISTINCT T1.TOAANID,T2.CANBOID FROM AHS_VUAN T1
                INNER JOIN AHS_SOTHAM_HDXX T2 ON T2.VUANID=T1.ID
                INNER JOIN DM_CANBO T3 ON T3.ID=T2.CANBOID AND T3.TOAANID=T1.TOAANID
                INNER JOIN AHS_PHUCTHAM_BANAN T4 ON T4.VUANID=T1.ID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
                WHERE INSTR('02,05,16,17,03,04,06,13,14',T5.MA)>0 -- kết luận phúc hủy, sửa BA/QD sơ thẩm
                      AND (T4.NGAYBANAN BETWEEN vTuNgay AND vDenNgay)
                      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0 --> Thẩm phán
                UNION
                -- Dân sự
                SELECT DISTINCT T1.TOAANID,T2.CANBOID FROM ADS_DON T1
                INNER JOIN ADS_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
                INNER JOIN DM_CANBO T3 ON T3.ID=T2.CANBOID AND T3.TOAANID=T1.TOAANID
                INNER JOIN ADS_PHUCTHAM_BANAN T4 ON T4.DONID=T1.ID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
                WHERE INSTR('02,05,16,17,03,04,06,13,14',T5.MA)>0 -- kết luận phúc hủy, sửa BA/QD sơ thẩm
                      AND (T4.NGAYTUYENAN BETWEEN vTuNgay AND vDenNgay)
                      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0 --> Thẩm phán
                UNION
                -- Hành chính
                SELECT DISTINCT T1.TOAANID,T2.CANBOID FROM AHC_DON T1
                INNER JOIN AHC_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
                INNER JOIN DM_CANBO T3 ON T3.ID=T2.CANBOID AND T3.TOAANID=T1.TOAANID
                INNER JOIN AHC_PHUCTHAM_BANAN T4 ON T4.DONID=T1.ID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
                WHERE INSTR('02,05,16,17,03,04,06,13,14',T5.MA)>0 -- kết luận phúc hủy, sửa BA/QD sơ thẩm
                      AND (T4.NGAYTUYENAN BETWEEN vTuNgay AND vDenNgay)
                      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0 --> Thẩm phán
                UNION
                -- Hôn nhân
                SELECT DISTINCT T1.TOAANID,T2.CANBOID FROM AHN_DON T1
                INNER JOIN AHN_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
                INNER JOIN DM_CANBO T3 ON T3.ID=T2.CANBOID AND T3.TOAANID=T1.TOAANID
                INNER JOIN AHN_PHUCTHAM_BANAN T4 ON T4.DONID=T1.ID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
                WHERE INSTR('02,05,16,17,03,04,06,13,14',T5.MA)>0 -- kết luận phúc hủy, sửa BA/QD sơ thẩm
                      AND (T4.NGAYTUYENAN BETWEEN vTuNgay AND vDenNgay)
                      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0 --> Thẩm phán
                UNION
                -- Kinh tế
                SELECT DISTINCT T1.TOAANID,T2.CANBOID FROM AKT_DON T1
                INNER JOIN AKT_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
                INNER JOIN DM_CANBO T3 ON T3.ID=T2.CANBOID AND T3.TOAANID=T1.TOAANID
                INNER JOIN AKT_PHUCTHAM_BANAN T4 ON T4.DONID=T1.ID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
                WHERE INSTR('02,05,16,17,03,04,06,13,14',T5.MA)>0 -- kết luận phúc hủy, sửa BA/QD sơ thẩm
                      AND (T4.NGAYTUYENAN BETWEEN vTuNgay AND vDenNgay)
                      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0 --> Thẩm phán
                UNION
                -- Phá sản
                SELECT DISTINCT T1.TOAANID,T2.CANBOID FROM APS_DON T1
                INNER JOIN APS_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
                INNER JOIN DM_CANBO T3 ON T3.ID=T2.CANBOID AND T3.TOAANID=T1.TOAANID
                INNER JOIN APS_PHUCTHAM_BANAN T4 ON T4.DONID=T1.ID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
                WHERE INSTR('02,05,16,17,03,04,06,13,14',T5.MA)>0 -- kết luận phúc hủy, sửa BA/QD sơ thẩm
                      AND (T4.NGAYTUYENAN BETWEEN vTuNgay AND vDenNgay)
                      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0 --> Thẩm phán
                UNION
                -- Lao động
                SELECT DISTINCT T1.TOAANID,T2.CANBOID FROM ALD_DON T1
                INNER JOIN ALD_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
                INNER JOIN DM_CANBO T3 ON T3.ID=T2.CANBOID AND T3.TOAANID=T1.TOAANID
                INNER JOIN ALD_PHUCTHAM_BANAN T4 ON T4.DONID=T1.ID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
                WHERE INSTR('02,05,16,17,03,04,06,13,14',T5.MA)>0 -- kết luận phúc hủy, sửa BA/QD sơ thẩm
                      AND (T4.NGAYTUYENAN BETWEEN vTuNgay AND vDenNgay)
                      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0 --> Thẩm phán
                UNION
                -- XLHC
                SELECT DISTINCT T1.TOAANID,T2.CANBOID FROM XLHC_DON T1
                INNER JOIN XLHC_SOTHAM_HDXX T2 ON T2.DONID=T1.ID
                INNER JOIN DM_CANBO T3 ON T3.ID=T2.CANBOID AND T3.TOAANID=T1.TOAANID
                INNER JOIN XLHC_PHUCTHAM_BANAN T4 ON T4.DONID=T1.ID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
                WHERE INSTR('02,05,16,17,03,04,06,13,14',T5.MA)>0 -- kết luận phúc hủy, sửa BA/QD sơ thẩm
                      AND (T4.NGAYTUYENAN BETWEEN vTuNgay AND vDenNgay)
                      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0 --> Thẩm phán 
                ) T ON T.TOAANID=T1.V_TOAAN
    GROUP BY T1.V_STT
   ) LOOP
    v_ARRAY(ITEM.V_STT).V_TP_SUAHUY:=ITEM.V_TP_SUAHUY;
   END LOOP;
   
   -- Tổng số TP có án bị hủy, sửa lớn hơn %(QĐ120) -- V_TP_SUAHUY_QD120
END;
PROCEDURE FILL_GSTP_HOME_CONGBOBAQD
