  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(T2.ID) V_DAXETXU_NAMHIENTAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_SOTHAM_BANAN T2 ON T2.TOAANID=T1.V_TOAAN
