  -- -- Phá sản sơ thẩm
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(T2.ID) V_DAXETXU_NAMTRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_SOTHAM_BANAN T2 ON T2.TOAANID=T1.V_TOAAN
    WHERE T2.NGAYTUYENAN BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
    GROUP BY T1.V_STT
  ) LOOP
    v_ARRAY(ITEM.V_STT).V_DAXETXU_NAMTRUOC:=v_ARRAY(ITEM.V_STT).V_DAXETXU_NAMTRUOC+ITEM.V_DAXETXU_NAMTRUOC;
  END LOOP;
  -- -- Phá sản phúc thẩm
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(T2.ID) V_DAXETXU_NAMTRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_PHUCTHAM_BANAN T2 ON T2.TOAANID=T1.V_TOAAN
    WHERE T2.NGAYTUYENAN BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
    GROUP BY T1.V_STT
  ) LOOP
    v_ARRAY(ITEM.V_STT).V_DAXETXU_NAMTRUOC:=v_ARRAY(ITEM.V_STT).V_DAXETXU_NAMTRUOC+ITEM.V_DAXETXU_NAMTRUOC;
  END LOOP;
  -- -- XLHC sơ thẩm
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(T2.ID) V_DAXETXU_NAMTRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN XLHC_SOTHAM_BANAN T2 ON T2.TOAANID=T1.V_TOAAN
    WHERE T2.NGAYTUYENAN BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
    GROUP BY T1.V_STT
  ) LOOP
    v_ARRAY(ITEM.V_STT).V_DAXETXU_NAMTRUOC:=v_ARRAY(ITEM.V_STT).V_DAXETXU_NAMTRUOC+ITEM.V_DAXETXU_NAMTRUOC;
  END LOOP;
  -- -- XLHC phúc thẩm
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(T2.ID) V_DAXETXU_NAMTRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN XLHC_PHUCTHAM_BANAN T2 ON T2.TOAANID=T1.V_TOAAN
    WHERE T2.NGAYTUYENAN BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
    GROUP BY T1.V_STT
  ) LOOP
    v_ARRAY(ITEM.V_STT).V_DAXETXU_NAMTRUOC:=v_ARRAY(ITEM.V_STT).V_DAXETXU_NAMTRUOC+ITEM.V_DAXETXU_NAMTRUOC;
  END LOOP;
  -- Tổng số BA/QĐ có kháng cáo, kháng nghị -- Năm hiện tại -- V_KCKN_NAMHIENTAI
  -- -- Hình sự kháng cáo,kháng nghị
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT DECODE(T3.VUANID,NULL,DECODE(T4.VUANID,NULL,NULL,T4.VUANID),T3.VUANID)) V_KCKN_NAMHIENTAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN AHS_SOTHAM_KHANGCAO T3 ON T3.VUANID=T2.ID AND (T3.NGAYKHANGCAO BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    LEFT JOIN AHS_SOTHAM_KHANGNGHI T4 ON T4.VUANID=T2.ID AND (T4.NGAYKN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  ) LOOP
    v_ARRAY(ITEM.V_STT).V_KCKN_NAMHIENTAI:=ITEM.V_KCKN_NAMHIENTAI;
  END LOOP;
  -- -- Dân sự kháng cáo,kháng nghị
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT DECODE(T3.DONID,NULL,DECODE(T4.DONID,NULL,NULL,T4.DONID),T3.DONID)) V_KCKN_NAMHIENTAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN ADS_SOTHAM_KHANGCAO T3 ON T3.DONID=T2.ID AND (T3.NGAYKHANGCAO BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    LEFT JOIN ADS_SOTHAM_KHANGNGHI T4 ON T4.DONID=T2.ID AND (T4.NGAYKN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  ) LOOP
    v_ARRAY(ITEM.V_STT).V_KCKN_NAMHIENTAI:=v_ARRAY(ITEM.V_STT).V_KCKN_NAMHIENTAI+ITEM.V_KCKN_NAMHIENTAI;
  END LOOP;
  -- -- Hành chính kháng cáo,kháng nghị
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT DECODE(T3.DONID,NULL,DECODE(T4.DONID,NULL,NULL,T4.DONID),T3.DONID)) V_KCKN_NAMHIENTAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN AHC_SOTHAM_KHANGCAO T3 ON T3.DONID=T2.ID AND (T3.NGAYKHANGCAO BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    LEFT JOIN AHC_SOTHAM_KHANGNGHI T4 ON T4.DONID=T2.ID AND (T4.NGAYKN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  ) LOOP
    v_ARRAY(ITEM.V_STT).V_KCKN_NAMHIENTAI:=v_ARRAY(ITEM.V_STT).V_KCKN_NAMHIENTAI+ITEM.V_KCKN_NAMHIENTAI;
  END LOOP;
  -- -- HNGD kháng cáo,kháng nghị
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT DECODE(T3.DONID,NULL,DECODE(T4.DONID,NULL,NULL,T4.DONID),T3.DONID)) V_KCKN_NAMHIENTAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN AHN_SOTHAM_KHANGCAO T3 ON T3.DONID=T2.ID AND (T3.NGAYKHANGCAO BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    LEFT JOIN AHN_SOTHAM_KHANGNGHI T4 ON T4.DONID=T2.ID AND (T4.NGAYKN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  ) LOOP
    v_ARRAY(ITEM.V_STT).V_KCKN_NAMHIENTAI:=v_ARRAY(ITEM.V_STT).V_KCKN_NAMHIENTAI+ITEM.V_KCKN_NAMHIENTAI;
  END LOOP;
  -- -- Kinh tế kháng cáo,kháng nghị
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT DECODE(T3.DONID,NULL,DECODE(T4.DONID,NULL,NULL,T4.DONID),T3.DONID)) V_KCKN_NAMHIENTAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON T2 ON T2.TOAANID=T1.V_TOAAN
