    LEFT JOIN AKT_SOTHAM_KHANGNGHI T4 ON T4.DONID=T2.ID AND (T4.NGAYKN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  ) LOOP
    v_ARRAY(ITEM.V_STT).V_KCKN_NAMHIENTAI:=v_ARRAY(ITEM.V_STT).V_KCKN_NAMHIENTAI+ITEM.V_KCKN_NAMHIENTAI;
  END LOOP;
  -- -- Lao động kháng cáo,kháng nghị
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT DECODE(T3.DONID,NULL,DECODE(T4.DONID,NULL,NULL,T4.DONID),T3.DONID)) V_KCKN_NAMHIENTAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN ALD_SOTHAM_KHANGCAO T3 ON T3.DONID=T2.ID AND (T3.NGAYKHANGCAO BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    LEFT JOIN ALD_SOTHAM_KHANGNGHI T4 ON T4.DONID=T2.ID AND (T4.NGAYKN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  ) LOOP
    v_ARRAY(ITEM.V_STT).V_KCKN_NAMHIENTAI:=v_ARRAY(ITEM.V_STT).V_KCKN_NAMHIENTAI+ITEM.V_KCKN_NAMHIENTAI;
  END LOOP;
  -- -- Phá sản kháng cáo,kháng nghị
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT DECODE(T3.DONID,NULL,DECODE(T4.DONID,NULL,NULL,T4.DONID),T3.DONID)) V_KCKN_NAMHIENTAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN APS_SOTHAM_KHANGCAO T3 ON T3.DONID=T2.ID AND (T3.NGAYKHANGCAO BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    LEFT JOIN APS_SOTHAM_KHANGNGHI T4 ON T4.DONID=T2.ID AND (T4.NGAYKN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  ) LOOP
