    LEFT JOIN AHS_SOTHAM_KHANGNGHI T4 ON T4.VUANID=T2.ID AND (T4.NGAYKN BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy)
