  END LOOP;
  -- -- Hành chính kháng cáo,kháng nghị
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT DECODE(T3.DONID,NULL,DECODE(T4.DONID,NULL,NULL,T4.DONID),T3.DONID)) V_KCKN_NAMTRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN AHC_SOTHAM_KHANGCAO T3 ON T3.DONID=T2.ID AND (T3.NGAYKHANGCAO BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy)
    LEFT JOIN AHC_SOTHAM_KHANGNGHI T4 ON T4.DONID=T2.ID AND (T4.NGAYKN BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy)
    GROUP BY T1.V_STT
  ) LOOP
    v_ARRAY(ITEM.V_STT).V_KCKN_NAMTRUOC:=v_ARRAY(ITEM.V_STT).V_KCKN_NAMTRUOC+ITEM.V_KCKN_NAMTRUOC;
  END LOOP;
  -- -- HNGD kháng cáo,kháng nghị
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT DECODE(T3.DONID,NULL,DECODE(T4.DONID,NULL,NULL,T4.DONID),T3.DONID)) V_KCKN_NAMTRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN AHN_SOTHAM_KHANGCAO T3 ON T3.DONID=T2.ID AND (T3.NGAYKHANGCAO BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy)
    LEFT JOIN AHN_SOTHAM_KHANGNGHI T4 ON T4.DONID=T2.ID AND (T4.NGAYKN BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy)
    GROUP BY T1.V_STT
  ) LOOP
    v_ARRAY(ITEM.V_STT).V_KCKN_NAMTRUOC:=v_ARRAY(ITEM.V_STT).V_KCKN_NAMTRUOC+ITEM.V_KCKN_NAMTRUOC;
  END LOOP;
  -- -- Kinh tế kháng cáo,kháng nghị
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT DECODE(T3.DONID,NULL,DECODE(T4.DONID,NULL,NULL,T4.DONID),T3.DONID)) V_KCKN_NAMTRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN AKT_SOTHAM_KHANGCAO T3 ON T3.DONID=T2.ID AND (T3.NGAYKHANGCAO BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy)
    LEFT JOIN AKT_SOTHAM_KHANGNGHI T4 ON T4.DONID=T2.ID AND (T4.NGAYKN BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy)
    GROUP BY T1.V_STT
  ) LOOP
    v_ARRAY(ITEM.V_STT).V_KCKN_NAMTRUOC:=v_ARRAY(ITEM.V_STT).V_KCKN_NAMTRUOC+ITEM.V_KCKN_NAMTRUOC;
  END LOOP;
  -- -- Lao động kháng cáo,kháng nghị
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT DECODE(T3.DONID,NULL,DECODE(T4.DONID,NULL,NULL,T4.DONID),T3.DONID)) V_KCKN_NAMTRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN ALD_SOTHAM_KHANGCAO T3 ON T3.DONID=T2.ID AND (T3.NGAYKHANGCAO BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy)
    LEFT JOIN ALD_SOTHAM_KHANGNGHI T4 ON T4.DONID=T2.ID AND (T4.NGAYKN BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy)
