    LEFT JOIN APS_SOTHAM_KHANGCAO T3 ON T3.DONID=T2.ID AND (T3.NGAYKHANGCAO BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy)
    LEFT JOIN APS_SOTHAM_KHANGNGHI T4 ON T4.DONID=T2.ID AND (T4.NGAYKN BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy)
    GROUP BY T1.V_STT
  ) LOOP
    v_ARRAY(ITEM.V_STT).V_KCKN_NAMTRUOC:=v_ARRAY(ITEM.V_STT).V_KCKN_NAMTRUOC+ITEM.V_KCKN_NAMTRUOC;
