END;
PROCEDURE FILL_GSTP_PAGE2_SOTHAM_HINHSU
(
  v_ARRAY IN OUT GSTP_PAGE2_SOTHAM_HS_T,
  vDate_Nam_HienTai_DauKy IN DATE,
  vDate_Nam_HienTai_CuoiKy IN DATE,
  vDate_Nam_Truoc_DauKy IN DATE,
  vDate_Nam_Truoc_CuoiKy IN DATE
)AS
BEGIN
  -- TỔNG THỤ LÝ -- Thụ lý mới + Chưa giải quyết kỳ trước -- Vụ -- V_TONGTHULY_VU
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY_VU
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_TONGTHULY_VU FROM AHS_VUAN T2
                INNER JOIN AHS_SOTHAM_THULY T3 ON T2.ID=T3.VUANID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY_VU:=ITEM.V_TONGTHULY_VU;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHS_SOTHAM_THULY T3 ON T3.VUANID=T2.ID
    LEFT JOIN ( SELECT T1.VUANID,T2.MA FROM AHS_SOTHAM_QUYETDINH_VUAN T1 
                INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              ) QD ON T2.ID =QD.VUANID 
    LEFT JOIN AHS_SOTHAM_BANAN BA ON T2.ID =BA.VUANID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.VUANID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_TONGTHULY_VU:=v_ARRAY(ITEM.V_STT).V_TONGTHULY_VU + ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- TỔNG THỤ LÝ -- Bị cáo = Thụ lý mới (bị cáo) + Chưa giải quyết kỳ trước (bị cáo) -- V_TONGTHULY_BICAO
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY_BICAO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(T4.ID) V_TONGTHULY_BICAO FROM AHS_VUAN T2
                INNER JOIN AHS_SOTHAM_THULY T3 ON T2.ID=T3.VUANID
                INNER JOIN AHS_BICANBICAO T4 ON T4.VUANID=T2.ID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY_BICAO:=ITEM.V_TONGTHULY_BICAO;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(BC.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHS_SOTHAM_THULY T3 ON T3.VUANID=T2.ID
    INNER JOIN AHS_BICANBICAO BC ON BC.VUANID=T2.ID 
    LEFT JOIN ( SELECT T1.VUANID,T2.MA FROM AHS_SOTHAM_QUYETDINH_VUAN T1 
                INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              ) QD ON T2.ID =QD.VUANID 
    LEFT JOIN AHS_SOTHAM_BANAN BA ON T2.ID =BA.VUANID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.VUANID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY_BICAO:=v_ARRAY(ITEM.V_STT).V_TONGTHULY_BICAO+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Chuyển hồ sơ vụ án -- Vụ -- V_GQ_CHUYENHOSO_VU
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_CHUYENHOSO_VU
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(T2.ID) V_GQ_CHUYENHOSO_VU FROM AHS_VUAN T2
                INNER JOIN AHS_CHUYEN_NHAN_AN T3 ON T2.ID=T3.VUANID AND T3.TOACHUYENID=T2.TOAANID
                WHERE T3.NGAYGIAO BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_CHUYENHOSO_VU:=ITEM.V_GQ_CHUYENHOSO_VU;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Chuyển hồ sơ vụ án -- Bị cáo -- V_GQ_CHUYENHOSO_BICAO
  FOR ITEM IN
  (
    SELECT T1.V_STT, T5.V_GQ_CHUYENHOSO_BICAO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(T4.ID) V_GQ_CHUYENHOSO_BICAO FROM AHS_VUAN T2
                INNER JOIN AHS_CHUYEN_NHAN_AN T3 ON T2.ID=T3.VUANID AND T3.TOACHUYENID=T2.TOAANID
                INNER JOIN AHS_BICANBICAO T4 ON T4.VUANID=T2.ID
                WHERE T3.NGAYGIAO BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T5 ON T5.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_CHUYENHOSO_BICAO:=ITEM.V_GQ_CHUYENHOSO_BICAO;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Đình chỉ -- Vụ -- V_GQ_DINHCHI_VU
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_DINHCHI_VU
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_GQ_DINHCHI_VU FROM AHS_VUAN T2
                INNER JOIN AHS_SOTHAM_QUYETDINH_VUAN T3 ON T2.ID=T3.VUANID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_DINHCHI_VU:=ITEM.V_GQ_DINHCHI_VU;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Đình chỉ -- Bị cáo -- V_GQ_DINHCHI_BICAO
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_DINHCHI_BICAO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(T5.ID) V_GQ_DINHCHI_BICAO FROM AHS_VUAN T2
                INNER JOIN AHS_SOTHAM_QUYETDINH_VUAN T3 ON T2.ID=T3.VUANID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN AHS_BICANBICAO T5 ON T5.VUANID=T2.ID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_DINHCHI_BICAO:=ITEM.V_GQ_DINHCHI_BICAO;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Trả hồ sơ VKS -- Vụ -- V_GQ_TRAHOSOVKS_VU
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_TRAHOSOVKS_VU
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_GQ_TRAHOSOVKS_VU FROM AHS_VUAN T2
                INNER JOIN AHS_SOTHAM_QUYETDINH_VUAN T3 ON T2.ID=T3.VUANID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='TRAHS'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TRAHOSOVKS_VU:=ITEM.V_GQ_TRAHOSOVKS_VU;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Trả hồ sơ VKS -- Bị cáo -- V_GQ_TRAHOSOVKS_BICAO
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_DINHCHI_BICAO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(T5.ID) V_GQ_DINHCHI_BICAO FROM AHS_VUAN T2
                INNER JOIN AHS_SOTHAM_QUYETDINH_VUAN T3 ON T2.ID=T3.VUANID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN AHS_BICANBICAO T5 ON T5.VUANID=T2.ID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='TRAHS'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_DINHCHI_BICAO:=ITEM.V_GQ_DINHCHI_BICAO;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Xét xử -- Vụ -- V_GQ_XETXU_VU
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(VA.ID) V_GQ_XETXU_VU
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN VA ON VA.TOAANID=T1.V_TOAAN
    INNER JOIN AHS_SOTHAM_BANAN BA ON BA.VUANID=VA.ID
    WHERE BA.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_XETXU_VU:=ITEM.V_GQ_XETXU_VU;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Xét xử -- Bị cáo -- V_GQ_XETXU_BICAO
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(BC.ID) V_GQ_XETXU_BICAO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN VA ON VA.TOAANID=T1.V_TOAAN
    INNER JOIN AHS_SOTHAM_BANAN BA ON BA.VUANID=VA.ID
    INNER JOIN AHS_BICANBICAO BC ON BC.VUANID=VA.ID
    WHERE BA.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_XETXU_BICAO:=ITEM.V_GQ_XETXU_BICAO;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỔNG SỐ GQ -- Vụ -- V_GQ_TONGGQ_VU
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ_VU
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAANID,COUNT(DISTINCT VA.ID) V_QD FROM AHS_VUAN VA
                INNER JOIN AHS_SOTHAM_QUYETDINH_VUAN QD ON QD.VUANID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAANID
                ) T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAANID,COUNT(VA.ID) V_BA FROM AHS_VUAN VA
                INNER JOIN AHS_SOTHAM_BANAN BA ON BA.VUANID=VA.ID
                WHERE BA.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAANID
                ) T3 ON T3.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ_VU:=ITEM.V_GQ_TONGGQ_VU;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỔNG SỐ GQ -- Bị cáo -- V_GQ_TONGGQ_BICAO
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ_BICAO
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAANID,COUNT(BC.ID) V_QD FROM AHS_VUAN VA
                INNER JOIN AHS_SOTHAM_QUYETDINH_VUAN QD ON QD.VUANID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                INNER JOIN AHS_BICANBICAO BC ON BC.VUANID=VA.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAANID
                ) T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAANID,COUNT(BC.ID) V_BA FROM AHS_VUAN VA
                INNER JOIN AHS_SOTHAM_BANAN BA ON BA.VUANID=VA.ID
                INNER JOIN AHS_BICANBICAO BC ON BC.VUANID=VA.ID
                WHERE BA.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAANID
                ) T3 ON T3.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ_BICAO:=ITEM.V_GQ_TONGGQ_BICAO;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỶ LỆ GQ -- Vụ -- V_GQ_TYLEGQ_VU
  -- GIẢI QUYẾT ÁN -- TỶ LỆ GQ -- Bị cáo -- V_GQ_TYLEGQ_BICAO
  -- ÁN BỊ HỦY -- V_ANHUY
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_ANHUY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHS_PHUCTHAM_BANAN T4 ON T4.VUANID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('03,04,06,13,14',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND T5.ISAHS=1
          AND (T4.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY:=ITEM.V_ANHUY;
  END LOOP;
  -- Tính án hủy theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
    WHERE T2.XXGDTTT_ISKETQUA = 1
          AND T2.LOAIAN=1 --> án hình sự
          AND T2.XXGDTTT_KETQUAID IN (1262,1263,1268,1269,1270,1322,1327,1328,1374) --> án hủy
          AND XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANHUY:=v_ARRAY(ITEM.V_STT).V_ANHUY+ITEM.V_ANHUY;
	END LOOP;
  -- ÁN BỊ SỬA -- V_ANSUA
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_ANSUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHS_PHUCTHAM_BANAN T4 ON T4.VUANID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('02,05,16,17',T5.MA)>0 -- kết luận phúc sửa BA/QD sơ thẩm
          AND T5.ISAHS=1
          AND (T4.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANSUA:=ITEM.V_ANSUA;
  END LOOP;
  -- Tính án sửa theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANSUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
    WHERE T2.XXGDTTT_ISKETQUA = 1
          AND T2.LOAIAN=1 --> án hình sự
          AND T2.XXGDTTT_KETQUAID IN (1330,1319) --> án sửa
          AND XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANSUA:=v_ARRAY(ITEM.V_STT).V_ANSUA+ITEM.V_ANSUA;
	END LOOP;
  -- CÒN LẠI = Tổng thụ lý - Đã giải quyết -- Vụ -- V_CONLAI_VU
  -- CÒN LẠI -- Bị cáo = Tổng thụ lý (bị cáo) - Đã giải quyết(bị cáo) -- V_CONLAI_BICAO
  -- ÁN QUÁ HẠN LUẬT ĐỊNH CHƯA GQ -- Vụ -- V_QUAHAN_CHUAGQ_VU
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN_CHUAGQ_VU
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHS_SOTHAM_BANAN BA ON T2.ID =BA.VUANID
    WHERE BA.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN_CHUAGQ_VU:=ITEM.V_QUAHAN_CHUAGQ_VU;
  END LOOP;
  -- ÁN QUÁ HẠN LUẬT ĐỊNH CHƯA GQ -- Bị cáo -- V_QUAHAN_CHUAGQ_BICAO
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(BC.ID) V_QUAHAN_CHUAGQ_BICAO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHS_BICANBICAO BC ON BC.VUANID=T2.ID
    INNER JOIN AHS_SOTHAM_BANAN BA ON T2.ID =BA.VUANID
    WHERE BA.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN_CHUAGQ_BICAO:=ITEM.V_QUAHAN_CHUAGQ_BICAO;
  END LOOP;
END;
PROCEDURE FILL_GSTP_PAGE2_SOTHAM_DANSU
(
  v_ARRAY IN OUT GSTP_PAGE2_SOTHAM_DS_T,
  vDate_Nam_HienTai_DauKy IN DATE,
  vDate_Nam_HienTai_CuoiKy IN DATE,
  vDate_Nam_Truoc_DauKy IN DATE,
  vDate_Nam_Truoc_CuoiKy IN DATE
)AS
BEGIN
  -- TỔNG THỤ LÝ = Thụ lý mới + Chưa giải quyết kỳ trước -- V_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_TONGTHULY FROM ADS_DON T2
                INNER JOIN ADS_SOTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=ITEM.V_TONGTHULY;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN ADS_SOTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM ADS_SOTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN ADS_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Chuyển hồ sơ vụ án -- V_GQ_CHUYENHOSO
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_CHUYENHOSO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(T2.ID) V_GQ_CHUYENHOSO FROM ADS_DON T2
                INNER JOIN ADS_CHUYEN_NHAN_AN T3 ON T2.ID=T3.VUANID AND T3.TOACHUYENID=T2.TOAANID
                WHERE T3.NGAYGIAO BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_CHUYENHOSO:=ITEM.V_GQ_CHUYENHOSO;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Đình chỉ -- V_GQ_DINHCHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_DINHCHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_GQ_DINHCHI FROM ADS_DON T2
                INNER JOIN ADS_SOTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_DINHCHI:=ITEM.V_GQ_DINHCHI;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Công nhận thỏa thuận -- V_GQ_CONGNHANTHOATHUAN
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_CONGNHANTHOATHUAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_GQ_CONGNHANTHOATHUAN FROM ADS_DON T2
                INNER JOIN ADS_SOTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='CNTT'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_CONGNHANTHOATHUAN:=ITEM.V_GQ_CONGNHANTHOATHUAN;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Xét xử -- V_GQ_XETXU
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(VA.ID) V_GQ_XETXU
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON VA ON VA.TOAANID=T1.V_TOAAN
    INNER JOIN ADS_SOTHAM_BANAN BA ON BA.DONID=VA.ID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_XETXU:=ITEM.V_GQ_XETXU;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỔNG SỐ GQ -- V_GQ_TONGGQ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAANID,COUNT(DISTINCT VA.ID) V_QD FROM ADS_DON VA
                INNER JOIN ADS_SOTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAANID
                ) T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAANID,COUNT(VA.ID) V_BA FROM ADS_DON VA
                INNER JOIN ADS_SOTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAANID
                ) T3 ON T3.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ:=ITEM.V_GQ_TONGGQ;
  END LOOP;
  -- ÁN BỊ HỦY -- V_ANHUY
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_ANHUY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN ADS_PHUCTHAM_BANAN T4 ON T4.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('03,04,06,13,14',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND T5.ISADS=1
          AND (T4.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY:=ITEM.V_ANHUY;
  END LOOP;
  -- Tính án hủy theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
    WHERE T2.XXGDTTT_ISKETQUA = 1
          AND T2.LOAIAN=2 --> vụ việc dân sự
          AND T2.XXGDTTT_KETQUAID IN (1262,1263,1268,1269,1270,1322,1327,1328,1374) --> án hủy
          AND XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANHUY:=v_ARRAY(ITEM.V_STT).V_ANHUY+ITEM.V_ANHUY;
	END LOOP;
  -- ÁN BỊ SỬA -- V_ANSUA
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_ANSUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN ADS_PHUCTHAM_BANAN T4 ON T4.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('02,05,16,17',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND T5.ISADS=1
          AND (T4.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANSUA:=ITEM.V_ANSUA;
  END LOOP;
  -- Tính án sửa theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANSUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
    WHERE T2.XXGDTTT_ISKETQUA = 1
          AND T2.LOAIAN=2 --> vụ việc dân sự
          AND T2.XXGDTTT_KETQUAID IN (1330,1319) --> án sửa
          AND XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANSUA:=v_ARRAY(ITEM.V_STT).V_ANSUA+ITEM.V_ANSUA;
	END LOOP;
  -- TỔNG SỐ VỤ ÁN CÒN LẠI = Tổng thụ lý - đã giải quyết -- V_CONLAI
  -- ÁN QUÁ HẠN LUẬT ĐỊNH CHƯA GQ -- V_QUAHAN_CHUAGQ
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN_CHUAGQ
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN ADS_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN_CHUAGQ:=ITEM.V_QUAHAN_CHUAGQ;
  END LOOP;
END;
PROCEDURE FILL_GSTP_PAGE2_SOTHAM_HNGD
(
  v_ARRAY IN OUT GSTP_PAGE2_SOTHAM_DS_T,
  vDate_Nam_HienTai_DauKy IN DATE,
  vDate_Nam_HienTai_CuoiKy IN DATE,
  vDate_Nam_Truoc_DauKy IN DATE,
  vDate_Nam_Truoc_CuoiKy IN DATE
)AS
BEGIN
   -- TỔNG THỤ LÝ -- Thụ lý mới + Chưa giải quyết kỳ trước -- V_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_TONGTHULY FROM AHN_DON T2
                INNER JOIN AHN_SOTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=ITEM.V_TONGTHULY;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHN_SOTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM AHN_SOTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN AHN_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Chuyển hồ sơ vụ án -- V_GQ_CHUYENHOSO
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_CHUYENHOSO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(T2.ID) V_GQ_CHUYENHOSO FROM AHN_DON T2
                INNER JOIN AHN_CHUYEN_NHAN_AN T3 ON T2.ID=T3.VUANID AND T3.TOACHUYENID=T2.TOAANID
                WHERE T3.NGAYGIAO BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_CHUYENHOSO:=ITEM.V_GQ_CHUYENHOSO;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Đình chỉ -- V_GQ_DINHCHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_DINHCHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_GQ_DINHCHI FROM AHN_DON T2
                INNER JOIN AHN_SOTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_DINHCHI:=ITEM.V_GQ_DINHCHI;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Công nhận thỏa thuận -- V_GQ_CONGNHANTHOATHUAN
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_CONGNHANTHOATHUAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_GQ_CONGNHANTHOATHUAN FROM AHN_DON T2
                INNER JOIN AHN_SOTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='CNTT'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_CONGNHANTHOATHUAN:=ITEM.V_GQ_CONGNHANTHOATHUAN;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Xét xử -- V_GQ_XETXU
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(VA.ID) V_GQ_XETXU
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON VA ON VA.TOAANID=T1.V_TOAAN
    INNER JOIN AHN_SOTHAM_BANAN BA ON BA.DONID=VA.ID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_XETXU:=ITEM.V_GQ_XETXU;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỔNG SỐ GQ -- V_GQ_TONGGQ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAANID,COUNT(DISTINCT VA.ID) V_QD FROM AHN_DON VA
                INNER JOIN AHN_SOTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAANID
                ) T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAANID,COUNT(VA.ID) V_BA FROM AHN_DON VA
                INNER JOIN AHN_SOTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAANID
                ) T3 ON T3.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ:=ITEM.V_GQ_TONGGQ;
  END LOOP;
  -- ÁN BỊ HỦY -- V_ANHUY
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_ANHUY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHN_PHUCTHAM_BANAN T4 ON T4.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('03,04,06,13,14',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND T5.ISAHN=1
          AND (T4.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY:=ITEM.V_ANHUY;
  END LOOP;
  -- Tính án hủy theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
    WHERE T2.XXGDTTT_ISKETQUA = 1
          AND T2.LOAIAN=3 --> vụ việc hôn nhân gia đình
          AND T2.XXGDTTT_KETQUAID IN (1262,1263,1268,1269,1270,1322,1327,1328,1374) --> án hủy
          AND XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANHUY:=v_ARRAY(ITEM.V_STT).V_ANHUY+ITEM.V_ANHUY;
	END LOOP;
  -- ÁN BỊ SỬA -- V_ANSUA
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_ANSUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHN_PHUCTHAM_BANAN T4 ON T4.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('02,05,16,17',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND T5.ISAHN=1
          AND (T4.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANSUA:=ITEM.V_ANSUA;
  END LOOP;
  -- Tính án sửa theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANSUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
    WHERE T2.XXGDTTT_ISKETQUA = 1
          AND T2.LOAIAN=3 --> vụ việc hôn nhân gia đình
          AND T2.XXGDTTT_KETQUAID IN (1330,1319) --> án sửa
          AND XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANSUA:=v_ARRAY(ITEM.V_STT).V_ANSUA+ITEM.V_ANSUA;
	END LOOP;
  -- TỔNG SỐ VỤ ÁN CÒN LẠI = Tổng thụ lý - Đã giải quyết -- V_CONLAI
  -- ÁN QUÁ HẠN LUẬT ĐỊNH CHƯA GQ -- V_QUAHAN_CHUAGQ
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN_CHUAGQ
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHN_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN_CHUAGQ:=ITEM.V_QUAHAN_CHUAGQ;
  END LOOP;
END;
PROCEDURE FILL_GSTP_PAGE2_SOTHAM_KINHTE
(
  v_ARRAY IN OUT GSTP_PAGE2_SOTHAM_DS_T,
  vDate_Nam_HienTai_DauKy IN DATE,
  vDate_Nam_HienTai_CuoiKy IN DATE,
  vDate_Nam_Truoc_DauKy IN DATE,
  vDate_Nam_Truoc_CuoiKy IN DATE
)AS
BEGIN
  -- Phá sản cộng dồn vào kinh tế
   -- TỔNG THỤ LÝ -- Thụ lý mới + Chưa giải quyết kỳ trước -- V_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_TONGTHULY FROM AKT_DON T2
                INNER JOIN AKT_SOTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=ITEM.V_TONGTHULY;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AKT_SOTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM AKT_SOTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN AKT_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- phá sản
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_TONGTHULY FROM APS_DON T2
                INNER JOIN APS_SOTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_TONGTHULY;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN APS_SOTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM APS_SOTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN APS_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Chuyển hồ sơ vụ án -- V_GQ_CHUYENHOSO
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_CHUYENHOSO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(T2.ID) V_GQ_CHUYENHOSO FROM AKT_DON T2
                INNER JOIN AKT_CHUYEN_NHAN_AN T3 ON T2.ID=T3.VUANID AND T3.TOACHUYENID=T2.TOAANID
                WHERE T3.NGAYGIAO BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_CHUYENHOSO:=ITEM.V_GQ_CHUYENHOSO;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_CHUYENHOSO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(T2.ID) V_GQ_CHUYENHOSO FROM APS_DON T2
                INNER JOIN APS_CHUYEN_NHAN_AN T3 ON T2.ID=T3.VUANID AND T3.TOACHUYENID=T2.TOAANID
                WHERE T3.NGAYGIAO BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_CHUYENHOSO:=v_ARRAY(ITEM.V_STT).V_GQ_CHUYENHOSO+ITEM.V_GQ_CHUYENHOSO;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Đình chỉ -- V_GQ_DINHCHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_DINHCHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_GQ_DINHCHI FROM AKT_DON T2
                INNER JOIN AKT_SOTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_DINHCHI:=ITEM.V_GQ_DINHCHI;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_DINHCHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_GQ_DINHCHI FROM APS_DON T2
                INNER JOIN APS_SOTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_DINHCHI:=v_ARRAY(ITEM.V_STT).V_GQ_DINHCHI+ITEM.V_GQ_DINHCHI;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Công nhận thỏa thuận -- V_GQ_CONGNHANTHOATHUAN
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_CONGNHANTHOATHUAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_GQ_CONGNHANTHOATHUAN FROM AKT_DON T2
                INNER JOIN AKT_SOTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='CNTT'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_CONGNHANTHOATHUAN:=ITEM.V_GQ_CONGNHANTHOATHUAN;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_CONGNHANTHOATHUAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_GQ_CONGNHANTHOATHUAN FROM APS_DON T2
                INNER JOIN APS_SOTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='CNTT'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_CONGNHANTHOATHUAN:=v_ARRAY(ITEM.V_STT).V_GQ_CONGNHANTHOATHUAN+ITEM.V_GQ_CONGNHANTHOATHUAN;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Xét xử -- V_GQ_XETXU
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(VA.ID) V_GQ_XETXU
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON VA ON VA.TOAANID=T1.V_TOAAN
    INNER JOIN AKT_SOTHAM_BANAN BA ON BA.DONID=VA.ID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_XETXU:=ITEM.V_GQ_XETXU;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(VA.ID) V_GQ_XETXU
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_DON VA ON VA.TOAANID=T1.V_TOAAN
    INNER JOIN APS_SOTHAM_BANAN BA ON BA.DONID=VA.ID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_XETXU:=v_ARRAY(ITEM.V_STT).V_GQ_XETXU+ITEM.V_GQ_XETXU;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỔNG SỐ GQ -- V_GQ_TONGGQ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAANID,COUNT(DISTINCT VA.ID) V_QD FROM AKT_DON VA
                INNER JOIN AKT_SOTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAANID
                ) T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAANID,COUNT(VA.ID) V_BA FROM AKT_DON VA
                INNER JOIN AKT_SOTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAANID
                ) T3 ON T3.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ:=ITEM.V_GQ_TONGGQ;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAANID,COUNT(DISTINCT VA.ID) V_QD FROM APS_DON VA
                INNER JOIN APS_SOTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAANID
                ) T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAANID,COUNT(VA.ID) V_BA FROM APS_DON VA
                INNER JOIN APS_SOTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAANID
                ) T3 ON T3.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ:=v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ+ITEM.V_GQ_TONGGQ;
  END LOOP;
  -- ÁN BỊ HỦY -- V_ANHUY
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_ANHUY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AKT_PHUCTHAM_BANAN T4 ON T4.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('03,04,06,13,14',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND T5.ISAKT=1
          AND (T4.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY:=ITEM.V_ANHUY;
  END LOOP;
  -- Tính án hủy theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
    WHERE T2.XXGDTTT_ISKETQUA = 1
          AND T2.LOAIAN=4 --> vụ việc Kinh tế
          AND T2.XXGDTTT_KETQUAID IN (1262,1263,1268,1269,1270,1322,1327,1328,1374) --> án hủy
          AND XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANHUY:=v_ARRAY(ITEM.V_STT).V_ANHUY+ITEM.V_ANHUY;
	END LOOP;
  -- phá sản án hủy
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_ANHUY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN APS_PHUCTHAM_BANAN T4 ON T4.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('03,04,06,13,14',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND T5.ISAPS=1
          AND (T4.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY:=v_ARRAY(ITEM.V_STT).V_ANHUY+ITEM.V_ANHUY;
  END LOOP;
  -- Tính án hủy theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
    WHERE T2.XXGDTTT_ISKETQUA = 1
          AND T2.LOAIAN=7 --> vụ việc phá sản
          AND T2.XXGDTTT_KETQUAID IN (1262,1263,1268,1269,1270,1322,1327,1328,1374) --> án hủy
          AND XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANHUY:=v_ARRAY(ITEM.V_STT).V_ANHUY+ITEM.V_ANHUY;
	END LOOP;
  -- ÁN BỊ SỬA -- V_ANSUA
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_ANSUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AKT_PHUCTHAM_BANAN T4 ON T4.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('02,05,16,17',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND T5.ISAKT=1
          AND (T4.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANSUA:=ITEM.V_ANSUA;
  END LOOP;
  -- Tính án sửa theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANSUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
    WHERE T2.XXGDTTT_ISKETQUA = 1
          AND T2.LOAIAN=4 --> vụ việc Kinh tế
          AND T2.XXGDTTT_KETQUAID IN (1330,1319) --> án sửa
          AND XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANSUA:=v_ARRAY(ITEM.V_STT).V_ANSUA+ITEM.V_ANSUA;
	END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_ANSUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN APS_PHUCTHAM_BANAN T4 ON T4.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('02,05,16,17',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND T5.ISAPS=1
          AND (T4.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANSUA:=v_ARRAY(ITEM.V_STT).V_ANSUA+ITEM.V_ANSUA;
  END LOOP;
  -- Tính án sửa theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANSUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
    WHERE T2.XXGDTTT_ISKETQUA = 1
          AND T2.LOAIAN=7 --> vụ việc Phá sản
          AND T2.XXGDTTT_KETQUAID IN (1330,1319) --> án sửa
          AND XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANSUA:=v_ARRAY(ITEM.V_STT).V_ANSUA+ITEM.V_ANSUA;
	END LOOP;
  -- TỔNG SỐ VỤ ÁN CÒN LẠI = Tổng thụ lý - Đã giải quyết -- V_CONLAI
  -- ÁN QUÁ HẠN LUẬT ĐỊNH CHƯA GQ -- V_QUAHAN_CHUAGQ
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN_CHUAGQ
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AKT_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN_CHUAGQ:=ITEM.V_QUAHAN_CHUAGQ;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN_CHUAGQ
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN APS_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN_CHUAGQ:=v_ARRAY(ITEM.V_STT).V_QUAHAN_CHUAGQ+ITEM.V_QUAHAN_CHUAGQ;
  END LOOP;
END;
PROCEDURE FILL_GSTP_PAGE2_SOTHAM_HC
(
  v_ARRAY IN OUT GSTP_PAGE2_SOTHAM_DS_T,
  vDate_Nam_HienTai_DauKy IN DATE,
  vDate_Nam_HienTai_CuoiKy IN DATE,
  vDate_Nam_Truoc_DauKy IN DATE,
  vDate_Nam_Truoc_CuoiKy IN DATE
)AS
BEGIN
   -- TỔNG THỤ LÝ -- Thụ lý mới + Chưa giải quyết kỳ trước -- V_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_TONGTHULY FROM AHC_DON T2
                INNER JOIN AHC_SOTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=ITEM.V_TONGTHULY;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHC_SOTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM AHC_SOTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN AHC_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Chuyển hồ sơ vụ án -- V_GQ_CHUYENHOSO
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_CHUYENHOSO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(T2.ID) V_GQ_CHUYENHOSO FROM AHC_DON T2
                INNER JOIN AHC_CHUYEN_NHAN_AN T3 ON T2.ID=T3.VUANID AND T3.TOACHUYENID=T2.TOAANID
                WHERE T3.NGAYGIAO BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_CHUYENHOSO:=ITEM.V_GQ_CHUYENHOSO;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Đình chỉ -- V_GQ_DINHCHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_DINHCHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_GQ_DINHCHI FROM AHC_DON T2
                INNER JOIN AHC_SOTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_DINHCHI:=ITEM.V_GQ_DINHCHI;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Công nhận thỏa thuận -- V_GQ_CONGNHANTHOATHUAN
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_CONGNHANTHOATHUAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_GQ_CONGNHANTHOATHUAN FROM AHC_DON T2
                INNER JOIN AHC_SOTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='CNTT'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_CONGNHANTHOATHUAN:=ITEM.V_GQ_CONGNHANTHOATHUAN;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Xét xử -- V_GQ_XETXU
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(VA.ID) V_GQ_XETXU
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON VA ON VA.TOAANID=T1.V_TOAAN
    INNER JOIN AHC_SOTHAM_BANAN BA ON BA.DONID=VA.ID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_XETXU:=ITEM.V_GQ_XETXU;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỔNG SỐ GQ -- V_GQ_TONGGQ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAANID,COUNT(DISTINCT VA.ID) V_QD FROM AHC_DON VA
                INNER JOIN AHC_SOTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAANID
                ) T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAANID,COUNT(VA.ID) V_BA FROM AHC_DON VA
                INNER JOIN AHC_SOTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAANID
                ) T3 ON T3.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ:=ITEM.V_GQ_TONGGQ;
  END LOOP;
  -- ÁN BỊ HỦY -- V_ANHUY
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_ANHUY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHC_PHUCTHAM_BANAN T4 ON T4.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('03,04,06,13,14',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND T5.ISAHC=1
          AND (T4.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY:=ITEM.V_ANHUY;
  END LOOP;
  -- Tính án hủy theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
    WHERE T2.XXGDTTT_ISKETQUA = 1
          AND T2.LOAIAN=6 --> vụ việc hành chính
          AND T2.XXGDTTT_KETQUAID IN (1262,1263,1268,1269,1270,1322,1327,1328,1374) --> án hủy
          AND XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANHUY:=v_ARRAY(ITEM.V_STT).V_ANHUY+ITEM.V_ANHUY;
	END LOOP;
  -- ÁN BỊ SỬA -- V_ANSUA
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_ANSUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHC_PHUCTHAM_BANAN T4 ON T4.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('02,05,16,17',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND T5.ISAHC=1
          AND (T4.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANSUA:=ITEM.V_ANSUA;
  END LOOP;
  -- Tính án sửa theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANSUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
    WHERE T2.XXGDTTT_ISKETQUA = 1
          AND T2.LOAIAN=6 --> vụ việc hành chính
          AND T2.XXGDTTT_KETQUAID IN (1330,1319) --> án sửa
          AND XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANSUA:=v_ARRAY(ITEM.V_STT).V_ANSUA+ITEM.V_ANSUA;
	END LOOP;
  -- TỔNG SỐ VỤ ÁN CÒN LẠI = Tổng thụ lý - đã giải quyết -- V_CONLAI
  -- ÁN QUÁ HẠN LUẬT ĐỊNH CHƯA GQ -- V_QUAHAN_CHUAGQ
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN_CHUAGQ
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN AHC_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN_CHUAGQ:=ITEM.V_QUAHAN_CHUAGQ;
  END LOOP;
END;
PROCEDURE FILL_GSTP_PAGE2_SOTHAM_LAODONG
(
  v_ARRAY IN OUT GSTP_PAGE2_SOTHAM_DS_T,
  vDate_Nam_HienTai_DauKy IN DATE,
  vDate_Nam_HienTai_CuoiKy IN DATE,
  vDate_Nam_Truoc_DauKy IN DATE,
  vDate_Nam_Truoc_CuoiKy IN DATE
)AS
BEGIN
   -- TỔNG THỤ LÝ -- Thụ lý mới + Chưa giải quyết kỳ trước -- V_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_TONGTHULY FROM ALD_DON T2
                INNER JOIN ALD_SOTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=ITEM.V_TONGTHULY;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN ALD_SOTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM ALD_SOTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN ALD_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Chuyển hồ sơ vụ án -- V_GQ_CHUYENHOSO
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_CHUYENHOSO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(T2.ID) V_GQ_CHUYENHOSO FROM ALD_DON T2
                INNER JOIN ALD_CHUYEN_NHAN_AN T3 ON T2.ID=T3.VUANID AND T3.TOACHUYENID=T2.TOAANID
                WHERE T3.NGAYGIAO BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_CHUYENHOSO:=ITEM.V_GQ_CHUYENHOSO;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Đình chỉ -- V_GQ_DINHCHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_DINHCHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_GQ_DINHCHI FROM ALD_DON T2
                INNER JOIN ALD_SOTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_DINHCHI:=ITEM.V_GQ_DINHCHI;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Công nhận thỏa thuận -- V_GQ_CONGNHANTHOATHUAN
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_CONGNHANTHOATHUAN
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAANID,COUNT(DISTINCT T2.ID) V_GQ_CONGNHANTHOATHUAN FROM ALD_DON T2
                INNER JOIN ALD_SOTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='CNTT'
                GROUP BY T2.TOAANID
                ) T4 ON T4.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_CONGNHANTHOATHUAN:=ITEM.V_GQ_CONGNHANTHOATHUAN;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- Xét xử -- V_GQ_XETXU
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(VA.ID) V_GQ_XETXU
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON VA ON VA.TOAANID=T1.V_TOAAN
    INNER JOIN ALD_SOTHAM_BANAN BA ON BA.DONID=VA.ID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_XETXU:=ITEM.V_GQ_XETXU;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỔNG SỐ GQ -- V_GQ_TONGGQ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAANID,COUNT(DISTINCT VA.ID) V_QD FROM ALD_DON VA
                INNER JOIN ALD_SOTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAANID
                ) T2 ON T2.TOAANID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAANID,COUNT(VA.ID) V_BA FROM ALD_DON VA
                INNER JOIN ALD_SOTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAANID
                ) T3 ON T3.TOAANID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ:=ITEM.V_GQ_TONGGQ;
  END LOOP;
  -- ÁN BỊ HỦY -- V_ANHUY
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_ANHUY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN ALD_PHUCTHAM_BANAN T4 ON T4.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('03,04,06,13,14',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND T5.ISALD=1
          AND (T4.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANHUY:=ITEM.V_ANHUY;
  END LOOP;
  -- Tính án hủy theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANHUY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
    WHERE T2.XXGDTTT_ISKETQUA = 1
          AND T2.LOAIAN=5 --> vụ việc lao động
          AND T2.XXGDTTT_KETQUAID IN (1262,1263,1268,1269,1270,1322,1327,1328,1374) --> án hủy
          AND XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANHUY:=v_ARRAY(ITEM.V_STT).V_ANHUY+ITEM.V_ANHUY;
	END LOOP;
  -- ÁN BỊ SỬA -- V_ANSUA
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_ANSUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN ALD_PHUCTHAM_BANAN T4 ON T4.DONID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('02,05,16,17',T5.MA)>0
          AND T5.ISALD=1
          AND (T4.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_ANSUA:=ITEM.V_ANSUA;
  END LOOP;
  -- Tính án sửa theo GĐT
  FOR ITEM IN
  (
    SELECT T1.V_STT,COUNT(DISTINCT T2.ID) V_ANSUA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN GDTTT_VUAN T2 ON T2.TOAANSOTHAM=T1.V_TOAAN
    WHERE T2.XXGDTTT_ISKETQUA = 1
          AND T2.LOAIAN=5 --> vụ việc lao động
          AND T2.XXGDTTT_KETQUAID IN (1330,1319) --> án sửa
          AND XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
	) LOOP
		v_ARRAY(ITEM.V_STT).V_ANSUA:=v_ARRAY(ITEM.V_STT).V_ANSUA+ITEM.V_ANSUA;
	END LOOP;
  -- TỔNG SỐ VỤ ÁN CÒN LẠI = Tổng thụ lý - Đã giải quyết -- V_CONLAI
  -- ÁN QUÁ HẠN LUẬT ĐỊNH CHƯA GQ -- V_QUAHAN_CHUAGQ
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN_CHUAGQ
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON T2 ON T2.TOAANID=T1.V_TOAAN
    INNER JOIN ALD_SOTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_QUAHAN_CHUAGQ:=ITEM.V_QUAHAN_CHUAGQ;
  END LOOP;
END;

PROCEDURE FILL_GSTP_PAGE2_PHUCTHAM_AHS
(
  v_ARRAY IN OUT GSTP_PAGE2_PHUCTHAM_HS_T,
  vDate_Nam_HienTai_DauKy IN DATE,
  vDate_Nam_HienTai_CuoiKy IN DATE,
  vDate_Nam_Truoc_DauKy IN DATE,
  vDate_Nam_Truoc_CuoiKy IN DATE
)AS
BEGIN
  -- TỔNG THỤ LÝ = thụ lý + chưa giải quyết kỳ trước -- Vụ -- V_TONGTHULY_VU
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY_VU
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_TONGTHULY_VU FROM AHS_VUAN T2
                INNER JOIN AHS_PHUCTHAM_THULY T3 ON T2.ID=T3.VUANID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY_VU:=ITEM.V_TONGTHULY_VU;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHS_PHUCTHAM_THULY T3 ON T3.VUANID=T2.ID
    LEFT JOIN ( SELECT T1.VUANID,T2.MA FROM AHS_PHUCTHAM_QUYETDINH_VUAN T1 
                INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              ) QD ON T2.ID =QD.VUANID 
    LEFT JOIN AHS_PHUCTHAM_BANAN BA ON T2.ID =BA.VUANID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.VUANID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_TONGTHULY_VU:=v_ARRAY(ITEM.V_STT).V_TONGTHULY_VU + ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- TỔNG THỤ LÝ = Thụ lý + Chưa giải quyết kỳ trước -- Bị cáo -- V_TONGTHULY_BICAO
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY_BICAO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(T4.ID) V_TONGTHULY_BICAO FROM AHS_VUAN T2
                INNER JOIN AHS_PHUCTHAM_THULY T3 ON T2.ID=T3.VUANID
                INNER JOIN AHS_PHUCTHAM_BICANBICAO T4 ON T4.VUANID=T2.ID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY_BICAO:=ITEM.V_TONGTHULY_BICAO;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(BC.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHS_PHUCTHAM_THULY T3 ON T3.VUANID=T2.ID
    INNER JOIN AHS_BICANBICAO BC ON BC.VUANID=T2.ID 
    LEFT JOIN ( SELECT T1.VUANID,T2.MA FROM AHS_PHUCTHAM_QUYETDINH_VUAN T1 
                INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              ) QD ON T2.ID =QD.VUANID 
    LEFT JOIN AHS_PHUCTHAM_BANAN BA ON T2.ID =BA.VUANID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.VUANID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY_BICAO:=v_ARRAY(ITEM.V_STT).V_TONGTHULY_BICAO+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- RÚT KC-KN -- Vụ -- V_GQ_RUTKCKN_VU

  -- GIẢI QUYẾT ÁN -- XÉT XỬ -- Vụ -- V_GQ_XETXU_VU
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(VA.ID) V_GQ_XETXU_VU
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN VA ON VA.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHS_PHUCTHAM_BANAN BA ON BA.VUANID=VA.ID
    WHERE BA.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_XETXU_VU:=ITEM.V_GQ_XETXU_VU;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- XÉT XỬ -- Bị cáo -- V_GQ_XETXU_BICAO
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(BC.ID) V_GQ_XETXU_BICAO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN VA ON VA.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHS_PHUCTHAM_BANAN BA ON BA.VUANID=VA.ID
    INNER JOIN AHS_PHUCTHAM_BICANBICAO BC ON BC.VUANID=VA.ID
    WHERE BA.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_XETXU_BICAO:=ITEM.V_GQ_XETXU_BICAO;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỔNG SỐ GQ -- Vụ -- V_GQ_TONGGQ_VU
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ_VU
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(DISTINCT VA.ID) V_QD FROM AHS_VUAN VA
                INNER JOIN AHS_PHUCTHAM_QUYETDINH_VUAN QD ON QD.VUANID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAPHUCTHAMID
                ) T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(VA.ID) V_BA FROM AHS_VUAN VA
                INNER JOIN AHS_PHUCTHAM_BANAN BA ON BA.VUANID=VA.ID
                WHERE BA.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAPHUCTHAMID
                ) T3 ON T3.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ_VU:=ITEM.V_GQ_TONGGQ_VU;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỔNG SỐ GQ -- Bị cáo -- V_GQ_TONGGQ_BICAO
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ_BICAO
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(BC.ID) V_QD FROM AHS_VUAN VA
                INNER JOIN AHS_PHUCTHAM_QUYETDINH_VUAN QD ON QD.VUANID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                INNER JOIN AHS_BICANBICAO BC ON BC.VUANID=VA.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAPHUCTHAMID
                ) T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(BC.ID) V_BA FROM AHS_VUAN VA
                INNER JOIN AHS_PHUCTHAM_BANAN BA ON BA.VUANID=VA.ID
                INNER JOIN AHS_BICANBICAO BC ON BC.VUANID=VA.ID
                WHERE BA.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAPHUCTHAMID
                ) T3 ON T3.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ_BICAO:=ITEM.V_GQ_TONGGQ_BICAO;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỶ LỆ GQ -- Vụ -- V_GQ_TYLEGQ_VU
  -- GIẢI QUYẾT ÁN -- TỶ LỆ GQ -- Bị cáo -- V_GQ_TYLEGQ_BICAO
  -- ÁN HỦY, SỬA -- Sửa bản án, quyết định sơ thẩm -- V_SUA_BA
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_SUA_BA
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHS_PHUCTHAM_BANAN T4 ON T4.VUANID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('02,05,16,17',T5.MA)>0 -- kết luận phúc sửa BA/QD sơ thẩm
          AND (T4.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_SUA_BA:=ITEM.V_SUA_BA;
  END LOOP;
  -- ÁN HỦY, SỬA -- Sửa bản án, quyết định sơ thẩm -- Tính theo GĐTTT -- V_SUA_BA
  FOR ITEM IN
  (
  SELECT T1.V_STT,COUNT(T2.ID) V_SUA_BA 
  FROM TABLE(v_ARRAY) T1
  INNER JOIN GDTTT_VuAn T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
  WHERE LOAIAN =1 --> án hình sự
        AND NVL(T2.XXGDTTT_ISKETQUA,0) = 1 
        AND NVL(T2.XXGDTTT_KETQUAID,0) IN (1330,1319)--> Kết luận GĐT
        AND T2.XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
  GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_SUA_BA:=v_ARRAY(ITEM.V_STT).V_SUA_BA+ITEM.V_SUA_BA;
  END LOOP;
  -- ÁN HỦY, SỬA -- Huỷ bản án sơ thẩm, tuyên bố bị cáo không có tội và đình chỉ vụ án -- V_HUY_BA_TUYENBO_DINHCHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_HUY_BA_TUYENBO_DINHCHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHS_PHUCTHAM_BANAN T4 ON T4.VUANID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('13',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND (T4.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HUY_BA_TUYENBO_DINHCHI:=ITEM.V_HUY_BA_TUYENBO_DINHCHI;
  END LOOP;
  -- ÁN HỦY, SỬA -- Huỷ bản án sơ thẩm và đình chỉ vụ án -- V_HUY_BA_DINHCHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_HUY_BA_DINHCHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHS_PHUCTHAM_BANAN T4 ON T4.VUANID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('03',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND (T4.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HUY_BA_DINHCHI:=ITEM.V_HUY_BA_DINHCHI;
  END LOOP;
  -- ÁN HỦY, SỬA -- Huỷ bản án sơ thẩm và đình chỉ vụ án -- Tính theo GĐTTT -- V_HUY_BA_DINHCHI
  FOR ITEM IN
  (
  SELECT T1.V_STT,COUNT(T2.ID) V_HUY_BA_DINHCHI 
  FROM TABLE(v_ARRAY) T1
  INNER JOIN GDTTT_VuAn T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
  WHERE LOAIAN =1 --> án hình sự
        AND NVL(T2.XXGDTTT_ISKETQUA,0) = 1 
        AND NVL(T2.XXGDTTT_KETQUAID,0) IN (1269)--> Kết luận GĐT
        AND T2.XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
  GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HUY_BA_DINHCHI:=v_ARRAY(ITEM.V_STT).V_HUY_BA_DINHCHI+ITEM.V_HUY_BA_DINHCHI;
  END LOOP;
  -- ÁN HỦY, SỬA -- Huỷ bản án, quyết định sơ thẩm để điều tra lại -- V_HUY_BA_DIEUTRALAI
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_HUY_BA_DIEUTRALAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHS_PHUCTHAM_BANAN T4 ON T4.VUANID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('14',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND (T4.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HUY_BA_DIEUTRALAI:=ITEM.V_HUY_BA_DIEUTRALAI;
  END LOOP;
  -- ÁN HỦY, SỬA -- Huỷ bản án, quyết định sơ thẩm để điều tra lại -- Tính theo GĐTTT -- V_HUY_BA_DIEUTRALAI
  FOR ITEM IN
  (
  SELECT T1.V_STT,COUNT(T2.ID) V_HUY_BA_DIEUTRALAI 
  FROM TABLE(v_ARRAY) T1
  INNER JOIN GDTTT_VuAn T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
  WHERE LOAIAN =1 --> án hình sự
        AND NVL(T2.XXGDTTT_ISKETQUA,0) = 1 
        AND NVL(T2.XXGDTTT_KETQUAID,0) IN (1262)--> Kết luận GĐT
        AND T2.XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
  GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HUY_BA_DIEUTRALAI:=v_ARRAY(ITEM.V_STT).V_HUY_BA_DIEUTRALAI+ITEM.V_HUY_BA_DIEUTRALAI;
  END LOOP;
  -- ÁN HỦY, SỬA -- Huỷ bản án, quyết định sơ thẩm để xét xử sơ thẩm lại -- V_HUY_BA_XETXULAI
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(T2.ID) V_HUY_BA_XETXULAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHS_VUAN T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHS_PHUCTHAM_BANAN T4 ON T4.VUANID=T2.ID
    INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T4.KETQUAPHUCTHAMID
    WHERE INSTR('04,06',T5.MA)>0 -- kết luận phúc hủy BA/QD sơ thẩm
          AND (T4.NGAYBANAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HUY_BA_XETXULAI:=ITEM.V_HUY_BA_XETXULAI;
  END LOOP;
  -- ÁN HỦY, SỬA -- Huỷ bản án, quyết định sơ thẩm để xét xử sơ thẩm lại Tính theo GĐTTT -- V_HUY_BA_XETXULAI
  FOR ITEM IN
  (
  SELECT T1.V_STT,COUNT(T2.ID) V_HUY_BA_XETXULAI 
  FROM TABLE(v_ARRAY) T1
  INNER JOIN GDTTT_VuAn T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
  WHERE LOAIAN =1 --> án hình sự
        AND NVL(T2.XXGDTTT_ISKETQUA,0) = 1 
        AND NVL(T2.XXGDTTT_KETQUAID,0) IN (1263)--> Kết luận GĐT
        AND T2.XXGDTTT_NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
  GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_HUY_BA_XETXULAI:=v_ARRAY(ITEM.V_STT).V_HUY_BA_XETXULAI+ITEM.V_HUY_BA_XETXULAI;
  END LOOP;
  -- CÒN LẠI = Tổng thụ lý - đã gaải quyết -- Vụ -- V_CONLAI_VU
  -- CÒN LẠI = Tổng thụ lý - đã gaải quyết -- Bị cáo -- V_CONLAI_BICAO
  -- ÁN QUÁ HẠN LUẬT ĐỊNH CHƯA GQ -- Vụ -- V_QUAHAN_CHUAGQ_VU
  -- ÁN QUÁ HẠN LUẬT ĐỊNH CHƯA GQ -- Bị cáo -- V_QUAHAN_CHUAGQ_BICAO
END;

PROCEDURE FILL_GSTP_PAGE2_PHUCTHAM_ADS
(
  v_ARRAY IN OUT GSTP_PAGE2_PHUCTHAM_DS_T,
  vDate_Nam_HienTai_DauKy IN DATE,
  vDate_Nam_HienTai_CuoiKy IN DATE,
  vDate_Nam_Truoc_DauKy IN DATE,
  vDate_Nam_Truoc_CuoiKy IN DATE
)AS
BEGIN
  -- TỔNG THỤ LÝ = Thụ lý + chưa giải quyết kỳ trước-- V_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_TONGTHULY FROM ADS_DON T2
                INNER JOIN ADS_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=ITEM.V_TONGTHULY;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN ADS_PHUCTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM ADS_PHUCTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN ADS_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỔNG SỐ GQ -- V_GQ_TONGGQ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(DISTINCT VA.ID) V_QD FROM ADS_DON VA
                INNER JOIN ADS_PHUCTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAPHUCTHAMID
                ) T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(VA.ID) V_BA FROM ADS_DON VA
                INNER JOIN ADS_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAPHUCTHAMID
                ) T3 ON T3.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ:=ITEM.V_GQ_TONGGQ;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỶ LỆ GQ -- V_GQ_TYLEGQ
  -- GIẢI QUYẾT ÁN -- Số vụ án TA tổ chức phiên tòa rút kinh nghiệm -- V_GQ_RUTKINHNGHIEM
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_RUTKINHNGHIEM
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_GQ_RUTKINHNGHIEM FROM ADS_DON T2
                INNER JOIN ADS_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                INNER JOIN ADS_SAUXETXU T5 ON T5.VUANID=T2.ID
                WHERE T5.PT_NGAYRUT BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T5.PT_ISRUTKN=1
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_RUTKINHNGHIEM:=ITEM.V_GQ_RUTKINHNGHIEM;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Tạm đình chỉ -- V_PHANTICH_TAMDINHCHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_TAMDINHCHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_TAMDINHCHI FROM ADS_DON T2
                INNER JOIN ADS_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T2.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='TDC'
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_TAMDINHCHI:=ITEM.V_PHANTICH_TAMDINHCHI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Y án -- V_PHANTICH_ANLE
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(VA.ID) V_PHANTICH_ANLE
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ADS_DON VA ON VA.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN ADS_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
          AND BA.APDUNGANLE=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_ANLE:=ITEM.V_PHANTICH_ANLE;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Đình chỉ -- Rút kháng cáo -- V_PHANTICH_DC_RUTKHANGCAO
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_RUTKHANGCAO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_RUTKHANGCAO FROM ADS_DON T2
                INNER JOIN ADS_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')>0
                      AND INSTR(LOWER(T5.TEN),'kháng cáo')>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_RUTKHANGCAO:=ITEM.V_PHANTICH_DC_RUTKHANGCAO;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Đình chỉ -- Rút kháng nghị -- V_PHANTICH_DC_RUTKHANGNGHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_RUTKHANGNGHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_RUTKHANGNGHI FROM ADS_DON T2
                INNER JOIN ADS_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')>0
                      AND INSTR(LOWER(T5.TEN),'kháng nghị')>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_RUTKHANGNGHI:=ITEM.V_PHANTICH_DC_RUTKHANGNGHI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Đình chỉ -- Lý do khác -- V_PHANTICH_DC_LYDOKHAC
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_LYDOKHAC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_LYDOKHAC FROM ADS_DON T2
                INNER JOIN ADS_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')=0
                      AND (INSTR(LOWER(T5.TEN),'kháng cáo')=0 OR INSTR(LOWER(T5.TEN),'kháng nghị')=0)
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_LYDOKHAC:=ITEM.V_PHANTICH_DC_LYDOKHAC;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Sửa án -- Do cấp ST sai -- V_PHANTICH_SUA_CAPSOTHAMSAI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_SUA_CAPSOTHAMSAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_SUA_CAPSOTHAMSAI FROM ADS_DON T2
                INNER JOIN ADS_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('02,05,16,17',T5.MA)>0
                      AND INSTR('01',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_SUA_CAPSOTHAMSAI:=ITEM.V_PHANTICH_SUA_CAPSOTHAMSAI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Sửa án -- Do có tình tiết mới -- V_PHANTICH_SUA_TINHTIETMOI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_SUA_TINHTIETMOI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_SUA_TINHTIETMOI FROM ADS_DON T2
                INNER JOIN ADS_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('02,05,16,17',T5.MA)>0
                      AND INSTR('03',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_SUA_TINHTIETMOI:=ITEM.V_PHANTICH_SUA_TINHTIETMOI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Huỷ án -- Do cấp ST sai -- V_PHANTICH_HUY_CAPSOTHAMSAI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_HUY_CAPSOTHAMSAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_HUY_CAPSOTHAMSAI FROM ADS_DON T2
                INNER JOIN ADS_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('03,04,06,13,14',T5.MA)>0
                      AND INSTR('01',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_HUY_CAPSOTHAMSAI:=ITEM.V_PHANTICH_HUY_CAPSOTHAMSAI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Huỷ án -- Do có tình tiết mới -- V_PHANTICH_HUY_TINHTIETMOI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_HUY_TINHTIETMOI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_HUY_TINHTIETMOI FROM ADS_DON T2
                INNER JOIN ADS_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('03,04,06,13,14',T5.MA)>0
                      AND INSTR('03',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_HUY_TINHTIETMOI:=ITEM.V_PHANTICH_HUY_TINHTIETMOI;
  END LOOP;
  -- CÒN LẠI -- V_CONLAI
  -- ÁN QUÁ HẠN LUẬT ĐỊNH CHƯA GQ -- V_QUAHAN_CHUAGQ
--  FOR ITEM IN
--  (
--    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN_CHUAGQ
--    FROM TABLE(v_ARRAY) T1
--    INNER JOIN ADS_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
--    INNER JOIN ADS_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
--    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
--          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
--    GROUP BY T1.V_STT
--  )LOOP
--    v_ARRAY(ITEM.V_STT).V_QUAHAN_CHUAGQ:=ITEM.V_QUAHAN_CHUAGQ;
--  END LOOP;
END;

PROCEDURE FILL_GSTP_PAGE2_PHUCTHAM_AHN
(
  v_ARRAY IN OUT GSTP_PAGE2_PHUCTHAM_DS_T,
  vDate_Nam_HienTai_DauKy IN DATE,
  vDate_Nam_HienTai_CuoiKy IN DATE,
  vDate_Nam_Truoc_DauKy IN DATE,
  vDate_Nam_Truoc_CuoiKy IN DATE
)AS
BEGIN
  -- TỔNG THỤ LÝ = thụ lý + Chưa giải quyết kỳ trước -- V_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_TONGTHULY FROM AHN_DON T2
                INNER JOIN AHN_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=ITEM.V_TONGTHULY;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHN_PHUCTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM AHN_PHUCTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN AHN_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỔNG SỐ GQ -- V_GQ_TONGGQ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(DISTINCT VA.ID) V_QD FROM AHN_DON VA
                INNER JOIN AHN_PHUCTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAPHUCTHAMID
                ) T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(VA.ID) V_BA FROM AHN_DON VA
                INNER JOIN AHN_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAPHUCTHAMID
                ) T3 ON T3.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ:=ITEM.V_GQ_TONGGQ;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỶ LỆ GQ -- V_GQ_TYLEGQ
  -- GIẢI QUYẾT ÁN -- Số vụ án TA tổ chức phiên tòa rút kinh nghiệm -- V_GQ_RUTKINHNGHIEM
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_RUTKINHNGHIEM
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_GQ_RUTKINHNGHIEM FROM AHN_DON T2
                INNER JOIN AHN_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                INNER JOIN AHN_SAUXETXU T5 ON T5.VUANID=T2.ID
                WHERE T5.PT_NGAYRUT BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T5.PT_ISRUTKN=1
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_RUTKINHNGHIEM:=ITEM.V_GQ_RUTKINHNGHIEM;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Tạm đình chỉ -- V_PHANTICH_TAMDINHCHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_TAMDINHCHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_TAMDINHCHI FROM AHN_DON T2
                INNER JOIN AHN_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T2.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='TDC'
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_TAMDINHCHI:=ITEM.V_PHANTICH_TAMDINHCHI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Y án -- V_PHANTICH_ANLE
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(VA.ID) V_PHANTICH_ANLE
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHN_DON VA ON VA.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHN_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
          AND BA.APDUNGANLE=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_ANLE:=ITEM.V_PHANTICH_ANLE;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Đình chỉ -- Rút kháng cáo -- V_PHANTICH_DC_RUTKHANGCAO
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_RUTKHANGCAO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_RUTKHANGCAO FROM AHN_DON T2
                INNER JOIN AHN_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')>0
                      AND INSTR(LOWER(T5.TEN),'kháng cáo')>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_RUTKHANGCAO:=ITEM.V_PHANTICH_DC_RUTKHANGCAO;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Đình chỉ -- Rút kháng nghị -- V_PHANTICH_DC_RUTKHANGNGHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_RUTKHANGNGHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_RUTKHANGNGHI FROM AHN_DON T2
                INNER JOIN AHN_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')>0
                      AND INSTR(LOWER(T5.TEN),'kháng nghị')>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_RUTKHANGNGHI:=ITEM.V_PHANTICH_DC_RUTKHANGNGHI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Đình chỉ -- Lý do khác -- V_PHANTICH_DC_LYDOKHAC
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_LYDOKHAC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_LYDOKHAC FROM AHN_DON T2
                INNER JOIN AHN_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')=0
                      AND (INSTR(LOWER(T5.TEN),'kháng cáo')=0 OR INSTR(LOWER(T5.TEN),'kháng nghị')=0)
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_LYDOKHAC:=ITEM.V_PHANTICH_DC_LYDOKHAC;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Sửa án -- Do cấp ST sai -- V_PHANTICH_SUA_CAPSOTHAMSAI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_SUA_CAPSOTHAMSAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_SUA_CAPSOTHAMSAI FROM AHN_DON T2
                INNER JOIN AHN_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('02,05,16,17',T5.MA)>0
                      AND INSTR('01',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_SUA_CAPSOTHAMSAI:=ITEM.V_PHANTICH_SUA_CAPSOTHAMSAI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Sửa án -- Do có tình tiết mới -- V_PHANTICH_SUA_TINHTIETMOI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_SUA_TINHTIETMOI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_SUA_TINHTIETMOI FROM AHN_DON T2
                INNER JOIN AHN_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('02,05,16,17',T5.MA)>0
                      AND INSTR('03',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_SUA_TINHTIETMOI:=ITEM.V_PHANTICH_SUA_TINHTIETMOI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Huỷ án -- Do cấp ST sai -- V_PHANTICH_HUY_CAPSOTHAMSAI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_HUY_CAPSOTHAMSAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_HUY_CAPSOTHAMSAI FROM AHN_DON T2
                INNER JOIN AHN_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('03,04,06,13,14',T5.MA)>0
                      AND INSTR('01',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_HUY_CAPSOTHAMSAI:=ITEM.V_PHANTICH_HUY_CAPSOTHAMSAI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Huỷ án -- Do có tình tiết mới -- V_PHANTICH_HUY_TINHTIETMOI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_HUY_TINHTIETMOI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_HUY_TINHTIETMOI FROM AHN_DON T2
                INNER JOIN AHN_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('03,04,06,13,14',T5.MA)>0
                      AND INSTR('03',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_HUY_TINHTIETMOI:=ITEM.V_PHANTICH_HUY_TINHTIETMOI;
  END LOOP;
  -- CÒN LẠI -- V_CONLAI
  -- ÁN QUÁ HẠN LUẬT ĐỊNH CHƯA GQ -- V_QUAHAN_CHUAGQ
--  FOR ITEM IN
--  (
--    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN_CHUAGQ
--    FROM TABLE(v_ARRAY) T1
--    INNER JOIN AHN_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
--    INNER JOIN AHN_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
--    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
--          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
--    GROUP BY T1.V_STT
--  )LOOP
--    v_ARRAY(ITEM.V_STT).V_QUAHAN_CHUAGQ:=ITEM.V_QUAHAN_CHUAGQ;
--  END LOOP;
END;

PROCEDURE FILL_GSTP_PAGE2_PHUCTHAM_AKT
(
  v_ARRAY IN OUT GSTP_PAGE2_PHUCTHAM_DS_T,
  vDate_Nam_HienTai_DauKy IN DATE,
  vDate_Nam_HienTai_CuoiKy IN DATE,
  vDate_Nam_Truoc_DauKy IN DATE,
  vDate_Nam_Truoc_CuoiKy IN DATE
)AS
BEGIN
  --****** ÁN PHÁ SẢN sẽ được cộng dồn vào án kinh tế
  -- TỔNG THỤ LÝ = Thụ lý + Chưa giải quyết kỳ trước -- V_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_TONGTHULY FROM AKT_DON T2
                INNER JOIN AKT_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=ITEM.V_TONGTHULY;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_TONGTHULY FROM APS_DON T2
                INNER JOIN APS_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_TONGTHULY;
  END LOOP;
  -- Kinh tế chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AKT_PHUCTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM AKT_PHUCTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN AKT_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- Phá sản chưa giải quyết kỳ trước
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN APS_PHUCTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM APS_PHUCTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN APS_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỔNG SỐ GQ -- V_GQ_TONGGQ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(DISTINCT VA.ID) V_QD FROM AKT_DON VA
                INNER JOIN AKT_PHUCTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAPHUCTHAMID
                ) T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(VA.ID) V_BA FROM AKT_DON VA
                INNER JOIN AKT_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAPHUCTHAMID
                ) T3 ON T3.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ:=ITEM.V_GQ_TONGGQ;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(DISTINCT VA.ID) V_QD FROM APS_DON VA
                INNER JOIN APS_PHUCTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAPHUCTHAMID
                ) T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(VA.ID) V_BA FROM APS_DON VA
                INNER JOIN APS_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAPHUCTHAMID
                ) T3 ON T3.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ:=v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ+ITEM.V_GQ_TONGGQ;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỶ LỆ GQ -- V_GQ_TYLEGQ
  -- GIẢI QUYẾT ÁN -- Số vụ án TA tổ chức phiên tòa rút kinh nghiệm -- V_GQ_RUTKINHNGHIEM
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_RUTKINHNGHIEM
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_GQ_RUTKINHNGHIEM FROM AKT_DON T2
                INNER JOIN AKT_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                INNER JOIN AKT_SAUXETXU T5 ON T5.VUANID=T2.ID
                WHERE T5.PT_NGAYRUT BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T5.PT_ISRUTKN=1
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_RUTKINHNGHIEM:=ITEM.V_GQ_RUTKINHNGHIEM;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_GQ_RUTKINHNGHIEM
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_GQ_RUTKINHNGHIEM FROM APS_DON T2
                INNER JOIN APS_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                INNER JOIN APS_SAUXETXU T5 ON T5.VUANID=T2.ID
                WHERE T5.PT_NGAYRUT BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T5.PT_ISRUTKN=1
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_RUTKINHNGHIEM:=v_ARRAY(ITEM.V_STT).V_GQ_RUTKINHNGHIEM+ITEM.V_GQ_RUTKINHNGHIEM;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Tạm đình chỉ -- V_PHANTICH_TAMDINHCHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_TAMDINHCHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_TAMDINHCHI FROM AKT_DON T2
                INNER JOIN AKT_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T2.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='TDC'
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_TAMDINHCHI:=ITEM.V_PHANTICH_TAMDINHCHI;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_TAMDINHCHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_TAMDINHCHI FROM APS_DON T2
                INNER JOIN APS_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T2.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='TDC'
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_TAMDINHCHI:=v_ARRAY(ITEM.V_STT).V_PHANTICH_TAMDINHCHI+ITEM.V_PHANTICH_TAMDINHCHI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Y án -- V_PHANTICH_ANLE
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(VA.ID) V_PHANTICH_ANLE
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AKT_DON VA ON VA.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AKT_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
          AND BA.APDUNGANLE=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_ANLE:=ITEM.V_PHANTICH_ANLE;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(VA.ID) V_PHANTICH_ANLE
    FROM TABLE(v_ARRAY) T1
    INNER JOIN APS_DON VA ON VA.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN APS_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
          AND BA.APDUNGANLE=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_ANLE:=v_ARRAY(ITEM.V_STT).V_PHANTICH_ANLE+ITEM.V_PHANTICH_ANLE;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Đình chỉ -- Rút kháng cáo -- V_PHANTICH_DC_RUTKHANGCAO
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_RUTKHANGCAO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_RUTKHANGCAO FROM AKT_DON T2
                INNER JOIN AKT_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')>0
                      AND INSTR(LOWER(T5.TEN),'kháng cáo')>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_RUTKHANGCAO:=ITEM.V_PHANTICH_DC_RUTKHANGCAO;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_RUTKHANGCAO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_RUTKHANGCAO FROM APS_DON T2
                INNER JOIN APS_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')>0
                      AND INSTR(LOWER(T5.TEN),'kháng cáo')>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_RUTKHANGCAO:=v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_RUTKHANGCAO+ITEM.V_PHANTICH_DC_RUTKHANGCAO;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Đình chỉ -- Rút kháng nghị -- V_PHANTICH_DC_RUTKHANGNGHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_RUTKHANGNGHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_RUTKHANGNGHI FROM AKT_DON T2
                INNER JOIN AKT_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')>0
                      AND INSTR(LOWER(T5.TEN),'kháng nghị')>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_RUTKHANGNGHI:=ITEM.V_PHANTICH_DC_RUTKHANGNGHI;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_RUTKHANGNGHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_RUTKHANGNGHI FROM APS_DON T2
                INNER JOIN APS_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')>0
                      AND INSTR(LOWER(T5.TEN),'kháng nghị')>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_RUTKHANGNGHI:=v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_RUTKHANGNGHI+ITEM.V_PHANTICH_DC_RUTKHANGNGHI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Đình chỉ -- Lý do khác -- V_PHANTICH_DC_LYDOKHAC
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_LYDOKHAC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_LYDOKHAC FROM AKT_DON T2
                INNER JOIN AKT_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')=0
                      AND (INSTR(LOWER(T5.TEN),'kháng cáo')=0 OR INSTR(LOWER(T5.TEN),'kháng nghị')=0)
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_LYDOKHAC:=ITEM.V_PHANTICH_DC_LYDOKHAC;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_LYDOKHAC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_LYDOKHAC FROM APS_DON T2
                INNER JOIN APS_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')=0
                      AND (INSTR(LOWER(T5.TEN),'kháng cáo')=0 OR INSTR(LOWER(T5.TEN),'kháng nghị')=0)
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_LYDOKHAC:=v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_LYDOKHAC+ITEM.V_PHANTICH_DC_LYDOKHAC;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Sửa án -- Do cấp ST sai -- V_PHANTICH_SUA_CAPSOTHAMSAI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_SUA_CAPSOTHAMSAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_SUA_CAPSOTHAMSAI FROM AKT_DON T2
                INNER JOIN AKT_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('02,05,16,17',T5.MA)>0
                      AND INSTR('01',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_SUA_CAPSOTHAMSAI:=ITEM.V_PHANTICH_SUA_CAPSOTHAMSAI;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_SUA_CAPSOTHAMSAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_SUA_CAPSOTHAMSAI FROM APS_DON T2
                INNER JOIN APS_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('02,05,16,17',T5.MA)>0
                      AND INSTR('01',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_SUA_CAPSOTHAMSAI:=v_ARRAY(ITEM.V_STT).V_PHANTICH_SUA_CAPSOTHAMSAI+ITEM.V_PHANTICH_SUA_CAPSOTHAMSAI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Sửa án -- Do có tình tiết mới -- V_PHANTICH_SUA_TINHTIETMOI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_SUA_TINHTIETMOI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_SUA_TINHTIETMOI FROM AKT_DON T2
                INNER JOIN AKT_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('02,05,16,17',T5.MA)>0
                      AND INSTR('03',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_SUA_TINHTIETMOI:=ITEM.V_PHANTICH_SUA_TINHTIETMOI;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_SUA_TINHTIETMOI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_SUA_TINHTIETMOI FROM APS_DON T2
                INNER JOIN APS_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('02,05,16,17',T5.MA)>0
                      AND INSTR('03',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_SUA_TINHTIETMOI:=v_ARRAY(ITEM.V_STT).V_PHANTICH_SUA_TINHTIETMOI+ITEM.V_PHANTICH_SUA_TINHTIETMOI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Huỷ án -- Do cấp ST sai -- V_PHANTICH_HUY_CAPSOTHAMSAI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_HUY_CAPSOTHAMSAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_HUY_CAPSOTHAMSAI FROM AKT_DON T2
                INNER JOIN AKT_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('03,04,06,13,14',T5.MA)>0
                      AND INSTR('01',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_HUY_CAPSOTHAMSAI:=ITEM.V_PHANTICH_HUY_CAPSOTHAMSAI;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_HUY_CAPSOTHAMSAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_HUY_CAPSOTHAMSAI FROM APS_DON T2
                INNER JOIN APS_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('03,04,06,13,14',T5.MA)>0
                      AND INSTR('01',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_HUY_CAPSOTHAMSAI:=v_ARRAY(ITEM.V_STT).V_PHANTICH_HUY_CAPSOTHAMSAI+ITEM.V_PHANTICH_HUY_CAPSOTHAMSAI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Huỷ án -- Do có tình tiết mới -- V_PHANTICH_HUY_TINHTIETMOI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_HUY_TINHTIETMOI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_HUY_TINHTIETMOI FROM AKT_DON T2
                INNER JOIN AKT_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('03,04,06,13,14',T5.MA)>0
                      AND INSTR('03',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_HUY_TINHTIETMOI:=ITEM.V_PHANTICH_HUY_TINHTIETMOI;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_HUY_TINHTIETMOI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_HUY_TINHTIETMOI FROM APS_DON T2
                INNER JOIN APS_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('03,04,06,13,14',T5.MA)>0
                      AND INSTR('03',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_HUY_TINHTIETMOI:=v_ARRAY(ITEM.V_STT).V_PHANTICH_HUY_TINHTIETMOI+ITEM.V_PHANTICH_HUY_TINHTIETMOI;
  END LOOP;
  -- CÒN LẠI -- V_CONLAI
  -- ÁN QUÁ HẠN LUẬT ĐỊNH CHƯA GQ -- V_QUAHAN_CHUAGQ
--  FOR ITEM IN
--  (
--    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN_CHUAGQ
--    FROM TABLE(v_ARRAY) T1
--    INNER JOIN AKT_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
--    INNER JOIN AKT_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
--    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
--          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
--    GROUP BY T1.V_STT
--  )LOOP
--    v_ARRAY(ITEM.V_STT).V_QUAHAN_CHUAGQ:=ITEM.V_QUAHAN_CHUAGQ;
--  END LOOP;
  -- án phá sản không tính quá hạn ở giai đoạn phúc thẩm
END;

PROCEDURE FILL_GSTP_PAGE2_PHUCTHAM_AHC
(
  v_ARRAY IN OUT GSTP_PAGE2_PHUCTHAM_DS_T,
  vDate_Nam_HienTai_DauKy IN DATE,
  vDate_Nam_HienTai_CuoiKy IN DATE,
  vDate_Nam_Truoc_DauKy IN DATE,
  vDate_Nam_Truoc_CuoiKy IN DATE
)AS
BEGIN
  -- TỔNG THỤ LÝ = Thụ lý + Chưa giải quyết kỳ trước -- V_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_TONGTHULY FROM AHC_DON T2
                INNER JOIN AHC_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=ITEM.V_TONGTHULY;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHC_PHUCTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM AHC_PHUCTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN AHC_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỔNG SỐ GQ -- V_GQ_TONGGQ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(DISTINCT VA.ID) V_QD FROM AHC_DON VA
                INNER JOIN AHC_PHUCTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAPHUCTHAMID
                ) T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(VA.ID) V_BA FROM AHC_DON VA
                INNER JOIN AHC_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAPHUCTHAMID
                ) T3 ON T3.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ:=ITEM.V_GQ_TONGGQ;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỶ LỆ GQ -- V_GQ_TYLEGQ
  -- GIẢI QUYẾT ÁN -- Số vụ án TA tổ chức phiên tòa rút kinh nghiệm -- V_GQ_RUTKINHNGHIEM
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_TONGTHULY FROM AHC_DON T2
                INNER JOIN AHC_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                INNER JOIN AHC_SAUXETXU T5 ON T5.VUANID=T2.ID
                WHERE T5.PT_NGAYRUT BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T5.PT_ISRUTKN=1
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=ITEM.V_TONGTHULY;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Tạm đình chỉ -- V_PHANTICH_TAMDINHCHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_TAMDINHCHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_TAMDINHCHI FROM AHC_DON T2
                INNER JOIN AHC_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T2.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='TDC'
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_TAMDINHCHI:=ITEM.V_PHANTICH_TAMDINHCHI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Y án -- V_PHANTICH_ANLE
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(VA.ID) V_PHANTICH_ANLE
    FROM TABLE(v_ARRAY) T1
    INNER JOIN AHC_DON VA ON VA.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN AHC_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
          AND BA.APDUNGANLE=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_ANLE:=ITEM.V_PHANTICH_ANLE;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Đình chỉ -- Rút kháng cáo -- V_PHANTICH_DC_RUTKHANGCAO
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_RUTKHANGCAO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_RUTKHANGCAO FROM AHC_DON T2
                INNER JOIN AHC_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')>0
                      AND INSTR(LOWER(T5.TEN),'kháng cáo')>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_RUTKHANGCAO:=ITEM.V_PHANTICH_DC_RUTKHANGCAO;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Đình chỉ -- Rút kháng nghị -- V_PHANTICH_DC_RUTKHANGNGHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_RUTKHANGNGHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_RUTKHANGNGHI FROM AHC_DON T2
                INNER JOIN AHC_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')>0
                      AND INSTR(LOWER(T5.TEN),'kháng nghị')>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_RUTKHANGNGHI:=ITEM.V_PHANTICH_DC_RUTKHANGNGHI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Đình chỉ -- Lý do khác -- V_PHANTICH_DC_LYDOKHAC
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_LYDOKHAC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_LYDOKHAC FROM AHC_DON T2
                INNER JOIN AHC_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')=0
                      AND (INSTR(LOWER(T5.TEN),'kháng cáo')=0 OR INSTR(LOWER(T5.TEN),'kháng nghị')=0)
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_LYDOKHAC:=ITEM.V_PHANTICH_DC_LYDOKHAC;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Sửa án -- Do cấp ST sai -- V_PHANTICH_SUA_CAPSOTHAMSAI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_SUA_CAPSOTHAMSAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_SUA_CAPSOTHAMSAI FROM AHC_DON T2
                INNER JOIN AHC_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('02,05,16,17',T5.MA)>0
                      AND INSTR('01',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_SUA_CAPSOTHAMSAI:=ITEM.V_PHANTICH_SUA_CAPSOTHAMSAI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Sửa án -- Do có tình tiết mới -- V_PHANTICH_SUA_TINHTIETMOI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_SUA_TINHTIETMOI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_SUA_TINHTIETMOI FROM AHC_DON T2
                INNER JOIN AHC_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('02,05,16,17',T5.MA)>0
                      AND INSTR('03',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_SUA_TINHTIETMOI:=ITEM.V_PHANTICH_SUA_TINHTIETMOI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Huỷ án -- Do cấp ST sai -- V_PHANTICH_HUY_CAPSOTHAMSAI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_HUY_CAPSOTHAMSAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_HUY_CAPSOTHAMSAI FROM AHC_DON T2
                INNER JOIN AHC_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('03,04,06,13,14',T5.MA)>0
                      AND INSTR('01',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_HUY_CAPSOTHAMSAI:=ITEM.V_PHANTICH_HUY_CAPSOTHAMSAI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Huỷ án -- Do có tình tiết mới -- V_PHANTICH_HUY_TINHTIETMOI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_HUY_TINHTIETMOI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_HUY_TINHTIETMOI FROM AHC_DON T2
                INNER JOIN AHC_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('03,04,06,13,14',T5.MA)>0
                      AND INSTR('03',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_HUY_TINHTIETMOI:=ITEM.V_PHANTICH_HUY_TINHTIETMOI;
  END LOOP;
  -- CÒN LẠI -- V_CONLAI
  -- ÁN QUÁ HẠN LUẬT ĐỊNH CHƯA GQ -- V_QUAHAN_CHUAGQ
--  FOR ITEM IN
--  (
--    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN_CHUAGQ
--    FROM TABLE(v_ARRAY) T1
--    INNER JOIN AHC_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
--    INNER JOIN AHC_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
--    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
--          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
--    GROUP BY T1.V_STT
--  )LOOP
--    v_ARRAY(ITEM.V_STT).V_QUAHAN_CHUAGQ:=ITEM.V_QUAHAN_CHUAGQ;
--  END LOOP;
END;

PROCEDURE FILL_GSTP_PAGE2_PHUCTHAM_ALD
(
  v_ARRAY IN OUT GSTP_PAGE2_PHUCTHAM_DS_T,
  vDate_Nam_HienTai_DauKy IN DATE,
  vDate_Nam_HienTai_CuoiKy IN DATE,
  vDate_Nam_Truoc_DauKy IN DATE,
  vDate_Nam_Truoc_CuoiKy IN DATE
)AS
BEGIN
  -- TỔNG THỤ LÝ = Thụ lý + chưa giải quyết kỳ trước  -- V_TONGTHULY
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_TONGTHULY FROM ALD_DON T2
                INNER JOIN ALD_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                WHERE T3.NGAYTHULY BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=ITEM.V_TONGTHULY;
  END LOOP;
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(DISTINCT T2.ID) V_CHUA_GQ_KY_TRUOC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN ALD_PHUCTHAM_THULY T3 ON T3.DONID=T2.ID
    LEFT JOIN ( SELECT T4.DONID,T5.MA FROM ALD_PHUCTHAM_QUYETDINH T4 
                INNER JOIN DM_QD_LOAI T5 ON T4.LOAIQDID=T5.ID
              ) QD ON T2.ID =QD.DONID 
    LEFT JOIN ALD_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
    WHERE T3.NGAYTHULY BETWEEN vDate_Nam_Truoc_DauKy AND vDate_Nam_Truoc_CuoiKy
          AND (BA.DONID || ' '=' ' 
                OR QD.MA || ' '=' ' 
                OR INSTR('CNTT,CVA,DC',QD.MA)=0) -- CHƯA KẾT THÚC
    GROUP BY T1.V_STT
  )LOOP
	v_ARRAY(ITEM.V_STT).V_TONGTHULY:=v_ARRAY(ITEM.V_STT).V_TONGTHULY+ITEM.V_CHUA_GQ_KY_TRUOC;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỔNG SỐ GQ -- V_GQ_TONGGQ
  FOR ITEM IN
  (
    SELECT T1.V_STT, NVL(T2.V_QD,0) + NVL(T3.V_BA,0) V_GQ_TONGGQ
    FROM TABLE(v_ARRAY) T1
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(DISTINCT VA.ID) V_QD FROM ALD_DON VA
                INNER JOIN ALD_PHUCTHAM_QUYETDINH QD ON QD.DONID=VA.ID
                INNER JOIN DM_QD_LOAI Loai ON QD.LOAIQDID=Loai.ID
                WHERE INSTR('CNTT,CVA,DC',Loai.MA)>0
                      AND (QD.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy)
                GROUP BY VA.TOAPHUCTHAMID
                ) T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
    LEFT JOIN (SELECT VA.TOAPHUCTHAMID,COUNT(VA.ID) V_BA FROM ALD_DON VA
                INNER JOIN ALD_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
                WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                GROUP BY VA.TOAPHUCTHAMID
                ) T3 ON T3.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_GQ_TONGGQ:=ITEM.V_GQ_TONGGQ;
  END LOOP;
  -- GIẢI QUYẾT ÁN -- TỶ LỆ GQ -- V_GQ_TYLEGQ
  -- GIẢI QUYẾT ÁN -- Số vụ án TA tổ chức phiên tòa rút kinh nghiệm -- V_GQ_RUTKINHNGHIEM
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_TONGTHULY
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_TONGTHULY FROM ALD_DON T2
                INNER JOIN ALD_PHUCTHAM_THULY T3 ON T2.ID=T3.DONID
                INNER JOIN ALD_SAUXETXU T5 ON T5.VUANID=T2.ID
                WHERE T5.PT_NGAYRUT BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T5.PT_ISRUTKN=1
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_TONGTHULY:=ITEM.V_TONGTHULY;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Tạm đình chỉ -- V_PHANTICH_TAMDINHCHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_TAMDINHCHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_TAMDINHCHI FROM ALD_DON T2
                INNER JOIN ALD_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T2.ID=T3.LOAIQDID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='TDC'
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_TAMDINHCHI:=ITEM.V_PHANTICH_TAMDINHCHI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Y án -- V_PHANTICH_ANLE
  FOR ITEM IN
  (
    SELECT T1.V_STT, COUNT(VA.ID) V_PHANTICH_ANLE
    FROM TABLE(v_ARRAY) T1
    INNER JOIN ALD_DON VA ON VA.TOAPHUCTHAMID=T1.V_TOAAN
    INNER JOIN ALD_PHUCTHAM_BANAN BA ON BA.DONID=VA.ID
    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
          AND BA.APDUNGANLE=1
    GROUP BY T1.V_STT
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_ANLE:=ITEM.V_PHANTICH_ANLE;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Đình chỉ -- Rút kháng cáo -- V_PHANTICH_DC_RUTKHANGCAO
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_RUTKHANGCAO
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_RUTKHANGCAO FROM ALD_DON T2
                INNER JOIN ALD_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')>0
                      AND INSTR(LOWER(T5.TEN),'kháng cáo')>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_RUTKHANGCAO:=ITEM.V_PHANTICH_DC_RUTKHANGCAO;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Đình chỉ -- Rút kháng nghị -- V_PHANTICH_DC_RUTKHANGNGHI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_RUTKHANGNGHI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_RUTKHANGNGHI FROM ALD_DON T2
                INNER JOIN ALD_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')>0
                      AND INSTR(LOWER(T5.TEN),'kháng nghị')>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_RUTKHANGNGHI:=ITEM.V_PHANTICH_DC_RUTKHANGNGHI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Đình chỉ -- Lý do khác -- V_PHANTICH_DC_LYDOKHAC
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_DC_LYDOKHAC
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_DC_LYDOKHAC FROM ALD_DON T2
                INNER JOIN ALD_PHUCTHAM_QUYETDINH T3 ON T2.ID=T3.DONID
                INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
                INNER JOIN DM_QD_QUYETDINH_LYDO T5 ON T5.QDID=T3.QUYETDINHID AND T5.ID=T3.LYDOID
                WHERE T3.NGAYQD BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND T4.MA='DC'
                      AND INSTR(LOWER(T5.TEN),'rút')=0
                      AND (INSTR(LOWER(T5.TEN),'kháng cáo')=0 OR INSTR(LOWER(T5.TEN),'kháng nghị')=0)
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_DC_LYDOKHAC:=ITEM.V_PHANTICH_DC_LYDOKHAC;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Sửa án -- Do cấp ST sai -- V_PHANTICH_SUA_CAPSOTHAMSAI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_SUA_CAPSOTHAMSAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_SUA_CAPSOTHAMSAI FROM ALD_DON T2
                INNER JOIN ALD_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('02,05,16,17',T5.MA)>0
                      AND INSTR('01',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_SUA_CAPSOTHAMSAI:=ITEM.V_PHANTICH_SUA_CAPSOTHAMSAI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Sửa án -- Do có tình tiết mới -- V_PHANTICH_SUA_TINHTIETMOI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_SUA_TINHTIETMOI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_SUA_TINHTIETMOI FROM ALD_DON T2
                INNER JOIN ALD_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('02,05,16,17',T5.MA)>0
                      AND INSTR('03',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_SUA_TINHTIETMOI:=ITEM.V_PHANTICH_SUA_TINHTIETMOI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Huỷ án -- Do cấp ST sai -- V_PHANTICH_HUY_CAPSOTHAMSAI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_HUY_CAPSOTHAMSAI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_HUY_CAPSOTHAMSAI FROM ALD_DON T2
                INNER JOIN ALD_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('03,04,06,13,14',T5.MA)>0
                      AND INSTR('01',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_HUY_CAPSOTHAMSAI:=ITEM.V_PHANTICH_HUY_CAPSOTHAMSAI;
  END LOOP;
  -- PHÂN TÍCH CÁC VỤ ÁN ĐÃ GIẢI QUYẾT -- Huỷ án -- Do có tình tiết mới -- V_PHANTICH_HUY_TINHTIETMOI
  FOR ITEM IN
  (
    SELECT T1.V_STT, T4.V_PHANTICH_HUY_TINHTIETMOI
    FROM TABLE(v_ARRAY) T1
    INNER JOIN (SELECT T2.TOAPHUCTHAMID,COUNT(DISTINCT T2.ID) V_PHANTICH_HUY_TINHTIETMOI FROM ALD_DON T2
                INNER JOIN ALD_PHUCTHAM_BANAN T3 ON T2.ID=T3.DONID
                INNER JOIN DM_KETQUA_PHUCTHAM T5 ON T5.ID=T3.KETQUAPHUCTHAMID
                INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T6 ON T6.ID=T3.LYDOBANANID
                WHERE T3.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
                      AND INSTR('03,04,06,13,14',T5.MA)>0
                      AND INSTR('03',T6.MA)>0
                GROUP BY T2.TOAPHUCTHAMID
                ) T4 ON T4.TOAPHUCTHAMID=T1.V_TOAAN
  )LOOP
    v_ARRAY(ITEM.V_STT).V_PHANTICH_HUY_TINHTIETMOI:=ITEM.V_PHANTICH_HUY_TINHTIETMOI;
  END LOOP;
  -- CÒN LẠI -- V_CONLAI
  -- ÁN QUÁ HẠN LUẬT ĐỊNH CHƯA GQ -- V_QUAHAN_CHUAGQ
--  FOR ITEM IN
--  (
--    SELECT T1.V_STT, COUNT(T2.ID) V_QUAHAN_CHUAGQ
--    FROM TABLE(v_ARRAY) T1
--    INNER JOIN ALD_DON T2 ON T2.TOAPHUCTHAMID=T1.V_TOAAN
--    INNER JOIN ALD_PHUCTHAM_BANAN BA ON T2.ID =BA.DONID
--    WHERE BA.NGAYTUYENAN BETWEEN vDate_Nam_HienTai_DauKy AND vDate_Nam_HienTai_CuoiKy
--          AND (BA.TK_QUAHAN_CHUQUAN=1 OR BA.TK_QUAHAN_KHACHQUAN=1)
--    GROUP BY T1.V_STT
--  )LOOP
--    v_ARRAY(ITEM.V_STT).V_QUAHAN_CHUAGQ:=ITEM.V_QUAHAN_CHUAGQ;
--  END LOOP;
END;

PROCEDURE FILL_GSTP_THONGTIN_CT_TP_SL
(
  v_ARRAY IN OUT GSTP_THONGTIN_CHITIET_TP_T,
  in_THAMPHANID IN NUMBER
)AS
  v_NUM_AHS NUMBER DEFAULT 0;
  v_NUM_ADS NUMBER DEFAULT 0;
  v_NUM_AHN NUMBER DEFAULT 0;
  v_NUM_AHC NUMBER DEFAULT 0;
  v_NUM_AKT NUMBER DEFAULT 0;
  v_NUM_ALD NUMBER DEFAULT 0;
  v_NUM_APS NUMBER DEFAULT 0;
  v_NUM_XLHC NUMBER DEFAULT 0;
BEGIN
  -- 1 Tổng số vụ án được phân công giải quyết -- V_AN_PHANCONG_GIAIQUYET
  -- -- Hình sự
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_AHS FROM AHS_VUAN T1
  LEFT JOIN AHS_THAMPHANGIAIQUYET T2 ON T2.VUANID=T1.ID AND T2.CANBOID=in_THAMPHANID
  LEFT JOIN AHS_SOTHAM_HDXX T3 ON T3.VUANID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN AHS_PHUCTHAM_HDXX T4 ON T4.VUANID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  WHERE T2.VUANID>0
        OR T3.VUANID>0
        OR T4.VUANID>0;
  -- -- Dân sự
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_ADS FROM ADS_DON T1
  LEFT JOIN ADS_DON_THAMPHAN T2 ON T2.DONID=T1.ID AND T2.CANBOID=in_THAMPHANID
  LEFT JOIN ADS_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN ADS_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  WHERE T2.DONID>0
        OR T3.DONID>0
        OR T4.DONID>0;
  -- -- Hôn nhân
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_AHN FROM AHN_DON T1
  LEFT JOIN AHN_DON_THAMPHAN T2 ON T2.DONID=T1.ID AND T2.CANBOID=in_THAMPHANID
  LEFT JOIN AHN_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN AHN_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  WHERE T2.DONID>0
        OR T3.DONID>0
        OR T4.DONID>0;
  -- -- Hành chính
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_AHC FROM AHC_DON T1
  LEFT JOIN AHC_DON_THAMPHAN T2 ON T2.DONID=T1.ID AND T2.CANBOID=in_THAMPHANID
  LEFT JOIN AHC_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN AHC_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  WHERE T2.DONID>0
        OR T3.DONID>0
        OR T4.DONID>0;
  -- -- Kinh tế
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_AKT FROM AKT_DON T1
  LEFT JOIN AKT_DON_THAMPHAN T2 ON T2.DONID=T1.ID AND T2.CANBOID=in_THAMPHANID
  LEFT JOIN AKT_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN AKT_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  WHERE T2.DONID>0
        OR T3.DONID>0
        OR T4.DONID>0;
  -- -- Lao động
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_ALD FROM ALD_DON T1
  LEFT JOIN ALD_DON_THAMPHAN T2 ON T2.DONID=T1.ID AND T2.CANBOID=in_THAMPHANID
  LEFT JOIN ALD_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN ALD_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  WHERE T2.DONID>0
        OR T3.DONID>0
        OR T4.DONID>0;
  -- -- Phá sản
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_APS FROM APS_DON T1
  LEFT JOIN APS_DON_THAMPHAN T2 ON T2.DONID=T1.ID AND T2.CANBOID=in_THAMPHANID
  LEFT JOIN APS_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN APS_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  WHERE T2.DONID>0
        OR T3.DONID>0
        OR T4.DONID>0;
  -- -- XLHC
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_XLHC FROM XLHC_DON T1
  LEFT JOIN XLHC_DON_THAMPHAN T2 ON T2.DONID=T1.ID AND T2.CANBOID=in_THAMPHANID
  LEFT JOIN XLHC_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN XLHC_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  WHERE T2.DONID>0
        OR T3.DONID>0
        OR T4.DONID>0;
  v_ARRAY(1).V_AN_PHANCONG_GIAIQUYET:=v_NUM_AHS+v_NUM_ADS+v_NUM_AHN+v_NUM_AHC+v_NUM_AKT+v_NUM_ALD+v_NUM_APS+v_NUM_XLHC;
  v_NUM_AHS:=0;v_NUM_ADS:=0;v_NUM_AHN:=0;v_NUM_AHC:=0;v_NUM_AKT:=0;v_NUM_ALD:=0;v_NUM_APS:=0;v_NUM_XLHC:=0;
  -- 2 Số vụ án là thành viên HĐXX -- V_AN_THANHVIEN_HDXX
  -- -- Hình sự
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_AHS FROM AHS_VUAN T1
  LEFT JOIN AHS_SOTHAM_HDXX T3 ON T3.VUANID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHANHDXX'
  LEFT JOIN AHS_PHUCTHAM_HDXX T4 ON T4.VUANID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHANHDXX'
  WHERE T3.VUANID>0
        OR T4.VUANID>0;
  -- -- Dân sự
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_ADS FROM ADS_DON T1
  LEFT JOIN ADS_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHANHDXX'
  LEFT JOIN ADS_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHANHDXX'
  WHERE T3.DONID>0
        OR T4.DONID>0;
  -- -- Hôn nhân
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_AHN FROM AHN_DON T1
  LEFT JOIN AHN_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHANHDXX'
  LEFT JOIN AHN_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHANHDXX'
  WHERE T3.DONID>0
        OR T4.DONID>0;
  -- -- Hành chính
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_AHC FROM AHC_DON T1
  LEFT JOIN AHC_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHANHDXX'
  LEFT JOIN AHC_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHANHDXX'
  WHERE T3.DONID>0
        OR T4.DONID>0;
  -- -- Kinh tế
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_AKT FROM AKT_DON T1
  LEFT JOIN AKT_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHANHDXX'
  LEFT JOIN AKT_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHANHDXX'
  WHERE T3.DONID>0
        OR T4.DONID>0;
  -- -- Lao động
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_ALD FROM ALD_DON T1
  LEFT JOIN ALD_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHANHDXX'
  LEFT JOIN ALD_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHANHDXX'
  WHERE T3.DONID>0
        OR T4.DONID>0;
  -- -- Phá sản
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_APS FROM APS_DON T1
  LEFT JOIN APS_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHANHDXX'
  LEFT JOIN APS_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHANHDXX'
  WHERE T3.DONID>0
        OR T4.DONID>0;
  -- -- XLHC
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_XLHC FROM XLHC_DON T1
  LEFT JOIN XLHC_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHANHDXX'
  LEFT JOIN XLHC_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHANHDXX'
  WHERE T3.DONID>0
        OR T4.DONID>0;
  v_ARRAY(1).V_AN_THANHVIEN_HDXX:=v_NUM_AHS+v_NUM_ADS+v_NUM_AHN+v_NUM_AHC+v_NUM_AKT+v_NUM_ALD+v_NUM_APS+v_NUM_XLHC;
  v_NUM_AHS:=0;v_NUM_ADS:=0;v_NUM_AHN:=0;v_NUM_AHC:=0;v_NUM_AKT:=0;v_NUM_ALD:=0;v_NUM_APS:=0;v_NUM_XLHC:=0;
  -- 3 Tổng số vụ án đã giải quyết -- V_AN_DA_GIAIQUYET
  -- -- Án hình sự
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_AHS FROM AHS_VUAN T1
  LEFT JOIN AHS_SOTHAM_HDXX T3 ON T3.VUANID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.VUANID,T2.MA FROM AHS_SOTHAM_QUYETDINH_VUAN T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,CVA',T2.MA)>0
             ) QDST ON T1.ID =QDST.VUANID 
  LEFT JOIN AHS_SOTHAM_BANAN BAST ON T1.ID =BAST.VUANID
  LEFT JOIN AHS_PHUCTHAM_HDXX T4 ON T4.VUANID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.VUANID,T2.MA FROM AHS_SOTHAM_QUYETDINH_VUAN T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,CVA',T2.MA)>0
             ) QDPT ON T1.ID =QDPT.VUANID 
  LEFT JOIN AHS_PHUCTHAM_BANAN BAPT ON T1.ID =BAPT.VUANID
  WHERE (T3.VUANID>0 AND (QDST.VUANID>0 OR BAST.VUANID>0)) --> sơ thẩm
        OR
        (T4.VUANID>0 AND (QDPT.VUANID>0 OR BAPT.VUANID>0)) --> phúc thẩm
        ;
  -- -- Án Dân sự
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_ADS FROM ADS_DON T1
  LEFT JOIN ADS_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.DONID,T2.MA FROM ADS_SOTHAM_QUYETDINH T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,CVA',T2.MA)>0
             ) QDST ON T1.ID =QDST.DONID 
  LEFT JOIN ADS_SOTHAM_BANAN BAST ON T1.ID =BAST.DONID
  LEFT JOIN ADS_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.DONID,T2.MA FROM ADS_SOTHAM_QUYETDINH T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,CVA',T2.MA)>0
             ) QDPT ON T1.ID =QDPT.DONID
  LEFT JOIN ADS_PHUCTHAM_BANAN BAPT ON T1.ID =BAPT.DONID
  WHERE (T3.DONID>0 AND (QDST.DONID>0 OR BAST.DONID>0)) --> sơ thẩm
        OR
        (T4.DONID>0 AND (QDPT.DONID>0 OR BAPT.DONID>0)) --> phúc thẩm
        ;
  -- -- Án Hôn nhân
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_AHN FROM AHN_DON T1
  LEFT JOIN AHN_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.DONID,T2.MA FROM AHN_SOTHAM_QUYETDINH T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,TTLYHON,CVA',T2.MA)>0
             ) QDST ON T1.ID =QDST.DONID 
  LEFT JOIN AHN_SOTHAM_BANAN BAST ON T1.ID =BAST.DONID
  LEFT JOIN AHN_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.DONID,T2.MA FROM AHN_SOTHAM_QUYETDINH T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,TTLYHON,CVA',T2.MA)>0
             ) QDPT ON T1.ID =QDPT.DONID
  LEFT JOIN AHN_PHUCTHAM_BANAN BAPT ON T1.ID =BAPT.DONID
  WHERE (T3.DONID>0 AND (QDST.DONID>0 OR BAST.DONID>0)) --> sơ thẩm
        OR
        (T4.DONID>0 AND (QDPT.DONID>0 OR BAPT.DONID>0)) --> phúc thẩm
        ;
  -- -- Án Hành chính
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_AHC FROM AHC_DON T1
  LEFT JOIN AHC_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.DONID,T2.MA FROM AHC_SOTHAM_QUYETDINH T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,CVA',T2.MA)>0
             ) QDST ON T1.ID =QDST.DONID 
  LEFT JOIN AHC_SOTHAM_BANAN BAST ON T1.ID =BAST.DONID
  LEFT JOIN AHC_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.DONID,T2.MA FROM AHC_SOTHAM_QUYETDINH T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,CVA',T2.MA)>0
             ) QDPT ON T1.ID =QDPT.DONID
  LEFT JOIN AHC_PHUCTHAM_BANAN BAPT ON T1.ID =BAPT.DONID
  WHERE (T3.DONID>0 AND (QDST.DONID>0 OR BAST.DONID>0)) --> sơ thẩm
        OR
        (T4.DONID>0 AND (QDPT.DONID>0 OR BAPT.DONID>0)) --> phúc thẩm
        ;
  -- -- Án Kinh tế
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_AKT FROM AKT_DON T1
  LEFT JOIN AKT_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.DONID,T2.MA FROM AKT_SOTHAM_QUYETDINH T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,CVA',T2.MA)>0
             ) QDST ON T1.ID =QDST.DONID 
  LEFT JOIN AKT_SOTHAM_BANAN BAST ON T1.ID =BAST.DONID
  LEFT JOIN AKT_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.DONID,T2.MA FROM AKT_SOTHAM_QUYETDINH T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,CVA',T2.MA)>0
             ) QDPT ON T1.ID =QDPT.DONID
  LEFT JOIN AKT_PHUCTHAM_BANAN BAPT ON T1.ID =BAPT.DONID
  WHERE (T3.DONID>0 AND (QDST.DONID>0 OR BAST.DONID>0)) --> sơ thẩm
        OR
        (T4.DONID>0 AND (QDPT.DONID>0 OR BAPT.DONID>0)) --> phúc thẩm
        ;
  -- -- Án Lao động
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_ALD FROM ALD_DON T1
  LEFT JOIN ALD_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.DONID,T2.MA FROM ALD_SOTHAM_QUYETDINH T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,CVA',T2.MA)>0
             ) QDST ON T1.ID =QDST.DONID 
  LEFT JOIN ALD_SOTHAM_BANAN BAST ON T1.ID =BAST.DONID
  LEFT JOIN ALD_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.DONID,T2.MA FROM ALD_SOTHAM_QUYETDINH T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,CVA',T2.MA)>0
             ) QDPT ON T1.ID =QDPT.DONID
  LEFT JOIN ALD_PHUCTHAM_BANAN BAPT ON T1.ID =BAPT.DONID
  WHERE (T3.DONID>0 AND (QDST.DONID>0 OR BAST.DONID>0)) --> sơ thẩm
        OR
        (T4.DONID>0 AND (QDPT.DONID>0 OR BAPT.DONID>0)) --> phúc thẩm
        ;
  -- -- Án Phá sản
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_APS FROM APS_DON T1
  LEFT JOIN APS_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.DONID,T2.MA FROM APS_SOTHAM_QUYETDINH T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,CVA',T2.MA)>0
             ) QDST ON T1.ID =QDST.DONID 
  LEFT JOIN APS_SOTHAM_BANAN BAST ON T1.ID =BAST.DONID
  LEFT JOIN APS_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.DONID,T2.MA FROM APS_SOTHAM_QUYETDINH T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,CVA',T2.MA)>0
             ) QDPT ON T1.ID =QDPT.DONID
  LEFT JOIN APS_PHUCTHAM_BANAN BAPT ON T1.ID =BAPT.DONID
  WHERE (T3.DONID>0 AND (QDST.DONID>0 OR BAST.DONID>0)) --> sơ thẩm
        OR
        (T4.DONID>0 AND (QDPT.DONID>0 OR BAPT.DONID>0)) --> phúc thẩm
        ;
  -- -- Án XLHC
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_XLHC FROM XLHC_DON T1
  LEFT JOIN XLHC_SOTHAM_HDXX T3 ON T3.DONID=T1.ID AND T3.CANBOID=in_THAMPHANID AND T3.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.DONID,T2.MA FROM XLHC_SOTHAM_QUYETDINH T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,CVA',T2.MA)>0
             ) QDST ON T1.ID =QDST.DONID 
  LEFT JOIN XLHC_SOTHAM_BANAN BAST ON T1.ID =BAST.DONID
  LEFT JOIN XLHC_PHUCTHAM_HDXX T4 ON T4.DONID=T1.ID AND T4.CANBOID=in_THAMPHANID AND T4.MAVAITRO='THAMPHAN'
  LEFT JOIN ( SELECT T1.DONID,T2.MA FROM XLHC_SOTHAM_QUYETDINH T1 
              INNER JOIN DM_QD_LOAI T2 ON T1.LOAIQDID=T2.ID
              WHERE INSTR('DC,CNTT,CVA',T2.MA)>0
             ) QDPT ON T1.ID =QDPT.DONID
  LEFT JOIN XLHC_PHUCTHAM_BANAN BAPT ON T1.ID =BAPT.DONID
  WHERE (T3.DONID>0 AND (QDST.DONID>0 OR BAST.DONID>0)) --> sơ thẩm
        OR
        (T4.DONID>0 AND (QDPT.DONID>0 OR BAPT.DONID>0)) --> phúc thẩm
        ;
  v_ARRAY(1).V_AN_DA_GIAIQUYET:=v_NUM_AHS+v_NUM_ADS+v_NUM_AHN+v_NUM_AHC+v_NUM_AKT+v_NUM_ALD+v_NUM_APS+v_NUM_XLHC;
  v_NUM_AHS:=0;v_NUM_ADS:=0;v_NUM_AHN:=0;v_NUM_AHC:=0;v_NUM_AKT:=0;v_NUM_ALD:=0;v_NUM_APS:=0;v_NUM_XLHC:=0;
  -- 4 Tổng số vụ án có kháng cáo/kháng nghị -- V_AN_KHANGNGHI_KHANGCAO
  -- -- Hình sự
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_AHS FROM AHS_VUAN T1
  INNER JOIN AHS_SOTHAM_HDXX T2 ON T2.VUANID=T1.ID AND T2.CANBOID=in_THAMPHANID AND T2.MAVAITRO='THAMPHAN'
