  LEFT JOIN XLHC_SOTHAM_KHANGNGHI T4 ON T4.DONID=T1.ID
  WHERE T3.DONID>0 OR T4.DONID>0;
  v_ARRAY(1).V_AN_KHANGNGHI_KHANGCAO:=v_NUM_AHS+v_NUM_ADS+v_NUM_AHN+v_NUM_AHC+v_NUM_AKT+v_NUM_ALD+v_NUM_APS+v_NUM_XLHC;
  v_NUM_AHS:=0;v_NUM_ADS:=0;v_NUM_AHN:=0;v_NUM_AHC:=0;v_NUM_AKT:=0;v_NUM_ALD:=0;v_NUM_APS:=0;v_NUM_XLHC:=0;
  -- 5 Tổng số vụ án vi phạm thời hạn tạm giam -- V_AN_VIPHAM_THOIHAN_TAMGIAM
  SELECT COUNT(DISTINCT T1.ID) INTO v_NUM_AHS FROM AHS_VUAN T1
