  v_ARRAY(1).V_AN_VIPHAM_THOIHAN_TAMGIAM:=v_NUM_AHS+v_NUM_ADS+v_NUM_AHN+v_NUM_AHC+v_NUM_AKT+v_NUM_ALD+v_NUM_APS+v_NUM_XLHC;
  v_NUM_AHS:=0;v_NUM_ADS:=0;v_NUM_AHN:=0;v_NUM_AHC:=0;v_NUM_AKT:=0;v_NUM_ALD:=0;v_NUM_APS:=0;v_NUM_XLHC:=0;
  -- 6 Tổng số vụ án bị hủy -- V_AN_HUY
