  INNER JOIN AHS_PHUCTHAM_BANAN T3 ON T3.VUANID=T1.ID
  INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
  INNER JOIN DM_KETQUA_PHUCTHAM_LYDO T5 ON T5.ID=T3.LYDOBANANID
