  v_NUM_AHS:=0;v_NUM_ADS:=0;v_NUM_AHN:=0;v_NUM_AHC:=0;v_NUM_AKT:=0;v_NUM_ALD:=0;v_NUM_APS:=0;v_NUM_XLHC:=0;
  -- 18 Tổng số hồ sơ vụ án VKS chưa trả -- V_AN_HOSO_VKS_CHUA_TRA
  v_ARRAY(1).V_AN_HOSO_VKS_CHUA_TRA:=v_NUM_AHS+v_NUM_ADS+v_NUM_AHN+v_NUM_AHC+v_NUM_AKT+v_NUM_ALD+v_NUM_APS+v_NUM_XLHC;
  
END;

FUNCTION FUN_GSTP_HOME_ST 
(
  inToaAnID IN NUMBER,
  inCapToa IN VARCHAR2,
  vHienTai_TuNgay IN DATE,
  vHienTai_DenNgay IN DATE,
  vTruoc_TuNgay IN DATE,
  vTruoc_DenNgay IN DATE
) RETURN GSTP_HOME_ST_PT_T PIPELINED 
AS
  v_CAPTOA VARCHAR2(25) DEFAULT NULL;
  v_ARRAY GSTP_HOME_ST_PT_T;
BEGIN
  v_CAPTOA:=inCapToa;
  -- Nếu inToaAnID=0 và v_CAPTOA=NULL => cả nước
  IF v_CAPTOA || ' '=' ' THEN --> Lấy tất cả các tòa xét xử sơ thẩm
    SELECT GSTP_HOME_ST_PT_R(
      V_STT => ROW_NUMBER() OVER(ORDER BY T1.ID),
      V_TOAAN => T1.ID,
      V_THULYMOI =>0,
      V_TONGTHULY =>0,
      V_GIAIQUYET =>0,
      V_GIAIQUYET_TYLE =>0,
      V_ANHUY_SUA =>0,
      V_ANHUY_SUA_TYLE =>0,
      V_CHUA_GQ =>0,
      V_CHUA_GQ_TYLE =>0,
      V_QUAHAN =>0,
      V_RUTKN =>0,
      V_RUTKN_THAMPHAN =>0,
      V_HINHSU_TONGTHULY =>0,
      V_HINHSU_TONGGIAIQUYET =>0,
      V_DANSU_TONGTHULY =>0,
      V_DANSU_TONGGIAIQUYET =>0,
      V_HNGD_TONGTHULY =>0,
      V_HNGD_TONGGIAIQUYET =>0,
      V_KDTM_TONGTHULY =>0,
      V_KDTM_TONGGIAIQUYET =>0,
      V_HANHCHINH_TONGTHULY =>0,
      V_HANHCHINH_TONGGIAIQUYET =>0,
      V_LAODONG_TONGTHULY =>0,
      V_LAODONG_TONGGIAIQUYET =>0
    ) BULK COLLECT INTO v_ARRAY
    FROM DM_TOAAN T1
    WHERE INSTR('CAPTINH,CAPHUYEN,QSQUANKHU,QSKHUVUC',T1.LOAITOA)>0
          AND T1.HIEULUC=1;
  ELSE --> Tính sơ thẩm của đơn vị LOGIN
    SELECT GSTP_HOME_ST_PT_R(
      V_STT => ROW_NUMBER() OVER(ORDER BY T1.ID),
      V_TOAAN => T1.ID,
      V_THULYMOI =>0,
      V_TONGTHULY =>0,
      V_GIAIQUYET =>0,
      V_GIAIQUYET_TYLE =>0,
      V_ANHUY_SUA =>0,
      V_ANHUY_SUA_TYLE =>0,
      V_CHUA_GQ =>0,
      V_CHUA_GQ_TYLE =>0,
      V_QUAHAN =>0,
      V_RUTKN =>0,
      V_RUTKN_THAMPHAN =>0,
      V_HINHSU_TONGTHULY =>0,
      V_HINHSU_TONGGIAIQUYET =>0,
      V_DANSU_TONGTHULY =>0,
      V_DANSU_TONGGIAIQUYET =>0,
      V_HNGD_TONGTHULY =>0,
      V_HNGD_TONGGIAIQUYET =>0,
      V_KDTM_TONGTHULY =>0,
      V_KDTM_TONGGIAIQUYET =>0,
      V_HANHCHINH_TONGTHULY =>0,
      V_HANHCHINH_TONGGIAIQUYET =>0,
      V_LAODONG_TONGTHULY =>0,
      V_LAODONG_TONGGIAIQUYET =>0
    ) BULK COLLECT INTO v_ARRAY
    FROM DM_TOAAN T1
    WHERE T1.ID=inToaAnID;
  END IF;
  -- Các tòa khác sẽ gọi
  IF INSTR('CAPTINH,CAPHUYEN,QSQUANKHU,QSKHUVUC',v_CAPTOA)>0 OR v_CAPTOA || ' '=' ' THEN
    PKG_GSTP.FILL_GSTP_HOME_ST(v_ARRAY,vHienTai_TuNgay,vHienTai_DenNgay,vTruoc_TuNgay,vTruoc_DenNgay);
  END IF;

  FOR ITEM IN 
  (SELECT 
    SUM(V_THULYMOI) V_THULYMOI,
    SUM(V_TONGTHULY) V_TONGTHULY,
    SUM(V_GIAIQUYET) V_GIAIQUYET,
    DECODE(SUM(V_TONGTHULY),0,0,ROUND(SUM(V_GIAIQUYET)/SUM(V_TONGTHULY)*100)) V_GIAIQUYET_TYLE,
    SUM(V_ANHUY_SUA) V_ANHUY_SUA,
    DECODE(SUM(V_TONGTHULY),0,0,ROUND(SUM(V_ANHUY_SUA)/SUM(V_TONGTHULY)*100)) V_ANHUY_SUA_TYLE,
    SUM(V_TONGTHULY)-SUM(V_GIAIQUYET) V_CHUA_GQ,
    DECODE(SUM(V_TONGTHULY),0,0,ROUND((SUM(V_TONGTHULY)-SUM(V_GIAIQUYET))/SUM(V_TONGTHULY)*100)) V_CHUA_GQ_TYLE,
    SUM(V_QUAHAN) V_QUAHAN,
    SUM(V_RUTKN) V_RUTKN,
    SUM(V_RUTKN_THAMPHAN) V_RUTKN_THAMPHAN,
    SUM(V_HINHSU_TONGTHULY) V_HINHSU_TONGTHULY,
    SUM(V_HINHSU_TONGGIAIQUYET) V_HINHSU_TONGGIAIQUYET,
    SUM(V_DANSU_TONGTHULY) V_DANSU_TONGTHULY,
    SUM(V_DANSU_TONGGIAIQUYET) V_DANSU_TONGGIAIQUYET,
    SUM(V_HNGD_TONGTHULY) V_HNGD_TONGTHULY,
    SUM(V_HNGD_TONGGIAIQUYET) V_HNGD_TONGGIAIQUYET,
    SUM(V_KDTM_TONGTHULY) V_KDTM_TONGTHULY,
    SUM(V_KDTM_TONGGIAIQUYET) V_KDTM_TONGGIAIQUYET,
    SUM(V_HANHCHINH_TONGTHULY) V_HANHCHINH_TONGTHULY,
    SUM(V_HANHCHINH_TONGGIAIQUYET) V_HANHCHINH_TONGGIAIQUYET,
    SUM(V_LAODONG_TONGTHULY) V_LAODONG_TONGTHULY,
    SUM(V_LAODONG_TONGGIAIQUYET) V_LAODONG_TONGGIAIQUYET
  FROM TABLE(v_ARRAY) T1
  ) LOOP
    PIPE ROW(GSTP_HOME_ST_PT_R(1,inToaAnID,ITEM.V_THULYMOI,ITEM.V_TONGTHULY,ITEM.V_GIAIQUYET,ITEM.V_GIAIQUYET_TYLE,ITEM.V_ANHUY_SUA,ITEM.V_ANHUY_SUA_TYLE,ITEM.V_CHUA_GQ,ITEM.V_CHUA_GQ_TYLE,ITEM.V_QUAHAN,ITEM.V_RUTKN,ITEM.V_RUTKN_THAMPHAN,ITEM.V_HINHSU_TONGTHULY,ITEM.V_HINHSU_TONGGIAIQUYET,ITEM.V_DANSU_TONGTHULY,ITEM.V_DANSU_TONGGIAIQUYET,ITEM.V_HNGD_TONGTHULY,ITEM.V_HNGD_TONGGIAIQUYET,ITEM.V_KDTM_TONGTHULY,ITEM.V_KDTM_TONGGIAIQUYET,ITEM.V_HANHCHINH_TONGTHULY,ITEM.V_HANHCHINH_TONGGIAIQUYET,ITEM.V_LAODONG_TONGTHULY,ITEM.V_LAODONG_TONGGIAIQUYET));
  END LOOP;
END FUN_GSTP_HOME_ST;

