    SUM(V_LAODONG_TONGTHULY) V_LAODONG_TONGTHULY,
    SUM(V_LAODONG_TONGGIAIQUYET) V_LAODONG_TONGGIAIQUYET
  FROM TABLE(v_ARRAY) T1
  ) LOOP
    PIPE ROW(GSTP_HOME_ST_PT_R(1,inToaAnID,ITEM.V_THULYMOI,ITEM.V_TONGTHULY,ITEM.V_GIAIQUYET,ITEM.V_GIAIQUYET_TYLE,ITEM.V_ANHUY_SUA,ITEM.V_ANHUY_SUA_TYLE,ITEM.V_CHUA_GQ,ITEM.V_CHUA_GQ_TYLE,ITEM.V_QUAHAN,ITEM.V_RUTKN,ITEM.V_RUTKN_THAMPHAN,ITEM.V_HINHSU_TONGTHULY,ITEM.V_HINHSU_TONGGIAIQUYET,ITEM.V_DANSU_TONGTHULY,ITEM.V_DANSU_TONGGIAIQUYET,ITEM.V_HNGD_TONGTHULY,ITEM.V_HNGD_TONGGIAIQUYET,ITEM.V_KDTM_TONGTHULY,ITEM.V_KDTM_TONGGIAIQUYET,ITEM.V_HANHCHINH_TONGTHULY,ITEM.V_HANHCHINH_TONGGIAIQUYET,ITEM.V_LAODONG_TONGTHULY,ITEM.V_LAODONG_TONGGIAIQUYET));
  END LOOP;
END FUN_GSTP_HOME_PT;

FUNCTION FUN_GSTP_HOME_GDT 
(
  inToaAn IN NUMBER,
  vHienTai_TuNgay IN DATE,
  vHienTai_DenNgay IN DATE
) RETURN GSTP_HOME_GDT_T PIPELINED
AS
  --ArrSapXep_AnQuocHoi varchar2(250);
  --ArrSapXep_1033 varchar2(250);
  vSoNgayConThoiHieu number:=90;
  /*--------------Cac bien lay du lieu ---------------*/
  /*-----1.Vu an co don GDTTT-------------*/
  rDonVuAn_TongVuAn_KyBC number; 
  ---an 8.1---
  rDonVuAn_TongAnQH_KyBC number;
  ---sap het thoi hieu---------
  rDonVuAn_HetThoiHieu_KyBC number;
  ------------
  rDonVuAn_DaGQ_KyBC number;
  ------------
  rDonVuAn_ChuaGQ_KyBC number;
  /*-------2.Thong ke theo don GDTTT------------*/
  rDonGDT_TongDon_KyBC number;
  ------Don chuyen cac Vu, CQ------
  rDonGDT_ChuyenVu1_KyBC number;
  rDonGDT_ChuyenVu2_KyBC number;
  rDonGDT_ChuyenVu3_KyBC number;
  rDonGDT_ChuyenCQKhac_KyBC number;
  /*-------3.Thong ke theo XX GDTTT----------------*/
  rXX_TonKyTruoc number;
  rXX_TongSo_KyBC number;
  rXX_DaGQ_KyBC number;
  rXX_ChuaGQ_KyBC number;  
  rXX_AnQuaHan_KyBC number;
  ---------4.XXGDT theo loai an-----------------------
  rXX_HS_ThuLy number; rXX_HS_GiaiQuyet number;  
  rXX_DS_ThuLy number; rXX_DS_GiaiQuyet number;  
  rXX_HC_ThuLy number; rXX_HC_GiaiQuyet number;    
  rXX_HNGD_ThuLy number; rXX_HNGD_GiaiQuyet number;  
  rXX_LD_ThuLy number; rXX_LD_GiaiQuyet number;  
  rXX_KDTM_ThuLy number;  rXX_KDTM_GiaiQuyet number;
  /*--------Thong ke theo XX GDTTT----------------*/
  XX_TongSo_KyBC number;
BEGIN
  ------------Tong so vu an co don GDTTT trong ky/nam truoc (lay theo ngay nhan don)---------------
  select count (distinct(VuViecID)) into rDonVuAn_TongVuAn_KyBC from GDTTT_don 
  where NVL(VuViecId,0)>0 and CD_TRangThai=2 and CD_NgayXULy is not null
    and (CD_NgayXuLy between vHienTai_TuNgay and vHienTai_DenNgay)
    and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
    
  ----donvuan loai 8.1------------------
  select count(ID) into rDonVuAn_TongAnQH_KyBC from GDTTT_VuAn 
  where ID in (select distinct NVL(VuViecID,0) from GDTTT_Don where NVL(VuViecId,0)>0 and CD_TrangThai=2)
      and (NgayThuLyDon between vHienTai_TuNgay and vHienTai_DenNgay) and NVL(IsAnQuocHoi,0)=1
      and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  
 ----an thoi hieu---------------------
 select count(ID) into rDonVuAn_HetThoiHieu_KyBC from GDTTT_VuAn 
 where ID in (select distinct NVL(VuViecID,0) from GDTTT_Don where NVL(VuViecId,0)>0 and CD_TrangThai=2)
    and NgayThuLyDon<=vHienTai_DenNgay
    and GDTTT_VuAn_CheckHetHanThoiHieu(NVL(LoaiAn,0), NGAYXUPHUCTHAM, NGAYXUSOTHAM
                                      ,NVL(ThuLyLai_VuAnId, 0),vHienTai_DenNgay,vSoNgayConThoiHieu)>0
    and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
 
 ----An da giai quyet-----------------------------------
  select count(ID) into rDonVuAn_DaGQ_KyBC from GDTTT_VuAn 
  where ID in (select distinct NVL(VuViecID,0) from GDTTT_Don where NVL(VuViecId,0)>0 and CD_TrangThai=2)
      and NVL(GQD_LoaiKetQua,4)<=3 and (GDQ_Ngay between vHienTai_TuNgay and vHienTai_DenNgay)
      and NgayThuLyDon<=vHienTai_DenNgay
      and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
	  
  ----An chua giai quyet-----------------------------------
--  select count(ID) into rDonVuAn_ChuaGQ_KyBC from GDTTT_VuAn 
--  where ID in (select distinct NVL(VuViecID,0) from GDTTT_Don where NVL(VuViecId,0)>0 and CD_TrangThai=2)
--      and (NVL(GQD_LoaiKetQua,4)=4 
--            or (NVL(GQD_LoaiKetQua,4)<=3 and (GDQ_Ngay < vHienTai_TuNgay or GDQ_Ngay> vHienTai_DenNgay))
--          )
--      and NgayThuLyDon<=vHienTai_DenNgay
--      and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  rDonVuAn_ChuaGQ_KyBC:= NVL(rDonVuAn_TongVuAn_KyBC,0) - NVL(rDonVuAn_DaGQ_KyBC,0);
  /*=================================================================*/
  ------------Tong so don GDTTT trong ky/nam truoc (lay theo ngay nhan don)---------------
  select count(ID) into rDonGDT_TongDon_KyBC from GDTTT_don 
  where (CD_NgayXuLy is not null) 
        and (CD_NgayXuLy between vHienTai_TuNgay and vHienTai_DenNgay) 
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  ----------Tong don chuyen cac vu: GDTTT_Don.CD_TA_DONVIID --------------------------------
  -----Chuyen vu 1: CD_TA_DONVIID =2--> Lay theo ngay chuyen don
  select count(ID) into rDonGDT_ChuyenVu1_KyBC from GDTTT_don 
  where CD_NgayXuLy is not null and CD_TrangThai in (1,2)  
        and CD_TA_DONVIID=2
        and (CD_NgayXuLy between vHienTai_TuNgay and vHienTai_DenNgay) 
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  -----chuyen vu 2:CD_TA_DONVIID =3
  select count(ID) into rDonGDT_ChuyenVu2_KyBC from GDTTT_don 
  where CD_NgayXuLy is not null and CD_TrangThai in (1,2)  
        and CD_TA_DONVIID=3
        and (CD_NgayXuLy between vHienTai_TuNgay and vHienTai_DenNgay) 
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  -----chuyen vu 3:CD_TA_DONVIID=4
  select count(ID) into rDonGDT_ChuyenVu3_KyBC from GDTTT_don 
  where CD_NgayXuLy is not null and CD_TrangThai in (1,2)  
        and CD_TA_DONVIID=4
        and (CD_NgayXuLy between vHienTai_TuNgay and vHienTai_DenNgay) 
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  -------chuyen co quan khac ------------
  select  count(ID) into rDonGDT_ChuyenCQKhac_KyBC from GDTTT_don 
  where CD_NgayXuLy is not null and CD_TrangThai in (1,2)  
        and CD_TA_DONVIID not in (2,3,4)
        and (CD_NgayXuLy between vHienTai_TuNgay and vHienTai_DenNgay) 
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  /*=================================================================*/
  /*Quy tac tinh so lieu thong ke XXGDT:   
    so lieu thu ly kyBC = ton ky truoc + da thu ly ky nay (neu la thu ly xxgdt --> ngay thu ly vu an<=DenNgay)
    ton ky truoc = so vu da thu ly truoc ky bc va chua co kq xx*/
 
  -----------XX_GDTTT : Tong so-----------------------------
  select  count(ID) into rXX_TongSo_KyBC from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 
        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay) 
        and NGAYTHULYDON<=vHienTai_DenNgay 
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
        
  select  count(ID) into rXX_TonKyTruoc from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 
        and (NgayThuLyXXGDT < vHienTai_TuNgay) 
        and NGAYTHULYDON<vHienTai_TuNgay and GDTTT_XXGDTTT_GetLastXX(ID, 0)=0 
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
       
  XX_TongSo_KyBC:= NVL(rXX_TongSo_KyBC,0) + NVL(rXX_TonKyTruoc,0);
  
  ----------XXGDT_Da giai quyet----------------
  select  count(ID) into rXX_DaGQ_KyBC from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 
        and GDTTT_XXGDTTT_GetLastXX(ID, 0)>0
        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay)
        and NGAYTHULYDON<=vHienTai_DenNgay 
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  ----------XXGDT_chua giai quyet----------------
--  select  count(ID) into rXX_ChuaGQ_KyBC from GDTTT_VuAn
--  where NVL(TrangThaiID,0)=15 
--        and GDTTT_XXGDTTT_GetLastXX(ID, 0)=0
--        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay)
--        and NGAYTHULYDON<=vHienTai_DenNgay 
--        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  rXX_ChuaGQ_KyBC:=NVL( XX_TongSo_KyBC,0) - NVL(rXX_DaGQ_KyBC,0);  
  ----------XXGDTT---An het thoi hieu-----------------
  /*rXX_AnQuaHan_KyBC, rXX_AnQuaHan_KyTruoc*/
  select  count(ID) into rXX_AnQuaHan_KyBC from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 
        and GDTTT_XXGDTTT_GetLastXX(ID, 0)=0
        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay)
        and NGAYTHULYDON<=vHienTai_DenNgay
        and GDTTT_CheckThoiHieuByTime(NVL(LoaiAn,0), NGAYXUPHUCTHAM , NGAYXUSOTHAM
                                  , NVL(ThuLyLai_VuAnId, 0),vHienTai_TuNgay, vHienTai_DenNgay)=2 
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  --=====================================================================
  ----------XXGDT theo loai an-----------------------
  select count(ID) into rXX_HS_ThuLy from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 AND LoaiAn =1 
        and NGAYTHULYDON<=vHienTai_DenNgay 
        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay)
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  
  select count(ID) into rXX_HS_GiaiQuyet from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 and LoaiAn =1 
        and NGAYTHULYDON<=vHienTai_DenNgay 
        and GDTTT_XXGDTTT_GetLastXX(ID, 0)>0 
        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay)
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  --------------------
  select count(ID) into rXX_DS_ThuLy from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 
        and LoaiAn =2  
        and NGAYTHULYDON<=vHienTai_DenNgay 
        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay)
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  
  select  count(ID) into rXX_DS_GiaiQuyet from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 
        and LoaiAn =2  
        and NGAYTHULYDON<=vHienTai_DenNgay 
        and GDTTT_XXGDTTT_GetLastXX(ID, 0)>0
        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay)
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
        
  --------------------   
  select count(ID) into rXX_HC_ThuLy from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 
        and LoaiAn =6  
        and NGAYTHULYDON<=vHienTai_DenNgay 
        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay)
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  
  select  count(ID) into rXX_HC_GiaiQuyet from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 
        and LoaiAn =6  
        and NGAYTHULYDON<=vHienTai_DenNgay 
        and GDTTT_XXGDTTT_GetLastXX(ID, 0)>0
        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay)
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;  
        
   --------------------   
  select  count(ID) into rXX_HNGD_ThuLy from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 
        and LoaiAn =3  
        and NGAYTHULYDON<=vHienTai_DenNgay 
        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay)
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  
  select  count(ID) into rXX_HNGD_GiaiQuyet from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 
        and LoaiAn =3  
        and NGAYTHULYDON<=vHienTai_DenNgay 
        and GDTTT_XXGDTTT_GetLastXX(ID, 0)>0
        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay)
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;    
        
   --------------------   
  select  count(ID) into rXX_LD_ThuLy from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 
        and LoaiAn =5  
        and NGAYTHULYDON<=vHienTai_DenNgay 
        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay)
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  
  select  count(ID) into rXX_LD_GiaiQuyet from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 
        and LoaiAn =5  
        and NGAYTHULYDON<=vHienTai_DenNgay 
        and GDTTT_XXGDTTT_GetLastXX(ID, 0)>0
        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay)
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end; 
        
   --------------------   
  select  count(ID) into rXX_KDTM_ThuLy from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 
        and LoaiAn =4  
        and NGAYTHULYDON<=vHienTai_DenNgay 
        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay)
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  
  select  count(ID) into rXX_KDTM_GiaiQuyet from GDTTT_VuAn
  where NVL(TrangThaiID,0)=15 
        and LoaiAn =4 
        and GDTTT_XXGDTTT_GetLastXX(ID, 0)>0
        and (NgayThuLyXXGDT between vHienTai_TuNgay and vHienTai_DenNgay)
        and 1=case when inToaAn=0 then 1 when TOAANID=inToaAn then 1 else 0 end;
  
  FOR ITEM IN 
  (
    SELECT   NVL(rDonVuAn_TongVuAn_KyBC,0) as DonVuAn_TongVuAn_KyBC
            , NVL(rDonVuAn_TongAnQH_KyBC,0) as DonVuAn_TongAnQH_KyBC
            , NVL(rDonVuAn_HetThoiHieu_KyBC,0) as DonVuAn_HetThoiHieu_KyBC
            , NVL(rDonVuAn_DaGQ_KyBC,0) as DonVuAn_DaGQ_KyBC
            , NVL(rDonVuAn_ChuaGQ_KyBC,0) as DonVuAn_ChuaGQ_KyBC
            
            , NVL(rDonGDT_TongDon_KyBC,0) as DonGDT_TongDon_KyBC
            , NVL(rDonGDT_ChuyenVu1_KyBC,0) as DonGDT_ChuyenVu1_KyBC
            , NVL(rDonGDT_ChuyenVu2_KyBC,0) as DonGDT_ChuyenVu2_KyBC
            , NVL(rDonGDT_ChuyenVu3_KyBC,0) as DonGDT_ChuyenVu3_KyBC
            , NVL(rDonGDT_ChuyenCQKhac_KyBC,0) as DonGDT_ChuyenCQKhac_KyBC
           
            , NVL(XX_TongSo_KyBC,0) as XX_TongSo_KyBC
            , NVL(rXX_DaGQ_KyBC,0) as XX_DaGQ_KyBC
            , NVL(rXX_ChuaGQ_KyBC,0) as XX_ChuaGQ_KyBC
            , NVL(rXX_AnQuaHan_KyBC,0) as XX_AnQuaHan_KyBC
            
            , NVL(rXX_HS_ThuLy,0) as XX_HS_ThuLy
            , NVL(rXX_HS_GiaiQuyet,0) as XX_HS_GiaiQuyet
            , NVL(rXX_DS_ThuLy,0) as XX_DS_ThuLy
            , NVL(rXX_DS_GiaiQuyet,0)  as XX_DS_GiaiQuyet
            , NVL(rXX_HC_ThuLy,0) as XX_HC_ThuLy
            , NVL(rXX_HC_GiaiQuyet,0) as XX_HC_GiaiQuyet
            , NVL(rXX_HNGD_ThuLy,0) as XX_HNGD_ThuLy
            , NVL(rXX_HNGD_GiaiQuyet,0)  as XX_HNGD_GiaiQuyet
            , NVL(rXX_LD_ThuLy,0) as XX_LD_ThuLy
            , NVL(rXX_LD_GiaiQuyet,0) as XX_LD_GiaiQuyet
            , NVL(rXX_KDTM_ThuLy,0) as XX_KDTM_ThuLy
            , NVL(rXX_KDTM_GiaiQuyet, 0) as XX_KDTM_GiaiQuyet
            , NVL(rXX_TongSo_KyBC,0) as XX_ThuLyMoi
        FROM dual
  ) LOOP
    PIPE ROW(GSTP_HOME_GDT_R(1,inToaAn,ITEM.DonVuAn_TongVuAn_KyBC,ITEM.DonVuAn_TongAnQH_KyBC,ITEM.DonVuAn_HetThoiHieu_KyBC,ITEM.DonVuAn_DaGQ_KyBC,ITEM.DonVuAn_ChuaGQ_KyBC,ITEM.DonGDT_TongDon_KyBC,ITEM.DonGDT_ChuyenVu1_KyBC,ITEM.DonGDT_ChuyenVu2_KyBC,ITEM.DonGDT_ChuyenVu3_KyBC,ITEM.DonGDT_ChuyenCQKhac_KyBC,ITEM.XX_TongSo_KyBC,ITEM.XX_DaGQ_KyBC,ITEM.XX_ChuaGQ_KyBC,ITEM.XX_AnQuaHan_KyBC,ITEM.XX_HS_ThuLy,ITEM.XX_HS_GiaiQuyet,ITEM.XX_DS_ThuLy,ITEM.XX_DS_GiaiQuyet,ITEM.XX_HC_ThuLy,ITEM.XX_HC_GiaiQuyet,ITEM.XX_HNGD_ThuLy,ITEM.XX_HNGD_GiaiQuyet,ITEM.XX_LD_ThuLy,ITEM.XX_LD_GiaiQuyet,ITEM.XX_KDTM_ThuLy,ITEM.XX_KDTM_GiaiQuyet,ITEM.XX_ThuLyMoi));
  END LOOP;
END FUN_GSTP_HOME_GDT;

FUNCTION FUN_GSTP_HOME_TP_DANGCT 
(
  inToaAn IN NUMBER,
  inCapToa IN VARCHAR2,
  vHienTai_TuNgay IN DATE,
  vHienTai_DenNgay IN DATE
) RETURN T_ID PIPELINED
AS
  vCapToa VARCHAR2(25);
  isCaNuoc NUMBER DEFAULT 0;
  vGroupChucDanhID NUMBER DEFAULT 0;
  vDangCongTac NUMBER DEFAULT 1;
BEGIN
  vCapToa:=inCapToa;
  SELECT ID INTO vGroupChucDanhID FROM DM_DATAGROUP WHERE MA='CHUCDANH';
  IF vCapToa || ' '=' ' THEN
    isCaNuoc:=1;
  END IF;
  FOR ITEM IN 
  (
    SELECT COUNT(T2.ID) V_TP_DANGCONGTAC 
    FROM DM_TOAAN T1
    INNER JOIN DM_CANBO T2 ON T1.ID=T2.TOAANID
    INNER JOIN DM_DATAITEM T3 ON T3.ID=T2.CHUCDANHID
    WHERE T1.HIEULUC=1
      AND 1=CASE WHEN isCaNuoc=1 THEN 1 WHEN isCaNuoc=0 AND T1.ID=inToaAn THEN 1 ELSE 0 END
      AND T2.HIEULUC=vDangCongTac
      AND T3.GROUPID=vGroupChucDanhID
      AND INSTR('TPSC,TPTC,TPCC',T3.MA)>0
  ) LOOP
    PIPE ROW(R_ID(ITEM.V_TP_DANGCONGTAC));
  END LOOP;
END;

FUNCTION FUN_GETVUANBPTT_BY_TP
(
	vThamPhanID IN NUMBER,
	vNgayBoNhiem in date,
	vNgayKetThuc in date,
	vLoaiAn in varchar2
) RETURN NUMBER AS
	vTongAnTDC number:=0;
	vADS_ST number:=0;vADS_PT number:=0; vAHC_ST number:=0;vAHC_PT number:=0;
	vAHN_ST number:=0;vAHN_PT number:=0; vAKT_ST number:=0;vAKT_PT number:=0;
	vALD_ST number:=0;vALD_PT number:=0; vAHS_ST number:=0;vAHS_PT number:=0;
	vAPS_ST number:=0;vAPS_PT number:=0; vXLHC_ST number:=0;vXLHC_PT number:=0;
BEGIN
	if INSTR(vLoaiAn,'AN_DANSU,')>0 then
	-- Dân sự sơ thẩm
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vADS_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from ADS_SOTHAM_HDXX c
		inner join (select distinct qd.DONID from ADS_SOTHAM_QUYETDINH qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISDANSU=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Dân sự phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vADS_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from ADS_PHUCTHAM_HDXX c
		inner join (select distinct qd.DONID from ADS_PHUCTHAM_QUYETDINH qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISDANSU=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	if INSTR(vLoaiAn,'AN_HANHCHINH,')>0 then
		-- Hành chính sơ thẩm
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAHC_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from AHC_SOTHAM_HDXX c
		inner join (select distinct qd.DONID from AHC_SOTHAM_QUYETDINH qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISHANHCHINH=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Hành chính phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAHC_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from AHC_PHUCTHAM_HDXX c
		inner join (select distinct qd.DONID from AHC_PHUCTHAM_QUYETDINH qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISHANHCHINH=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	if INSTR(vLoaiAn,'AN_HNGD,')>0 then
	-- Hôn nhân sơ thẩm
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAHN_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from AHN_SOTHAM_HDXX c
		inner join (select distinct qd.DONID from AHN_SOTHAM_QUYETDINH qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISHNGD=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Hôn nhân phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAHN_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from AHN_PHUCTHAM_HDXX c
		inner join (select distinct qd.DONID from AHN_PHUCTHAM_QUYETDINH qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISHNGD=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	if INSTR(vLoaiAn,'AN_KDTM,')>0 then
	-- Kinh tế sơ thẩm
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAKT_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from AKT_SOTHAM_HDXX c
		inner join (select distinct qd.DONID from AKT_SOTHAM_QUYETDINH qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISKDTM=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Kinh tế phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAKT_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from AKT_PHUCTHAM_HDXX c
		inner join (select distinct qd.DONID from AKT_PHUCTHAM_QUYETDINH qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISKDTM=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	if INSTR(vLoaiAn,'AN_LAODONG,')>0 then
	-- Lao động sơ thẩm
		select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vALD_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from ALD_SOTHAM_HDXX c
		inner join (select distinct qd.DONID from ALD_SOTHAM_QUYETDINH qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISLAODONG=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Lao động phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vALD_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from ALD_PHUCTHAM_HDXX c
		inner join (select distinct qd.DONID from ALD_PHUCTHAM_QUYETDINH qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISLAODONG=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	if INSTR(vLoaiAn,'AN_HINHSU,')>0 then
	 -- Hình sự sơ thẩm
	 select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAHS_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.VUANID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.VUANID) end as CanhGa
		from AHS_SOTHAM_HDXX c
		inner join (select distinct qd.VUANID from AHS_SOTHAM_QUYETDINH_VUAN qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISHINHSU=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.VUANID=c.VUANID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Hình sự phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAHS_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.VUANID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.VUANID) end as CanhGa
		from AHS_PHUCTHAM_HDXX c
		inner join (select distinct qd.VUANID from AHS_PHUCTHAM_QUYETDINH_VUAN qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISHINHSU=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.VUANID=c.VUANID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	if INSTR(vLoaiAn,'AN_PHASAN,')>0 then
	-- Phá sản sơ thẩm
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAPS_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from APS_SOTHAM_HDXX c
		inner join (select distinct qd.DONID from APS_SOTHAM_QUYETDINH qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISPHASAN=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Phá sản phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAPS_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from APS_PHUCTHAM_HDXX c
		inner join (select distinct qd.DONID from APS_PHUCTHAM_QUYETDINH qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISPHASAN=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	if INSTR(vLoaiAn,'BPXLHC,')>0 then
	-- XLHC sơ thẩm
		select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vXLHC_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from XLHC_SOTHAM_HDXX c
		inner join (select distinct qd.DONID from XLHC_SOTHAM_QUYETDINH qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISXLHC=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- XLHC phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vXLHC_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from XLHC_PHUCTHAM_HDXX c
		inner join (select distinct qd.DONID from XLHC_PHUCTHAM_QUYETDINH qd
								inner join (select f.ID from DM_QD_LOAI f where f.ISXLHC=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=qd.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	vTongAnTDC:=nvl(vADS_ST,0)+nvl(vAHC_ST,0)+nvl(vAHN_ST,0)+nvl(vAKT_ST,0)+nvl(vALD_ST,0)+nvl(vAHS_ST,0)
							+nvl(vAPS_ST,0)+nvl(vXLHC_ST,0)
							+nvl(vADS_PT,0)+nvl(vAHC_PT,0)+nvl(vAHN_PT,0)+nvl(vAKT_PT,0)+nvl(vALD_PT,0)+nvl(vAHS_PT,0)
							+nvl(vAPS_PT,0)+nvl(vXLHC_PT,0);
	RETURN nvl(vTongAnTDC,0);
	END FUN_GETVUANBPTT_BY_TP;

	FUNCTION FUN_GETVUANHUY_BY_TP 
(
	vThamPhanID IN NUMBER,
	vLoaiAn in varchar2
) RETURN NUMBER AS
	vTongAnHuy number:=0;
	vADS number:=0; vAHC number:=0; vAHN number:=0; vAKT number:=0;
	vALD number:=0; vAHS number:=0; vAPS number:=0; vXLHC number:=0;
BEGIN
	if INSTR(vLoaiAn,'AN_DANSU,')>0 then
	-- Án dân sự
	select sum(nvl(d.ChuToa,0))+sum(nvl(d.CanhGa,0))*0.5 into vADS 
	from(
		select case when hd.MAVAITRO='THAMPHAN' or hd.MAVAITRO='THAMPHANHDXX' then count(hd.DONID) end as ChuToa,
					 case when hd.MAVAITRO='THAMPHANDUKHUYET' then count(hd.DONID) end as CanhGa 
		from ADS_SOTHAM_HDXX hd
		inner join ADS_PHUCTHAM_BANAN ba on hd.DONID=ba.DONID
		inner join (select e.ID from DM_KETQUA_PHUCTHAM e where e.ISADS=1 and lower(e.TEN) like '%hủy%') kq on ba.KETQUAPHUCTHAMID=kq.ID
		where hd.CANBOID=vThamPhanID and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		group by hd.MAVAITRO
	)d;
	end if;
	if INSTR(vLoaiAn,'AN_HANHCHINH,')>0 then
	-- Án Hành chính
	select sum(nvl(ChuToa,0))+sum(nvl(CanhGa,0))*0.5 into vAHC 
	from(
		select case when hd.MAVAITRO='THAMPHAN' or hd.MAVAITRO='THAMPHANHDXX' then count(hd.DONID) end as ChuToa,
					 case when hd.MAVAITRO='THAMPHANDUKHUYET' then count(hd.DONID) end as CanhGa 
		from AHC_SOTHAM_HDXX hd
		inner join AHC_PHUCTHAM_BANAN ba on hd.DONID=ba.DONID
		inner join (select e.ID from DM_KETQUA_PHUCTHAM e where e.ISAHC=1 and lower(e.TEN) like '%hủy%') kq on ba.KETQUAPHUCTHAMID=kq.ID
		where hd.CANBOID=vThamPhanID and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		group by hd.MAVAITRO
	)d;
	end if;
	if INSTR(vLoaiAn,'AN_HNGD,')>0 then
	-- Án Hôn nhân
	select sum(nvl(ChuToa,0))+sum(nvl(CanhGa,0))*0.5 into vAHN 
	from(
		select case when hd.MAVAITRO='THAMPHAN' or hd.MAVAITRO='THAMPHANHDXX' then count(hd.DONID) end as ChuToa,
					 case when hd.MAVAITRO='THAMPHANDUKHUYET' then count(hd.DONID) end as CanhGa 
		from AHN_SOTHAM_HDXX hd
		inner join AHN_PHUCTHAM_BANAN ba on hd.DONID=ba.DONID
		inner join (select e.ID from DM_KETQUA_PHUCTHAM e where e.ISAHN=1 and lower(e.TEN) like '%hủy%') kq on ba.KETQUAPHUCTHAMID=kq.ID
		where hd.CANBOID=vThamPhanID and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		group by hd.MAVAITRO
			 )d;
	end if;
	if INSTR(vLoaiAn,'AN_KDTM,')>0 then
	-- Án Kinh tế
	select sum(nvl(ChuToa,0))+sum(nvl(CanhGa,0))*0.5 into vAKT 
	from(
		select case when hd.MAVAITRO='THAMPHAN' or hd.MAVAITRO='THAMPHANHDXX' then count(hd.DONID) end as ChuToa,
					 case when hd.MAVAITRO='THAMPHANDUKHUYET' then count(hd.DONID) end as CanhGa 
		from AKT_SOTHAM_HDXX hd
		inner join AKT_PHUCTHAM_BANAN ba on hd.DONID=ba.DONID
		inner join (select e.ID from DM_KETQUA_PHUCTHAM e where e.ISAKT=1 and lower(e.TEN) like '%hủy%') kq on ba.KETQUAPHUCTHAMID=kq.ID
		where hd.CANBOID=vThamPhanID and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		group by hd.MAVAITRO
			 )d;
	end if;
	if INSTR(vLoaiAn,'AN_LAODONG,')>0 then
	-- Án Lao động
	select sum(nvl(ChuToa,0))+sum(nvl(CanhGa,0))*0.5 into vALD 
	from(
		select case when hd.MAVAITRO='THAMPHAN' or hd.MAVAITRO='THAMPHANHDXX' then count(hd.DONID) end as ChuToa,
					 case when hd.MAVAITRO='THAMPHANDUKHUYET' then count(hd.DONID) end as CanhGa 
		from ALD_SOTHAM_HDXX hd
		inner join ALD_PHUCTHAM_BANAN ba on hd.DONID=ba.DONID
		inner join (select e.ID from DM_KETQUA_PHUCTHAM e where e.ISALD=1 and lower(e.TEN) like '%hủy%') kq on ba.KETQUAPHUCTHAMID=kq.ID
		where hd.CANBOID=vThamPhanID and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		group by hd.MAVAITRO
			 )d;
	end if;
	if INSTR(vLoaiAn,'AN_HINHSU,')>0 then
	-- Án Hình sự
	select sum(nvl(ChuToa,0))+sum(nvl(CanhGa,0))*0.5 into vAHS 
	from(
		select case when hd.MAVAITRO='THAMPHAN' or hd.MAVAITRO='THAMPHANHDXX' then count(hd.VUANID) end as ChuToa,
					 case when hd.MAVAITRO='THAMPHANDUKHUYET' then count(hd.VUANID) end as CanhGa 
		from AHS_SOTHAM_HDXX hd
		inner join AHS_PHUCTHAM_BANAN ba on hd.VUANID=ba.VUANID
		inner join (select e.ID from DM_KETQUA_PHUCTHAM e where e.ISAHS=1 and lower(e.TEN) like '%hủy%') kq on ba.KETQUAPHUCTHAMID=kq.ID
		where hd.CANBOID=vThamPhanID and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		group by hd.MAVAITRO
			 )d;
	end if;
	if INSTR(vLoaiAn,'AN_PHASAN,')>0 then
	-- Án Phá sản
	select sum(nvl(ChuToa,0))+sum(nvl(CanhGa,0))*0.5 into vAPS 
	from(
		select case when hd.MAVAITRO='THAMPHAN' or hd.MAVAITRO='THAMPHANHDXX' then count(hd.DONID) end as ChuToa,
					 case when hd.MAVAITRO='THAMPHANDUKHUYET' then count(hd.DONID) end as CanhGa 
		from APS_SOTHAM_HDXX hd
		inner join APS_PHUCTHAM_BANAN ba on hd.DONID=ba.DONID
		inner join (select e.ID from DM_KETQUA_PHUCTHAM e where e.ISAPS=1 and lower(e.TEN) like '%hủy%') kq on ba.KETQUAPHUCTHAMID=kq.ID
		where hd.CANBOID=vThamPhanID and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		group by hd.MAVAITRO
			 )d;
	end if;
	if INSTR(vLoaiAn,'BPXLHC,')>0 then
	-- Án XLHC
	select sum(nvl(ChuToa,0))+sum(nvl(CanhGa,0))*0.5 into vXLHC 
	from(
		select case when hd.MAVAITRO='THAMPHAN' or hd.MAVAITRO='THAMPHANHDXX' then count(hd.DONID) end as ChuToa,
					 case when hd.MAVAITRO='THAMPHANDUKHUYET' then count(hd.DONID) end as CanhGa 
		from XLHC_SOTHAM_HDXX hd
		inner join XLHC_PHUCTHAM_BANAN ba on hd.DONID=ba.DONID
		inner join (select e.ID from DM_KETQUA_PHUCTHAM e where e.ISXLHC=1 and lower(e.TEN) like '%hủy%') kq on ba.KETQUAPHUCTHAMID=kq.ID
		where hd.CANBOID=vThamPhanID and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		group by hd.MAVAITRO
			 )d;
	end if;
	vTongAnHuy:=nvl(vADS,0)+nvl(vAHC,0)+nvl(vAHN,0)+nvl(vAKT,0)+nvl(vALD,0)+nvl(vAHS,0)+nvl(vAPS,0)+nvl(vXLHC,0);
	RETURN nvl(vTongAnHuy,0);
	END FUN_GETVUANHUY_BY_TP;
 
	FUNCTION FUN_GETVUANSUA_BY_TP 
(
	vThamPhanID IN NUMBER,
	vNgayBoNhiem in date,
	vNgayKetThuc in date,
	vLoaiAn in varchar2
) RETURN NUMBER AS
	vTongAnSua number:=0;
	vADS number:=0;vAHC number:=0;vAHN number:=0;vAKT number:=0;
	vALD number:=0;vAHS number:=0;vAPS number:=0;vXLHC number:=0;
BEGIN
	if INSTR(vLoaiAn,'AN_DANSU,')>0 then
	-- Án dân sự
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vADS 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from ADS_SOTHAM_HDXX c
		inner join (select a.DONID from ADS_PHUCTHAM_BANAN a
								inner join (select e.ID from DM_KETQUA_PHUCTHAM e 
														where e.ISADS=1 and lower(e.TEN) like '%sửa%'
														) kq on a.KETQUAPHUCTHAMID=kq.ID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
