					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Lao động phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vALD_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from ALD_PHUCTHAM_HDXX c
		inner join ALD_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from ALD_PHUCTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISLAODONG=1 and f.HIEULUC=1 and f.MA='TDC'
													) loai on loai.ID=a.LOAIQDID 
