								inner join (select f.ID from DM_QD_LOAI f where f.ISPHASAN=1 and f.HIEULUC=1 and f.MA='TDC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Phá sản phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAPS_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from APS_PHUCTHAM_HDXX c
		inner join APS_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from APS_PHUCTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISPHASAN=1 and f.HIEULUC=1 and f.MA='TDC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	if INSTR(vLoaiAn,'BPXLHC,')>0 then
	-- XLHC sơ thẩm
		select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vXLHC_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from XLHC_SOTHAM_HDXX c
		inner join XLHC_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from XLHC_SOTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISXLHC=1 and f.HIEULUC=1 and f.MA='TDC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- XLHC phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vXLHC_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from XLHC_PHUCTHAM_HDXX c
		inner join XLHC_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from XLHC_PHUCTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISXLHC=1 and f.HIEULUC=1 and f.MA='TDC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	vTongAnTDC:=nvl(vADS_ST,0)+nvl(vAHC_ST,0)+nvl(vAHN_ST,0)+nvl(vAKT_ST,0)+nvl(vALD_ST,0)+nvl(vAHS_ST,0)
							+nvl(vAPS_ST,0)+nvl(vXLHC_ST,0)
							+nvl(vADS_PT,0)+nvl(vAHC_PT,0)+nvl(vAHN_PT,0)+nvl(vAKT_PT,0)+nvl(vALD_PT,0)+nvl(vAHS_PT,0)
							+nvl(vAPS_PT,0)+nvl(vXLHC_PT,0);
	RETURN nvl(vTongAnTDC,0);
	END FUN_GETVUANTDC_BY_TP;
FUNCTION FUN_GETVUANDC_BY_TP 
(
	vThamPhanID IN NUMBER,
	vNgayBoNhiem in date,
	vNgayKetThuc in date,
	vLoaiAn in varchar2
) RETURN NUMBER AS
	vTongAnDC number:=0;
	vADS_ST number:=0;vADS_PT number:=0; vAHC_ST number:=0;vAHC_PT number:=0;
	vAHN_ST number:=0;vAHN_PT number:=0; vAKT_ST number:=0;vAKT_PT number:=0;
	vALD_ST number:=0;vALD_PT number:=0; vAHS_ST number:=0;vAHS_PT number:=0;
	vAPS_ST number:=0;vAPS_PT number:=0; vXLHC_ST number:=0;vXLHC_PT number:=0;
BEGIN
	if INSTR(vLoaiAn,'AN_DANSU,')>0 then
	-- Dân sự sơ thẩm
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vADS_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from ADS_SOTHAM_HDXX c
		inner join ADS_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from ADS_SOTHAM_QUYETDINH a 
								inner join (select f.ID from DM_QD_LOAI f where f.ISDANSU=1 and f.HIEULUC=1 and f.MA='DC'
														) loai on loai.ID=a.LOAIQDID
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Dân sự phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vADS_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from ADS_PHUCTHAM_HDXX c
		inner join ADS_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from ADS_PHUCTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISDANSU=1 and f.HIEULUC=1 and f.MA='DC'
														) loai on loai.ID=a.LOAIQDID
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	if INSTR(vLoaiAn,'AN_HANHCHINH,')>0 then
	-- Hành chính sơ thẩm
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAHC_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from AHC_SOTHAM_HDXX c
		inner join AHC_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from AHC_SOTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISHANHCHINH=1 and f.HIEULUC=1 and f.MA='DC'
														) loai on loai.ID=a.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Hành chính phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAHC_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from AHC_PHUCTHAM_HDXX c
		inner join AHC_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from AHC_PHUCTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISHANHCHINH=1 and f.HIEULUC=1 and f.MA='DC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	if INSTR(vLoaiAn,'AN_HNGD,')>0 then
	-- Hôn nhân sơ thẩm
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAHN_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from AHN_SOTHAM_HDXX c
		inner join AHN_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from AHN_SOTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISHNGD=1 and f.HIEULUC=1 and f.MA='DC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Hôn nhân phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAHN_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from AHN_PHUCTHAM_HDXX c
		inner join AHN_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from AHN_PHUCTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISHNGD=1 and f.HIEULUC=1 and f.MA='DC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	if INSTR(vLoaiAn,'AN_KDTM,')>0 then
	-- Kinh tế sơ thẩm
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAKT_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from AKT_SOTHAM_HDXX c
		inner join AKT_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from AKT_SOTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISKDTM=1 and f.HIEULUC=1 and f.MA='DC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Kinh tế phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAKT_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from AKT_PHUCTHAM_HDXX c
		inner join AKT_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from AKT_PHUCTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISKDTM=1 and f.HIEULUC=1 and f.MA='DC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	if INSTR(vLoaiAn,'AN_LAODONG,')>0 then
	-- Lao động sơ thẩm
		select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vALD_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from ALD_SOTHAM_HDXX c
		inner join ALD_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from ALD_SOTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISLAODONG=1 and f.HIEULUC=1 and f.MA='DC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Lao động phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vALD_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from ALD_PHUCTHAM_HDXX c
		inner join ALD_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from ALD_PHUCTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISLAODONG=1 and f.HIEULUC=1 and f.MA='DC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	if INSTR(vLoaiAn,'AN_HINHSU,')>0 then
	-- Hình sự sơ thẩm
	 select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAHS_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.VUANID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.VUANID) end as CanhGa
		from AHS_SOTHAM_HDXX c
		inner join AHS_VUAN don on don.ID=c.VUANID
		inner join (select DISTINCT a.VUANID from AHS_SOTHAM_QUYETDINH_VUAN a
								inner join (select f.ID from DM_QD_LOAI f where f.ISHINHSU=1 and f.HIEULUC=1 and f.MA='DC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.VUANID=c.VUANID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Hình sự phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAHS_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.VUANID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.VUANID) end as CanhGa
		from AHS_PHUCTHAM_HDXX c
		inner join AHS_VUAN don on don.ID=c.VUANID
		inner join (select DISTINCT a.VUANID from AHS_PHUCTHAM_QUYETDINH_VUAN a
								inner join (select f.ID from DM_QD_LOAI f where f.ISHINHSU=1 and f.HIEULUC=1 and f.MA='DC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.VUANID=c.VUANID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	if INSTR(vLoaiAn,'AN_PHASAN,')>0 then
	-- Phá sản sơ thẩm
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAPS_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from APS_SOTHAM_HDXX c
		inner join APS_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from APS_SOTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISPHASAN=1 and f.HIEULUC=1 and f.MA='DC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- Phá sản phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vAPS_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from APS_PHUCTHAM_HDXX c
		inner join APS_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from APS_PHUCTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISPHASAN=1 and f.HIEULUC=1 and f.MA='DC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	if INSTR(vLoaiAn,'BPXLHC,')>0 then
	-- XLHC sơ thẩm
		select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vXLHC_ST 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from XLHC_SOTHAM_HDXX c
		inner join XLHC_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from XLHC_SOTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISXLHC=1 and f.HIEULUC=1 and f.MA='DC'
													) loai on loai.ID=a.LOAIQdID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	-- XLHC phúc thẩm 
	select sum(nvl(ChuToa,0)) + sum(nvl(CanhGa,0))*0.5 into vXLHC_PT 
	from(   
		select case when c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX' then count(c.DONID) end as ChuToa,
					 case when c.MAVAITRO='THAMPHANDUKHUYET' then count(c.DONID) end as CanhGa
		from XLHC_PHUCTHAM_HDXX c
		inner join XLHC_DON don on don.ID=c.DONID
		inner join (select DISTINCT a.DONID from XLHC_PHUCTHAM_QUYETDINH a
								inner join (select f.ID from DM_QD_LOAI f where f.ISXLHC=1 and f.HIEULUC=1 and f.MA='DC'
													) loai on loai.ID=a.LOAIQDID 
								) ba on ba.DONID=c.DONID
		where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET') and c.CANBOID=vThamPhanID
					and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
		group by c.MAVAITRO
		) d;
	end if;
	vTongAnDC:=nvl(vADS_ST,0)+nvl(vAHC_ST,0)+nvl(vAHN_ST,0)+nvl(vAKT_ST,0)+nvl(vALD_ST,0)+nvl(vAHS_ST,0)
							+nvl(vAPS_ST,0)+nvl(vXLHC_ST,0)
							+nvl(vADS_PT,0)+nvl(vAHC_PT,0)+nvl(vAHN_PT,0)+nvl(vAKT_PT,0)+nvl(vALD_PT,0)+nvl(vAHS_PT,0)
							+nvl(vAPS_PT,0)+nvl(vXLHC_PT,0);
	RETURN nvl(vTongAnDC,0);
	END FUN_GETVUANDC_BY_TP;

	FUNCTION FUN_GETVUANTREO_BY_TP 
(
	vThamPhanID IN NUMBER,
	vNgayBoNhiem in date,
	vNgayKetThuc in date
) RETURN NUMBER AS
	vTongAnTreo number:=0;
	vAnTreoSoTham number:=0;
	vAnTreoPhucTham number:=0;
BEGIN
	-- Vụ án áp dụng án treo chỉ có ở án HÌNH SỰ
	 select sum(nvl(ChuToa,0))+FLOOR(sum(nvl(CanhGa,0))*0.5) into vAnTreoSoTham 
	 from(select case hdxx.VaiTroTP when 1 then count(distinct bact.BANANID) end as ChuToa,
							 case hdxx.VaiTroTP when 2 then count(distinct bact.BANANID) end as CanhGa
			 from AHS_SOTHAM_BANAN_DIEU_CHITIET bact
			 inner join AHS_SOTHAM_BANAN ba on bact.BANANID=ba.ID
			 inner join (select c.VUANID,case when (c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX') then 1
																			 when c.MAVAITRO='THAMPHANDUKHUYET' then 2 end as VaiTroTP 
									from AHS_SOTHAM_HDXX c 
									where c.CANBOID=vThamPhanID and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
									) hdxx on ba.VUANID=hdxx.VUANID
			 where bact.ISANTREO=1
			 group by hdxx.VaiTroTP
			 )d;
		select sum(nvl(ChuToa,0))+FLOOR(sum(nvl(CanhGa,0))*0.5) into vAnTreoPhucTham 
		from(select case hdxx.VaiTroTP when 1 then count(distinct bact.BANANID) end as ChuToa,
							 case hdxx.VaiTroTP when 2 then count(distinct bact.BANANID) end as CanhGa
			 from AHS_PHUCTHAM_BANAN_DIEU_CT bact
			 inner join AHS_PHUCTHAM_BANAN ba on bact.BANANID=ba.ID
			 inner join (select c.VUANID,case when (c.MAVAITRO='THAMPHAN' or c.MAVAITRO='THAMPHANHDXX') then 1
																			 when c.MAVAITRO='THAMPHANDUKHUYET' then 2 end as VaiTroTP 
									from AHS_PHUCTHAM_HDXX c 
									where c.CANBOID=vThamPhanID and vNgayBoNhiem <= c.NGAYPHANCONG and c.NGAYPHANCONG <= vNgayKetThuc
									) hdxx on ba.VUANID=hdxx.VUANID
			 where bact.ISANTREO=1
			 group by hdxx.VaiTroTP
			 )d;
		 vTongAnTreo:=nvl(vAnTreoSoTham,0)+nvl(vAnTreoPhucTham,0);
	RETURN nvl(vTongAnTreo,0);
	END FUN_GETVUANTREO_BY_TP;
FUNCTION FUN_GETVUANQH_BY_TP 
(
	vThamPhanID IN NUMBER,
	vNgayBoNhiem in date,
	vNgayKetThuc in date,
	vLoaiAn in varchar2
) RETURN NUMBER AS
	vTongAnQH number:=0;
	vADS_ST number:=0;vADS_PT number:=0;
	vAHC_ST number:=0;vAHC_PT number:=0;
	vAHN_ST number:=0;vAHN_PT number:=0;
	vAHS_ST number:=0;
	vAKT_ST number:=0;vAKT_PT number:=0;
	vALD_ST number:=0;vALD_PT number:=0;
	vAPS_ST number:=0;
	vXLHC_ST number:=0;vXLHC_PT number:=0;
BEGIN
	if INSTR(vLoaiAn,'AN_DANSU,')>0 then
	-- án dân sự
	select count(ba.DONID) into vADS_ST from ADS_SOTHAM_BANAN ba
	inner join ADS_DON don on don.ID=ba.DONID
	inner join ADS_SOTHAM_HDXX hd on ba.DONID=hd.DONID 
	where ba.TK_ISQUAHAN=1 and hd.CANBOID=vThamPhanID
		and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		and vNgayBoNhiem <= hd.NGAYPHANCONG and hd.NGAYPHANCONG <= vNgayKetThuc;
    
	select count(ba.DONID) into vADS_PT from ADS_PHUCTHAM_BANAN ba
	inner join ADS_DON don on don.ID=ba.DONID
	inner join ADS_PHUCTHAM_HDXX hd on ba.DONID=hd.DONID 
	where ba.TK_ISQUAHAN=1 and hd.CANBOID=vThamPhanID
		and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		and vNgayBoNhiem <= hd.NGAYPHANCONG and hd.NGAYPHANCONG <= vNgayKetThuc;
	end if;
	if INSTR(vLoaiAn,'AN_HANHCHINH,')>0 then
	-- án hành chính
	select count(ba.DONID) into vAHC_ST from AHC_SOTHAM_BANAN ba
	inner join AHC_DON don on don.ID=ba.DONID
	inner join AHC_SOTHAM_HDXX hd on ba.DONID=hd.DONID 
	where ba.TK_ISQUAHAN=1 and hd.CANBOID=vThamPhanID
		and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		and vNgayBoNhiem <= hd.NGAYPHANCONG and hd.NGAYPHANCONG <= vNgayKetThuc;
    
	select count(ba.DONID) into vAHC_PT from AHC_PHUCTHAM_BANAN ba
	inner join AHC_DON don on don.ID=ba.DONID
	inner join AHC_PHUCTHAM_HDXX hd on ba.DONID=hd.DONID 
	where ba.TK_ISQUAHAN=1 and hd.CANBOID=vThamPhanID
		and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		and vNgayBoNhiem <= hd.NGAYPHANCONG and hd.NGAYPHANCONG <= vNgayKetThuc;
	end if;
	if INSTR(vLoaiAn,'AN_HNGD,')>0 then
	-- án hôn nhân
	select count(ba.DONID) into vAHN_ST from AHN_SOTHAM_BANAN ba
	inner join AHN_DON don on don.ID=ba.DONID
	inner join AHN_SOTHAM_HDXX hd on ba.DONID=hd.DONID 
	where ba.TK_ISQUAHAN=1 and hd.CANBOID=vThamPhanID
		and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		and vNgayBoNhiem <= hd.NGAYPHANCONG and hd.NGAYPHANCONG <= vNgayKetThuc;
    
	select count(ba.DONID) into vAHN_PT from AHN_PHUCTHAM_BANAN ba
	inner join AHN_DON don on don.ID=ba.DONID
	inner join AHN_PHUCTHAM_HDXX hd on ba.DONID=hd.DONID 
	where ba.TK_ISQUAHAN=1 and hd.CANBOID=vThamPhanID
		and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		and vNgayBoNhiem <= hd.NGAYPHANCONG and hd.NGAYPHANCONG <= vNgayKetThuc;
	end if;
	if INSTR(vLoaiAn,'AN_KDTM,')>0 then
	-- án kinh tế
	select count(ba.DONID) into vAKT_ST from AKT_SOTHAM_BANAN ba
	inner join AKT_DON don on don.ID=ba.DONID
	inner join AKT_SOTHAM_HDXX hd on ba.DONID=hd.DONID 
	where ba.TK_ISQUAHAN=1 and hd.CANBOID=vThamPhanID
		and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		and vNgayBoNhiem <= hd.NGAYPHANCONG and hd.NGAYPHANCONG <= vNgayKetThuc;
    
	select count(ba.DONID) into vAKT_PT from AKT_PHUCTHAM_BANAN ba
	inner join AKT_DON don on don.ID=ba.DONID
	inner join AKT_PHUCTHAM_HDXX hd on ba.DONID=hd.DONID 
	where ba.TK_ISQUAHAN=1 and hd.CANBOID=vThamPhanID
		and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		and vNgayBoNhiem <= hd.NGAYPHANCONG and hd.NGAYPHANCONG <= vNgayKetThuc;
	end if;
	if INSTR(vLoaiAn,'AN_LAODONG,')>0 then
	-- án lao động
	select count(ba.DONID) into vALD_ST from ALD_SOTHAM_BANAN ba
	inner join ALD_DON don on don.ID=ba.DONID
	inner join ALD_SOTHAM_HDXX hd on ba.DONID=hd.DONID 
	where ba.TK_ISQUAHAN=1 and hd.CANBOID=vThamPhanID
		and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		and vNgayBoNhiem <= hd.NGAYPHANCONG and hd.NGAYPHANCONG <= vNgayKetThuc;
    
	select count(ba.DONID) into vALD_PT from ALD_PHUCTHAM_BANAN ba
	inner join ALD_DON don on don.ID=ba.DONID
	inner join ALD_PHUCTHAM_HDXX hd on ba.DONID=hd.DONID 
	where ba.TK_ISQUAHAN=1 and hd.CANBOID=vThamPhanID
		and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		and vNgayBoNhiem <= hd.NGAYPHANCONG and hd.NGAYPHANCONG <= vNgayKetThuc;
	end if;
	if INSTR(vLoaiAn,'AN_HINHSU,')>0 then
	-- án hình sự
	select count(ba.VUANID) into vAHS_ST from AHS_SOTHAM_BANAN ba
	inner join AHS_VUAN don on don.ID=ba.VUANID
	inner join AHS_SOTHAM_HDXX hd on ba.VUANID=hd.VUANID 
	where (ba.TK_QUAHAN_CHUQUAN=1 or ba.TK_QUAHAN_KHACHQUAN=1) and hd.CANBOID=vThamPhanID
		and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		and vNgayBoNhiem <= hd.NGAYPHANCONG and hd.NGAYPHANCONG <= vNgayKetThuc;
	end if;
	if INSTR(vLoaiAn,'AN_PHASAN,')>0 then
	-- án phá sản
	select count(ba.DONID) into vAPS_ST from APS_SOTHAM_BANAN ba
	inner join APS_DON don on don.ID=ba.DONID
	inner join APS_SOTHAM_HDXX hd on ba.DONID=hd.DONID 
	where ba.TK_ISQUAHAN=1 and hd.CANBOID=vThamPhanID
		and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		and vNgayBoNhiem <= hd.NGAYPHANCONG and hd.NGAYPHANCONG <= vNgayKetThuc;
	end if;
	if INSTR(vLoaiAn,'BPXLHC,')>0 then
	-- án XLHC
	select count(ba.DONID) into vXLHC_ST from XLHC_SOTHAM_BANAN ba
	inner join XLHC_DON don on don.ID=ba.DONID
	inner join XLHC_SOTHAM_HDXX hd on ba.DONID=hd.DONID 
	where ba.TK_ISQUAHAN=1 and hd.CANBOID=vThamPhanID
		and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		and vNgayBoNhiem <= hd.NGAYPHANCONG and hd.NGAYPHANCONG <= vNgayKetThuc;
    
	select count(ba.DONID) into vXLHC_PT from XLHC_PHUCTHAM_BANAN ba
	inner join XLHC_DON don on don.ID=ba.DONID
	inner join XLHC_PHUCTHAM_HDXX hd on ba.DONID=hd.DONID 
	where ba.TK_ISQUAHAN=1 and hd.CANBOID=vThamPhanID
		and hd.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
		and vNgayBoNhiem <= hd.NGAYPHANCONG and hd.NGAYPHANCONG <= vNgayKetThuc;
	end if;
	vTongAnQH:=nvl(vADS_ST,0)+nvl(vADS_PT,0)+nvl(vAHC_ST,0)+nvl(vAHC_PT,0)+nvl(vAHN_ST,0)+nvl(vAHN_PT,0)+nvl(vAHS_ST,0)+nvl(vAKT_ST,0)+nvl(vAKT_PT,0)+nvl(vALD_ST,0)+nvl(vALD_PT,0)+nvl(vAPS_ST,0)+nvl(vXLHC_ST,0)+nvl(vXLHC_PT,0);
	RETURN nvl(vTongAnQH,0);
END FUN_GETVUANQH_BY_TP;
	FUNCTION FUN_GETTYLE_ANBPTT_BYTP 
(
	vThamPhanID IN NUMBER,
	vNgayBoNhiem in date,
	vNgayKetThuc in date
) RETURN NUMBER AS
	vTyLeAnBPTT number:=0;vTongAn number:=0;
	vLoaiAn varchar2(100):='AN_HINHSU,AN_DANSU,AN_HANHCHINH,AN_HNGD,AN_KDTM,AN_LAODONG,AN_PHASAN,BPXLHC,';
BEGIN
	-- 02 án với vai trò là thẩm phán cánh gà thì được tính thành 01 án.
	select (FUN_GETVUANCHUTOA_BY_TP(vThamPhanID)+ FUN_GETVUANCANHGA_BY_TP(vThamPhanID)) into vTongAn from SYS.DUAL;
	if nvl(vTongAn,0)=0 then
		vTyLeAnBPTT:=0;
	else
		select round((FUN_GETVUANBPTT_BY_TP(vThamPhanID,vNgayBoNhiem,vNgayKetThuc,vLoaiAn)/vTongAn)*100,2) into vTyLeAnBPTT from SYS.DUAL;
	end if;
  
	RETURN nvl(vTyLeAnBPTT,0);
	END FUN_GETTYLE_ANBPTT_BYTP;

