PROCEDURE GETALLVUANTHAMGIA
(
	vThamPhanID IN number,
	vVaiTro in number,
	vTuNgay in date,
	vDenNgay in date,
	CurReturn OUT sys_refcursor
)
AS
BEGIN
	open CurReturn for
	select re.VuAnID
	from (
	-- Án dân sự sơ thẩm
	select don.ID as VuAnID,don.MAVUVIEC as MaVuAn,don.TENVUVIEC as TenVuAn,ta.TEN as TenToaAn,'Dân sự' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NgayTuyenAn,'' as TrangThai 
	from ADS_SOTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join ADS_DON don on don.ID=a.DONID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join ADS_SOTHAM_BANAN ba on ba.DONID=a.DONID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYTUYENAN and ba.NGAYTUYENAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	union
	-- Án dân sự phúc thẩm
	select don.ID as VuAnID,don.MAVUVIEC as MaVuAn,don.TENVUVIEC as TenVuAn,ta.TEN as TenToaAn,'Dân sự' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NgayTuyenAn,'' as TrangThai 
	from ADS_PHUCTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join ADS_DON don on don.ID=a.DONID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join ADS_PHUCTHAM_BANAN ba on ba.DONID=a.DONID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYTUYENAN and ba.NGAYTUYENAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	union
	-- Án Hôn nhân sơ thẩm
	select don.ID as VuAnID,don.MAVUVIEC as MaVuAn,don.TENVUVIEC as TenVuAn,ta.TEN as TenToaAn,'Hôn nhân' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NgayTuyenAn,'' as TrangThai 
	from AHN_SOTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join AHN_DON don on don.ID=a.DONID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join AHN_SOTHAM_BANAN ba on ba.DONID=a.DONID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYTUYENAN and ba.NGAYTUYENAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	union
	-- Án Hôn Nhân phúc thẩm
	select don.ID as VuAnID,don.MAVUVIEC as MaVuAn,don.TENVUVIEC as TenVuAn,ta.TEN as TenToaAn,'Hôn nhân' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NgayTuyenAn,'' as TrangThai 
	from AHN_PHUCTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join AHN_DON don on don.ID=a.DONID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join AHN_PHUCTHAM_BANAN ba on ba.DONID=a.DONID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYTUYENAN and ba.NGAYTUYENAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	union
	-- Án Kinh tế sơ thẩm
	select don.ID as VuAnID,don.MAVUVIEC as MaVuAn,don.TENVUVIEC as TenVuAn,ta.TEN as TenToaAn,'Kinh doanh thương mại' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NgayTuyenAn,'' as TrangThai 
	from AKT_SOTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join AKT_DON don on don.ID=a.DONID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join AKT_SOTHAM_BANAN ba on ba.DONID=a.DONID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYTUYENAN and ba.NGAYTUYENAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	union
	-- Án Kinh tế phúc thẩm
	select don.ID as VuAnID,don.MAVUVIEC as MaVuAn,don.TENVUVIEC as TenVuAn,ta.TEN as TenToaAn,'Kinh doanh thương mại' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NgayTuyenAn,'' as TrangThai 
	from AKT_PHUCTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join AKT_DON don on don.ID=a.DONID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join AKT_PHUCTHAM_BANAN ba on ba.DONID=a.DONID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYTUYENAN and ba.NGAYTUYENAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	union
	-- Án Lao động sơ thẩm
	select don.ID as VuAnID,don.MAVUVIEC as MaVuAn,don.TENVUVIEC as TenVuAn,ta.TEN as TenToaAn,'Lao động' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NgayTuyenAn,'' as TrangThai 
	from ALD_SOTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join ALD_DON don on don.ID=a.DONID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join ALD_SOTHAM_BANAN ba on ba.DONID=a.DONID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYTUYENAN and ba.NGAYTUYENAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	union
	-- Án Lao động phúc thẩm
	select don.ID as VuAnID,don.MAVUVIEC as MaVuAn,don.TENVUVIEC as TenVuAn,ta.TEN as TenToaAn,'Lao động' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NgayTuyenAn,'' as TrangThai 
	from ALD_PHUCTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join ALD_DON don on don.ID=a.DONID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join ALD_PHUCTHAM_BANAN ba on ba.DONID=a.DONID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYTUYENAN and ba.NGAYTUYENAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	union
	-- Án Hành chính sơ thẩm
	select don.ID as VuAnID,don.MAVUVIEC as MaVuAn,don.TENVUVIEC as TenVuAn,ta.TEN as TenToaAn,'Hành chính' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NgayTuyenAn,'' as TrangThai 
	from AHC_SOTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join AHC_DON don on don.ID=a.DONID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join AHC_SOTHAM_BANAN ba on ba.DONID=a.DONID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYTUYENAN and ba.NGAYTUYENAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	union
	-- Án Hành chính phúc thẩm
	select don.ID as VuAnID,don.MAVUVIEC as MaVuAn,don.TENVUVIEC as TenVuAn,ta.TEN as TenToaAn,'Hành chính' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NgayTuyenAn,'' as TrangThai 
	from AHC_PHUCTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join AHC_DON don on don.ID=a.DONID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join AHC_PHUCTHAM_BANAN ba on ba.DONID=a.DONID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYTUYENAN and ba.NGAYTUYENAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	union
	-- Án Phá sản sơ thẩm
	select don.ID as VuAnID,don.MAVUVIEC as MaVuAn,don.TENVUVIEC as TenVuAn,ta.TEN as TenToaAn,'Phá sản' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NgayTuyenAn,'' as TrangThai 
	from APS_SOTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join APS_DON don on don.ID=a.DONID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join APS_SOTHAM_BANAN ba on ba.DONID=a.DONID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYTUYENAN and ba.NGAYTUYENAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	union
	-- Án Phá sản phúc thẩm
	select don.ID as VuAnID,don.MAVUVIEC as MaVuAn,don.TENVUVIEC as TenVuAn,ta.TEN as TenToaAn,'Phá sản' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NgayTuyenAn,'' as TrangThai 
	from APS_PHUCTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join APS_DON don on don.ID=a.DONID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join APS_PHUCTHAM_BANAN ba on ba.DONID=a.DONID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYTUYENAN and ba.NGAYTUYENAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	union
	-- Án XLHC sơ thẩm
	select don.ID as VuAnID,don.MAVUVIEC as MaVuAn,don.TENVUVIEC as TenVuAn,ta.TEN as TenToaAn,'Biện pháp xử lý hành chính' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NgayTuyenAn,'' as TrangThai 
	from XLHC_SOTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join XLHC_DON don on don.ID=a.DONID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join XLHC_SOTHAM_BANAN ba on ba.DONID=a.DONID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYTUYENAN and ba.NGAYTUYENAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	union
	-- Án XLHC phúc thẩm
	select don.ID as VuAnID,don.MAVUVIEC as MaVuAn,don.TENVUVIEC as TenVuAn,ta.TEN as TenToaAn,'Biện pháp xử lý hành chính' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NgayTuyenAn,'' as TrangThai 
	from XLHC_PHUCTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join XLHC_DON don on don.ID=a.DONID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join XLHC_PHUCTHAM_BANAN ba on ba.DONID=a.DONID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYTUYENAN and ba.NGAYTUYENAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	union
	-- Án Hình sự sơ thẩm
	select don.ID as VuAnID,don.MAVUAN as MaVuAn,don.TENVUAN as TenVuAn,ta.TEN as TenToaAn,'Hình sự' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NGAYBANAN as NgayTuyenAn,'' as TrangThai 
	from AHS_SOTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join AHS_VUAN don on don.ID=a.VUANID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join AHS_SOTHAM_BANAN ba on ba.VUANID=a.VUANID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYBANAN and ba.NGAYBANAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	union
	-- Án Hình sự phúc thẩm
	select don.ID as VuAnID,don.MAVUAN as MaVuAn,don.TENVUAN as TenVuAn,ta.TEN as TenToaAn,'Hình sự' as LinhVuc,
					don.MAGIAIDOAN,case when a.MAVAITRO='THAMPHAN' then 1
										 when (a.MAVAITRO='THAMPHANDUKHUYET' or a.MAVAITRO='THAMPHANHDXX') then 2 end as VaiTroTP,
					ba.NGAYBANAN as NgayTuyenAn,'' as TrangThai 
	from AHS_PHUCTHAM_HDXX a
	inner join DM_CANBO cbo on cbo.ID=a.CANBOID
	inner join AHS_VUAN don on don.ID=a.VUANID
	inner join DM_TOAAN ta on ta.ID=cbo.TOAANID
	left join AHS_PHUCTHAM_BANAN ba on ba.VUANID=a.VUANID
	where a.CANBOID=vThamPhanID and cbo.NGAYBONHIEM <= ba.NGAYBANAN and ba.NGAYBANAN <= cbo.NGAYKETTHUC
				and a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
	) re
	where (1=case when vVaiTro=0 then 1 when vVaiTro=re.VaiTroTP then 1 end)
				and
				(1=case when (vTuNgay is null or vDenNgay is null) then 1 
								when (vTuNgay <= re.NgayTuyenAn and re.NgayTuyenAn <= vDenNgay) then 1 end)
				;
END GETALLVUANTHAMGIA;
PROCEDURE DS_THAMPHAN_BYTOAAN 
(
    vDonViLogin in number,
	vDonViID in number,
	vTenThamPhan in varchar2,
	vNgaySinh in varchar2,
	vChucDanhID in number,
	vVaiTro in varchar2,
	vNgayPCTuNgay in date,
	vNgayPCDenNgay in date,
	vSapHetNhiemKy in varchar2,
	vKhieuNai in varchar2,
	vKyLuat in varchar2,
	vAnBiHuy in varchar2,
	vAnApDungBPTT in varchar2,
	vAnDinhChi in varchar2,
	vAnTamDinhChi in varchar2,
	vAnQuaHan in varchar2,
	vAnBiSua in varchar2,
	vAnTreo in varchar2,
    vPageIndex in number,
    vPageSize in number,
	curReturn OUT sys_refcursOR
) AS
  vArrSapxep varchar2(250);
	vGroupChucDanhID number;
	vMaVaiTro varchar2(50);
	vNumDay_HetNhiemKy number default 0;
  vMin number default 0;
  vMax number default 0;
BEGIN
  vMin := vPageSize*(vPageIndex - 1) + 1;
	vMax := vPageIndex*vPageSize ;
	IF(vVaiTro || ' ' = ' ') THEN
		vMaVaiTro:='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,';
  ELSE
    vMaVaiTro:=vVaiTro || ',';
	END IF;
  IF vDonViID=0 THEN
		SELECT ARRSAPXEP INTO vArrSapxep FROM DM_TOAAN WHERE ID=vDonViLogin;
	ELSE
		SELECT ARRSAPXEP INTO vArrSapxep FROM DM_TOAAN WHERE ID=vDonViID;
	END IF;
	SELECT ID INTO vGroupChucDanhID FROM DM_DATAGROUP WHERE MA='CHUCDANH';
	-- Thời gian trước khi hết nhiệm kỳ
	SELECT a.HETNHIEMKY INTO vNumDay_HetNhiemKy FROM GSTP_CAUHINH a;
  
	OPEN curReturn FOR
  WITH cteData AS (
	SELECT cbo.ID,cbo.HOTEN,ta.TEN AS TENDonVi,cbo.NGAYSINH,cd.TEN AS ChucDanh,ta.ARRTHUTU
	FROM DM_CANBO cbo
	INNER JOIN DM_DATAITEM cd on cbo.CHUCDANHID=cd.ID AND cd.GROUPID=vGroupChucDanhID
	INNER JOIN DM_TOAAN ta on cbo.TOAANID=ta.ID
	WHERE 
        1=CASE WHEN vDonViID=0 AND ta.ARRSAPXEP LIKE vArrSapxep || '%' THEN 1 WHEN vDonViID>0 AND ta.ARRSAPXEP = vArrSapxep THEN 1 ELSE 0 END
        AND (1=CASE WHEN vChucDanhID=0 AND INSTR('TPSC,TPTC,TPCC',cd.MA)>0 THEN 1 WHEN cd.ID=vChucDanhID THEN 1 ELSE 0 END)
        AND (1=CASE WHEN vTenThamPhan || ' '=' ' THEN 1 WHEN lower(cbo.HOTEN) like '%' || lower(vTenThamPhan) || '%' THEN 1 ELSE 0 END)
				AND (1=CASE WHEN vNgaySinh || ' ' = ' ' THEN 1 WHEN to_char(cbo.NGAYSINH,'dd/MM/yyyy')=vNgaySinh THEN 1 ELSE 0 END)
				-- Vai trò tiến hành tố tụng
				AND
				(
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM ADS_SOTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM ADS_PHUCTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM AHC_SOTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM AHC_PHUCTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM AHN_SOTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM AHN_PHUCTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM AHS_SOTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM AHS_PHUCTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM AKT_SOTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM AKT_PHUCTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM ALD_SOTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM ALD_PHUCTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM APS_SOTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM APS_PHUCTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM XLHC_SOTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN (SELECT COUNT(DISTINCT ID) FROM XLHC_PHUCTHAM_HDXX vt WHERE vt.CANBOID=cbo.ID AND INSTR(vMaVaiTro,vt.MAVAITRO)>0 )>0 THEN 1 ELSE 0 END
				)
				-- Ngày phân công từ ngày
				AND
				(
					1=CASE WHEN vNgayPCTuNgay || ' '=' ' THEN 1
                 WHEN (SELECT COUNT(DISTINCT pc.ID) FROM ADS_SOTHAM_HDXX pc 
                        WHERE vNgayPCTuNgay <= pc.NGAYPHANCONG
                               AND pc.CANBOID=cbo.ID 
                               )>0  THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vNgayPCTuNgay || ' '=' ' THEN 1
                 WHEN (SELECT COUNT(DISTINCT pc.ID) FROM ADS_PHUCTHAM_HDXX pc 
														WHERE vNgayPCTuNgay <= pc.NGAYPHANCONG
															AND pc.CANBOID=cbo.ID 
														)>0  THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vNgayPCTuNgay || ' '=' ' THEN 1
                 WHEN (SELECT COUNT(DISTINCT pc.ID) FROM AHC_SOTHAM_HDXX pc 
														WHERE vNgayPCTuNgay <= pc.NGAYPHANCONG
															AND pc.CANBOID=cbo.ID 
														)>0  THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vNgayPCTuNgay || ' '=' ' THEN 1
                 WHEN (SELECT COUNT(DISTINCT pc.ID) FROM AHC_PHUCTHAM_HDXX pc 
														WHERE vNgayPCTuNgay <= pc.NGAYPHANCONG
															AND pc.CANBOID=cbo.ID 
														)>0  THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vNgayPCTuNgay || ' '=' ' THEN 1
                 WHEN (SELECT COUNT(DISTINCT pc.ID) FROM AHN_SOTHAM_HDXX pc 
														WHERE vNgayPCTuNgay <= pc.NGAYPHANCONG
															AND pc.CANBOID=cbo.ID 
														)>0  THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vNgayPCTuNgay || ' '=' ' THEN 1
                 WHEN (SELECT COUNT(DISTINCT pc.ID) FROM AHN_PHUCTHAM_HDXX pc 
														WHERE vNgayPCTuNgay <= pc.NGAYPHANCONG
															AND pc.CANBOID=cbo.ID 
														)>0  THEN 1 ELSE 0 END
					OR
					1=CASE WHEN vNgayPCTuNgay || ' '=' ' THEN 1
                 WHEN (SELECT COUNT(DISTINCT pc.ID) FROM AHS_SOTHAM_HDXX pc 
														WHERE vNgayPCTuNgay <= pc.NGAYPHANCONG
															AND pc.CANBOID=cbo.ID 
