																	AND 1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN INSTR(vMaVaiTro,hd.MAVAITRO)>0 THEN 1 ELSE 0 END
																	--AND (hd.NGAYPHANCONG BETWEEN cbo.NGAYBONHIEM AND cbo.NGAYKETTHUC)
													)>0 AND vAnQuaHan='1' THEN 1 ELSE 0 END)
					OR
					1=(CASE WHEN vAnQuaHan='0' THEN 1 
										WHEN (SELECT COUNT(hd.CANBOID) FROM AKT_PHUCTHAM_BANAN bapt
														INNER JOIN AKT_PHUCTHAM_HDXX hd ON bapt.DONID=hd.DONID 
														WHERE bapt.TK_ISQUAHAN=1 AND hd.CANBOID=cbo.ID
																	AND 1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN INSTR(vMaVaiTro,hd.MAVAITRO)>0 THEN 1 ELSE 0 END
																	--AND (hd.NGAYPHANCONG BETWEEN cbo.NGAYBONHIEM AND cbo.NGAYKETTHUC)
													)>0 AND vAnQuaHan='1' THEN 1 ELSE 0 END)
					OR
					1=(CASE WHEN vAnQuaHan='0' THEN 1 
										WHEN (SELECT COUNT(hd.CANBOID) FROM ALD_SOTHAM_BANAN bast
														INNER JOIN ALD_SOTHAM_HDXX hd ON bast.DONID=hd.DONID 
														WHERE bast.TK_ISQUAHAN=1 AND hd.CANBOID=cbo.ID
																	AND 1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN INSTR(vMaVaiTro,hd.MAVAITRO)>0 THEN 1 ELSE 0 END
																	--AND (hd.NGAYPHANCONG BETWEEN cbo.NGAYBONHIEM AND cbo.NGAYKETTHUC)
													)>0 AND vAnQuaHan='1' THEN 1 ELSE 0 END)
					OR
					1=(CASE WHEN vAnQuaHan='0' THEN 1 
										WHEN (SELECT COUNT(hd.CANBOID) FROM ALD_PHUCTHAM_BANAN bapt
														INNER JOIN ALD_PHUCTHAM_HDXX hd ON bapt.DONID=hd.DONID 
														WHERE bapt.TK_ISQUAHAN=1 AND hd.CANBOID=cbo.ID
																	AND 1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN INSTR(vMaVaiTro,hd.MAVAITRO)>0 THEN 1 ELSE 0 END
																	--AND (hd.NGAYPHANCONG BETWEEN cbo.NGAYBONHIEM AND cbo.NGAYKETTHUC)
													)>0 AND vAnQuaHan='1' THEN 1 ELSE 0 END)
					OR
					1=(CASE WHEN vAnQuaHan='0' THEN 1 
										WHEN (SELECT COUNT(hd.CANBOID) FROM APS_SOTHAM_BANAN bast
														INNER JOIN APS_SOTHAM_HDXX hd ON bast.DONID=hd.DONID 
														WHERE bast.TK_ISQUAHAN=1 AND hd.CANBOID=cbo.ID
																	AND 1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN INSTR(vMaVaiTro,hd.MAVAITRO)>0 THEN 1 ELSE 0 END
																	--AND (hd.NGAYPHANCONG BETWEEN cbo.NGAYBONHIEM AND cbo.NGAYKETTHUC)
													)>0 AND vAnQuaHan='1' THEN 1 ELSE 0 END)
					OR
					1=(CASE WHEN vAnQuaHan='0' THEN 1 
										WHEN (SELECT COUNT(hd.CANBOID) FROM XLHC_SOTHAM_BANAN bast
														INNER JOIN XLHC_SOTHAM_HDXX hd ON bast.DONID=hd.DONID 
														WHERE bast.TK_ISQUAHAN=1 AND hd.CANBOID=cbo.ID
																	AND 1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN INSTR(vMaVaiTro,hd.MAVAITRO)>0 THEN 1 ELSE 0 END
																	--AND (hd.NGAYPHANCONG BETWEEN cbo.NGAYBONHIEM AND cbo.NGAYKETTHUC)
													)>0 THEN 1 ELSE 0 END)
					OR
					1=(CASE WHEN vAnQuaHan='0' THEN 1 
										WHEN (SELECT COUNT(hd.CANBOID) FROM XLHC_PHUCTHAM_BANAN bapt
														INNER JOIN XLHC_PHUCTHAM_HDXX hd ON bapt.DONID=hd.DONID 
														WHERE bapt.TK_ISQUAHAN=1 AND hd.CANBOID=cbo.ID
																	AND 1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN INSTR(vMaVaiTro,hd.MAVAITRO)>0 THEN 1 ELSE 0 END
																	--AND (hd.NGAYPHANCONG BETWEEN cbo.NGAYBONHIEM AND cbo.NGAYKETTHUC)
													)>0 AND vAnQuaHan='1' THEN 1 ELSE 0 END)
				)
				-- vAnTreo
				AND
				(
					1=(CASE WHEN vAnTreo='0' THEN 1 
									WHEN (SELECT COUNT(hd.CANBOID) FROM AHS_SOTHAM_BANAN_DIEU_CHITIET ct
													INNER JOIN AHS_SOTHAM_HDXX hd on ct.BANANID=hd.VUANID 
													WHERE ct.ISANTREO=1 AND hd.CANBOID=cbo.ID
																AND 1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN INSTR(vMaVaiTro,hd.MAVAITRO)>0 THEN 1 ELSE 0 END
																--AND (hd.NGAYPHANCONG BETWEEN cbo.NGAYBONHIEM AND cbo.NGAYKETTHUC)
												)>0 AND vAnTreo='1' THEN 1 ELSE 0 END)
					OR
					1=(CASE WHEN vAnTreo='0' THEN 1 
									WHEN (SELECT COUNT(hd.CANBOID) FROM AHS_PHUCTHAM_BANAN_DIEU_CT ct
													INNER JOIN AHS_SOTHAM_HDXX hd on ct.BANANID=hd.VUANID 
													WHERE ct.ISANTREO=1 AND hd.CANBOID=cbo.ID
																AND 1=CASE WHEN vMaVaiTro='THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET,' THEN 1 WHEN INSTR(vMaVaiTro,hd.MAVAITRO)>0 THEN 1 ELSE 0 END
																	--AND (hd.NGAYPHANCONG BETWEEN cbo.NGAYBONHIEM AND cbo.NGAYKETTHUC)
												)>0 AND vAnTreo='1' THEN 1 ELSE 0 END)
				)
	),
 cteTotal AS (
   SELECT COUNT(ID) AS Total FROM cteData
 ),
 cteFinal AS(
   SELECT ROW_NUMBER() OVER (ORDER BY a.ARRTHUTU,a.HOTEN) STT,a.ID,a.HOTEN,
   a.TENDonVi,a.NGAYSINH,a.ChucDanh,a.ARRTHUTU,(SELECT Total FROM cteTotal) AS Total
   FROM cteData a
 )
 
 SELECT a.*
 FROM cteFinal a WHERE a.STT between vMin AND vMax;
  
END DS_THAMPHAN_BYTOAAN;

PROCEDURE THONGKE_TP_HOMEPAGE 
(
	in_DonViID IN NUMBER,
	curReturn OUT sys_refcursor
)
AS
  vDonViID NUMBER;
  v_ARRAY THONGKE_TP_HOMEPAGE_T;
  v_ARRAY_TP_VUAN_NAM T_ID;
  v_ARRAY_TP_VUAN_THANG T_ID;
  vGroupChucDanhID NUMBER DEFAULT 0;
	vDayHetNhiemKy NUMBER DEFAULT 0;
  vDayBoNhiemMoi NUMBER DEFAULT 0;
  v_Now_Thang NUMBER DEFAULT 0;
  v_Now_Nam NUMBER DEFAULT 0;
  v_TP_Nam NUMBER DEFAULT 0;
  v_TP_Thang NUMBER DEFAULT 0;
  v_Tong_Nam NUMBER DEFAULT 0;
  v_Tong_Thang NUMBER DEFAULT 0;
BEGIN
  vDonViID:=in_DonViID;
  v_Now_Thang:=EXTRACT(MONTH FROM SYSDATE);
  v_Now_Nam:=EXTRACT(YEAR FROM SYSDATE);
  SELECT HETNHIEMKY,BONHIEMMOI INTO vDayHetNhiemKy,vDayBoNhiemMoi FROM GSTP_CAUHINH;
  --vDayHetNhiemKy:=60;--> Trước 60 ngày so với ngày kết thúc nhiệm kỳ sẽ được tính để cảnh báo sắp hết nhiệm kỳ
  --vDayBoNhiemMoi:=60;--> Trong khoảng 60 ngày kể từ ngày bắt đầu bổ nhiệm sẽ được tính là bổ nhiệm mới
  SELECT ID INTO vGroupChucDanhID FROM DM_DATAGROUP where MA='CHUCDANH';
  -- Khai báo bảng dữ liệu và khởi tạo
  v_ARRAY:=new THONGKE_TP_HOMEPAGE_T();
  v_ARRAY.EXTEND(11);
  v_ARRAY(1):=THONGKE_TP_HOMEPAGE_R(1,vDonViID,'Đang công tác',0,0,0,0,0,0);
  v_ARRAY(2):=THONGKE_TP_HOMEPAGE_R(2,vDonViID,'Bổ nhiệm mới',0,0,0,0,0,0);
  v_ARRAY(3):=THONGKE_TP_HOMEPAGE_R(3,vDonViID,'Sắp hết nhiệm kỳ',0,0,0,0,0,0);
  v_ARRAY(4):=THONGKE_TP_HOMEPAGE_R(4,vDonViID,'Bị dừng xét xử',0,0,0,0,0,0);
  v_ARRAY(5):=THONGKE_TP_HOMEPAGE_R(5,vDonViID,'Bị khiếu nại, tố cáo',0,0,0,0,0,0);
  v_ARRAY(6):=THONGKE_TP_HOMEPAGE_R(6,vDonViID,'Có án áp dụng biện pháp tạm thời',0,0,0,0,0,0);
  v_ARRAY(7):=THONGKE_TP_HOMEPAGE_R(7,vDonViID,'Có án bị hủy',0,0,0,0,0,0);
  v_ARRAY(8):=THONGKE_TP_HOMEPAGE_R(8,vDonViID,'Có án bị sửa',0,0,0,0,0,0);
  v_ARRAY(9):=THONGKE_TP_HOMEPAGE_R(9,vDonViID,'Có án quá hạn',0,0,0,0,0,0);
  v_ARRAY(10):=THONGKE_TP_HOMEPAGE_R(10,vDonViID,'Có án treo',0,0,0,0,0,0);
  v_ARRAY(11):=THONGKE_TP_HOMEPAGE_R(11,vDonViID,'Có án bị tạm đình chỉ',0,0,0,0,0,0);
  -- Tính tổng thẩm phán theo năm, tháng hiện tại
  SELECT COUNT(T1.ID) INTO v_Tong_Nam FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND (v_Now_Nam BETWEEN EXTRACT(YEAR FROM T1.NGAYBONHIEM) AND EXTRACT(YEAR FROM T1.NGAYKETTHUC));
  
  SELECT COUNT(T1.ID) INTO v_Tong_Thang FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND 1=CASE WHEN v_Now_Nam > EXTRACT(YEAR FROM T1.NGAYBONHIEM) AND v_Now_Nam < EXTRACT(YEAR FROM T1.NGAYKETTHUC) THEN 1
               WHEN v_Now_Nam = EXTRACT(YEAR FROM T1.NGAYBONHIEM) AND v_Now_Thang >= EXTRACT(MONTH FROM T1.NGAYBONHIEM) THEN 1
               WHEN v_Now_Nam = EXTRACT(YEAR FROM T1.NGAYKETTHUC) AND v_Now_Thang <= EXTRACT(MONTH FROM T1.NGAYKETTHUC) THEN 1
               ELSE 0 END;
  -- Tính dữ liệu theo 11 tiêu chí
  -- -- Tiêu chí 1: Đang công tác
  SELECT COUNT(T1.ID) INTO v_TP_Nam FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T1.HIEULUC=1 --> Đang công tác
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND (v_Now_Nam BETWEEN EXTRACT(YEAR FROM T1.NGAYBONHIEM) AND EXTRACT(YEAR FROM T1.NGAYKETTHUC));
  
  SELECT COUNT(T1.ID) INTO v_TP_Thang FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T1.HIEULUC=1 --> Đang công tác
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND 1=CASE WHEN v_Now_Nam > EXTRACT(YEAR FROM T1.NGAYBONHIEM) AND v_Now_Nam < EXTRACT(YEAR FROM T1.NGAYKETTHUC) THEN 1
               WHEN v_Now_Nam = EXTRACT(YEAR FROM T1.NGAYBONHIEM) AND v_Now_Thang >= EXTRACT(MONTH FROM T1.NGAYBONHIEM) THEN 1
               WHEN v_Now_Nam = EXTRACT(YEAR FROM T1.NGAYKETTHUC) AND v_Now_Thang <= EXTRACT(MONTH FROM T1.NGAYKETTHUC) THEN 1
               ELSE 0 END;
  v_ARRAY(1).v_NAM:=v_TP_Nam;
  v_ARRAY(1).v_THANG:=v_TP_Thang;
  v_ARRAY(1).v_TONG_NAM:=v_Tong_Nam;
  v_ARRAY(1).v_TONG_THANG:=v_Tong_Thang;
  IF v_Tong_Nam=0 THEN
    v_ARRAY(1).v_TYLENAM:=0;
  ELSE
    v_ARRAY(1).v_TYLENAM:=(v_TP_Nam/v_Tong_Nam)*100;
  END IF;
  IF v_Tong_Thang=0 THEN
    v_ARRAY(1).v_TYLETHANG:=0;
  ELSE
    v_ARRAY(1).v_TYLETHANG:=(v_TP_Thang/v_Tong_Thang)*100;
  END IF;
  -- -- Tiêu chí 2: Bổ nhiệm mới (Tính theo ngày hiện tại nên số liệu tính được của năm = tháng)
  SELECT COUNT(T1.ID) INTO v_TP_Nam FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND TRUNC(SYSDATE - T1.NGAYBONHIEM) <= 60; --> Mới bổ nhiệm
  v_TP_Thang:=v_TP_Nam;
  v_ARRAY(2).v_NAM:=v_TP_Nam;
  v_ARRAY(2).v_THANG:=v_TP_Thang;
  v_ARRAY(2).v_TONG_NAM:=v_Tong_Nam;
  v_ARRAY(2).v_TONG_THANG:=v_Tong_Thang;
  IF v_Tong_Nam=0 THEN
    v_ARRAY(2).v_TYLENAM:=0;
  ELSE
    v_ARRAY(2).v_TYLENAM:=(v_TP_Nam/v_Tong_Nam)*100;
  END IF;
  IF v_Tong_Thang=0 THEN
    v_ARRAY(2).v_TYLETHANG:=0;
  ELSE
    v_ARRAY(2).v_TYLETHANG:=(v_TP_Thang/v_Tong_Thang)*100;
  END IF;
  -- -- Tiêu chí 3: Sắp hết nhiệm kỳ  (Tính theo ngày hiện tại nên số liệu tính được của năm = tháng)
  SELECT COUNT(T1.ID) INTO v_TP_Nam FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND TRUNC(T1.NGAYKETTHUC - SYSDATE) <= 60; --> Sắp hết nhiệm kỳ
  v_TP_Thang:=v_TP_Nam;
  v_ARRAY(3).v_NAM:=v_TP_Nam;
  v_ARRAY(3).v_THANG:=v_TP_Thang;
  v_ARRAY(3).v_TONG_NAM:=v_Tong_Nam;
  v_ARRAY(3).v_TONG_THANG:=v_Tong_Thang;
  IF v_Tong_Nam=0 THEN
    v_ARRAY(3).v_TYLENAM:=0;
  ELSE
    v_ARRAY(3).v_TYLENAM:=(v_TP_Nam/v_Tong_Nam)*100;
  END IF;
  IF v_Tong_Thang=0 THEN
    v_ARRAY(3).v_TYLETHANG:=0;
  ELSE
    v_ARRAY(3).v_TYLETHANG:=(v_TP_Thang/v_Tong_Thang)*100;
  END IF;
  -- -- Tiêu chí 4: Bị dừng xét xử
  SELECT COUNT(T1.ID) INTO v_TP_Nam FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T1.HIEULUC=3 --> Bị dừng xét xử
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND (v_Now_Nam BETWEEN EXTRACT(YEAR FROM T1.NGAYBONHIEM) AND EXTRACT(YEAR FROM T1.NGAYKETTHUC));
  
  SELECT COUNT(T1.ID) INTO v_TP_Thang FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T1.HIEULUC=3 --> Bị dừng xét xử
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND 1=CASE WHEN v_Now_Nam > EXTRACT(YEAR FROM T1.NGAYBONHIEM) AND v_Now_Nam < EXTRACT(YEAR FROM T1.NGAYKETTHUC) THEN 1
               WHEN v_Now_Nam = EXTRACT(YEAR FROM T1.NGAYBONHIEM) AND v_Now_Thang >= EXTRACT(MONTH FROM T1.NGAYBONHIEM) THEN 1
               WHEN v_Now_Nam = EXTRACT(YEAR FROM T1.NGAYKETTHUC) AND v_Now_Thang <= EXTRACT(MONTH FROM T1.NGAYKETTHUC) THEN 1
               ELSE 0 END;
  v_ARRAY(4).v_NAM:=v_TP_Nam;
  v_ARRAY(4).v_THANG:=v_TP_Thang;
  v_ARRAY(4).v_TONG_NAM:=v_Tong_Nam;
  v_ARRAY(4).v_TONG_THANG:=v_Tong_Thang;
  IF v_Tong_Nam=0 THEN
    v_ARRAY(4).v_TYLENAM:=0;
  ELSE
    v_ARRAY(4).v_TYLENAM:=(v_TP_Nam/v_Tong_Nam)*100;
  END IF;
  IF v_Tong_Thang=0 THEN
    v_ARRAY(4).v_TYLETHANG:=0;
  ELSE
    v_ARRAY(4).v_TYLETHANG:=(v_TP_Thang/v_Tong_Thang)*100;
  END IF;
  -- -- Tiêu chí 5: Bị khiếu nại, tố cáo
  -- -- -- Chưa xác định được cách tổng hợp
  v_ARRAY(5).v_NAM:=0;
  v_ARRAY(5).v_THANG:=0;
  v_ARRAY(5).v_TONG_NAM:=v_Tong_Nam;
  v_ARRAY(5).v_TONG_THANG:=v_Tong_Thang;
  v_ARRAY(5).v_TYLENAM:=0;
  v_ARRAY(5).v_TYLETHANG:=0;
  -- -- Tiêu chí 6: Có án áp dụng biện pháp tạm thời
  -- -- -- Tính toán trên 8 loại với 2 giai đoạn sơ thẩm + phúc thẩm 
  v_ARRAY_TP_VUAN_NAM := new T_ID();
  v_ARRAY_TP_VUAN_THANG := new T_ID();
  PKG_GSTP.THONGKE_TP_HOMEPAGE_BPTT_NAM(v_ARRAY_TP_VUAN_NAM,vDonViID,v_Now_Nam);
  PKG_GSTP.THONGKE_TP_HOMEPAGE_BPTT_THANG(v_ARRAY_TP_VUAN_THANG,vDonViID,v_Now_Nam,v_Now_Thang);
  SELECT COUNT(DISTINCT v_ID) INTO v_TP_Nam FROM TABLE(v_ARRAY_TP_VUAN_NAM);
  SELECT COUNT(DISTINCT v_ID) INTO v_TP_Thang FROM TABLE(v_ARRAY_TP_VUAN_THANG);
  v_ARRAY(6).v_NAM:=v_TP_Nam;
  v_ARRAY(6).v_THANG:=v_TP_Thang;
  v_ARRAY(6).v_TONG_NAM:=v_Tong_Nam;
  v_ARRAY(6).v_TONG_THANG:=v_Tong_Thang;
  IF v_Tong_Nam=0 THEN
    v_ARRAY(6).v_TYLENAM:=0;
  ELSE
    v_ARRAY(6).v_TYLENAM:=(v_TP_Nam/v_Tong_Nam)*100;
  END IF;
  IF v_Tong_Thang=0 THEN
    v_ARRAY(6).v_TYLETHANG:=0;
  ELSE
    v_ARRAY(6).v_TYLETHANG:=(v_TP_Thang/v_Tong_Thang)*100;
  END IF;
  -- -- Tiêu chí 7: Có án bị hủy
  v_ARRAY_TP_VUAN_NAM:=new T_ID();
  v_ARRAY_TP_VUAN_THANG:=new T_ID();
  PKG_GSTP.THONGKE_TP_HOMEPAGE_HUY_NAM(v_ARRAY_TP_VUAN_NAM,vDonViID,v_Now_Nam);
  PKG_GSTP.THONGKE_TP_HOMEPAGE_HUY_THANG(v_ARRAY_TP_VUAN_THANG,vDonViID,v_Now_Nam,v_Now_Thang);
  SELECT COUNT(DISTINCT v_ID) INTO v_TP_Nam FROM TABLE(v_ARRAY_TP_VUAN_NAM);
  SELECT COUNT(DISTINCT v_ID) INTO v_TP_Thang FROM TABLE(v_ARRAY_TP_VUAN_THANG);
  v_ARRAY(7).v_NAM:=v_TP_Nam;
  v_ARRAY(7).v_THANG:=v_TP_Thang;
  v_ARRAY(7).v_TONG_NAM:=v_Tong_Nam;
  v_ARRAY(7).v_TONG_THANG:=v_Tong_Thang;
  IF v_Tong_Nam=0 THEN
    v_ARRAY(7).v_TYLENAM:=0;
  ELSE
    v_ARRAY(7).v_TYLENAM:=(v_TP_Nam/v_Tong_Nam)*100;
  END IF;
  IF v_Tong_Thang=0 THEN
    v_ARRAY(7).v_TYLETHANG:=0;
  ELSE
    v_ARRAY(7).v_TYLETHANG:=(v_TP_Thang/v_Tong_Thang)*100;
  END IF;
  -- -- Tiêu chí 8: Có án bị sửa
  v_ARRAY_TP_VUAN_NAM:=new T_ID();
  v_ARRAY_TP_VUAN_THANG:=new T_ID();
  PKG_GSTP.THONGKE_TP_HOMEPAGE_SUA_NAM(v_ARRAY_TP_VUAN_NAM,vDonViID,v_Now_Nam);
  PKG_GSTP.THONGKE_TP_HOMEPAGE_SUA_THANG(v_ARRAY_TP_VUAN_THANG,vDonViID,v_Now_Nam,v_Now_Thang);
  SELECT COUNT(DISTINCT v_ID) INTO v_TP_Nam FROM TABLE(v_ARRAY_TP_VUAN_NAM);
  SELECT COUNT(DISTINCT v_ID) INTO v_TP_Thang FROM TABLE(v_ARRAY_TP_VUAN_THANG);
  v_ARRAY(8).v_NAM:=v_TP_Nam;
  v_ARRAY(8).v_THANG:=v_TP_Thang;
  v_ARRAY(8).v_TONG_NAM:=v_Tong_Nam;
  v_ARRAY(8).v_TONG_THANG:=v_Tong_Thang;
  IF v_Tong_Nam=0 THEN
    v_ARRAY(8).v_TYLENAM:=0;
  ELSE
    v_ARRAY(8).v_TYLENAM:=(v_TP_Nam/v_Tong_Nam)*100;
  END IF;
  IF v_Tong_Thang=0 THEN
    v_ARRAY(8).v_TYLETHANG:=0;
  ELSE
    v_ARRAY(8).v_TYLETHANG:=(v_TP_Thang/v_Tong_Thang)*100;
  END IF;
  -- -- Tiêu chí 9: Có án quá hạn
  v_ARRAY_TP_VUAN_NAM:=new T_ID();
  v_ARRAY_TP_VUAN_THANG:=new T_ID();
  PKG_GSTP.THONGKE_TP_HOMEPAGE_QHAN_NAM(v_ARRAY_TP_VUAN_NAM,vDonViID,v_Now_Nam);
  PKG_GSTP.THONGKE_TP_HOMEPAGE_QHAN_THANG(v_ARRAY_TP_VUAN_THANG,vDonViID,v_Now_Nam,v_Now_Thang);
  SELECT COUNT(DISTINCT v_ID) INTO v_TP_Nam FROM TABLE(v_ARRAY_TP_VUAN_NAM);
  SELECT COUNT(DISTINCT v_ID) INTO v_TP_Thang FROM TABLE(v_ARRAY_TP_VUAN_THANG);
  v_ARRAY(9).v_NAM:=v_TP_Nam;
  v_ARRAY(9).v_THANG:=v_TP_Thang;
  v_ARRAY(9).v_TONG_NAM:=v_Tong_Nam;
  v_ARRAY(9).v_TONG_THANG:=v_Tong_Thang;
  IF v_Tong_Nam=0 THEN
    v_ARRAY(9).v_TYLENAM:=0;
  ELSE
    v_ARRAY(9).v_TYLENAM:=(v_TP_Nam/v_Tong_Nam)*100;
  END IF;
  IF v_Tong_Thang=0 THEN
    v_ARRAY(9).v_TYLETHANG:=0;
  ELSE
    v_ARRAY(9).v_TYLETHANG:=(v_TP_Thang/v_Tong_Thang)*100;
  END IF;
  -- -- Tiêu chí 10: Có án treo
  v_ARRAY_TP_VUAN_NAM:=new T_ID();
  v_ARRAY_TP_VUAN_THANG:=new T_ID();
  PKG_GSTP.THONGKE_TP_HOMEPAGE_TREO_NAM(v_ARRAY_TP_VUAN_NAM,vDonViID,v_Now_Nam);
  PKG_GSTP.THONGKE_TP_HOMEPAGE_TREO_THANG(v_ARRAY_TP_VUAN_THANG,vDonViID,v_Now_Nam,v_Now_Thang);
  SELECT COUNT(DISTINCT v_ID) INTO v_TP_Nam FROM TABLE(v_ARRAY_TP_VUAN_NAM);
  SELECT COUNT(DISTINCT v_ID) INTO v_TP_Thang FROM TABLE(v_ARRAY_TP_VUAN_THANG);
  v_ARRAY(10).v_NAM:=v_TP_Nam;
  v_ARRAY(10).v_THANG:=v_TP_Thang;
  v_ARRAY(10).v_TONG_NAM:=v_Tong_Nam;
  v_ARRAY(10).v_TONG_THANG:=v_Tong_Thang;
  IF v_Tong_Nam=0 THEN
    v_ARRAY(10).v_TYLENAM:=0;
  ELSE
    v_ARRAY(10).v_TYLENAM:=(v_TP_Nam/v_Tong_Nam)*100;
  END IF;
  IF v_Tong_Thang=0 THEN
    v_ARRAY(10).v_TYLETHANG:=0;
  ELSE
    v_ARRAY(10).v_TYLETHANG:=(v_TP_Thang/v_Tong_Thang)*100;
  END IF;
  -- -- Tiêu chí 11: Có án bị tạm đình chỉ
  v_ARRAY_TP_VUAN_NAM:=new T_ID();
  v_ARRAY_TP_VUAN_THANG:=new T_ID();
  PKG_GSTP.THONGKE_TP_HOMEPAGE_TDC_NAM(v_ARRAY_TP_VUAN_NAM,vDonViID,v_Now_Nam);
  PKG_GSTP.THONGKE_TP_HOMEPAGE_TDC_THANG(v_ARRAY_TP_VUAN_THANG,vDonViID,v_Now_Nam,v_Now_Thang);
  SELECT COUNT(DISTINCT v_ID) INTO v_TP_Nam FROM TABLE(v_ARRAY_TP_VUAN_NAM);
  SELECT COUNT(DISTINCT v_ID) INTO v_TP_Thang FROM TABLE(v_ARRAY_TP_VUAN_THANG);
  v_ARRAY(11).v_NAM:=v_TP_Nam;
  v_ARRAY(11).v_THANG:=v_TP_Thang;
  v_ARRAY(11).v_TONG_NAM:=v_Tong_Nam;
  v_ARRAY(11).v_TONG_THANG:=v_Tong_Thang;
  IF v_Tong_Nam=0 THEN
    v_ARRAY(11).v_TYLENAM:=0;
  ELSE
    v_ARRAY(11).v_TYLENAM:=(v_TP_Nam/v_Tong_Nam)*100;
  END IF;
  IF v_Tong_Thang=0 THEN
    v_ARRAY(11).v_TYLETHANG:=0;
  ELSE
    v_ARRAY(11).v_TYLETHANG:=(v_TP_Thang/v_Tong_Thang)*100;
  END IF;
  
  OPEN curReturn FOR
  SELECT a.v_STT,a.v_TOAANID,a.v_CHITIEU,a.v_NAM,a.v_THANG,a.v_TONG_NAM,a.v_TONG_THANG,
    ROUND(a.v_TYLENAM,2) v_TYLENAM,ROUND(a.v_TYLETHANG,2) v_TYLETHANG
  FROM TABLE(v_ARRAY) a;
  
END THONGKE_TP_HOMEPAGE;

PROCEDURE THONGKE_TP_3NAM_3TIEUCHI 
(
  in_DonViID in number,
  curReturn OUT sys_refcursor
)
AS
  vDonViID NUMBER;
  v_ARRAY THONGKE_TP_HOMEPAGE_T;
  vGroupChucDanhID NUMBER;
  v_Nam_Now NUMBER;
  v_Nam_Past1 NUMBER;
  v_Nam_Past2 NUMBER;
  v_Date_Past1 DATE;
  v_Date_Past2 DATE;
  vDayHetNhiemKy NUMBER;
  vDayBoNhiemMoi NUMBER;
  v_TP_Nam NUMBER;
BEGIN
  -- v_ARRAY.v_NAM : Lưu năm hiện tại
  -- v_ARRAY.v_THANG : Lưu trước năm hiện tại 1 năm
  -- v_ARRAY.v_TONG_NAM : Lưu trước năm hiện tại 2 năm
  -- v_ARRAY.v_TONG_THANG : Lưu số biến động (chỉ trong tiêu chí đang công tác)
  -- v_ARRAY.v_TYLENAM : Lưu Tỷ lệ biến động (chỉ trong tiêu chí đang công tác)
  vDonViID := in_DonViID;
  v_Nam_Now := EXTRACT(YEAR FROM SYSDATE);
  v_Nam_Past1 := v_Nam_Now - 1;
  v_Nam_Past2 := v_Nam_Now - 2;
  SELECT TO_DATE('31/12/'||v_Nam_Past1,'dd/MM/yyyy'),TO_DATE('31/12/'||v_Nam_Past2,'dd/MM/yyyy') INTO v_Date_Past1,v_Date_Past2 FROM DUAL;
  vDayHetNhiemKy:=60;--> Trước 60 ngày so với ngày kết thúc nhiệm kỳ sẽ được tính để cảnh báo sắp hết nhiệm kỳ
  vDayBoNhiemMoi:=60;--> Trong khoảng 60 ngày kể từ ngày bắt đầu bổ nhiệm sẽ được tính là bổ nhiệm mới
  SELECT ID INTO vGroupChucDanhID FROM DM_DATAGROUP where MA='CHUCDANH';
  -- Khai báo bảng dữ liệu và khởi tạo
  v_ARRAY:=new THONGKE_TP_HOMEPAGE_T();
  v_ARRAY.EXTEND(11);
  v_ARRAY(1):=THONGKE_TP_HOMEPAGE_R(1,vDonViID,'Đang công tác',0,0,0,0,0,0);
  v_ARRAY(2):=THONGKE_TP_HOMEPAGE_R(2,vDonViID,'Sắp hết nhiệm kỳ',0,0,0,0,0,0);
  v_ARRAY(3):=THONGKE_TP_HOMEPAGE_R(3,vDonViID,'Bổ nhiệm mới',0,0,0,0,0,0);
  -- Tiêu chí 1: Đang công tác
  -- -- Năm hiện tại
  SELECT COUNT(T1.ID) INTO v_TP_Nam FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T1.HIEULUC=1 --> Đang công tác
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND (v_Nam_Now BETWEEN EXTRACT(YEAR FROM T1.NGAYBONHIEM) AND EXTRACT(YEAR FROM T1.NGAYKETTHUC));
  v_ARRAY(1).v_NAM:=v_TP_Nam;
  -- -- Trước năm hiện tại 1 năm
  SELECT COUNT(T1.ID) INTO v_TP_Nam FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T1.HIEULUC=1 --> Đang công tác
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND (v_Nam_Past1 BETWEEN EXTRACT(YEAR FROM T1.NGAYBONHIEM) AND EXTRACT(YEAR FROM T1.NGAYKETTHUC));
  v_ARRAY(1).v_THANG:=v_TP_Nam;
  v_ARRAY(1).v_TONG_THANG:=v_ARRAY(1).v_NAM - v_ARRAY(1).v_THANG; --> Số biến động
  IF v_ARRAY(1).v_NAM=0 THEN
    v_ARRAY(1).v_TYLENAM:=0; --> Tỷ lệ biến động
  ELSE
    v_ARRAY(1).v_TYLENAM:=(v_ARRAY(1).v_TONG_THANG/v_ARRAY(1).v_NAM)*100; --> Tỷ lệ biến động
  END IF;
  -- -- Trước năm hiện tại 2 năm
  SELECT COUNT(T1.ID) INTO v_TP_Nam FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T1.HIEULUC=1 --> Đang công tác
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND (v_Nam_Past2 BETWEEN EXTRACT(YEAR FROM T1.NGAYBONHIEM) AND EXTRACT(YEAR FROM T1.NGAYKETTHUC));
  v_ARRAY(1).v_TONG_NAM:=v_TP_Nam;
  -- Tiêu chí 2: Sắp hết nhiệm kỳ
  -- -- Năm hiện tại
  SELECT COUNT(T1.ID) INTO v_TP_Nam FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND TRUNC(T1.NGAYKETTHUC - SYSDATE) <= 60; --> Sắp hết nhiệm kỳ
  v_ARRAY(2).v_NAM:=v_TP_Nam;
  -- -- Trước năm hiện tại 1 năm
  SELECT COUNT(T1.ID) INTO v_TP_Nam FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND TRUNC(T1.NGAYKETTHUC - v_Date_Past1) <= 60; --> Sắp hết nhiệm kỳ
  v_ARRAY(2).v_THANG:=v_TP_Nam;
  -- -- Trước năm hiện tại 2 năm
  SELECT COUNT(T1.ID) INTO v_TP_Nam FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND TRUNC(T1.NGAYKETTHUC - v_Date_Past2) <= 60; --> Sắp hết nhiệm kỳ
  v_ARRAY(2).v_TONG_NAM:=v_TP_Nam;
  -- Tiêu chí 3: Bổ nhiệm mới
  -- -- Năm hiện tại
  SELECT COUNT(T1.ID) INTO v_TP_Nam FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND TRUNC(SYSDATE - T1.NGAYBONHIEM) <= 60; --> Mới bổ nhiệm
  v_ARRAY(3).v_NAM:=v_TP_Nam;
  -- -- Trước năm hiện tại 1 năm
  SELECT COUNT(T1.ID) INTO v_TP_Nam FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND TRUNC(v_Date_Past1 - T1.NGAYBONHIEM) <= 60; --> Mới bổ nhiệm
  v_ARRAY(3).v_THANG:=v_TP_Nam;
  -- -- Trước năm hiện tại 2 năm
  SELECT COUNT(T1.ID) INTO v_TP_Nam FROM DM_CANBO T1
	INNER JOIN DM_DATAITEM T3 ON T3.ID=T1.CHUCDANHID
  WHERE T1.TOAANID=vDonViID
    AND T3.GROUPID=vGroupChucDanhID
    AND INSTR('TP,TPSC,TPTC,TPCC,TPTATC',T3.MA)>0 --> Thẩm phán
    AND TRUNC(v_Date_Past2 - T1.NGAYBONHIEM) <= 60; --> Mới bổ nhiệm
  v_ARRAY(3).v_TONG_NAM:=v_TP_Nam;
  
  
  OPEN curReturn FOR
  SELECT a.v_STT,a.v_TOAANID,a.v_CHITIEU,a.v_NAM,a.v_THANG,a.v_TONG_NAM,a.v_TONG_THANG,
    ROUND(a.v_TYLENAM,2) v_TYLENAM
  FROM TABLE(v_ARRAY) a;
END THONGKE_TP_3NAM_3TIEUCHI;

PROCEDURE THONGKE_TP_HOMEPAGE_BPTT_NAM 
(
	v_ARRAY IN OUT T_ID,
  vDonViID IN NUMBER,
  v_Now_Nam IN NUMBER
)AS
BEGIN
  -- Hình sự sơ thẩm
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN AHS_SOTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN AHS_SOTHAM_QUYETDINH_VUAN T3 ON T3.VUANID=T2.VUANID
    INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYQD)=v_Now_Nam
      AND T4.MA='ADBPTT'
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  -- Hình sự Phúc thẩm
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN AHS_PHUCTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN AHS_PHUCTHAM_QUYETDINH_VUAN T3 ON T3.VUANID=T2.VUANID
    INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYQD)=v_Now_Nam
      AND T4.MA='ADBPTT'
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  -- Dân sự sơ thẩm
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN ADS_SOTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN ADS_SOTHAM_QUYETDINH T3 ON T3.DONID=T2.DONID
    INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYQD)=v_Now_Nam
      AND T4.MA='ADBPTT'
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  -- Dân sự Phúc thẩm
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN ADS_PHUCTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN ADS_PHUCTHAM_QUYETDINH T3 ON T3.DONID=T2.DONID
    INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYQD)=v_Now_Nam
      AND T4.MA='ADBPTT'
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  -- Hôn nhân - Gia đình sơ thẩm
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN AHN_SOTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN AHN_SOTHAM_QUYETDINH T3 ON T3.DONID=T2.DONID
    INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYQD)=v_Now_Nam
      AND T4.MA='ADBPTT'
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  -- Hôn nhân - Gia đình phúc thẩm
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN AHN_PHUCTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN AHN_PHUCTHAM_QUYETDINH T3 ON T3.DONID=T2.DONID
    INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYQD)=v_Now_Nam
      AND T4.MA='ADBPTT'
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  -- Kinh tế sơ thẩm
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN AKT_SOTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN AKT_SOTHAM_QUYETDINH T3 ON T3.DONID=T2.DONID
    INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYQD)=v_Now_Nam
      AND T4.MA='ADBPTT'
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  -- Kinh tế phúc thẩm
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN AKT_PHUCTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN AKT_PHUCTHAM_QUYETDINH T3 ON T3.DONID=T2.DONID
    INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYQD)=v_Now_Nam
      AND T4.MA='ADBPTT'
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  -- Lao động sơ thẩm
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN ALD_SOTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN ALD_SOTHAM_QUYETDINH T3 ON T3.DONID=T2.DONID
    INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYQD)=v_Now_Nam
      AND T4.MA='ADBPTT'
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  -- Lao động phúc thẩm
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN ALD_PHUCTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN ALD_PHUCTHAM_QUYETDINH T3 ON T3.DONID=T2.DONID
    INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYQD)=v_Now_Nam
      AND T4.MA='ADBPTT'
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  -- Hành chính sơ thẩm
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN AHC_SOTHAM_HDXX T2 ON T1.ID=T2.CANBOID
