PROCEDURE THONGKE_TP_HOMEPAGE_HUY_NAM 
(
  v_ARRAY IN OUT T_ID,
  vDonViID IN NUMBER,
  v_Now_Nam IN NUMBER
)
AS
BEGIN
  -- Hình sự
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN AHS_PHUCTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN AHS_PHUCTHAM_BANAN T3 ON T3.VUANID=T2.VUANID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYBANAN)=v_Now_Nam
      AND INSTR('03,04,06,13,14',T4.MA)>0
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  -- Dân sự
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN ADS_PHUCTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN ADS_PHUCTHAM_BANAN T3 ON T3.DONID=T2.DONID
    INNER JOIN DM_KETQUA_PHUCTHAM T4 ON T4.ID=T3.KETQUAPHUCTHAMID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYTUYENAN)=v_Now_Nam
      AND INSTR('03,04,06,13,14',T4.MA)>0
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  -- Hôn nhân
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN AHN_PHUCTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN AHN_PHUCTHAM_BANAN T3 ON T3.DONID=T2.DONID
