PROCEDURE THONGKE_TP_HOMEPAGE_TREO_NAM 
(
  v_ARRAY IN OUT T_ID,
  vDonViID IN NUMBER,
  v_Now_Nam IN NUMBER
)
AS
BEGIN
  -- Chỉ có ở án hình sự
   FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN AHS_SOTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN AHS_SOTHAM_BANAN T3 ON T3.VUANID=T2.VUANID
    INNER JOIN AHS_SOTHAM_BANAN_DIEU_CHITIET T4 ON T4.BANANID=T3.ID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYBANAN)=v_Now_Nam
      AND T4.ISANTREO=1
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN AHS_PHUCTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN AHS_PHUCTHAM_BANAN T3 ON T3.VUANID=T2.VUANID
    INNER JOIN AHS_PHUCTHAM_BANAN_DIEU_CT T4 ON T4.BANANID=T3.ID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYBANAN)=v_Now_Nam
      AND T4.ISANTREO=1
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
END;

