    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN XLHC_SOTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN XLHC_SOTHAM_QUYETDINH T3 ON T3.DONID=T2.DONID
    INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYQD)=v_Now_Nam
      AND T4.MA='TDC'
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  -- XLHC phúc thẩm
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN XLHC_PHUCTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN XLHC_PHUCTHAM_QUYETDINH T3 ON T3.DONID=T2.DONID
    INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYQD)=v_Now_Nam
      AND T4.MA='TDC'
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
END;

PROCEDURE THONGKE_TP_HOMEPAGE_TDC_THANG 
(
  v_ARRAY IN OUT T_ID,
  vDonViID IN NUMBER,
  v_Now_Nam IN NUMBER,
  v_Now_Thang IN NUMBER
)
AS
BEGIN
   -- Hình sự sơ thẩm
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN AHS_SOTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN AHS_SOTHAM_QUYETDINH_VUAN T3 ON T3.VUANID=T2.VUANID
    INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYQD)=v_Now_Nam
      AND EXTRACT(MONTH FROM T3.NGAYQD)=v_Now_Thang
      AND T4.MA='TDC'
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  -- Hình sự Phúc thẩm
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN AHS_PHUCTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN AHS_PHUCTHAM_QUYETDINH_VUAN T3 ON T3.VUANID=T2.VUANID
    INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
    WHERE T1.TOAANID=vDonViID
      AND (T2.NGAYPHANCONG BETWEEN T1.NGAYBONHIEM AND T1.NGAYKETTHUC)
      AND INSTR('THAMPHAN,THAMPHANHDXX,THAMPHANDUKHUYET',T2.MAVAITRO)>0
      AND EXTRACT(YEAR FROM T3.NGAYQD)=v_Now_Nam
      AND EXTRACT(MONTH FROM T3.NGAYQD)=v_Now_Thang
      AND T4.MA='TDC'
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  -- Dân sự sơ thẩm
  FOR item IN (
    SELECT DISTINCT T1.ID FROM DM_CANBO T1
    INNER JOIN ADS_SOTHAM_HDXX T2 ON T1.ID=T2.CANBOID
    INNER JOIN ADS_SOTHAM_QUYETDINH T3 ON T3.DONID=T2.DONID
    INNER JOIN DM_QD_LOAI T4 ON T4.ID=T3.LOAIQDID
