PROCEDURE THONGKE_AN_HOMEPAGE 
(
	vDonViID in number,
	curReturn OUT sys_refcursor
)
AS
  v_ARRAY THONGKE_TP_HOMEPAGE_T;
  v_ARRAY_VUAN_NAM T_ID;
  v_ARRAY_VUAN_THANG T_ID;
  v_Now_Thang NUMBER DEFAULT 0;
  v_Now_Nam NUMBER DEFAULT 0;
  v_VuAn_Nam NUMBER DEFAULT 0;
  v_VuAn_Thang NUMBER DEFAULT 0;
BEGIN
  v_Now_Thang:=EXTRACT(MONTH FROM SYSDATE);
  v_Now_Nam:=EXTRACT(YEAR FROM SYSDATE);
  -- Khai báo bảng dữ liệu và khởi tạo
  v_ARRAY:=new THONGKE_TP_HOMEPAGE_T();
  v_ARRAY.EXTEND(6);
  v_ARRAY(1):=THONGKE_TP_HOMEPAGE_R(1,vDonViID,'Án bị hủy',0,0,0,0,0,0);
  v_ARRAY(2):=THONGKE_TP_HOMEPAGE_R(2,vDonViID,'Án bị sửa',0,0,0,0,0,0);
  v_ARRAY(3):=THONGKE_TP_HOMEPAGE_R(3,vDonViID,'Án quá hạn',0,0,0,0,0,0);
  v_ARRAY(4):=THONGKE_TP_HOMEPAGE_R(4,vDonViID,'Án bị tạm đình chỉ',0,0,0,0,0,0);
  v_ARRAY(5):=THONGKE_TP_HOMEPAGE_R(5,vDonViID,'Án treo',0,0,0,0,0,0);
  v_ARRAY(6):=THONGKE_TP_HOMEPAGE_R(6,vDonViID,'Án áp dụng BPTT',0,0,0,0,0,0);
  -- Tính dữ liệu theo 6 tiêu chí
  -- -- Tiêu chí 1: Án bị hủy
  v_ARRAY_VUAN_NAM := new T_ID();
  v_ARRAY_VUAN_THANG := new T_ID();
  PKG_GSTP.THONGKE_AN_HOMEPAGE_HUY_NAM(v_ARRAY_VUAN_NAM,vDonViID,v_Now_Nam);
  PKG_GSTP.THONGKE_AN_HOMEPAGE_HUY_THANG(v_ARRAY_VUAN_THANG,vDonViID,v_Now_Nam,v_Now_Thang);
  SELECT COUNT(DISTINCT v_ID) INTO v_VuAn_Nam FROM TABLE(v_ARRAY_VUAN_NAM);
  SELECT COUNT(DISTINCT v_ID) INTO v_VuAn_Thang FROM TABLE(v_ARRAY_VUAN_THANG);
  v_ARRAY(1).v_NAM:=v_VuAn_Nam;
  v_ARRAY(1).v_THANG:=v_VuAn_Thang;
  -- -- Tiêu chí 2: Án bị sửa
  v_ARRAY_VUAN_NAM := new T_ID();
  v_ARRAY_VUAN_THANG := new T_ID();
  PKG_GSTP.THONGKE_AN_HOMEPAGE_SUA_NAM(v_ARRAY_VUAN_NAM,vDonViID,v_Now_Nam);
  PKG_GSTP.THONGKE_AN_HOMEPAGE_SUA_THANG(v_ARRAY_VUAN_THANG,vDonViID,v_Now_Nam,v_Now_Thang);
  SELECT COUNT(DISTINCT v_ID) INTO v_VuAn_Nam FROM TABLE(v_ARRAY_VUAN_NAM);
  SELECT COUNT(DISTINCT v_ID) INTO v_VuAn_Thang FROM TABLE(v_ARRAY_VUAN_THANG);
  v_ARRAY(2).v_NAM:=v_VuAn_Nam;
  v_ARRAY(2).v_THANG:=v_VuAn_Thang;
  -- -- Tiêu chí 3: Án quá hạn
  v_ARRAY_VUAN_NAM := new T_ID();
  v_ARRAY_VUAN_THANG := new T_ID();
  PKG_GSTP.THONGKE_AN_HOMEPAGE_QHAN_NAM(v_ARRAY_VUAN_NAM,vDonViID,v_Now_Nam);
  PKG_GSTP.THONGKE_AN_HOMEPAGE_QHAN_THANG(v_ARRAY_VUAN_THANG,vDonViID,v_Now_Nam,v_Now_Thang);
  SELECT COUNT(DISTINCT v_ID) INTO v_VuAn_Nam FROM TABLE(v_ARRAY_VUAN_NAM);
  SELECT COUNT(DISTINCT v_ID) INTO v_VuAn_Thang FROM TABLE(v_ARRAY_VUAN_THANG);
  v_ARRAY(3).v_NAM:=v_VuAn_Nam;
  v_ARRAY(3).v_THANG:=v_VuAn_Thang;
  -- -- Tiêu chí 4: Án bị tạm đình chỉ
  v_ARRAY_VUAN_NAM := new T_ID();
  v_ARRAY_VUAN_THANG := new T_ID();
  PKG_GSTP.THONGKE_AN_HOMEPAGE_TDC_NAM(v_ARRAY_VUAN_NAM,vDonViID,v_Now_Nam);
  PKG_GSTP.THONGKE_AN_HOMEPAGE_TDC_THANG(v_ARRAY_VUAN_THANG,vDonViID,v_Now_Nam,v_Now_Thang);
  SELECT COUNT(DISTINCT v_ID) INTO v_VuAn_Nam FROM TABLE(v_ARRAY_VUAN_NAM);
  SELECT COUNT(DISTINCT v_ID) INTO v_VuAn_Thang FROM TABLE(v_ARRAY_VUAN_THANG);
  v_ARRAY(4).v_NAM:=v_VuAn_Nam;
  v_ARRAY(4).v_THANG:=v_VuAn_Thang;
  -- -- Tiêu chí 5: Án treo
  v_ARRAY_VUAN_NAM := new T_ID();
  v_ARRAY_VUAN_THANG := new T_ID();
  PKG_GSTP.THONGKE_AN_HOMEPAGE_TREO_NAM(v_ARRAY_VUAN_NAM,vDonViID,v_Now_Nam);
  PKG_GSTP.THONGKE_AN_HOMEPAGE_TREO_THANG(v_ARRAY_VUAN_THANG,vDonViID,v_Now_Nam,v_Now_Thang);
  SELECT COUNT(DISTINCT v_ID) INTO v_VuAn_Nam FROM TABLE(v_ARRAY_VUAN_NAM);
  SELECT COUNT(DISTINCT v_ID) INTO v_VuAn_Thang FROM TABLE(v_ARRAY_VUAN_THANG);
  v_ARRAY(5).v_NAM:=v_VuAn_Nam;
  v_ARRAY(5).v_THANG:=v_VuAn_Thang;
  -- -- Tiêu chí 6: Án áp dụng BPTT
  v_ARRAY_VUAN_NAM := new T_ID();
  v_ARRAY_VUAN_THANG := new T_ID();
  PKG_GSTP.THONGKE_AN_HOMEPAGE_BPTT_NAM(v_ARRAY_VUAN_NAM,vDonViID,v_Now_Nam);
  PKG_GSTP.THONGKE_AN_HOMEPAGE_BPTT_THANG(v_ARRAY_VUAN_THANG,vDonViID,v_Now_Nam,v_Now_Thang);
  SELECT COUNT(DISTINCT v_ID) INTO v_VuAn_Nam FROM TABLE(v_ARRAY_VUAN_NAM);
  SELECT COUNT(DISTINCT v_ID) INTO v_VuAn_Thang FROM TABLE(v_ARRAY_VUAN_THANG);
  v_ARRAY(6).v_NAM:=v_VuAn_Nam;
  v_ARRAY(6).v_THANG:=v_VuAn_Thang;
  
  OPEN curReturn FOR
  SELECT a.v_STT,a.v_CHITIEU,a.v_NAM,a.v_THANG 
  FROM TABLE(v_ARRAY) a;

END THONGKE_AN_HOMEPAGE;
PROCEDURE THONGKE_AN_HOMEPAGE_HUY_NAM
