PROCEDURE THONGKE_AN_HOMEPAGE_QHAN_NAM
(
  v_ARRAY IN OUT T_ID,
  vDonViID IN NUMBER,
  v_Now_Nam IN NUMBER
)
AS
BEGIN
  -- Hình sự
  FOR item IN (
    SELECT DISTINCT T1.ID FROM AHS_VUAN T1
    INNER JOIN AHS_SOTHAM_BANAN T2 ON T2.VUANID=T1.ID
    WHERE T2.TOAANID=vDonViID
      AND EXTRACT(YEAR FROM T2.NGAYBANAN)=v_Now_Nam
      AND (T2.TK_QUAHAN_KHACHQUAN=1 OR T2.TK_QUAHAN_CHUQUAN=1)
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
	-- Dân sự
