PROCEDURE THONGKE_AN_HOMEPAGE_TREO_NAM
(
  v_ARRAY IN OUT T_ID,
  vDonViID IN NUMBER,
  v_Now_Nam IN NUMBER
)
AS
BEGIN
  -- Chỉ có ở án hình sự
   FOR item IN (
    SELECT DISTINCT T1.ID FROM AHS_VUAN T1
    INNER JOIN AHS_SOTHAM_BANAN T2 ON T2.VUANID=T1.ID
    INNER JOIN AHS_SOTHAM_BANAN_DIEU_CHITIET T3 ON T3.BANANID=T2.ID
    WHERE T2.TOAANID=vDonViID
      AND T3.ISANTREO=1
      AND EXTRACT(YEAR FROM T2.NGAYBANAN)=v_Now_Nam
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
  
  FOR item IN (
    SELECT DISTINCT T1.ID FROM AHS_VUAN T1
    INNER JOIN AHS_PHUCTHAM_BANAN T2 ON T2.VUANID=T1.ID
    INNER JOIN AHS_PHUCTHAM_BANAN_DIEU_CT T3 ON T3.BANANID=T2.ID
    WHERE T2.TOAANID=vDonViID
      AND T3.ISANTREO=1
      AND EXTRACT(YEAR FROM T2.NGAYBANAN)=v_Now_Nam
  ) LOOP
    v_ARRAY.EXTEND();
    v_ARRAY(v_ARRAY.COUNT):=R_ID(item.ID);
  END LOOP;
END;
