PROCEDURE THONGKE_TP_DANGCONGTAC
(
  vDonViID in number,
  vIsTrongNam in number,
	vThang in number,
	vNam in number,
  vPageIndex in number,
  vPageSize in number,
  CurReturn OUT sys_refcursor
) As
vArrSapXep varchar2(250);vIsToaCapCao number;vGroupChucDanhID number:=0;vMin number:=0;vMax number;
vDangCongTac number:=1;
BEGIN
	vMin := vPageSize*(vPageIndex - 1) + 1;
	vMax := vPageIndex*vPageSize ;
	if vDonViID>0 then
			begin
			select t.ARRSAPXEP into vArrSapXep from DM_TOAAN t where t.ID=vDonViID;
			select count(t.ID) into vIsToaCapCao from DM_TOAAN t where t.ID=vDonViID and t.LOAITOA='CAPCAO';
			end;
	else
			begin
			vArrSapXep:='0';
			vIsToaCapCao:=0;
			end;
	end if;
  select a.ID into vGroupChucDanhID from DM_DATAGROUP a where a.MA='CHUCDANH';
  open CurReturn for
  with cteData as (
	select cb.ID,cb.HOTEN as TenTP,ta.TenToaAn,cd.ChucDanh,cb.NGAYKETTHUC,ta.ARRTHUTU from DM_CANBO cb
	inner join (select g.ID,g.TEN as ChucDanh from DM_DATAITEM g where g.GROUPID=vGroupChucDanhID and g.MA in ('TP','TPSC','TPTC','TPCC','TPTATC')) cd on cd.ID=cb.CHUCDANHID
	inner join (select a.ID,a.MA_TEN as TenToaAn,a.ARRTHUTU from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on cb.TOAANID=ta.ID
	where cb.HIEULUC=vDangCongTac
				and 1=case when extract(year from cb.NGAYKETTHUC)>=vNam and vIsTrongNam=1 then 1
									 when (extract(year from cb.NGAYKETTHUC)>vNam or(extract(year from cb.NGAYKETTHUC)=vNam and extract(month from cb.NGAYKETTHUC)>=vThang)) and vIsTrongNam=0 then 1
									 else 0 end
 ),
  cteTotal as (
    select count(ID) as Total from cteData
  ),
  cteFinal AS(
    select ROW_NUMBER() OVER (ORDER BY a.ARRTHUTU,a.TenTP) STT,a.ID,a.TenTP,a.TenToaAn,a.ChucDanh,a.NGAYKETTHUC,(select Total from cteTotal) as Total
    from cteData a
  )
  
  select a.STT,a.ID as TPID,a.TenTP,a.TenToaAn,a.ChucDanh,a.NGAYKETTHUC,a.Total
  from cteFinal a where a.STT between vMin and vMax;
END THONGKE_TP_DANGCONGTAC;
PROCEDURE THONGKE_TP_BONHIEMMOI
(
  vDonViID in number,
  vIsTrongNam in number,
	vThang in number,
	vNam in number,
  vPageIndex in number,
  vPageSize in number,
  CurReturn OUT sys_refcursor
) As
vArrSapXep varchar2(250);vIsToaCapCao number;vGroupChucDanhID number:=0;vMin number:=0;vMax number;
vBoNhiemMoi number:=60;vNgay number;vDate date;
BEGIN
  if(vThang=2) then
    vNgay:=28;
  elsif (vThang=4 or vThang=6 or vThang=9 or vThang=11) then
    vNgay:=30;
  else
    vNgay:=31;
  end if;
  select to_date(to_char(vNam)||'-'||to_char(vThang)||'-'||to_char(vNgay),'YYYY-MM-DD') into vDate from dual;
	
  vMin := vPageSize*(vPageIndex - 1) + 1;
	vMax := vPageIndex*vPageSize ;
	if vDonViID>0 then
			begin
			select t.ARRSAPXEP into vArrSapXep from DM_TOAAN t where t.ID=vDonViID;
			select count(t.ID) into vIsToaCapCao from DM_TOAAN t where t.ID=vDonViID and t.LOAITOA='CAPCAO';
			end;
	else
			begin
			vArrSapXep:='0';
			vIsToaCapCao:=0;
			end;
	end if;
  select a.ID into vGroupChucDanhID from DM_DATAGROUP a where a.MA='CHUCDANH';
  select a.BONHIEMMOI into vBoNhiemMoi from GSTP_CAUHINH a;
  open CurReturn for
  with cteData as (
	select cb.ID,cb.HOTEN as TenTP,ta.TenToaAn,cd.ChucDanh,cb.NGAYKETTHUC,ta.ARRTHUTU from DM_CANBO cb
	inner join (select g.ID,g.TEN as ChucDanh from DM_DATAITEM g where g.GROUPID=vGroupChucDanhID and g.MA in ('TP','TPSC','TPTC','TPCC','TPTATC')) cd on cd.ID=cb.CHUCDANHID
	inner join (select a.ID,a.MA_TEN as TenToaAn,a.ARRTHUTU from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on cb.TOAANID=ta.ID
	where TRUNC(vDate-cb.NGAYBONHIEM)<=vBoNhiemMoi
				and 1=case when extract(year from cb.NGAYBONHIEM)=vNam and vIsTrongNam=1 then 1
									 when extract(year from cb.NGAYBONHIEM)=vNam and extract(month from cb.NGAYBONHIEM)<=vThang and vIsTrongNam=0 then 1
									 else 0 end
 ),
  cteTotal as (
    select count(ID) as Total from cteData
  ),
  cteFinal AS(
    select ROW_NUMBER() OVER (ORDER BY a.ARRTHUTU,a.TenTP) STT,a.ID,a.TenTP,a.TenToaAn,a.ChucDanh,a.NGAYKETTHUC,(select Total from cteTotal) as Total
    from cteData a
  )
  
  select a.STT,a.ID as TPID,a.TenTP,a.TenToaAn,a.ChucDanh,a.NGAYKETTHUC,a.Total
  from cteFinal a where a.STT between vMin and vMax;
END THONGKE_TP_BONHIEMMOI;
PROCEDURE THONGKE_TP_SAPHETNHIEMKY
(
	vDonViID in number,
  vIsTrongNam in number,
	vThang in number,
	vNam in number,
  vPageIndex in number,
  vPageSize in number,
	CurReturn OUT sys_refcursor
) AS
  vArrSapXep varchar2(250);vIsToaCapCao number;vGroupChucDanhID number:=0;vMin number:=0;vMax number;
	vHetNhiemKy number;vNgay number;vDate date;
BEGIN
  if(vThang=2) then
    vNgay:=28;
  elsif (vThang=4 or vThang=6 or vThang=9 or vThang=11) then
    vNgay:=30;
  else
    vNgay:=31;
  end if;
  select to_date(to_char(vNam)||'-'||to_char(vThang)||'-'||to_char(vNgay),'YYYY-MM-DD') into vDate from dual;
  
	vMin := vPageSize*(vPageIndex - 1) + 1;
	vMax := vPageIndex*vPageSize ;
	if vDonViID>0 then
			begin
			select t.ARRSAPXEP into vArrSapXep from DM_TOAAN t where t.ID=vDonViID;
			select count(t.ID) into vIsToaCapCao from DM_TOAAN t where t.ID=vDonViID and t.LOAITOA='CAPCAO';
			end;
	else
			begin
			vArrSapXep:='0';
			vIsToaCapCao:=0;
			end;
	end if;
	select a.HETNHIEMKY into vHetNhiemKy from GSTP_CAUHINH a;
	select a.ID into vGroupChucDanhID from DM_DATAGROUP a where a.MA='CHUCDANH';
  open CurReturn for
  with cteData as (
	select cb.ID,cb.HOTEN as TenTP,ta.TenToaAn,cd.ChucDanh,cb.NGAYKETTHUC,ta.ARRTHUTU from DM_CANBO cb
	inner join (select g.ID,g.TEN as ChucDanh from DM_DATAITEM g where g.GROUPID=vGroupChucDanhID and g.MA in ('TP','TPSC','TPTC','TPCC','TPTATC')) cd on cd.ID=cb.CHUCDANHID
	inner join (select a.ID,a.MA_TEN as TenToaAn,a.ARRTHUTU from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on cb.TOAANID=ta.ID
	where TRUNC(cb.NGAYKETTHUC-vDate)<=vHetNhiemKy
				and 1=case when extract(year from cb.NGAYKETTHUC)=vNam and vIsTrongNam=1 then 1
									 when extract(year from cb.NGAYKETTHUC)=vNam and extract(month from cb.NGAYKETTHUC)>=vThang and vIsTrongNam=0 then 1
									 else 0 end
 ),
  cteTotal as (
    select count(ID) as Total from cteData
  ),
  cteFinal AS(
    select ROW_NUMBER() OVER (ORDER BY a.ARRTHUTU,a.TenTP) STT,a.ID,a.TenTP,a.TenToaAn,a.ChucDanh,a.NGAYKETTHUC,(select Total from cteTotal) as Total
    from cteData a
  )
  
  select a.STT,a.ID as TPID,a.TenTP,a.TenToaAn,a.ChucDanh,a.NGAYKETTHUC,a.Total
  from cteFinal a where a.STT between vMin and vMax;
END THONGKE_TP_SAPHETNHIEMKY;
