	where cb.NGAYBONHIEM <= hdxx.NGAYPHANCONG and hdxx.NGAYPHANCONG <= cb.NGAYKETTHUC
	), cteData as (
		select tp.ID as TPID,tp.HOTEN as TenTP,tp.TenToaAn,cd.ChucDanh,tp.ARRTHUTU,
			PKG_GSTP.FUN_GETTYLE_ANHUY_BYTP(tp.ID,tp.NGAYBONHIEM,tp.NGAYKETTHUC) as TyLeAnHuy
		from cteTP tp
		inner join (select g.ID,g.TEN as ChucDanh from DM_DATAITEM g where g.GROUPID=vGroupChucDanhID  and g.MA in ('TP','TPSC','TPTC','TPCC','TPTATC')) cd on cd.ID=tp.CHUCDANHID
		),
  cteTotal as (
    select count(TPID) as Total from cteData
  ),
  cteFinal AS(
    select ROW_NUMBER() OVER (ORDER BY a.ARRTHUTU,a.TenTP) STT,a.TPID,a.TenTP,a.TenToaAn,a.ChucDanh,a.TyLeAnHuy,(select Total from cteTotal) as Total
    from cteData a
  )
  
  select a.STT,a.TPID,a.TenTP,a.TenToaAn,a.ChucDanh,a.TyLeAnHuy,a.Total
  from cteFinal a where a.STT between vMin and vMax;    
END THONGKE_TP_ANHUY;
PROCEDURE THONGKE_TP_ANSUA
(
	vDonViID in number,
  vIsTrongNam in number,
	vThang in number,
	vNam in number,
	vPageIndex in number,
	vPageSize in number,
	CurReturn OUT sys_refcursor
) AS
vArrSapXep varchar2(250);vIsToaCapCao number;vGroupChucDanhID number:=0;vMin number:=0;vMax number;
--vTyLeAnHuy number;
BEGIN
	vMin := vPageSize*(vPageIndex - 1) + 1;
	vMax := vPageIndex*vPageSize ;
	if vDonViID>0 then
			begin
			select t.ARRSAPXEP into vArrSapXep from DM_TOAAN t where t.ID=vDonViID;
			select count(t.ID) into vIsToaCapCao from DM_TOAAN t where t.ID=vDonViID and t.LOAITOA='CAPCAO';
			end;
	else
			begin
			vArrSapXep:='0';
			vIsToaCapCao:=0;
			end;
	end if;
  --select a.ANHUY into vTyLeAnHuy from GSTP_CAUHINH a;
  select a.ID into vGroupChucDanhID from DM_DATAGROUP a where a.MA='CHUCDANH';
  open CurReturn for
  WITH cteTP as(
	-- Hình sự
	select cb.ID,cb.HOTEN,cb.CHUCDANHID,cb.NGAYBONHIEM,cb.NGAYKETTHUC,ta.TenToaAn,ta.ARRTHUTU 
  from DM_CANBO cb
	inner join (select c.VUANID,c.CANBOID,c.NGAYPHANCONG from AHS_SOTHAM_HDXX c 
									where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
							) hdxx on cb.ID=hdxx.CANBOID
	inner join (select f.VUANID,f.KETQUAPHUCTHAMID,f.TOAANID from AHS_PHUCTHAM_BANAN f
							inner join (select e.ID from DM_KETQUA_PHUCTHAM e where e.ISAHS=1 and lower(e.TEN) like '%sửa%') kq on f.KETQUAPHUCTHAMID=kq.ID
							where 1=case when extract(year from f.NGAYBANAN)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from f.NGAYBANAN)=vNam and extract(month from f.NGAYBANAN)=vThang and vIsTrongNam=0 then 1
										else 0 end
							) ba on ba.VUANID=hdxx.VUANID
	inner join (select a.ID,a.MA_TEN as TenToaAn,a.ARRTHUTU from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on ta.ID=ba.TOAANID and cb.TOAANID=ta.ID 
	where cb.NGAYBONHIEM <= hdxx.NGAYPHANCONG and hdxx.NGAYPHANCONG <= cb.NGAYKETTHUC
	union
	-- Dân sự
	select cb.ID,cb.HOTEN,cb.CHUCDANHID,cb.NGAYBONHIEM,cb.NGAYKETTHUC,ta.TenToaAn,ta.ARRTHUTU 
