	where cb.NGAYBONHIEM <= hdxx.NGAYPHANCONG and hdxx.NGAYPHANCONG <= cb.NGAYKETTHUC
	union
	-- Lao động
	select cb.ID,cb.HOTEN,cb.CHUCDANHID,cb.NGAYBONHIEM,cb.NGAYKETTHUC,ta.TenToaAn,ta.ARRTHUTU 
  from DM_CANBO cb
	inner join (select c.DONID,c.CANBOID,c.NGAYPHANCONG from ALD_SOTHAM_HDXX c 
									where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
							) hdxx on cb.ID=hdxx.CANBOID
	inner join (select f.DONID,f.KETQUAPHUCTHAMID,f.TOAANID from ALD_PHUCTHAM_BANAN f
							inner join (select e.ID from DM_KETQUA_PHUCTHAM e where e.ISALD=1 and lower(e.TEN) like '%sửa%') kq on f.KETQUAPHUCTHAMID=kq.ID
							where 1=case when extract(year from f.NGAYTUYENAN)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from f.NGAYTUYENAN)=vNam and extract(month from f.NGAYTUYENAN)=vThang and vIsTrongNam=0 then 1
										else 0 end
							) ba on ba.DONID=hdxx.DONID
	inner join (select a.ID,a.MA_TEN as TenToaAn,a.ARRTHUTU from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on ta.ID=ba.TOAANID and cb.TOAANID=ta.ID 
	where cb.NGAYBONHIEM <= hdxx.NGAYPHANCONG and hdxx.NGAYPHANCONG <= cb.NGAYKETTHUC
	union
	-- Phá sản
	select cb.ID,cb.HOTEN,cb.CHUCDANHID,cb.NGAYBONHIEM,cb.NGAYKETTHUC,ta.TenToaAn,ta.ARRTHUTU 
  from DM_CANBO cb
	inner join (select c.DONID,c.CANBOID,c.NGAYPHANCONG from APS_SOTHAM_HDXX c 
									where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
							) hdxx on cb.ID=hdxx.CANBOID
	inner join (select f.DONID,f.KETQUAPHUCTHAMID,f.TOAANID from APS_PHUCTHAM_BANAN f
							inner join (select e.ID from DM_KETQUA_PHUCTHAM e where e.ISAPS=1 and lower(e.TEN) like '%sửa%') kq on f.KETQUAPHUCTHAMID=kq.ID
							where 1=case when extract(year from f.NGAYTUYENAN)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from f.NGAYTUYENAN)=vNam and extract(month from f.NGAYTUYENAN)=vThang and vIsTrongNam=0 then 1
										else 0 end
							) ba on ba.DONID=hdxx.DONID
	inner join (select a.ID,a.MA_TEN as TenToaAn,a.ARRTHUTU from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on ta.ID=ba.TOAANID and cb.TOAANID=ta.ID 
	where cb.NGAYBONHIEM <= hdxx.NGAYPHANCONG and hdxx.NGAYPHANCONG <= cb.NGAYKETTHUC
	union
	-- XLHC
	select cb.ID,cb.HOTEN,cb.CHUCDANHID,cb.NGAYBONHIEM,cb.NGAYKETTHUC,ta.TenToaAn,ta.ARRTHUTU 
  from DM_CANBO cb
	inner join (select c.DONID,c.CANBOID,c.NGAYPHANCONG from XLHC_SOTHAM_HDXX c 
									where c.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
							) hdxx on cb.ID=hdxx.CANBOID
	inner join (select f.DONID,f.KETQUAPHUCTHAMID,f.TOAANID from XLHC_PHUCTHAM_BANAN f
							inner join (select e.ID from DM_KETQUA_PHUCTHAM e where e.ISXLHC=1 and lower(e.TEN) like '%sửa%') kq on f.KETQUAPHUCTHAMID=kq.ID
							where 1=case when extract(year from f.NGAYTUYENAN)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from f.NGAYTUYENAN)=vNam and extract(month from f.NGAYTUYENAN)=vThang and vIsTrongNam=0 then 1
										else 0 end
							) ba on ba.DONID=hdxx.DONID
	inner join (select a.ID,a.MA_TEN as TenToaAn,a.ARRTHUTU from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on ta.ID=ba.TOAANID and cb.TOAANID=ta.ID 
	where cb.NGAYBONHIEM <= hdxx.NGAYPHANCONG and hdxx.NGAYPHANCONG <= cb.NGAYKETTHUC
	), cteData as (
		select tp.ID as TPID,tp.HOTEN as TenTP,tp.TenToaAn,cd.ChucDanh,tp.ARRTHUTU,
			PKG_GSTP.FUN_GETTYLE_ANSUA_BYTP(tp.ID,tp.NGAYBONHIEM,tp.NGAYKETTHUC) as TyLeAnSua
		from cteTP tp
		inner join (select g.ID,g.TEN as ChucDanh from DM_DATAITEM g where g.GROUPID=vGroupChucDanhID  and g.MA in ('TP','TPSC','TPTC','TPCC','TPTATC')) cd on cd.ID=tp.CHUCDANHID
		),
  cteTotal as (
    select count(TPID) as Total from cteData
  ),
  cteFinal AS(
    select ROW_NUMBER() OVER (ORDER BY a.ARRTHUTU,a.TenTP) STT,a.TPID,a.TenTP,a.TenToaAn,a.ChucDanh,a.TyLeAnSua,(select Total from cteTotal) as Total
    from cteData a
  )
  
  select a.STT,a.TPID,a.TenTP,a.TenToaAn,a.ChucDanh,a.TyLeAnSua,a.Total
  from cteFinal a where a.STT between vMin and vMax;
END THONGKE_TP_ANSUA;
PROCEDURE THONGKE_TP_ANQUAHAN
(
	vDonViID in number,
  vIsTrongNam in number,
	vThang in number,
	vNam in number,
	vPageIndex in number,
	vPageSize in number,
	CurReturn OUT sys_refcursor
) AS
vArrSapXep varchar2(250);vIsToaCapCao number;vGroupChucDanhID number:=0;vMin number:=0;vMax number;
BEGIN
	vMin := vPageSize*(vPageIndex - 1) + 1;
	vMax := vPageIndex*vPageSize ;
	if vDonViID>0 then
			begin
			select t.ARRSAPXEP into vArrSapXep from DM_TOAAN t where t.ID=vDonViID;
			select count(t.ID) into vIsToaCapCao from DM_TOAAN t where t.ID=vDonViID and t.LOAITOA='CAPCAO';
			end;
	else
			begin
			vArrSapXep:='0';
			vIsToaCapCao:=0;
			end;
	end if;
  --select a.ANHUY into vTyLeAnHuy from GSTP_CAUHINH a;
  select a.ID into vGroupChucDanhID from DM_DATAGROUP a where a.MA='CHUCDANH';
  open CurReturn for
  WITH cteTP as(
	-- Hình sự sơ thẩm
  select cb.ID,cb.HOTEN,cb.CHUCDANHID,cb.NGAYBONHIEM,cb.NGAYKETTHUC,b.TenToaAn,b.ARRTHUTU 
  from DM_CANBO cb
	inner join (select ta.ID,ta.MA_TEN as TenToaAn,ta.ARRTHUTU,hdxx.CANBOID,hdxx.NGAYPHANCONG from DM_TOAAN ta
              inner join (select st.VUANID,st.TOAANID from AHS_SOTHAM_BANAN st
                          where (st.TK_QUAHAN_KHACHQUAN=1 or st.TK_QUAHAN_CHUQUAN=1) and
                                1=case when extract(year from st.NGAYBANAN)=vNam and vIsTrongNam=1 then 1 
                                       when extract(year from st.NGAYBANAN)=vNam and extract(month from st.NGAYBANAN)=vThang and vIsTrongNam=0 then 1
                                    else 0 end
                          ) qd on qd.TOAANID=ta.ID
              inner join (select a.VUANID,a.CANBOID,a.NGAYPHANCONG from AHS_SOTHAM_HDXX a
                          where a.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
                          ) hdxx on qd.VUANID=hdxx.VUANID
              where 1= case when((ta.ARRSAPXEP like (vArrSapXep ||'/%') or ta.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                            when ta.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) b on cb.ID=b.CANBOID
	where cb.NGAYBONHIEM <= b.NGAYPHANCONG and b.NGAYPHANCONG <= cb.NGAYKETTHUC
  union
	--  Dân sự sơ thẩm
