                          where st.TK_ISQUAHAN=1 and
                                1=case when extract(year from st.NGAYTUYENAN)=vNam and vIsTrongNam=1 then 1 
                                       when extract(year from st.NGAYTUYENAN)=vNam and extract(month from st.NGAYTUYENAN)=vThang and vIsTrongNam=0 then 1
                                    else 0 end
                          ) qd on qd.TOAANID=ta.ID
              inner join (select a.DONID,a.CANBOID,a.NGAYPHANCONG from ADS_SOTHAM_HDXX a
