                          ) ta on ta.ID=qd.TOAANID
              where hdxx.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
							) b on cb.ID=b.CANBOID
	where cb.NGAYBONHIEM <= b.NGAYPHANCONG and b.NGAYPHANCONG <= cb.NGAYKETTHUC
	union
	-- Hành chính phúc thẩm
	select cb.ID,cb.HOTEN,cb.CHUCDANHID,cb.NGAYBONHIEM,cb.NGAYKETTHUC,b.TenToaAn,b.ARRTHUTU 
  from DM_CANBO cb
	inner join (select hdxx.DONID,hdxx.CANBOID,hdxx.NGAYPHANCONG,ta.TenToaAn,ta.ARRTHUTU from AHC_PHUCTHAM_HDXX hdxx
              inner join (select pt.DONID,pt.TOAANID from AHC_PHUCTHAM_QUYETDINH pt
                          inner join (select f.ID from DM_QD_LOAI f where f.ISHANHCHINH=1 and f.HIEULUC=1 and f.MA='TDC'
                                      ) loai on loai.ID=pt.LOAIQDID
                          where 1=case when extract(year from pt.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                                       when extract(year from pt.NGAYQD)=vNam and extract(month from pt.NGAYQD)=vThang and vIsTrongNam=0 then 1
                                    else 0 end
                          ) qd on qd.DONID=hdxx.DONID
              inner join (select a.ID,a.MA_TEN as TenToaAn,a.ARRTHUTU from DM_TOAAN a where 
                          1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
