                          1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                                  when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                          ) ta on ta.ID=qd.TOAANID
              where hdxx.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
							) b on cb.ID=b.CANBOID
	where cb.NGAYBONHIEM <= b.NGAYPHANCONG and b.NGAYPHANCONG <= cb.NGAYKETTHUC
	), cteData as (
		select tp.ID as TPID,tp.HOTEN as TenTP,tp.TenToaAn,cd.ChucDanh,tp.ARRTHUTU,
			PKG_GSTP.FUN_GETTYLE_ANTDC_BYTP(tp.ID,tp.NGAYBONHIEM,tp.NGAYKETTHUC) as TyLeTDC
		from cteTP tp
		inner join (select g.ID,g.TEN as ChucDanh from DM_DATAITEM g where g.GROUPID=vGroupChucDanhID  and g.MA in ('TP','TPSC','TPTC','TPCC','TPTATC')) cd on cd.ID=tp.CHUCDANHID
		),
  cteTotal as (
    select count(TPID) as Total from cteData
  ),
  cteFinal AS(
    select ROW_NUMBER() OVER (ORDER BY a.ARRTHUTU,a.TenTP) STT,a.TPID,a.TenTP,a.TenToaAn,a.ChucDanh,a.TyLeTDC,(select Total from cteTotal) as Total
    from cteData a
  )
  
  select a.STT,a.TPID,a.TenTP,a.TenToaAn,a.ChucDanh,a.TyLeTDC,a.Total
  from cteFinal a where a.STT between vMin and vMax;
END THONGKE_TP_ANTAMDINHCHI;
PROCEDURE THONGKE_TP_ANBPTT
(
	vDonViID in number,
  vIsTrongNam in number,
	vThang in number,
	vNam in number,
	vPageIndex in number,
	vPageSize in number,
	CurReturn OUT sys_refcursor
) AS
	vArrSapXep varchar2(250);vIsToaCapCao number;vGroupChucDanhID number:=0;vMin number:=0;vMax number;
BEGIN
	vMin := vPageSize*(vPageIndex - 1) + 1;
	vMax := vPageIndex*vPageSize ;
	if vDonViID>0 then
			begin
			select t.ARRSAPXEP into vArrSapXep from DM_TOAAN t where t.ID=vDonViID;
			select count(t.ID) into vIsToaCapCao from DM_TOAAN t where t.ID=vDonViID and t.LOAITOA='CAPCAO';
			end;
	else
			begin
			vArrSapXep:='0';
			vIsToaCapCao:=0;
			end;
	end if;
  --select a.ANHUY into vTyLeAnHuy from GSTP_CAUHINH a;
  select a.ID into vGroupChucDanhID from DM_DATAGROUP a where a.MA='CHUCDANH';
  open CurReturn for
  WITH cteTP as(
  -- Hình sự sơ thẩm
  select cb.ID,cb.HOTEN,cb.CHUCDANHID,cb.NGAYBONHIEM,cb.NGAYKETTHUC,b.TenToaAn,b.ARRTHUTU 
  from DM_CANBO cb
	inner join (select hdxx.VUANID,hdxx.CANBOID,hdxx.NGAYPHANCONG,ta.TenToaAn,ta.ARRTHUTU from AHS_SOTHAM_HDXX hdxx
              inner join (select st.VUANID,st.DONVIID from AHS_SOTHAM_QUYETDINH_VUAN st
                          inner join (select f.ID from DM_QD_LOAI f where f.ISHINHSU=1 and f.HIEULUC=1 and f.MA='ADBPTT'
                                      ) loai on loai.ID=st.LOAIQDID
                          where 1=case when extract(year from st.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                                       when extract(year from st.NGAYQD)=vNam and extract(month from st.NGAYQD)=vThang and vIsTrongNam=0 then 1
                                    else 0 end
                          ) qd on qd.VUANID=hdxx.VUANID
              inner join (select a.ID,a.MA_TEN as TenToaAn,a.ARRTHUTU from DM_TOAAN a where 
                          1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                                  when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                          ) ta on ta.ID=qd.DONVIID
              where hdxx.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
							) b on cb.ID=b.CANBOID
	where cb.NGAYBONHIEM <= b.NGAYPHANCONG and b.NGAYPHANCONG <= cb.NGAYKETTHUC
  union
  -- Hình sự phúc thẩm
  select cb.ID,cb.HOTEN,cb.CHUCDANHID,cb.NGAYBONHIEM,cb.NGAYKETTHUC,b.TenToaAn,b.ARRTHUTU 
  from DM_CANBO cb
	inner join (select hdxx.VUANID,hdxx.CANBOID,hdxx.NGAYPHANCONG,ta.TenToaAn,ta.ARRTHUTU from AHS_PHUCTHAM_HDXX hdxx
              inner join (select pt.VUANID,pt.DONVIID from AHS_PHUCTHAM_QUYETDINH_VUAN pt
                          inner join (select f.ID from DM_QD_LOAI f where f.ISHINHSU=1 and f.HIEULUC=1 and f.MA='ADBPTT'
                                      ) loai on loai.ID=pt.LOAIQDID
                          where 1=case when extract(year from pt.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                                       when extract(year from pt.NGAYQD)=vNam and extract(month from pt.NGAYQD)=vThang and vIsTrongNam=0 then 1
                                    else 0 end
                          ) qd on qd.VUANID=hdxx.VUANID
              inner join (select a.ID,a.MA_TEN as TenToaAn,a.ARRTHUTU from DM_TOAAN a where 
                          1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                                  when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                          ) ta on ta.ID=qd.DONVIID
              where hdxx.MAVAITRO in ('THAMPHAN','THAMPHANHDXX','THAMPHANDUKHUYET')
							) b on cb.ID=b.CANBOID
	where cb.NGAYBONHIEM <= b.NGAYPHANCONG and b.NGAYPHANCONG <= cb.NGAYKETTHUC
  union
	-- Dân sự sơ thẩm
  select cb.ID,cb.HOTEN,cb.CHUCDANHID,cb.NGAYBONHIEM,cb.NGAYKETTHUC,b.TenToaAn,b.ARRTHUTU 
  from DM_CANBO cb
