	), cteData as (
		select tp.ID as TPID,tp.HOTEN as TenTP,tp.TenToaAn,cd.ChucDanh,tp.ARRTHUTU,
			PKG_GSTP.FUN_GETTYLE_ANBPTT_BYTP(tp.ID,tp.NGAYBONHIEM,tp.NGAYKETTHUC) as TyLeBPTT
		from cteTP tp
		inner join (select g.ID,g.TEN as ChucDanh from DM_DATAITEM g where g.GROUPID=vGroupChucDanhID  and g.MA in ('TP','TPSC','TPTC','TPCC','TPTATC')) cd on cd.ID=tp.CHUCDANHID
		),
  cteTotal as (
    select count(TPID) as Total from cteData
  ),
  cteFinal AS(
    select ROW_NUMBER() OVER (ORDER BY a.ARRTHUTU,a.TenTP) STT,a.TPID,a.TenTP,a.TenToaAn,a.ChucDanh,a.TyLeBPTT,(select Total from cteTotal) as Total
    from cteData a
  )
  
  select a.STT,a.TPID,a.TenTP,a.TenToaAn,a.ChucDanh,a.TyLeBPTT,a.Total
  from cteFinal a where a.STT between vMin and vMax;
END THONGKE_TP_ANBPTT;
PROCEDURE THONGKE_DS_ANHUY(
