							) ta on ta.ID=don.TOAPHUCTHAMID and ba.TOAANID=ta.ID
	),
	cteTotal as (
		select count(ID) as Total from cteData
	),
	cteFinal AS(
		select ROW_NUMBER() OVER (ORDER BY a.ArrThuTuToaAn,a.LinhVuc,a.GiaiDoan,a.MAVUVIEC) STT,
			a.MAVUVIEC,a.TENVUVIEC,a.TenToa,a.GiaiDoan,a.LinhVuc,(select Total from cteTotal) as Total
	from cteData a
	)
  
	select a.STT,a.MAVUVIEC,a.TENVUVIEC,a.TenToa,a.GiaiDoan,a.LinhVuc,a.Total
	from cteFinal a where a.STT between vMin and vMax;
  
END THONGKE_DS_ANHUY;
