	from APS_DON don
	inner join (select f.DONID,f.KETQUAPHUCTHAMID,f.NGAYTUYENAN,f.TOAANID from APS_PHUCTHAM_BANAN f
							inner join (select e.ID from DM_KETQUA_PHUCTHAM e where e.ISAPS=1 and lower(e.TEN) like '%sửa%') kq on f.KETQUAPHUCTHAMID=kq.ID
							where 1=case when extract(year from f.NGAYTUYENAN)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from f.NGAYTUYENAN)=vNam and extract(month from f.NGAYTUYENAN)=vThang and vIsTrongNam=0 then 1
										else 0 end
							) ba on ba.DONID=don.ID
	inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on ta.ID=don.TOAPHUCTHAMID and ba.TOAANID=ta.ID
	union
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,'Xử lý hành chính' as LinhVuc,ta.TenToa, 
		'Phúc thẩm' as GiaiDoan,ta.ArrThuTuToaAn
	from XLHC_DON don
	inner join (select f.DONID,f.KETQUAPHUCTHAMID,f.NGAYTUYENAN,f.TOAANID from XLHC_PHUCTHAM_BANAN f
							inner join (select e.ID from DM_KETQUA_PHUCTHAM e where e.ISXLHC=1 and lower(e.TEN) like '%sửa%') kq on f.KETQUAPHUCTHAMID=kq.ID
							where 1=case when extract(year from f.NGAYTUYENAN)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from f.NGAYTUYENAN)=vNam and extract(month from f.NGAYTUYENAN)=vThang and vIsTrongNam=0 then 1
										else 0 end
							) ba on ba.DONID=don.ID
	inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on ta.ID=don.TOAPHUCTHAMID and ba.TOAANID=ta.ID
	),
	cteTotal as (
		select count(ID) as Total from cteData
	),
	cteFinal AS(
		select ROW_NUMBER() OVER (ORDER BY a.ArrThuTuToaAn,a.LinhVuc,a.GiaiDoan,a.MAVUVIEC) STT,
			a.MAVUVIEC,a.TENVUVIEC,a.TenToa,a.GiaiDoan,a.LinhVuc,(select Total from cteTotal) as Total
	from cteData a
	)
  
	select a.STT,a.MAVUVIEC,a.TENVUVIEC,a.TenToa,a.GiaiDoan,a.LinhVuc,a.Total
	from cteFinal a where a.STT between vMin and vMax;
END THONGKE_DS_ANSUA;
PROCEDURE THONGKE_DS_ANQUAHAN(
	vDonViID in number,
	vIsTrongNam in number,
	vThang in number,
	vNam in number,
	vPageIndex in number,
	vPageSize in number,
	curReturn OUT sys_refcursor
)
AS
vArrSapXep varchar2(250);vIsToaCapCao number;vTotal number:=0;vMin number:=0;vMax number;
BEGIN
	vMin := vPageSize*(vPageIndex - 1) + 1;
	vMax := vPageIndex*vPageSize ;
	if vDonViID>0 then
			begin
			select t.ARRSAPXEP into vArrSapXep from DM_TOAAN t where t.ID=vDonViID;
			select count(t.ID) into vIsToaCapCao from DM_TOAAN t where t.ID=vDonViID and t.LOAITOA='CAPCAO';
			end;
	else
			begin
			vArrSapXep:='0';
			vIsToaCapCao:=0;
			end;
	end if;
	open curReturn for
	with cteData as (
  -- Hình sự
	select don.ID,don.MAVUAN as MAVUVIEC,don.TENVUAN as TENVUVIEC,'Hình sự' as LinhVuc,st.TenToa, 
		'Sơ thẩm' as GiaiDoan,st.ArrThuTuToaAn 
	from AHS_VUAN don
	inner join (select ba.VUANID,ta.TenToa,ta.ArrThuTuToaAn from AHS_SOTHAM_BANAN ba
              inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
                          1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                                  when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                          ) ta on ta.ID=ba.TOAANID
							where 1=case when extract(year from ba.NGAYBANAN)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from ba.NGAYBANAN)=vNam and extract(month from ba.NGAYBANAN)=vThang and vIsTrongNam=0 then 1
										else 0 end
										and (ba.TK_QUAHAN_CHUQUAN=1 or ba.TK_QUAHAN_KHACHQUAN=1)
							) st on st.VUANID=don.ID
	union
  -- Dân sự
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,'Dân sự' as LinhVuc,st.TenToa,'Sơ thẩm' as GiaiDoan,st.ArrThuTuToaAn 
	from ADS_DON don
	inner join (select ba.DONID,ba.TOAANID,ta.TenToa,ta.ArrThuTuToaAn from ADS_SOTHAM_BANAN ba
              inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
                          1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                                  when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                          ) ta on ta.ID=ba.TOAANID
							where 1=case when extract(year from ba.NGAYTUYENAN)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from ba.NGAYTUYENAN)=vNam and extract(month from ba.NGAYTUYENAN)=vThang and vIsTrongNam=0 then 1
										else 0 end
										and ba.TK_ISQUAHAN=1
              )st on st.DONID=don.ID
  union
  select don.ID,don.MAVUVIEC,don.TENVUVIEC,'Dân sự' as LinhVuc,pt.TenToa,'Phúc thẩm' as GiaiDoan,pt.ArrThuTuToaAn 
	from ADS_DON don
