  union
  select don.ID,don.MAVUVIEC,don.TENVUVIEC,'Hôn nhân gia đình' as LinhVuc,pt.TenToa,'Phúc thẩm' as GiaiDoan,pt.ArrThuTuToaAn 
	from AHN_DON don
  inner join (select ba.DONID,ba.TOAANID,ta.TenToa,ta.ArrThuTuToaAn from AHN_PHUCTHAM_BANAN ba
              inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
