  union
  select don.ID,don.MAVUVIEC,don.TENVUVIEC,'Kinh doanh thương mại' as LinhVuc,pt.TenToa,'Phúc thẩm' as GiaiDoan,pt.ArrThuTuToaAn 
	from AKT_DON don
  inner join (select ba.DONID,ba.TOAANID,ta.TenToa,ta.ArrThuTuToaAn from AKT_PHUCTHAM_BANAN ba
              inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
                          1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
