										and ba.TK_ISQUAHAN=1
							) pt on pt.DONID=don.ID
	union
  --Lao động
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,'Lao động' as LinhVuc,st.TenToa,'Sơ thẩm' as GiaiDoan,st.ArrThuTuToaAn 
