										else 0 end
										and ba.TK_ISQUAHAN=1
              )st on st.DONID=don.ID
	union
  -- Xử lý hành chính
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,'Xử lý hành chính' as LinhVuc,st.TenToa,'Sơ thẩm' as GiaiDoan,st.ArrThuTuToaAn 
