	from XLHC_DON don
  inner join (select ba.DONID,ba.TOAANID,ta.TenToa,ta.ArrThuTuToaAn from XLHC_PHUCTHAM_BANAN ba
              inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
                          1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                                  when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                          ) ta on ta.ID=ba.TOAANID
							where 1=case when extract(year from ba.NGAYTUYENAN)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from ba.NGAYTUYENAN)=vNam and extract(month from ba.NGAYTUYENAN)=vThang and vIsTrongNam=0 then 1
										else 0 end
										and ba.TK_ISQUAHAN=1
							) pt on pt.DONID=don.ID
	),
	cteTotal as (
		select count(ID) as Total from cteData
	),
	cteFinal AS(
		select ROW_NUMBER() OVER (ORDER BY a.ArrThuTuToaAn,a.LinhVuc,a.GiaiDoan,a.MAVUVIEC) STT,
			a.MAVUVIEC,a.TENVUVIEC,a.TenToa,a.GiaiDoan,a.LinhVuc,(select Total from cteTotal) as Total
	from cteData a
	)
  
	select a.STT,a.MAVUVIEC,a.TENVUVIEC,a.TenToa,a.GiaiDoan,a.LinhVuc,a.Total
	from cteFinal a where a.STT between vMin and vMax;
END THONGKE_DS_ANQUAHAN;
PROCEDURE THONGKE_DS_ANTREO(
	vDonViID in number,
	vIsTrongNam in number,
	vThang in number,
	vNam in number,
	vPageIndex in number,
	vPageSize in number,
	curReturn OUT sys_refcursor
)
AS
vArrSapXep varchar2(250);vIsToaCapCao number;vTotal number:=0;vMin number:=0;vMax number;
vIndex number:=0;vGiaiDoanST number:=2;vGiaiDoanPT number:=3;
BEGIN
	vMin := vPageSize*(vPageIndex - 1) + 1;
	vMax := vPageIndex*vPageSize ;
	vIndex:=1;
	if vDonViID>0 then
			begin
			select t.ARRSAPXEP into vArrSapXep from DM_TOAAN t where t.ID=vDonViID;
			select count(t.ID) into vIsToaCapCao from DM_TOAAN t where t.ID=vDonViID and t.LOAITOA='CAPCAO';
			end;
	else
			begin
			vArrSapXep:='0';
			vIsToaCapCao:=0;
			end;
	end if;
	open curReturn for
	with cteQD as (
  select distinct ba.VUANID,ta.TenToa,ta.ArrThuTuToaAn,'Sơ thẩm' GiaiDoan from AHS_SOTHAM_BANAN_DIEU_CHITIET ct
    inner join (select a.ID,a.VUANID,a.TOAANID from AHS_SOTHAM_BANAN a 
                where 1=case when extract(year from a.NGAYBANAN)=vNam and vIsTrongNam=1 then 1 
                             when extract(year from a.NGAYBANAN)=vNam and extract(month from a.NGAYBANAN)=vThang and vIsTrongNam=0 then 1
              else 0 end) ba on ba.ID=ct.BANANID
    inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
                1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                        when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                ) ta on ta.ID=ba.TOAANID
    where ct.ISANTREO=1
  union
	select distinct ba.VUANID,ta.TenToa,ta.ArrThuTuToaAn,'Phúc thẩm' as GiaiDoan from AHS_PHUCTHAM_BANAN_DIEU_CT ct
  inner join (select a.ID,a.VUANID,a.TOAANID from AHS_PHUCTHAM_BANAN a 
              where 1=case when extract(year from a.NGAYBANAN)=vNam and vIsTrongNam=1 then 1 
                           when extract(year from a.NGAYBANAN)=vNam and extract(month from a.NGAYBANAN)=vThang and vIsTrongNam=0 then 1
            else 0 end) ba on ba.ID=ct.BANANID
  inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
              1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                      when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
              ) ta on ta.ID=ba.TOAANID
    where ct.ISANTREO=1
	),
  cteData as (
    select an.ID,an.MAVUAN as MAVUVIEC,an.TENVUAN as TENVUVIEC,qd.TenToa,qd.GiaiDoan,'Hình sự' as LinhVuc,qd.ArrThuTuToaAn 
    from AHS_VUAN an
    inner join cteQD qd on qd.VUANID=an.ID
  ),
	cteTotal as (
		select count(ID) as Total from cteData
	),
	cteFinal AS(
		select ROW_NUMBER() OVER (ORDER BY a.ArrThuTuToaAn,a.LinhVuc,a.GiaiDoan,a.MAVUVIEC) STT,a.ID,
			a.MAVUVIEC,a.TENVUVIEC,a.TenToa,a.GiaiDoan,a.LinhVuc,(select Total from cteTotal) as Total
	from cteData a
	)
  
	select a.STT,a.ID,a.MAVUVIEC,a.TENVUVIEC,a.TenToa,a.GiaiDoan,a.LinhVuc,a.Total
	from cteFinal a where a.STT between vMin and vMax;
END THONGKE_DS_ANTREO;
PROCEDURE THONGKE_DS_ANTAMDINHCHI(
	vDonViID in number,
	vIsTrongNam in number,
	vThang in number,
	vNam in number,
	vPageIndex in number,
	vPageSize in number,
	curReturn OUT sys_refcursor
)
AS
vArrSapXep varchar2(250);vIsToaCapCao number;vMin number:=0;vMax number;
vGiaiDoanST number:=2;vGiaiDoanPT number:=3;
BEGIN
	vMin := vPageSize*(vPageIndex - 1) + 1;
	vMax := vPageIndex*vPageSize ;
	if vDonViID>0 then
			begin
			select t.ARRSAPXEP into vArrSapXep from DM_TOAAN t where t.ID=vDonViID;
			select count(t.ID) into vIsToaCapCao from DM_TOAAN t where t.ID=vDonViID and t.LOAITOA='CAPCAO';
			end;
	else
			begin
			vArrSapXep:='0';
			vIsToaCapCao:=0;
			end;
	end if;
	open curReturn for
  
	WITH cteData as(
  -- Hình sự
  select an.ID,an.MAVUAN as MAVUVIEC,an.TENVUAN as TENVUVIEC,st.TenToa,'Hình sự' as LinhVuc,'Sơ thẩm' as GiaiDoan,st.ARRTHUTU
  from AHS_VUAN an
  inner join (
              select distinct qd.VUANID,ta.TenToa,ta.ARRTHUTU from AHS_SOTHAM_QUYETDINH_VUAN qd
              inner join (select f.ID from DM_QD_LOAI f where f.ISHINHSU=1 and f.HIEULUC=1 and f.MA='TDC'
                          ) loai on loai.ID=qd.LOAIQDID
              inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU from DM_TOAAN a where 
                          1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                              when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                          ) ta on ta.ID=qd.DONVIID
              where 1=case when extract(year from qd.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                           when extract(year from qd.NGAYQD)=vNam and extract(month from qd.NGAYQD)=vThang and vIsTrongNam=0 then 1
                           else 0 end
              ) st on st.VUANID=an.ID
  union
  select an.ID,an.MAVUAN as MAVUVIEC,an.TENVUAN as TENVUVIEC,pt.TenToa,'Hình sự' as LinhVuc,'Phúc thẩm' as GiaiDoan,pt.ARRTHUTU
  from AHS_VUAN an
  inner join (
              select distinct qd.VUANID,ta.TenToa,ta.ARRTHUTU from AHS_PHUCTHAM_QUYETDINH_VUAN qd
              inner join (select f.ID from DM_QD_LOAI f where f.ISHINHSU=1 and f.HIEULUC=1 and f.MA='TDC'
                          ) loai on loai.ID=qd.LOAIQDID
              inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU from DM_TOAAN a where 
                          1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                              when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                          ) ta on ta.ID=qd.DONVIID
              where 1=case when extract(year from qd.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                           when extract(year from qd.NGAYQD)=vNam and extract(month from qd.NGAYQD)=vThang and vIsTrongNam=0 then 1
                           else 0 end
	) pt on pt.VUANID=an.ID
	union
  -- Dân sự
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,st.TenToa,'Dân sự' as LinhVuc,'Sơ thẩm' as GiaiDoan,st.ARRTHUTU 
  from ADS_DON don
  inner join(
            select distinct qd.DONID,ta.TenToa,ta.ARRTHUTU from ADS_SOTHAM_QUYETDINH qd
            inner join (select f.ID from DM_QD_LOAI f where f.ISDANSU=1 and f.HIEULUC=1 and f.MA='TDC'
                        ) loai on loai.ID=qd.LOAIQDID
            inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU from DM_TOAAN a where 
                        1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                            when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                        ) ta on ta.ID=qd.TOAANID
            where 1=case when extract(year from qd.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                         when extract(year from qd.NGAYQD)=vNam and extract(month from qd.NGAYQD)=vThang and vIsTrongNam=0 then 1
                         else 0 end
            ) st on st.DONID=don.ID
  union
  select don.ID,don.MAVUVIEC,don.TENVUVIEC,pt.TenToa,'Dân sự' as LinhVuc,'Phúc thẩm' as GiaiDoan,pt.ARRTHUTU 
  from ADS_DON don
  inner join(
            select distinct qd.DONID,ta.TenToa,ta.ARRTHUTU from ADS_PHUCTHAM_QUYETDINH qd
            inner join (select f.ID from DM_QD_LOAI f where f.ISDANSU=1 and f.HIEULUC=1 and f.MA='TDC'
                        ) loai on loai.ID=qd.LOAIQDID
            inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU from DM_TOAAN a where 
                        1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                            when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                        ) ta on ta.ID=qd.TOAANID
            where 1=case when extract(year from qd.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                         when extract(year from qd.NGAYQD)=vNam and extract(month from qd.NGAYQD)=vThang and vIsTrongNam=0 then 1
                         else 0 end
            ) pt on pt.DONID=don.ID
	union
	-- Hôn nhân
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,st.TenToa,'Hôn nhân gia đình' as LinhVuc,'Sơ thẩm' as GiaiDoan,st.ARRTHUTU 
  from AHN_DON don
  inner join(
            select distinct qd.DONID,ta.TenToa,ta.ARRTHUTU from AHN_SOTHAM_QUYETDINH qd
            inner join (select f.ID from DM_QD_LOAI f where f.ISHNGD=1 and f.HIEULUC=1 and f.MA='TDC'
                        ) loai on loai.ID=qd.LOAIQDID
            inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU from DM_TOAAN a where 
                        1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                            when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                        ) ta on ta.ID=qd.TOAANID
            where 1=case when extract(year from qd.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                         when extract(year from qd.NGAYQD)=vNam and extract(month from qd.NGAYQD)=vThang and vIsTrongNam=0 then 1
                         else 0 end
            ) st on st.DONID=don.ID
  union
  select don.ID,don.MAVUVIEC,don.TENVUVIEC,pt.TenToa,'Hôn nhân gia đình' as LinhVuc,'Phúc thẩm' as GiaiDoan,pt.ARRTHUTU 
  from AHN_DON don
  inner join(
            select distinct qd.DONID,ta.TenToa,ta.ARRTHUTU from AHN_PHUCTHAM_QUYETDINH qd
            inner join (select f.ID from DM_QD_LOAI f where f.ISHNGD=1 and f.HIEULUC=1 and f.MA='TDC'
                        ) loai on loai.ID=qd.LOAIQDID
            inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU from DM_TOAAN a where 
                        1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                            when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                        ) ta on ta.ID=qd.TOAANID
            where 1=case when extract(year from qd.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                         when extract(year from qd.NGAYQD)=vNam and extract(month from qd.NGAYQD)=vThang and vIsTrongNam=0 then 1
                         else 0 end
            ) pt on pt.DONID=don.ID
	union
	-- Kinh tế
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,st.TenToa,'Kinh doanh thương mại' as LinhVuc,'Sơ thẩm' as GiaiDoan,st.ARRTHUTU 
  from AKT_DON don
  inner join(
            select distinct qd.DONID,ta.TenToa,ta.ARRTHUTU from AKT_SOTHAM_QUYETDINH qd
            inner join (select f.ID from DM_QD_LOAI f where f.ISKDTM=1 and f.HIEULUC=1 and f.MA='TDC'
                        ) loai on loai.ID=qd.LOAIQDID
            inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU from DM_TOAAN a where 
                        1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                            when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                        ) ta on ta.ID=qd.TOAANID
            where 1=case when extract(year from qd.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                         when extract(year from qd.NGAYQD)=vNam and extract(month from qd.NGAYQD)=vThang and vIsTrongNam=0 then 1
                         else 0 end
            ) st on st.DONID=don.ID
  union
  select don.ID,don.MAVUVIEC,don.TENVUVIEC,pt.TenToa,'Kinh doanh thương mại' as LinhVuc,'Phúc thẩm' as GiaiDoan,pt.ARRTHUTU 
  from AKT_DON don
  inner join(
            select distinct qd.DONID,ta.TenToa,ta.ARRTHUTU from AKT_PHUCTHAM_QUYETDINH qd
            inner join (select f.ID from DM_QD_LOAI f where f.ISKDTM=1 and f.HIEULUC=1 and f.MA='TDC'
                        ) loai on loai.ID=qd.LOAIQDID
            inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU from DM_TOAAN a where 
                        1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                            when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                        ) ta on ta.ID=qd.TOAANID
            where 1=case when extract(year from qd.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                         when extract(year from qd.NGAYQD)=vNam and extract(month from qd.NGAYQD)=vThang and vIsTrongNam=0 then 1
                         else 0 end
            ) pt on pt.DONID=don.ID
	union
	-- Lao động
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,st.TenToa,'Lao động' as LinhVuc,'Sơ thẩm' as GiaiDoan,st.ARRTHUTU 
  from ALD_DON don
  inner join(
