  from ALD_DON don
  inner join(
            select distinct qd.DONID,ta.TenToa,ta.ARRTHUTU from ALD_PHUCTHAM_QUYETDINH qd
            inner join (select f.ID from DM_QD_LOAI f where f.ISLAODONG=1 and f.HIEULUC=1 and f.MA='TDC'
                        ) loai on loai.ID=qd.LOAIQDID
            inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU from DM_TOAAN a where 
                        1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                            when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                        ) ta on ta.ID=qd.TOAANID
            where 1=case when extract(year from qd.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                         when extract(year from qd.NGAYQD)=vNam and extract(month from qd.NGAYQD)=vThang and vIsTrongNam=0 then 1
                         else 0 end
            ) pt on pt.DONID=don.ID
	union
	-- Hành chính
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,st.TenToa,'Hành chính' as LinhVuc,'Sơ thẩm' as GiaiDoan,st.ARRTHUTU 
  from AHC_DON don
  inner join(
            select distinct qd.DONID,ta.TenToa,ta.ARRTHUTU from AHC_SOTHAM_QUYETDINH qd
            inner join (select f.ID from DM_QD_LOAI f where f.ISHANHCHINH=1 and f.HIEULUC=1 and f.MA='TDC'
                        ) loai on loai.ID=qd.LOAIQDID
            inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU from DM_TOAAN a where 
                        1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                            when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                        ) ta on ta.ID=qd.TOAANID
            where 1=case when extract(year from qd.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                         when extract(year from qd.NGAYQD)=vNam and extract(month from qd.NGAYQD)=vThang and vIsTrongNam=0 then 1
                         else 0 end
            ) st on st.DONID=don.ID
  union
  select don.ID,don.MAVUVIEC,don.TENVUVIEC,pt.TenToa,'Hành chính' as LinhVuc,'Phúc thẩm' as GiaiDoan,pt.ARRTHUTU 
  from AHC_DON don
  inner join(
            select distinct qd.DONID,ta.TenToa,ta.ARRTHUTU from AHC_PHUCTHAM_QUYETDINH qd
            inner join (select f.ID from DM_QD_LOAI f where f.ISHANHCHINH=1 and f.HIEULUC=1 and f.MA='TDC'
                        ) loai on loai.ID=qd.LOAIQDID
            inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU from DM_TOAAN a where 
                        1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                            when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                        ) ta on ta.ID=qd.TOAANID
            where 1=case when extract(year from qd.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                         when extract(year from qd.NGAYQD)=vNam and extract(month from qd.NGAYQD)=vThang and vIsTrongNam=0 then 1
                         else 0 end
            ) pt on pt.DONID=don.ID
	union
	-- Phá sản
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,st.TenToa,'Phá sản' as LinhVuc,'Sơ thẩm' as GiaiDoan,st.ARRTHUTU 
  from APS_DON don
  inner join(
            select distinct qd.DONID,ta.TenToa,ta.ARRTHUTU from APS_SOTHAM_QUYETDINH qd
            inner join (select f.ID from DM_QD_LOAI f where f.ISPHASAN=1 and f.HIEULUC=1 and f.MA='TDC'
                        ) loai on loai.ID=qd.LOAIQDID
            inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU from DM_TOAAN a where 
                        1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                            when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                        ) ta on ta.ID=qd.TOAANID
            where 1=case when extract(year from qd.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                         when extract(year from qd.NGAYQD)=vNam and extract(month from qd.NGAYQD)=vThang and vIsTrongNam=0 then 1
                         else 0 end
            ) st on st.DONID=don.ID
  union
  select don.ID,don.MAVUVIEC,don.TENVUVIEC,pt.TenToa,'Phá sản' as LinhVuc,'Phúc thẩm' as GiaiDoan,pt.ARRTHUTU 
  from APS_DON don
  inner join(
            select distinct qd.DONID,ta.TenToa,ta.ARRTHUTU from APS_PHUCTHAM_QUYETDINH qd
            inner join (select f.ID from DM_QD_LOAI f where f.ISPHASAN=1 and f.HIEULUC=1 and f.MA='TDC'
                        ) loai on loai.ID=qd.LOAIQDID
            inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU from DM_TOAAN a where 
                        1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                            when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                        ) ta on ta.ID=qd.TOAANID
            where 1=case when extract(year from qd.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                         when extract(year from qd.NGAYQD)=vNam and extract(month from qd.NGAYQD)=vThang and vIsTrongNam=0 then 1
                         else 0 end
            ) pt on pt.DONID=don.ID
	union
	-- XLHC
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,st.TenToa,'Xử lý hành chính' as LinhVuc,'Sơ thẩm' as GiaiDoan,st.ARRTHUTU 
  from XLHC_DON don
  inner join(
            select distinct qd.DONID,ta.TenToa,ta.ARRTHUTU from XLHC_SOTHAM_QUYETDINH qd
            inner join (select f.ID from DM_QD_LOAI f where f.ISXLHC=1 and f.HIEULUC=1 and f.MA='TDC'
                        ) loai on loai.ID=qd.LOAIQDID
            inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU from DM_TOAAN a where 
                        1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                            when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                        ) ta on ta.ID=qd.TOAANID
            where 1=case when extract(year from qd.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                         when extract(year from qd.NGAYQD)=vNam and extract(month from qd.NGAYQD)=vThang and vIsTrongNam=0 then 1
