  select don.ID,don.MAVUVIEC,don.TENVUVIEC,pt.TenToa,'Xử lý hành chính' as LinhVuc,'Phúc thẩm' as GiaiDoan,pt.ARRTHUTU 
  from XLHC_DON don
  inner join(
            select distinct qd.DONID,ta.TenToa,ta.ARRTHUTU from XLHC_PHUCTHAM_QUYETDINH qd
            inner join (select f.ID from DM_QD_LOAI f where f.ISXLHC=1 and f.HIEULUC=1 and f.MA='TDC'
                        ) loai on loai.ID=qd.LOAIQDID
            inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU from DM_TOAAN a where 
                        1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
                            when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
                        ) ta on ta.ID=qd.TOAANID
            where 1=case when extract(year from qd.NGAYQD)=vNam and vIsTrongNam=1 then 1 
                         when extract(year from qd.NGAYQD)=vNam and extract(month from qd.NGAYQD)=vThang and vIsTrongNam=0 then 1
                         else 0 end
            ) pt on pt.DONID=don.ID
  ),
	cteTotal as (
		select count(ID) as Total from cteData
	),
	cteFinal AS(
		select ROW_NUMBER() OVER (ORDER BY a.ARRTHUTU,a.LinhVuc,a.GiaiDoan,a.MAVUVIEC) STT,a.ID,
			a.MAVUVIEC,a.TENVUVIEC,a.TenToa,a.GiaiDoan,a.LinhVuc,(select Total from cteTotal) as Total
	from cteData a
	)
  
	select a.STT,a.ID,a.MAVUVIEC,a.TENVUVIEC,a.TenToa,a.GiaiDoan,a.LinhVuc,a.Total
	from cteFinal a where a.STT between vMin and vMax;

END THONGKE_DS_ANTAMDINHCHI;
PROCEDURE THONGKE_DS_ANBPTT(
	vDonViID in number,
	vIsTrongNam in number,
	vThang in number,
	vNam in number,
	vPageIndex in number,
	vPageSize in number,
	curReturn OUT sys_refcursor
)
AS
vArrSapXep varchar2(250);vIsToaCapCao number;vTotal number:=0;vMin number:=0;vMax number;
vIndex number:=0;vGiaiDoanST number:=2;vGiaiDoanPT number:=3;
BEGIN
	vMin := vPageSize*(vPageIndex - 1) + 1;
	vMax := vPageIndex*vPageSize ;
	vIndex:=1;
	if vDonViID>0 then
			begin
			select t.ARRSAPXEP into vArrSapXep from DM_TOAAN t where t.ID=vDonViID;
			select count(t.ID) into vIsToaCapCao from DM_TOAAN t where t.ID=vDonViID and t.LOAITOA='CAPCAO';
			end;
	else
			begin
			vArrSapXep:='0';
			vIsToaCapCao:=0;
			end;
	end if;
	open curReturn for
	with cteData as (
	select don.ID,don.MAVUAN as MAVUVIEC,don.TENVUAN as TENVUVIEC,'Hình sự' as LinhVuc,ta.TenToa, 
		case don.MAGIAIDOAN when 2 then 'Sơ thẩm'
												when 3 then 'Phúc thẩm'
												when 4 then 'GĐT,TT' end as GiaiDoan,ta.ArrThuTuToaAn 
	from AHS_VUAN don
	inner join (select distinct a.VUANID from AHS_SOTHAM_QUYETDINH_VUAN a
							inner join (select f.ID from DM_QD_LOAI f where f.ISHINHSU=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							union
							select distinct a.VUANID from AHS_PHUCTHAM_QUYETDINH_VUAN a
							inner join (select f.ID from DM_QD_LOAI f where f.ISHINHSU=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							) qd on qd.VUANID=don.ID
	inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on ((ta.ID=don.TOAANID and don.MAGIAIDOAN=vGiaiDoanST) or (ta.ID=don.TOAPHUCTHAMID and don.MAGIAIDOAN=vGiaiDoanPT))
	union
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,'Dân sự' as LinhVuc,ta.TenToa, 
		case don.MAGIAIDOAN when 2 then 'Sơ thẩm'
												when 3 then 'Phúc thẩm'
												when 4 then 'GĐT,TT' end as GiaiDoan,ta.ArrThuTuToaAn 
	from ADS_DON don
	inner join (select distinct a.DONID from ADS_SOTHAM_QUYETDINH a
							inner join (select f.ID from DM_QD_LOAI f where f.ISDANSU=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							union
							select distinct a.DONID from ADS_PHUCTHAM_QUYETDINH a
							inner join (select f.ID from DM_QD_LOAI f where f.ISDANSU=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							) qd on qd.DONID=don.ID
	inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on ((ta.ID=don.TOAANID and don.MAGIAIDOAN=vGiaiDoanST) or (ta.ID=don.TOAPHUCTHAMID and don.MAGIAIDOAN=vGiaiDoanPT))
	union
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,'Hôn nhân gia đình' as LinhVuc,ta.TenToa, 
		case don.MAGIAIDOAN when 2 then 'Sơ thẩm'
												when 3 then 'Phúc thẩm'
												when 4 then 'GĐT,TT' end as GiaiDoan,ta.ArrThuTuToaAn 
	from AHN_DON don
	inner join (select distinct a.DONID from AHN_SOTHAM_QUYETDINH a
							inner join (select f.ID from DM_QD_LOAI f where f.ISHNGD=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							union
							select distinct a.DONID from AHN_PHUCTHAM_QUYETDINH a
							inner join (select f.ID from DM_QD_LOAI f where f.ISHNGD=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							) qd on qd.DONID=don.ID
	inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on ((ta.ID=don.TOAANID and don.MAGIAIDOAN=vGiaiDoanST) or (ta.ID=don.TOAPHUCTHAMID and don.MAGIAIDOAN=vGiaiDoanPT))
	union
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,'Kinh doanh thương mại' as LinhVuc,ta.TenToa, 
		case don.MAGIAIDOAN when 2 then 'Sơ thẩm'
												when 3 then 'Phúc thẩm'
												when 4 then 'GĐT,TT' end as GiaiDoan,ta.ArrThuTuToaAn 
	from AKT_DON don
	inner join (select distinct a.DONID from AKT_SOTHAM_QUYETDINH a
							inner join (select f.ID from DM_QD_LOAI f where f.ISKDTM=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							union
							select distinct a.DONID from AKT_PHUCTHAM_QUYETDINH a
							inner join (select f.ID from DM_QD_LOAI f where f.ISKDTM=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							) qd on qd.DONID=don.ID
	inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on ((ta.ID=don.TOAANID and don.MAGIAIDOAN=vGiaiDoanST) or (ta.ID=don.TOAPHUCTHAMID and don.MAGIAIDOAN=vGiaiDoanPT))
	union
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,'Lao động' as LinhVuc,ta.TenToa, 
		case don.MAGIAIDOAN when 2 then 'Sơ thẩm'
												when 3 then 'Phúc thẩm'
												when 4 then 'GĐT,TT' end as GiaiDoan,ta.ArrThuTuToaAn 
	from ALD_DON don
	inner join (select distinct a.DONID from ALD_SOTHAM_QUYETDINH a
							inner join (select f.ID from DM_QD_LOAI f where f.ISLAODONG=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							union
							select distinct a.DONID from ALD_PHUCTHAM_QUYETDINH a
							inner join (select f.ID from DM_QD_LOAI f where f.ISLAODONG=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							) qd on qd.DONID=don.ID
	inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on ((ta.ID=don.TOAANID and don.MAGIAIDOAN=vGiaiDoanST) or (ta.ID=don.TOAPHUCTHAMID and don.MAGIAIDOAN=vGiaiDoanPT))
	union
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,'Hành chính' as LinhVuc,ta.TenToa, 
		case don.MAGIAIDOAN when 2 then 'Sơ thẩm'
												when 3 then 'Phúc thẩm'
												when 4 then 'GĐT,TT' end as GiaiDoan,ta.ArrThuTuToaAn 
	from AHC_DON don
	inner join (select distinct a.DONID from AHC_SOTHAM_QUYETDINH a
							inner join (select f.ID from DM_QD_LOAI f where f.ISHANHCHINH=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							union
							select distinct a.DONID from AHC_PHUCTHAM_QUYETDINH a
							inner join (select f.ID from DM_QD_LOAI f where f.ISHANHCHINH=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							) qd on qd.DONID=don.ID
	inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on ((ta.ID=don.TOAANID and don.MAGIAIDOAN=vGiaiDoanST) or (ta.ID=don.TOAPHUCTHAMID and don.MAGIAIDOAN=vGiaiDoanPT))
	union
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,'Phá sản' as LinhVuc,ta.TenToa, 
		case don.MAGIAIDOAN when 2 then 'Sơ thẩm'
												when 3 then 'Phúc thẩm'
												when 4 then 'GĐT,TT' end as GiaiDoan,ta.ArrThuTuToaAn 
	from APS_DON don
	inner join (select distinct a.DONID from APS_SOTHAM_QUYETDINH a
							inner join (select f.ID from DM_QD_LOAI f where f.ISPHASAN=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							union
							select distinct a.DONID from APS_PHUCTHAM_QUYETDINH a
							inner join (select f.ID from DM_QD_LOAI f where f.ISPHASAN=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							) qd on qd.DONID=don.ID
	inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on ((ta.ID=don.TOAANID and don.MAGIAIDOAN=vGiaiDoanST) or (ta.ID=don.TOAPHUCTHAMID and don.MAGIAIDOAN=vGiaiDoanPT))
	union
	select don.ID,don.MAVUVIEC,don.TENVUVIEC,'Xử lý hành chính' as LinhVuc,ta.TenToa, 
		case don.MAGIAIDOAN when 2 then 'Sơ thẩm'
												when 3 then 'Phúc thẩm'
												when 4 then 'GĐT,TT' end as GiaiDoan,ta.ArrThuTuToaAn 
	from XLHC_DON don
	inner join (select distinct a.DONID from XLHC_SOTHAM_QUYETDINH a
							inner join (select f.ID from DM_QD_LOAI f where f.ISXLHC=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							union
							select distinct a.DONID from XLHC_PHUCTHAM_QUYETDINH a
							inner join (select f.ID from DM_QD_LOAI f where f.ISXLHC=1 and f.HIEULUC=1 and f.MA='ADBPTT'
													) loai on loai.ID=a.LOAIQDID
							where 1=case when extract(year from a.NGAYQD)=vNam and vIsTrongNam=1 then 1 
													 when extract(year from a.NGAYQD)=vNam and extract(month from a.NGAYQD)=vThang and vIsTrongNam=0 then 1
										else 0 end
							) qd on qd.DONID=don.ID
	inner join (select a.ID,a.MA_TEN as TenToa,a.ARRTHUTU as ArrThuTuToaAn from DM_TOAAN a where 
							1= case when((a.ARRSAPXEP like (vArrSapXep ||'/%') or a.ARRSAPXEP=vArrSapXep ) and vIsToaCapCao=0) then 1 
											when a.ID=vDonViID and vIsToaCapCao>0 then 1 else 0 end
							) ta on ((ta.ID=don.TOAANID and don.MAGIAIDOAN=vGiaiDoanST) or (ta.ID=don.TOAPHUCTHAMID and don.MAGIAIDOAN=vGiaiDoanPT))
	),
	cteTotal as (
		select count(ID) as Total from cteData
	),
	cteFinal AS(
		select ROW_NUMBER() OVER (ORDER BY a.ArrThuTuToaAn,a.LinhVuc,a.GiaiDoan,a.MAVUVIEC) STT,
			a.MAVUVIEC,a.TENVUVIEC,a.TenToa,a.GiaiDoan,a.LinhVuc,(select Total from cteTotal) as Total
	from cteData a
	)
  
	select a.STT,a.MAVUVIEC,a.TENVUVIEC,a.TenToa,a.GiaiDoan,a.LinhVuc,a.Total
	from cteFinal a where a.STT between vMin and vMax;
END THONGKE_DS_ANBPTT;

FUNCTION FUN_GETVUANCHUTOA_BY_TP 
(
	vThamPhanID IN number
) RETURN NUMBER AS
	vTongVuAn number:=0;
	vADS_ST number:=0;vADS_PT number:=0;
	vAHC_ST number:=0;vAHC_PT number:=0;
	vAHN_ST number:=0;vAHN_PT number:=0;
	vAKT_ST number:=0;vAKT_PT number:=0;
	vALD_ST number:=0;vALD_PT number:=0;
	vAHS_ST number:=0;vAHS_PT number:=0;
	vAPS_ST number:=0;vAPS_PT number:=0;
	vXLHC_ST number:=0;vXLHC_PT number:=0;
BEGIN
	-- 1 Thẩm phán chỉ được xét xử 1 vụ án ở Sơ thẩm hoặc Phúc thẩm
	-- Án dân sự
	select count(c.DONID) into vADS_ST
	from ADS_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
  
	select count(c.DONID) into vADS_PT
	from ADS_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
	-- Án Hành chính
	select count(c.DONID) into vAHC_ST
	from AHC_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
  
	select count(c.DONID) into vAHC_PT
	from AHC_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
	-- Án Hôn nhân
	select count(c.DONID) into vAHN_ST
	from AHN_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
  
	select count(c.DONID) into vAHN_PT
	from AHN_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
	-- Án Kinh tế
	select count(c.DONID) into vAKT_ST
	from AKT_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
  
	select count(c.DONID) into vAKT_PT
	from AKT_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
	-- Án Lao động
	select count(c.DONID) into vALD_ST
	from ALD_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
  
	select count(c.DONID) into vALD_PT
	from ALD_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
	-- Án Hình sự
	select count(c.VUANID) into vAHS_ST
	from AHS_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
  
	select count(c.VUANID) into vAHS_PT
	from AHS_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
	-- Án Phá sản
	select count(c.DONID) into vAPS_ST
	from APS_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
  
	select count(c.DONID) into vAPS_PT
	from APS_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
	-- Án XLHC
	select count(c.DONID) into vXLHC_ST
	from XLHC_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
  
	select count(c.DONID) into vXLHC_PT
	from XLHC_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and c.MAVAITRO='THAMPHAN';
  
	vTongVuAn:=nvl(vADS_ST,0)+nvl(vAHC_ST,0)+nvl(vAHN_ST,0)+
						 nvl(vAKT_ST,0)+nvl(vALD_ST,0)+nvl(vAHS_ST,0)+
						 nvl(vAPS_ST,0)+nvl(vXLHC_ST,0)+
						 nvl(vADS_PT,0)+nvl(vAHC_PT,0)+nvl(vAHN_PT,0)+
						 nvl(vAKT_PT,0)+nvl(vALD_PT,0)+nvl(vAHS_PT,0)+
						 nvl(vAPS_PT,0)+nvl(vXLHC_PT,0);
	RETURN nvl(vTongVuAn,0);
END FUN_GETVUANCHUTOA_BY_TP;
FUNCTION FUN_GETVUANCANHGA_BY_TP 
(
	vThamPhanID IN number
) RETURN NUMBER AS
	vTongVuAn number:=0;
	vADS_ST number:=0;vADS_PT number:=0;
	vAHC_ST number:=0;vAHC_PT number:=0;
	vAHN_ST number:=0;vAHN_PT number:=0;
	vAKT_ST number:=0;vAKT_PT number:=0;
	vALD_ST number:=0;vALD_PT number:=0;
	vAHS_ST number:=0;vAHS_PT number:=0;
	vAPS_ST number:=0;vAPS_PT number:=0;
	vXLHC_ST number:=0;vXLHC_PT number:=0;
BEGIN
	-- 1 Thẩm phán chỉ được xét xử 1 vụ án ở Sơ thẩm hoặc Phúc thẩm
	-- Án dân sự
	select count(c.DONID) into vADS_ST
	from ADS_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
  
	select count(c.DONID) into vADS_PT
	from ADS_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
	-- Án Hành chính
	select count(c.DONID) into vAHC_ST
	from AHC_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
  
	select count(c.DONID) into vAHC_PT
	from AHC_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
	-- Án Hôn nhân
	select count(c.DONID) into vAHN_ST
	from AHN_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
  
	select count(c.DONID) into vAHN_PT
	from AHN_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
	-- Án Kinh tế
	select count(c.DONID) into vAKT_ST
	from AKT_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
  
	select count(c.DONID) into vAKT_PT
	from AKT_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
	-- Án Lao động
	select count(c.DONID) into vALD_ST
	from ALD_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
  
	select count(c.DONID) into vALD_PT
	from ALD_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
	-- Án Hình sự
	select count(c.VUANID) into vAHS_ST
	from AHS_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
  
	select count(c.VUANID) into vAHS_PT
	from AHS_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
	-- Án Phá sản
	select count(c.DONID) into vAPS_ST
	from APS_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
  
	select count(c.DONID) into vAPS_PT
	from APS_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
	-- Án XLHC
	select count(c.DONID) into vXLHC_ST
	from XLHC_SOTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
  
	select count(c.DONID) into vXLHC_PT
	from XLHC_PHUCTHAM_HDXX c
	where c.CANBOID=vThamPhanID and INSTR('THAMPHANDUKHUYET,THAMPHANHDXX,',c.MAVAITRO || ',')>0;
  
	vTongVuAn:=nvl(vADS_ST,0)+nvl(vAHC_ST,0)+nvl(vAHN_ST,0)+
						 nvl(vAKT_ST,0)+nvl(vALD_ST,0)+nvl(vAHS_ST,0)+
						 nvl(vAPS_ST,0)+nvl(vXLHC_ST,0)+
						 nvl(vADS_PT,0)+nvl(vAHC_PT,0)+nvl(vAHN_PT,0)+
						 nvl(vAKT_PT,0)+nvl(vALD_PT,0)+nvl(vAHS_PT,0)+
						 nvl(vAPS_PT,0)+nvl(vXLHC_PT,0);
	RETURN nvl(vTongVuAn,0);
END FUN_GETVUANCANHGA_BY_TP;

END PKG_GSTP;

/
